insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('first-errand', '🥕', '토리의 첫 심부름', '["토리는 오늘 처음으로 혼자 심부름을 가기로 했어요.","엄마는 토리에게 두부 한 모를 사 오라고 했어요.","토리는 씩씩하게 가게로 걸어갔어요.","가게에 도착했더니 두부가 다 팔리고 없었어요.","토리는 속상했지만 울지 않고 다른 가게를 찾아보기로 했어요.","옆 가게에서 드디어 두부를 찾았어요.","토리는 두부를 안전하게 들고 집으로 돌아왔어요.","엄마는 토리를 꼭 안아주며 정말 잘했다고 칭찬했어요.","토리는 스스로 해냈다는 생각에 마음이 뿌듯했어요."]'::jsonb, '[{"word":"심부름","meaning":"다른 사람이 시킨 일을 대신 하는 것"},{"word":"속상하다","meaning":"마음이 아프고 안 좋다"},{"word":"뿌듯하다","meaning":"마음이 흐뭇하고 자랑스럽다"}]'::jsonb, '[{"answer":true,"statement":"토리는 오늘 혼자 심부름을 갔어요."},{"answer":false,"statement":"토리는 사탕을 사러 갔어요."},{"answer":false,"statement":"첫 번째 가게에는 두부가 있었어요."},{"answer":true,"statement":"토리는 결국 두부를 사서 집에 돌아왔어요."}]'::jsonb, '{"choices":["심부름은 힘든 일이니 하지 않는 게 좋아요","두부는 맛이 없어요","엄마는 화가 많이 났어요","포기하지 않고 끝까지 해내면 뿌듯함을 느낄 수 있어요"],"question":"이 이야기가 말하고 싶은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"심부름","choices":["다른 사람이 시킨 일을 대신 하는 것","혼자 노는 것","귀찮게 되니 피해야 하는 것","학문이나 기술을 배우고 익히는 것"],"answerIndex":0},{"type":"vocab","word":"속상하다","choices":["기분이 아주 좋다","배가 고프다","마음이 아프고 안 좋다","신이 난다"],"answerIndex":2},{"type":"vocab","word":"뿌듯하다","choices":["너무 슬프다","마음이 흐뭇하고 자랑스럽다","화가 난다","졸리다"],"answerIndex":1}]'::jsonb, 0)
