insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('spring-garden', '🌱', '봄이 온 텃밭', '["토리네 반 친구들은 학교 텃밭에 씨앗을 심었어요.","토리는 작은 상추 씨앗을 흙 속에 콕 심었어요.","친구들은 매일 물을 주며 새싹이 나오기를 기다렸어요.","하루, 이틀이 지나도 아무 변화가 없어서 토리는 조금 실망했어요.","선생님은 씨앗이 자라려면 시간이 필요하다고 말해주었어요.","일주일이 지나자 흙 사이로 작은 초록 새싹이 쏙 올라왔어요.","토리와 친구들은 새싹을 보고 손뼉을 치며 기뻐했어요.","새싹은 날마다 조금씩 자라서 커다란 상추가 되었어요.","토리는 기다림 끝에 얻은 상추를 보고 뿌듯함을 느꼈어요."]'::jsonb, '[{"word":"새싹","meaning":"씨앗에서 처음 돋아난 어린 싹"},{"word":"실망하다","meaning":"바라던 대로 되지 않아 마음이 아쉽다"},{"word":"기다림","meaning":"어떤 일이 이루어지기를 참고 바라는 것"}]'::jsonb, '[{"answer":false,"statement":"새싹은 심자마자 바로 나왔어요."},{"answer":true,"statement":"친구들은 학교 텃밭에 씨앗을 심었어요."},{"answer":false,"statement":"선생님은 씨앗이 필요 없다고 했어요."},{"answer":true,"statement":"토리는 상추 씨앗을 심었어요."}]'::jsonb, '{"choices":["씨앗은 절대 자라지 않아요","기다리면 좋은 결과를 얻을 수 있어요","텃밭은 필요 없는 곳이에요","친구들은 서로 싸웠어요"],"question":"이 이야기의 중심 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"새싹","choices":["다 자란 나무","씨앗에서 처음 돋아난 어린 싹","마른 나뭇잎","커다란 꽃"],"answerIndex":1},{"type":"vocab","word":"실망하다","choices":["아주 기쁘다","괜히 미워하고 싫어하다","졸음이 온다","바라던 대로 되지 않아 마음이 아쉽다"],"answerIndex":3},{"type":"vocab","word":"기다림","choices":["어떤 일이 이루어지기를 참고 바라는 것","빨리 뛰어가는 것","크게 소리치는 것","기억에서 사라지는 것"],"answerIndex":0}]'::jsonb, 1)
