insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('sharing-crayons', '🖍️', '무지개를 함께 그려요', '["미소는 알록달록한 색연필을 아주 아꼈어요.","짝꿍 하늘이가 색연필을 빌려달라고 했지만 미소는 싫다고 했어요.","하늘이는 속상한 표정으로 자리로 돌아갔어요.","미소는 혼자 그림을 그렸지만 어쩐지 재미가 없었어요.","선생님은 함께 그리면 더 멋진 그림이 나온다고 말씀하셨어요.","미소는 용기를 내어 하늘이에게 색연필을 나누어 주었어요.","둘은 힘을 합쳐 커다란 무지개 그림을 완성했어요.","미소와 하늘이는 서로 마주 보며 활짝 웃었어요.","나누어 쓰니 그림도 더 예쁘고 마음도 더 따뜻해졌어요."]'::jsonb, '[{"word":"아끼다","meaning":"소중히 여겨 함부로 하지 않다"},{"word":"용기","meaning":"두렵지 않고 씩씩한 마음"},{"word":"나누다","meaning":"여럿이 함께 가지거나 쓰다"}]'::jsonb, '[{"answer":true,"statement":"미소는 처음에 색연필을 빌려주지 않았어요."},{"answer":true,"statement":"미소와 하늘이는 함께 그림을 완성했어요."},{"answer":false,"statement":"하늘이는 색연필을 빌려서 처음부터 기뻐했어요."},{"answer":false,"statement":"둘은 끝까지 사이가 나빴어요."}]'::jsonb, '{"choices":["색연필은 절대 빌려주면 안 돼요","그림은 꼭 혼자 그려야 멋져요","나누어 쓰면 마음이 따뜻해지고 즐거워져요","친구는 없어도 괜찮아요"],"question":"이 이야기가 전하고 싶은 마음은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"아끼다","choices":["아무렇게나 버리다","크게 화를 내다","소중히 여겨 함부로 하지 않다","빨리 먹어버리다"],"answerIndex":2},{"type":"vocab","word":"용기","choices":["두렵지 않고 씩씩한 마음","아주 무서운 마음","졸린 마음","배고픈 마음"],"answerIndex":0},{"type":"vocab","word":"나누다","choices":["혼자 다 가지다","숨기고 감추다","버리고 잊다","여럿이 함께 가지거나 쓰다"],"answerIndex":3}]'::jsonb, 2)
