insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('kind-words', '💬', '말 한마디의 힘', '["민준이는 축구 경기에서 실수로 공을 놓쳐 팀이 지고 말았어요.","화가 난 친구 태호가 \"너 때문에 다 졌잖아!\"라며 날카롭게 소리쳤어요.","민준이는 속상한 마음에 아무 말도 하지 못하고 고개를 숙였어요.","다음 날 태호는 준비물을 깜빡 잊고 학교에 왔어요.","태호는 민준이에게 지우개를 빌려달라고 조심스럽게 물었어요.","민준이는 어제 들었던 말이 떠올라 \"싫어, 너도 나한테 그렇게 말했잖아\"라고 쏘아붙였어요.","둘은 하루 종일 서먹하게 지내며 마음이 불편했어요.","집에 돌아온 태호는 할머니께 오늘 있었던 일을 이야기했어요.","할머니는 \"가는 말이 고와야 오는 말이 곱다는 말이 있단다\"라고 말씀해 주셨어요.","다음 날 태호는 민준이에게 먼저 다가가 어제는 미안했다고 진심으로 사과했어요.","민준이도 활짝 웃으며 사과를 받아 주었고, 둘은 다시 예전처럼 친하게 지냈어요."]'::jsonb, '[{"word":"날카롭다","meaning":"말이나 태도가 매섭고 거칠다"},{"word":"서먹하다","meaning":"친하지 않아 어색하고 불편하다"}]'::jsonb, '[{"answer":false,"statement":"태호는 민준이에게 처음부터 다정하게 말했어요."},{"answer":false,"statement":"민준이와 태호는 끝까지 화해하지 않았어요."},{"answer":true,"statement":"민준이는 축구 경기에서 실수를 했어요."},{"answer":true,"statement":"태호는 할머니께 속상한 마음을 이야기했어요."}]'::jsonb, '{"choices":["화가 나면 큰 소리로 말해야 해요","친구의 실수는 절대 용서하면 안 돼요","축구는 팀워크가 필요 없어요","내가 하는 말이 고와야 상대방도 나에게 곱게 말해요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"날카롭다","choices":["아주 부드럽고 다정하다","말이나 태도가 매섭고 거칠다","조용하고 차분하다","즐겁고 신난다"],"answerIndex":1},{"type":"vocab","word":"서먹하다","choices":["아주 친하고 편안하다","기쁘고 즐겁다","친하지 않아 어색하고 불편하다","화가 나서 소리치다"],"answerIndex":2},{"type":"proverb","word":"가는 말이 고와야 오는 말이 곱다","choices":["내가 좋게 말해야 남도 나에게 좋게 말한다는 뜻이에요","말은 아무렇게나 해도 된다는 뜻이에요","말을 하지 않는 것이 가장 좋다는 뜻이에요","가는 길이 예뻐야 한다는 뜻이에요"],"answerIndex":0}]'::jsonb, 3)
