insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('coin-bank', '🐷', '저금통 속 작은 동전', '["서연이는 문구점에서 예쁜 필통을 보고 꼭 갖고 싶어졌어요.","필통 가격은 만 원이었지만, 서연이의 용돈은 겨우 천 원밖에 없었어요.","서연이는 속상해서 엄마에게 필통을 사 달라고 졸랐어요.","엄마는 \"한 번에 다 가지려고 하지 말고 조금씩 모아보는 건 어떨까?\"라고 말씀하셨어요.","서연이는 그날부터 심부름을 하고 받은 용돈을 저금통에 차곡차곡 모으기 시작했어요.","처음에는 며칠이 지나도 저금통이 무거워지지 않아 실망스러웠어요.","하지만 서연이는 포기하지 않고 한 달 동안 꾸준히 동전을 모았어요.","어느새 저금통이 묵직해졌고, 동전을 세어보니 만 원이 훌쩍 넘었어요.","엄마는 \"티끌 모아 태산이라더니, 정말 큰 돈이 되었구나!\"라며 활짝 웃으셨어요.","서연이는 스스로 모은 돈으로 필통을 사서 더욱 뿌듯하고 소중하게 느껴졌어요."]'::jsonb, '[{"word":"차곡차곡","meaning":"물건 등을 가지런히 겹치거나 쌓는 모양"},{"word":"묵직하다","meaning":"보기보다 꽤 무겁다"}]'::jsonb, '[{"answer":false,"statement":"서연이는 용돈을 한 번에 다 받았어요."},{"answer":true,"statement":"서연이는 필통을 사고 싶어 했어요."},{"answer":true,"statement":"서연이는 심부름을 해서 용돈을 받았어요."},{"answer":false,"statement":"서연이는 한 달도 안 되어 포기했어요."}]'::jsonb, '{"choices":["작은 돈도 꾸준히 모으면 큰돈이 될 수 있어요","용돈은 다 써버리는 것이 좋아요","원하는 것은 무조건 바로 사야 해요","저금은 힘들기만 하고 소용없어요"],"question":"이 이야기가 주는 교훈은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"차곡차곡","choices":["마구 흩어 놓는 모양","빠르게 뛰어가는 모양","크게 소리 지르는 모양","물건을 가지런히 겹치거나 쌓는 모양"],"answerIndex":3},{"type":"vocab","word":"묵직하다","choices":["아주 가볍다","보기보다 꽤 무겁다","매우 뜨겁다","몹시 차갑다"],"answerIndex":1},{"type":"proverb","word":"티끌 모아 태산","choices":["티끌은 아무리 모아도 소용없다는 뜻이에요","산은 티끌로 이루어졌다는 뜻이에요","작은 것도 꾸준히 모으면 큰 것이 된다는 뜻이에요","돈은 모으지 않는 것이 좋다는 뜻이에요"],"answerIndex":2}]'::jsonb, 4)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('lift-together', '🧹', '함께 들면 가벼워요', '["오늘은 교실 대청소를 하는 날이었어요.","지훈이는 혼자서 무거운 책상을 옮기려고 낑낑댔어요.","책상은 꿈쩍도 하지 않았고, 지훈이의 이마에는 땀이 송골송골 맺혔어요.","지나가던 유나가 그 모습을 보고 \"내가 같이 들어줄게!\"라며 다가왔어요.","둘이 힘을 합치자 무겁던 책상이 거짓말처럼 스르륵 움직였어요.","곧이어 다른 친구들도 하나둘 모여들어 함께 청소를 도왔어요.","순식간에 교실 전체가 반짝반짝 깨끗해졌어요.","선생님은 흐뭇한 얼굴로 \"백지장도 맞들면 낫다는 말이 있지\"라고 말씀하셨어요.","지훈이는 혼자 끙끙대던 아까와 달리 마음이 훨씬 가볍고 즐거웠어요.","함께하니 힘든 일도 금세 끝나고, 웃음까지 더해진다는 것을 깨달았어요."]'::jsonb, '[{"word":"낑낑대다","meaning":"힘든 일을 하느라 애를 쓰며 괴로워하다"},{"word":"송골송골","meaning":"땀이나 물방울이 자잘하게 많이 맺힌 모양"}]'::jsonb, '[{"answer":true,"statement":"오늘은 교실 대청소를 하는 날이었어요."},{"answer":false,"statement":"지훈이는 처음부터 친구들과 함께 책상을 옮겼어요."},{"answer":true,"statement":"유나는 지훈이를 도와주었어요."},{"answer":false,"statement":"친구들이 도와줘도 교실은 깨끗해지지 않았어요."}]'::jsonb, '{"choices":["청소는 혼자 해야 더 빨라요","힘든 일도 함께하면 쉽고 즐거워져요","무거운 물건은 절대 옮기면 안 돼요","친구는 도움이 필요 없어요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"낑낑대다","choices":["힘든 일을 하느라 애를 쓰며 괴로워하다","신이 나서 크게 웃다","아무 걱정 없이 잠을 자다","가볍게 콧노래를 부르다"],"answerIndex":0},{"type":"vocab","word":"송골송골","choices":["눈이 펑펑 내리는 모양","바람이 세차게 부는 모양","불이 활활 타오르는 모양","땀이나 물방울이 자잘하게 많이 맺힌 모양"],"answerIndex":3},{"type":"proverb","word":"백지장도 맞들면 낫다","choices":["종이는 혼자 드는 것이 좋다는 뜻이에요","쉬운 일도 함께 하면 더 수월해진다는 뜻이에요","무거운 것은 절대 들면 안 된다는 뜻이에요","백지장은 아무 쓸모가 없다는 뜻이에요"],"answerIndex":1}]'::jsonb, 5)
