insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('broken-flowerpot', '🪴', '깨진 화분, 숨겨진 마음', '["준서는 쉬는 시간에 친구들과 교실 뒤에서 축구공을 가지고 놀았어요.","\"조심해! 창가 화분 건드리지 마!\" 담임 선생님이 아끼시는 화분이 창가에 놓여 있었거든요.","하지만 준서가 힘차게 찬 공이 화분을 향해 날아갔고, 화분은 그대로 바닥에 떨어져 산산조각이 났어요.","교실 안은 순식간에 조용해졌고, 준서의 심장은 쿵쾅거리기 시작했어요.","마침 선생님은 교무실에 계셨고, 그 자리에 있던 친구들도 많지 않았어요.","준서는 문득 ''아무도 못 봤다고 하면 넘어갈 수 있지 않을까''라는 생각이 스쳤어요.","하지만 짝꿍 다은이의 걱정스러운 눈빛과 마주치자, 마음 한구석이 계속 무거워졌어요.","그날 오후 내내 준서는 수업에 집중하지 못하고 화분 생각만 났어요.","집에 돌아온 준서는 엄마에게 오늘 있었던 일을 조심스럽게 털어놓았어요.","엄마는 \"작은 거짓말이 쌓이면 나중에는 걷잡을 수 없이 커진단다\"라고 다정하게 말씀해 주셨어요.","다음 날 아침, 준서는 떨리는 마음으로 선생님을 찾아가 사실대로 말씀드렸어요.","선생님은 오히려 솔직하게 말해 준 준서를 칭찬하시며, 함께 새 화분을 사러 가자고 하셨어요.","준서는 마음속에 있던 무거운 돌덩이가 사라진 것처럼 홀가분한 기분이 들었어요."]'::jsonb, '[{"word":"산산조각","meaning":"여러 조각으로 잘게 부서진 상태"},{"word":"걷잡을 수 없이","meaning":"마음을 진정하거나 붙잡을 수 없을 정도로"},{"word":"홀가분하다","meaning":"마음에 부담이 없고 가볍다"},{"word":"털어놓다","meaning":"마음속에 있는 이야기를 숨기지 않고 말하다"}]'::jsonb, '[{"answer":true,"statement":"준서는 쉬는 시간에 교실 뒤에서 축구를 하다가 화분을 깨뜨렸어요."},{"answer":false,"statement":"준서는 화분을 깨뜨리자마자 바로 선생님께 사실대로 말씀드렸어요."},{"answer":true,"statement":"준서는 엄마에게 있었던 일을 이야기했어요."},{"answer":false,"statement":"선생님은 준서에게 크게 화를 내며 혼을 냈어요."}]'::jsonb, '{"choices":["잘못을 했을 때는 숨기기보다 솔직하게 말하는 것이 마음을 더 편안하게 해요","화분은 깨지기 쉬우니 조심해서 다뤄야 해요","축구는 교실 안에서 하면 안 되는 위험한 운동이에요","선생님은 학생의 실수를 절대 용서하지 않아요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"산산조각","choices":["아주 크고 튼튼한 상태","여러 조각으로 잘게 부서진 상태","반짝반짝 빛나는 상태","고요하고 잠잠한 상태"],"answerIndex":1},{"type":"vocab","word":"홀가분하다","choices":["몹시 화가 나다","계속 눈물이 난다","마음에 부담이 없고 가볍다","자꾸 졸리다"],"answerIndex":2},{"type":"proverb","word":"바늘 도둑이 소도둑 된다","choices":["바늘과 소는 서로 관계가 없다는 말이에요","도둑은 항상 밤에만 나타난다는 말이에요","작은 물건은 훔쳐도 괜찮다는 말이에요","작은 잘못이라도 그냥 넘기면 점점 더 큰 잘못으로 이어질 수 있다는 말이에요"],"answerIndex":3},{"type":"synonym","word":"털어놓다","choices":["고백하다","숨기다","자랑하다","외면하다"],"answerIndex":0},{"type":"antonym","word":"홀가분하다","choices":["즐겁다","부담스럽다","빠르다","조용하다"],"answerIndex":1}]'::jsonb, 6)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('piano-recital', '🎹', '떨리는 손, 첫 도전', '["하윤이는 이번 학예회에서 처음으로 피아노 독주를 하기로 했어요.","곡은 손가락이 빠르게 움직여야 하는 어려운 곡이라, 처음에는 손가락이 자꾸 꼬였어요.","연습을 시작한 첫째 주, 하윤이는 같은 부분에서 계속 틀려서 속상한 마음이 들었어요.","\"역시 나한테는 너무 어려운 곡인가 봐.\" 하윤이는 포기하고 싶은 마음이 스멀스멀 올라왔어요.","그 모습을 본 피아노 선생님은 \"천 리 길도 한 걸음부터라는 말이 있잖니. 오늘은 딱 두 마디만 완벽하게 쳐 보자\"라고 말씀하셨어요.","하윤이는 선생님의 말씀대로 욕심을 버리고, 매일 조금씩 어려운 부분만 반복해서 연습했어요.","처음에는 두 마디, 다음 날은 네 마디, 그다음 날은 한 줄까지 손가락이 자연스럽게 움직이기 시작했어요.","실수할 때마다 좌절하지 않고, 어제보다 나아진 부분을 찾아 스스로를 칭찬해 주었어요.","학예회 전날 밤, 하윤이는 곡 전체를 실수 없이 연주할 수 있게 되었어요.","드디어 학예회 날, 무대에 오른 하윤이의 손은 여전히 떨렸지만 마음만은 어느 때보다 단단했어요.","연주가 끝나자 강당을 가득 채운 박수 소리가 들려왔어요.","하윤이는 어려운 곡을 포기하지 않고 끝까지 연습한 스스로가 무척 자랑스러웠어요."]'::jsonb, '[{"word":"스멀스멀","meaning":"어떤 생각이나 느낌이 조금씩 슬며시 생겨나는 모양"},{"word":"좌절하다","meaning":"어떤 일을 이루려다가 뜻대로 되지 않아 힘이 꺾이다"},{"word":"단단하다","meaning":"흔들리지 않고 굳세다"}]'::jsonb, '[{"answer":false,"statement":"하윤이는 처음부터 곡 전체를 한 번에 완벽하게 연주했어요."},{"answer":true,"statement":"하윤이는 이번 학예회에서 피아노 독주를 하기로 했어요."},{"answer":false,"statement":"하윤이는 학예회 날 무대에서 전혀 떨지 않았어요."},{"answer":true,"statement":"피아노 선생님은 하윤이에게 어려운 부분을 조금씩 나누어 연습하라고 알려주셨어요."}]'::jsonb, '{"choices":["피아노는 어릴 때부터 배워야 잘 칠 수 있어요","어려운 일도 조금씩 꾸준히 연습하면 결국 이룰 수 있어요","학예회에서는 항상 실수를 하기 마련이에요","선생님의 도움 없이는 어떤 것도 배울 수 없어요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"좌절하다","choices":["기뻐서 크게 웃다","빠르게 달려가다","조용히 잠을 자다","힘이 꺾여 뜻을 이루지 못하다"],"answerIndex":3},{"type":"vocab","word":"단단하다","choices":["흔들리지 않고 굳세다","말랑말랑하고 부드럽다","가볍고 얇다","뜨겁고 매콤하다"],"answerIndex":0},{"type":"proverb","word":"천 리 길도 한 걸음부터","choices":["천 리는 아주 가까운 거리라는 말이에요","아무리 큰일이라도 작은 것부터 차근차근 시작해야 한다는 말이에요","걸음이 빠른 사람이 항상 이긴다는 말이에요","길을 걸을 때는 뒤를 보면 안 된다는 말이에요"],"answerIndex":1},{"type":"synonym","word":"좌절하다","choices":["기뻐하다","자랑하다","낙담하다","안심하다"],"answerIndex":2},{"type":"antonym","word":"단단하다","choices":["무겁다","빠르다","조용하다","약하다"],"answerIndex":3}]'::jsonb, 7)
