insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('reunited-friends', '🤝', '다시 찾은 짝꿍', '["은우와 서아는 1학년 때부터 단짝이었지만, 최근 며칠 동안 서로 말을 하지 않고 있었어요.","지난주 토요일, 서아는 은우와 놀이터에서 만나기로 약속했지만 나타나지 않았어요.","은우는 한 시간 가까이 혼자 기다리다가 화가 나서 집으로 돌아왔어요.","다음 날 학교에서 마주쳤을 때도, 은우는 서아에게 인사조차 하지 않았어요.","서아 역시 은우가 왜 화가 났는지 묻지 않고 그냥 넘어갔고, 둘 사이에는 어색한 침묵만 흘렀어요.","사실 서아는 그날 갑자기 동생이 아파서 병원에 가느라 약속을 지키지 못한 것이었어요.","며칠이 지나도 냉랭한 분위기가 풀리지 않자, 짝꿍인 지호가 조심스럽게 물었어요. \"혹시 무슨 일 있었어?\"","은우는 그제야 자신이 서아의 사정을 물어보지도 않고 오해했다는 것을 깨달았어요.","다음 날 은우는 용기를 내어 서아에게 다가가 먼저 말을 걸었어요. \"그날 무슨 일 있었어? 왜 못 왔는지 궁금했어.\"","서아는 그동안의 사정을 설명했고, 은우는 자신이 서아의 마음도 헤아리지 않고 화부터 냈다는 것을 사과했어요.","\"가는 말이 고와야 오는 말이 곱다더니, 내가 먼저 다정하게 물어봤으면 이렇게 오래 서먹해지지 않았을 텐데.\" 은우가 멋쩍게 웃으며 말했어요.","두 친구는 다시 예전처럼 활짝 웃으며 손을 맞잡았어요."]'::jsonb, '[{"word":"단짝","meaning":"매우 친하여 늘 함께 어울리는 사이"},{"word":"냉랭하다","meaning":"태도가 정답지 않고 차갑다"},{"word":"서먹하다","meaning":"낯설고 어색하다"},{"word":"헤아리다","meaning":"남의 사정을 미루어 생각하다"}]'::jsonb, '[{"answer":true,"statement":"은우와 서아는 오랫동안 친하게 지낸 단짝이었어요."},{"answer":true,"statement":"짝꿍 지호는 두 사람이 어색해진 것을 알아채고 물어봤어요."},{"answer":false,"statement":"서아는 아무 이유 없이 은우와의 약속을 어겼어요."},{"answer":false,"statement":"은우는 끝까지 서아에게 먼저 말을 걸지 않았어요."}]'::jsonb, '{"choices":["약속은 어떤 이유로도 어기면 안 돼요","친구와 다투면 다시는 화해할 수 없어요","화가 나는 일이 있어도 상대방의 사정을 먼저 헤아리고 다정하게 물어보는 것이 중요해요","짝꿍은 항상 문제를 대신 해결해 줘야 해요"],"question":"이 이야기의 중심 생각으로 가장 알맞은 것은 무엇인가요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"헤아리다","choices":["남의 사정을 미루어 생각하다","큰 소리로 야단치다","숫자를 빠르게 세다","멀리 떨어져 지내다"],"answerIndex":0},{"type":"vocab","word":"서먹하다","choices":["매우 친하고 편안하다","낯설고 어색하다","몹시 바쁘다","기운이 넘친다"],"answerIndex":1},{"type":"proverb","word":"가는 말이 고와야 오는 말이 곱다","choices":["말은 빨리 할수록 좋다는 뜻이에요","오고 가는 길이 예뻐야 한다는 뜻이에요","내가 남에게 좋게 말해야 남도 나에게 좋게 말한다는 뜻이에요","말을 하지 않는 것이 가장 안전하다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"냉랭하다","choices":["다정하다","활발하다","분주하다","쌀쌀하다"],"answerIndex":3},{"type":"antonym","word":"헤아리다","choices":["무시하다","이해하다","존중하다","배려하다"],"answerIndex":0}]'::jsonb, 8)
