insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('polluted-stream', '🌊', '우리가 더럽힌 시냇물', '["4학년 2반은 봄맞이 현장체험학습으로 마을 뒷산 아래 흐르는 시냇물을 찾았어요.","예전에는 물이 맑아서 다슬기와 피라미가 헤엄치는 모습이 훤히 보였다고 선생님이 말씀하셨어요.","하지만 아이들이 도착한 시냇물은 뿌옇게 흐려져 있었고, 곳곳에 과자 봉지와 페트병이 떠다니고 있었어요.","\"이게 다 누가 버린 쓰레기일까?\" 지우가 눈살을 찌푸리며 말했어요.","선생님은 근처 공장에서 흘러나온 폐수와 사람들이 함부로 버린 쓰레기가 원인이라고 설명해 주셨어요.","\"우리가 물을 더럽히면, 결국 그 물을 마시고 사는 건 우리 자신이란다.\" 선생님의 말씀에 아이들은 숙연해졌어요.","반 아이들은 그 자리에서 장갑을 끼고 시냇물 주변의 쓰레기를 줍기 시작했어요.","한 시간 동안 주운 쓰레기는 커다란 봉지 세 개를 가득 채울 정도였어요.","쓰레기를 다 치우고 나니, 시냇물이 조금씩 다시 맑아지는 것처럼 느껴졌어요.","교실로 돌아온 아이들은 앞으로 일회용품 사용을 줄이고 쓰레기를 함부로 버리지 않기로 다짐했어요.","지우는 일기장에 이렇게 적었어요. \"누워서 침 뱉기라는 말처럼, 자연을 더럽히는 건 결국 우리에게 돌아오는 일이었다.\"","며칠 뒤, 반 아이들은 학교 게시판에 ''깨끗한 시냇물 지키기'' 캠페인 포스터를 만들어 붙였어요."]'::jsonb, '[{"word":"폐수","meaning":"공장 등에서 쓰고 난 뒤 버리는 더러운 물"},{"word":"눈살을 찌푸리다","meaning":"마음에 들지 않아 얼굴을 찡그리다"},{"word":"숙연해지다","meaning":"분위기가 조용하고 진지해지다"},{"word":"다짐하다","meaning":"마음을 굳게 정하다"}]'::jsonb, '[{"answer":false,"statement":"아이들이 본 시냇물은 예전처럼 아주 맑고 깨끗했어요."},{"answer":false,"statement":"선생님은 물이 더러워진 것과 사람들의 행동은 관련이 없다고 말씀하셨어요."},{"answer":true,"statement":"4학년 2반은 현장체험학습으로 시냇물을 찾아갔어요."},{"answer":true,"statement":"아이들은 시냇물 주변의 쓰레기를 함께 주웠어요."}]'::jsonb, '{"choices":["시냇물에는 원래 다슬기와 피라미가 살지 않아요","현장체험학습은 반드시 뒷산으로 가야 해요","쓰레기를 줍는 일은 어른들만 할 수 있어요","자연을 함부로 더럽히면 결국 그 피해가 우리에게 돌아오므로 환경을 아껴야 해요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"폐수","choices":["맑고 깨끗한 샘물","얼음이 녹은 물","쓰고 난 뒤 버리는 더러운 물","비가 내려 고인 물"],"answerIndex":2},{"type":"vocab","word":"다짐하다","choices":["깜빡 잊어버리다","크게 웃다","자리를 옮기다","마음을 굳게 정하다"],"answerIndex":3},{"type":"proverb","word":"누워서 침 뱉기","choices":["남을 해치려다 결국 자기 자신에게 해가 돌아온다는 말이에요","누워 있을 때는 아무 일도 할 수 없다는 말이에요","침은 뱉을수록 좋다는 말이에요","눕는 자세가 건강에 나쁘다는 말이에요"],"answerIndex":0},{"type":"synonym","word":"숙연해지다","choices":["신나다","진지해지다","시끄러워지다","가벼워지다"],"answerIndex":1},{"type":"antonym","word":"맑다","choices":["깊다","넓다","흐리다","차갑다"],"answerIndex":2}]'::jsonb, 9)
