insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('sipsiilban-fundraiser', '🤲', '십시일반, 마음을 모아', '["같은 반 민재가 갑작스러운 사고로 다리를 다쳐 몇 주째 학교에 나오지 못하고 있었어요.","담임 선생님은 민재의 치료비 부담을 조금이나마 덜어주고 싶다며 학급 회의를 열었어요.","\"우리가 조금씩 마음을 모으면 어떨까?\" 반장 유나가 조심스럽게 제안했어요.","처음에는 \"우리가 도와도 큰 도움이 안 될 것 같아\"라며 망설이는 친구들도 있었어요.","그때 부반장 태민이가 말했어요. \"십시일반이라는 말이 있잖아. 열 사람이 한 술씩 보태면 한 사람 먹을 밥이 된다는 뜻이래.\"","그 말을 들은 아이들은 저마다 용돈을 조금씩 모으거나, 안 쓰는 학용품을 팔아 돈을 보태기로 했어요.","어떤 친구는 그림을 그려 나눠 주고 마음을 담은 응원 카드를 받기로 했고, 어떤 친구는 집안일을 도와 용돈을 벌었어요.","일주일 뒤, 반 아이들이 모은 돈은 생각보다 훨씬 큰 금액이 되어 있었어요.","반 친구들은 모은 돈과 함께 정성 들여 쓴 편지를 모아 민재에게 전달했어요.","병문안을 간 날, 민재는 편지를 읽으며 눈시울이 붉어졌어요.","\"다들 이렇게까지 생각해 줄 줄 몰랐어. 정말 고마워.\" 민재가 떨리는 목소리로 말했어요.","유나는 작은 정성도 여럿이 모이면 큰 힘이 된다는 것을 이번 일을 통해 깊이 깨달았어요.","반 아이들은 민재가 얼른 나아서 다시 함께 뛰어놀 날을 손꼽아 기다렸어요."]'::jsonb, '[{"word":"십시일반","meaning":"여러 사람이 조금씩 힘을 보태면 한 사람을 돕기 충분하다는 뜻"},{"word":"망설이다","meaning":"이리저리 생각만 하고 결정을 내리지 못하다"},{"word":"정성","meaning":"온갖 힘을 다하려는 참되고 성실한 마음"},{"word":"눈시울이 붉어지다","meaning":"감동하거나 슬퍼서 눈물이 나려고 하다"}]'::jsonb, '[{"answer":false,"statement":"반 아이들은 처음부터 모두 적극적으로 돈을 모으자고 했어요."},{"answer":true,"statement":"민재는 사고로 다쳐서 학교에 나오지 못하고 있었어요."},{"answer":true,"statement":"아이들은 용돈을 모으거나 물건을 팔아 돈을 마련했어요."},{"answer":false,"statement":"민재는 친구들의 편지와 마음을 받고도 별다른 감정을 느끼지 않았어요."}]'::jsonb, '{"choices":["힘든 친구를 도울 때는 돈이 가장 중요해요","작은 정성이라도 여럿이 함께 모으면 누군가에게 큰 힘이 될 수 있어요","다친 친구는 혼자 이겨내야 더 빨리 나아요","반장과 부반장만 학급 일을 결정할 수 있어요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"정성","choices":["아무 관심이 없는 태도","온갖 힘을 다하려는 참되고 성실한 마음","화가 나서 다투는 마음","급하게 서두르는 태도"],"answerIndex":1},{"type":"vocab","word":"망설이다","choices":["결정을 내리지 못하고 머뭇거리다","단번에 결정하다","크게 소리치다","깊이 잠들다"],"answerIndex":0},{"type":"proverb","word":"십시일반","choices":["혼자 힘으로 모든 것을 해내야 한다는 말이에요","밥은 열 번에 나누어 먹어야 한다는 말이에요","남의 도움은 받지 않는 것이 좋다는 말이에요","여러 사람이 조금씩 힘을 모으면 한 사람에게 큰 도움이 될 수 있다는 말이에요"],"answerIndex":3},{"type":"synonym","word":"정성","choices":["무관심","불평","진심","의심"],"answerIndex":2},{"type":"antonym","word":"망설이다","choices":["머뭇거리다","결단하다","고민하다","주저하다"],"answerIndex":1}]'::jsonb, 10)
