insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('stage-fright', '🎤', '처음 올라간 무대', '["이번 학기 학급 회장 선거에 나가기로 한 도현이는 연설문을 밤새 준비했어요.","하지만 막상 연단에 서야 한다고 생각하니 심장이 쿵쾅거리고 손바닥에 땀이 났어요.","\"떨려서 목소리가 떨리면 어떡하지? 다들 비웃으면 어떡하지?\" 도현이의 머릿속은 걱정으로 가득 찼어요.","발표 전날 밤, 도현이는 이불 속에서 그만 포기하고 싶다는 생각까지 들었어요.","그 모습을 본 누나는 \"일단 첫 문장만 자신 있게 말해봐. 시작이 반이라잖아\"라고 다독여 주었어요.","다음 날 아침, 도현이는 거울 앞에서 첫 문장만이라도 크게 연습해 보았어요.","드디어 순서가 되어 연단에 오른 도현이의 다리는 후들거렸지만, 용기를 내어 첫마디를 뗐어요.","신기하게도 첫 문장을 말하고 나자 그다음 말은 생각보다 술술 이어졌어요.","도현이는 준비한 이야기를 끝까지 또박또박 마칠 수 있었어요.","연설이 끝나자 친구들의 박수 소리가 강당을 가득 채웠어요.","도현이는 결과와 상관없이 끝까지 해냈다는 사실만으로도 마음이 벅찼어요.","그날 이후 도현이는 어려운 일이 생길 때마다 ''일단 시작해보자''라고 스스로에게 말하게 되었어요."]'::jsonb, '[{"word":"다독이다","meaning":"남을 격려하고 위로하다"},{"word":"후들거리다","meaning":"몸이나 다리가 힘없이 자꾸 떨리다"},{"word":"벅차다","meaning":"감격스럽거나 기쁨이 넘칠 듯하다"}]'::jsonb, '[{"answer":true,"statement":"도현이는 학급 회장 선거에 나가기로 했어요."},{"answer":false,"statement":"도현이는 연설 전날 전혀 떨지 않았어요."},{"answer":true,"statement":"누나는 도현이에게 첫 문장만 자신 있게 말해보라고 했어요."},{"answer":false,"statement":"도현이는 결국 연단에 오르지 못했어요."}]'::jsonb, '{"choices":["두려운 일도 일단 용기를 내어 시작하면 해낼 수 있어요","연설은 누구에게나 쉬운 일이에요","회장 선거에서는 항상 이겨야 해요","가족의 도움 없이는 아무것도 할 수 없어요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"다독이다","choices":["심하게 꾸짖다","크게 웃다","남을 격려하고 위로하다","모르는 척하다"],"answerIndex":2},{"type":"vocab","word":"후들거리다","choices":["몸이나 다리가 힘없이 자꾸 떨리다","힘차고 씩씩하게 걷다","가만히 멈춰 서다","기운차게 뛰어오르다"],"answerIndex":0},{"type":"proverb","word":"시작이 반이다","choices":["일은 시작한 뒤에 계획을 세워야 한다는 말이에요","반만 하고 그만두어도 괜찮다는 말이에요","시작하는 사람은 항상 실패한다는 말이에요","어떤 일이든 시작하는 것 자체가 이미 절반을 이룬 것이나 다름없다는 말이에요"],"answerIndex":3},{"type":"synonym","word":"벅차다","choices":["지루하다","감격스럽다","심심하다","불안하다"],"answerIndex":1},{"type":"antonym","word":"후들거리다","choices":["든든하다","시끄럽다","가볍다","날카롭다"],"answerIndex":0}]'::jsonb, 11)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('giving-up-seat', '🚌', '버스 안에서 배운 마음', '["학원을 마치고 집에 가는 버스 안, 지안이는 창가 자리에 앉아 휴대폰 게임을 하고 있었어요.","다음 정류장에서 허리가 굽은 할머니 한 분이 무거운 짐을 들고 버스에 올라탔어요.","버스 안에는 빈자리가 없었고, 할머니는 손잡이를 잡은 채 힘겹게 서 계셨어요.","지안이는 자리를 양보해야 하나 잠깐 고민했지만, 게임에 정신이 팔려 못 본 척 넘어갔어요.","버스가 흔들릴 때마다 할머니는 짐을 안은 채 휘청거리셨어요.","그 모습을 본 옆자리 아저씨가 얼른 일어나 \"여기 앉으세요\" 하며 자리를 양보했어요.","할머니는 환하게 웃으며 \"고마워요, 학생\"이라고 인사하셨고, 아저씨도 흐뭇하게 웃으셨어요.","지안이는 그 모습을 보며 괜히 마음이 무거워졌어요.","''내가 먼저 양보할 수 있었는데, 나는 왜 내 생각만 했을까.'' 지안이는 스스로가 부끄러워졌어요.","집에 돌아온 지안이는 엄마에게 오늘 있었던 일을 이야기했어요.","엄마는 \"역지사지라는 말이 있잖아. 다음에는 그 할머니 입장이 되어 생각해 보렴\"이라고 말씀하셨어요.","다음 날부터 지안이는 버스를 탈 때마다 주위를 먼저 살피는 습관이 생겼어요.","며칠 뒤, 지안이는 다리가 불편해 보이는 아저씨께 망설임 없이 자리를 양보할 수 있었어요."]'::jsonb, '[{"word":"휘청거리다","meaning":"몸이 이리저리 흔들리며 넘어질 듯하다"},{"word":"흐뭇하다","meaning":"마음에 들어 매우 만족스럽고 좋다"},{"word":"역지사지","meaning":"다른 사람의 처지에서 생각해 본다는 뜻"}]'::jsonb, '[{"answer":false,"statement":"지안이는 처음부터 할머니께 자리를 양보했어요."},{"answer":true,"statement":"아저씨가 할머니께 자리를 양보했어요."},{"answer":false,"statement":"지안이는 자신의 행동을 전혀 부끄러워하지 않았어요."},{"answer":true,"statement":"지안이는 다음 날부터 주위를 먼저 살피게 되었어요."}]'::jsonb, '{"choices":["버스에서는 항상 창가 자리에 앉아야 해요","다른 사람의 입장에서 생각하면 먼저 배려하는 마음을 가질 수 있어요","짐이 많은 사람은 버스를 타면 안 돼요","양보는 어른들만 할 수 있는 행동이에요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"휘청거리다","choices":["몸이 이리저리 흔들리며 넘어질 듯하다","꼿꼿하게 잘 서 있다","가만히 앉아 있다","빠르게 달려 나가다"],"answerIndex":0},{"type":"vocab","word":"흐뭇하다","choices":["화가 나서 속상하다","몹시 지루하다","깜짝 놀라다","마음에 들어 매우 만족스럽고 좋다"],"answerIndex":3},{"type":"proverb","word":"역지사지","choices":["항상 자기 생각만 옳다고 여긴다는 뜻이에요","다른 사람의 처지에서 생각해 본다는 뜻이에요","땅의 위치를 바꾼다는 뜻이에요","다른 사람을 절대 도와주지 않는다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"흐뭇하다","choices":["서운하다","불편하다","흡족하다","조급하다"],"answerIndex":2},{"type":"antonym","word":"휘청거리다","choices":["부드럽다","조용하다","느긋하다","꼿꼿하다"],"answerIndex":3}]'::jsonb, 12)
