insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('humble-rice', '🌾', '고개 숙인 벼처럼', '["수학을 유난히 잘하는 재윤이는 반에서 어려운 문제를 가장 먼저 푸는 것으로 유명했어요.","친구들이 문제를 몰라 물어보면, 재윤이는 종종 \"이렇게 쉬운 걸 몰라?\"라며 으스대곤 했어요.","처음에는 재윤이의 실력을 부러워하던 친구들도 점점 재윤이 곁에 다가가기를 꺼리게 되었어요.","어느 날 전국 수학 경시대회가 열렸고, 재윤이는 자신만만하게 시험장에 들어갔어요.","하지만 시험 문제는 재윤이가 한 번도 본 적 없는 유형이었고, 절반도 풀지 못한 채 시험이 끝나 버렸어요.","결과가 발표된 날, 재윤이보다 평소 조용했던 짝꿍 은서가 훨씬 좋은 성적을 받았다는 사실에 재윤이는 큰 충격을 받았어요.","속상한 마음에 고개를 숙이고 있는 재윤이에게 은서가 다가와 어려웠던 문제의 풀이법을 다정하게 알려주었어요.","재윤이는 자신이 늘 잘난 척하며 친구들을 무시했던 것이 부끄러워졌어요.","담임 선생님은 \"벼는 익을수록 고개를 숙인다는 말이 있단다. 실력이 있을수록 겸손해야 더 존경받는 법이야\"라고 말씀해 주셨어요.","그날 이후 재윤이는 친구가 질문할 때마다 예전과 다른 태도로 차근차근 설명해 주기 시작했어요.","시간이 지나자 재윤이 곁에는 다시 하나둘 친구들이 모여들기 시작했어요.","재윤이는 실력보다 중요한 것이 겸손한 마음이라는 것을 깊이 깨달았어요."]'::jsonb, '[{"word":"으스대다","meaning":"잘난 척하며 뽐내다"},{"word":"자신만만하다","meaning":"매우 자신이 있다"},{"word":"겸손하다","meaning":"남을 존중하고 자신을 내세우지 않는 태도가 있다"}]'::jsonb, '[{"answer":true,"statement":"재윤이는 평소 수학을 잘한다고 잘난 척했어요."},{"answer":true,"statement":"은서는 경시대회에서 재윤이보다 좋은 성적을 받았어요."},{"answer":false,"statement":"재윤이는 경시대회 문제를 모두 완벽하게 풀었어요."},{"answer":false,"statement":"재윤이는 끝까지 태도를 바꾸지 않았어요."}]'::jsonb, '{"choices":["수학을 잘하는 사람은 항상 겸손할 필요가 없어요","경시대회는 참가하지 않는 것이 좋아요","실력이 뛰어날수록 겸손한 태도를 가져야 진정으로 인정받을 수 있어요","친구의 도움은 받지 않는 것이 자랑스러운 일이에요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"으스대다","choices":["조용히 숨어 지내다","남을 걱정하다","크게 슬퍼하다","잘난 척하며 뽐내다"],"answerIndex":3},{"type":"vocab","word":"자신만만하다","choices":["몹시 불안하고 초조하다","매우 자신이 있다","아무 관심이 없다","깊이 잠들다"],"answerIndex":1},{"type":"proverb","word":"벼는 익을수록 고개를 숙인다","choices":["실력이나 지식이 많을수록 더 겸손해져야 한다는 말이에요","벼는 익으면 무거워서 저절로 쓰러진다는 말이에요","고개를 숙이면 벼가 더 빨리 익는다는 말이에요","벼농사는 매우 힘든 일이라는 말이에요"],"answerIndex":0},{"type":"synonym","word":"겸손하다","choices":["거만하다","무례하다","공손하다","냉정하다"],"answerIndex":2},{"type":"antonym","word":"자신만만하다","choices":["즐겁다","자신없다","조용하다","다정하다"],"answerIndex":1}]'::jsonb, 13)
