insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('learning-bike', '🚲', '몇 번이고 다시 일어나', '["여름 방학이 시작되자 시우는 두발자전거 타는 법을 배우기로 마음먹었어요.","아빠가 뒤에서 자전거를 잡아 주었지만, 페달을 밟자마자 시우는 옆으로 쿵 넘어지고 말았어요.","무릎이 까져 따끔거렸지만, 시우는 이를 악물고 다시 자전거에 올라탔어요.","두 번째, 세 번째 시도에서도 시우는 균형을 잡지 못하고 계속 넘어졌어요.","\"나는 자전거랑 안 맞나 봐.\" 시우는 속상한 마음에 자전거를 팽개치고 싶어졌어요.","아빠는 \"열 번 찍어 안 넘어가는 나무 없다잖아. 열 번만 더 해보자\"라며 시우를 다독였어요.","시우는 다시 마음을 다잡고 페달을 밟았고, 이번에는 조금 더 오래 균형을 유지했어요.","넘어질 때마다 시우는 무엇이 잘못되었는지 곰곰이 생각하며 자세를 바로잡았어요.","열 번째 시도에서 마침내 시우는 아빠의 도움 없이 몇 미터를 혼자 달릴 수 있었어요.","처음으로 두 바퀴로 균형을 잡고 달리는 순간, 시우는 바람을 가르는 상쾌함을 느꼈어요.","그날 저녁, 시우는 무릎의 상처를 보면서도 웃음이 절로 났어요.","시우는 포기하지 않고 계속 도전한 끝에 결국 해냈다는 사실이 무엇보다 자랑스러웠어요."]'::jsonb, '[{"word":"팽개치다","meaning":"하던 일이나 물건을 내던지고 그만두다"},{"word":"다잡다","meaning":"마음이나 정신을 다시 가다듬어 바로잡다"},{"word":"곰곰이","meaning":"여러모로 깊이 생각하는 모양"}]'::jsonb, '[{"answer":false,"statement":"시우는 처음 시도에서 바로 자전거를 잘 탔어요."},{"answer":false,"statement":"시우는 한 번 넘어진 뒤 다시는 도전하지 않았어요."},{"answer":true,"statement":"아빠는 시우에게 열 번만 더 해보자고 격려했어요."},{"answer":true,"statement":"시우는 결국 혼자 힘으로 자전거를 탈 수 있게 되었어요."}]'::jsonb, '{"choices":["자전거는 어른이 도와줘야만 탈 수 있어요","한 번 넘어지면 다시 시도하지 않는 것이 좋아요","무릎을 다치지 않는 것이 가장 중요해요","실패해도 포기하지 않고 계속 도전하면 결국 해낼 수 있어요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"팽개치다","choices":["소중히 아끼고 보살피다","하던 일이나 물건을 내던지고 그만두다","차근차근 정리하다","기쁘게 받아들이다"],"answerIndex":1},{"type":"vocab","word":"다잡다","choices":["마음을 완전히 놓아 버리다","깊이 잠들다","마음이나 정신을 다시 가다듬어 바로잡다","크게 소리를 지르다"],"answerIndex":2},{"type":"proverb","word":"열 번 찍어 안 넘어가는 나무 없다","choices":["나무는 열 번 찍으면 반드시 넘어진다는 말이에요","한 번의 실수도 용서받을 수 없다는 말이에요","나무를 함부로 베면 안 된다는 말이에요","아무리 어려운 일이라도 여러 번 꾸준히 노력하면 결국 이루어진다는 말이에요"],"answerIndex":3},{"type":"synonym","word":"곰곰이","choices":["깊이","대충","재빨리","시끄럽게"],"answerIndex":0},{"type":"antonym","word":"다잡다","choices":["움켜쥐다","가다듬다","놓아버리다","붙잡다"],"answerIndex":2}]'::jsonb, 14)
