insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('class-hamster', '🐹', '꼬물이를 부탁해', '["3학년 1반 교실에는 ''꼬물이''라는 이름의 햄스터가 살고 있었어요.","담임 선생님은 이번 주 당번인 현우에게 꼬물이의 먹이와 물을 챙겨 달라고 부탁하셨어요.","월요일, 현우는 꼬물이에게 신선한 먹이와 깨끗한 물을 정성껏 챙겨 주었어요.","하지만 화요일부터 현우는 축구를 하느라 바빠서 꼬물이를 깜빡 잊어버리고 말았어요.","수요일 아침, 꼬물이의 물통이 텅 비어 있는 것을 본 짝꿍 서윤이가 걱정스러운 표정을 지었어요.","\"현우야, 꼬물이 물이 다 떨어졌어. 어제도 안 챙겨준 거야?\" 서윤이의 말에 현우는 뜨끔했어요.","현우는 \"내일 해도 되겠지\"라고 생각했던 자신이 부끄러워졌어요.","담임 선생님은 \"쇠뿔도 단김에 빼라는 말이 있단다. 해야 할 일은 미루지 않고 바로 하는 습관이 중요해\"라고 말씀하셨어요.","그 말을 들은 현우는 바로 자리에서 일어나 꼬물이에게 물과 먹이를 채워 주었어요.","꼬물이가 다시 물을 벌컥벌컥 마시는 모습을 보자 현우는 마음이 놓였어요.","그날 이후 현우는 매일 아침 등교하자마자 가장 먼저 꼬물이부터 살피는 습관을 들였어요.","당번이 끝난 뒤에도 현우는 종종 꼬물이의 안부를 살피러 갔어요."]'::jsonb, '[{"word":"뜨끔하다","meaning":"마음속으로 자극을 받아 따끔한 느낌이 들다"},{"word":"미루다","meaning":"정한 시간을 뒤로 늦추다"},{"word":"살피다","meaning":"두루두루 주의하여 자세히 보다"}]'::jsonb, '[{"answer":false,"statement":"현우는 매일 빠짐없이 꼬물이를 잘 돌보았어요."},{"answer":true,"statement":"서윤이는 꼬물이의 물통이 빈 것을 알아챘어요."},{"answer":true,"statement":"선생님은 현우에게 미루지 말고 바로 해야 한다고 말씀하셨어요."},{"answer":false,"statement":"현우는 그 뒤로도 계속 꼬물이를 잊어버렸어요."}]'::jsonb, '{"choices":["동물을 키우는 것은 어른들만 할 수 있는 일이에요","해야 할 일을 미루지 않고 바로 하는 책임감이 중요해요","당번이 끝나면 더 이상 신경 쓰지 않아도 돼요","친구가 알려주기 전까지는 몰라도 괜찮아요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"뜨끔하다","choices":["마음속으로 자극을 받아 따끔한 느낌이 들다","아주 편안하고 느긋하다","기운이 없어 축 처지다","너무 기뻐 어쩔 줄 모르다"],"answerIndex":0},{"type":"vocab","word":"미루다","choices":["바로 그 자리에서 해결하다","깨끗하게 정리하다","다른 사람에게 알려주다","정한 시간을 뒤로 늦추다"],"answerIndex":3},{"type":"proverb","word":"쇠뿔도 단김에 빼라","choices":["쇠뿔은 원래 뺄 수 없는 것이라는 말이에요","급하게 하는 일은 항상 실패한다는 말이에요","어떤 일이든 하려고 마음먹었을 때 바로 해야 한다는 말이에요","동물을 함부로 다루면 안 된다는 말이에요"],"answerIndex":2},{"type":"synonym","word":"살피다","choices":["무시하다","관찰하다","방해하다","숨기다"],"answerIndex":1},{"type":"antonym","word":"미루다","choices":["기다리다","생각하다","계획하다","바로 하다"],"answerIndex":3}]'::jsonb, 15)
