insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('exam-temptation', '📝', '옆자리 시험지', '["단원 평가 시험 시간, 유진이는 마지막 문제에서 도무지 답이 떠오르지 않았어요.","힐끗 옆을 보니 짝꿍 도윤이의 시험지에 답이 훤히 보였어요.","''한 문제만 슬쩍 보면 아무도 모르지 않을까.'' 유진이의 마음속에서 유혹이 스멀스멀 피어올랐어요.","하지만 지난주 도윤이의 답이 더 커 보인다고 부러워했던 자신의 모습이 떠올랐어요.","유진이는 손에 힘을 꽉 주고 다시 자기 시험지로 눈을 돌렸어요.","결국 그 문제는 끝까지 풀지 못한 채 시험지를 제출하게 되었어요.","시험이 끝난 뒤, 유진이는 마음 한편이 답답했지만 동시에 이상하게 떳떳한 기분도 들었어요.","집에 돌아온 유진이는 아빠에게 오늘 있었던 일을 솔직하게 털어놓았어요.","아빠는 \"남의 떡이 커 보인다는 말이 있지. 하지만 스스로 얻은 작은 성취가 훨씬 값진 거란다\"라고 말씀해 주셨어요.","며칠 뒤 시험 결과가 나왔을 때, 유진이의 점수는 도윤이보다 낮았지만 마음만은 부끄럽지 않았어요.","유진이는 다음 시험을 위해 그 문제를 다시 찾아보고 완전히 이해할 때까지 연습했어요.","유진이는 결과보다 스스로에게 떳떳한 것이 더 중요하다는 것을 깨달았어요."]'::jsonb, '[{"word":"유혹","meaning":"어떤 일을 하도록 마음을 흔들리게 하는 것"},{"word":"떳떳하다","meaning":"굽힐 것이 없이 당당하다"},{"word":"값지다","meaning":"가치가 있고 중요하다"}]'::jsonb, '[{"answer":true,"statement":"유진이는 마지막 문제의 답이 떠오르지 않았어요."},{"answer":false,"statement":"유진이는 결국 짝꿍의 답을 몰래 보고 베꼈어요."},{"answer":false,"statement":"유진이는 시험이 끝난 뒤 마음이 매우 불편하고 부끄러웠어요."},{"answer":true,"statement":"유진이는 시험 뒤에 그 문제를 다시 공부했어요."}]'::jsonb, '{"choices":["잠깐의 유혹에 흔들리지 않고 정직하게 행동하는 것이 더 값진 결과를 만들어요","시험 점수는 무엇보다 가장 중요한 것이에요","모르는 문제는 옆 사람의 답을 참고해도 괜찮아요","한 번의 실수는 절대 만회할 수 없어요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"유혹","choices":["아무 감정도 없는 상태","크게 화가 나는 것","어떤 일을 하도록 마음을 흔들리게 하는 것","깊이 잠드는 것"],"answerIndex":2},{"type":"vocab","word":"떳떳하다","choices":["굽힐 것이 없이 당당하다","몹시 부끄럽고 창피하다","조용하고 소극적이다","지치고 피곤하다"],"answerIndex":0},{"type":"proverb","word":"남의 떡이 커 보인다","choices":["떡은 남과 나누어 먹어야 맛있다는 말이에요","자기 것보다 남의 것이 더 좋아 보인다는 말이에요","남의 물건은 절대 만지면 안 된다는 말이에요","떡을 만드는 것은 어려운 일이라는 말이에요"],"answerIndex":1},{"type":"synonym","word":"값지다","choices":["하찮다","가볍다","흔하다","소중하다"],"answerIndex":3},{"type":"antonym","word":"떳떳하다","choices":["부끄럽다","즐겁다","조용하다","느긋하다"],"answerIndex":0}]'::jsonb, 16)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('sibling-chocolate', '🍫', '동생과 나눈 마지막 초콜릿', '["지호는 생일 선물로 받은 초콜릿 상자를 아껴 먹으며 조금씩 즐기고 있었어요.","어느 날 학교에서 돌아와 보니 상자 안 초콜릿이 절반이나 사라져 있었어요.","\"누나가 먹었지? 왜 물어보지도 않고 마음대로 먹어!\" 지호는 화가 나서 누나 수아에게 소리쳤어요.","수아는 \"몇 개만 먹은 거야, 왜 이렇게 화를 내\"라며 억울한 표정을 지었어요.","둘은 서로 잘못했다며 언성을 높이다가 결국 크게 다투고 말았어요.","그날 저녁, 두 사람은 서로 말 한마디 하지 않고 각자 방으로 들어가 버렸어요.","엄마는 두 사람을 불러 앉히고 조용히 이야기를 들어보셨어요.","알고 보니 수아는 지호가 시험을 잘 봤다는 소식을 듣고 축하하는 마음으로 초콜릿을 몇 개 꺼내 먹었던 것이었어요.","사정을 들은 지호는 자신이 오해로 화부터 냈다는 것을 깨닫고 미안해졌어요.","\"피는 물보다 진하다더니, 우리가 이렇게 다툴 일이 아니었나 봐.\" 지호가 멋쩍게 웃으며 말했어요.","지호는 남은 초콜릿을 수아와 나누어 먹으며 화해의 인사를 건넸어요.","두 사람은 다시 예전처럼 다정한 남매로 돌아왔어요."]'::jsonb, '[{"word":"언성을 높이다","meaning":"화가 나서 목소리를 크게 내다"},{"word":"오해","meaning":"어떤 일이나 말을 잘못 이해하는 것"},{"word":"멋쩍다","meaning":"어색하고 쑥스럽다"}]'::jsonb, '[{"answer":true,"statement":"지호의 초콜릿 상자에서 초콜릿이 절반이나 사라져 있었어요."},{"answer":false,"statement":"수아는 지호에게 미리 물어보고 초콜릿을 먹었어요."},{"answer":true,"statement":"수아는 지호가 시험을 잘 본 것을 축하하려고 초콜릿을 먹었어요."},{"answer":false,"statement":"지호와 수아는 끝까지 화해하지 못했어요."}]'::jsonb, '{"choices":["형제자매와는 물건을 절대 함께 쓰면 안 돼요","화가 날 때는 큰 소리로 표현하는 것이 가장 좋아요","선물은 혼자서만 사용해야 해요","오해가 생겼을 때는 화부터 내기보다 사정을 들어보는 것이 중요해요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"언성을 높이다","choices":["작은 소리로 속삭이다","조용히 미소를 짓다","가만히 눈을 감다","화가 나서 목소리를 크게 내다"],"answerIndex":3},{"type":"vocab","word":"오해","choices":["아주 정확하게 이해하는 것","어떤 일이나 말을 잘못 이해하는 것","기쁘게 축하하는 것","함께 힘을 모으는 것"],"answerIndex":1},{"type":"proverb","word":"피는 물보다 진하다","choices":["피는 물에 잘 섞이지 않는다는 말이에요","가족끼리는 절대 다투지 않는다는 말이에요","가족 사이의 정은 다른 무엇보다 깊고 강하다는 말이에요","물은 피보다 소중하다는 말이에요"],"answerIndex":2},{"type":"synonym","word":"멋쩍다","choices":["쑥스럽다","당당하다","즐겁다","편안하다"],"answerIndex":0},{"type":"antonym","word":"오해","choices":["소문","이해","다툼","걱정"],"answerIndex":1}]'::jsonb, 17)
