insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('jump-rope-contest', '🪢', '줄넘기 백 개의 비밀', '["다음 달 체육 대회에서는 반별 줄넘기 백 개 이어 뛰기 시합이 열릴 예정이었어요.","나연이는 줄넘기를 시작한 지 얼마 안 되어 열 개도 채 넘기지 못하고 자꾸 걸렸어요.","반 대표로 뽑힌 나연이는 시합 날짜가 다가올수록 부담감에 잠도 잘 오지 않았어요.","\"괜히 내가 대표를 한다고 했나 봐.\" 나연이는 자신 없는 마음에 몇 번이고 그만두고 싶었어요.","체육 선생님은 나연이에게 \"열 번 찍어 안 넘어가는 나무 없다잖니. 매일 조금씩만 늘려보자\"라고 격려해 주셨어요.","나연이는 그날부터 매일 아침 학교 가기 전 십 분씩 줄넘기를 연습하기 시작했어요.","처음 며칠은 여전히 자주 걸렸지만, 실수할 때마다 원인을 살펴보며 자세를 고쳐 나갔어요.","이 주가 지나자 나연이는 서른 개, 그다음 주에는 쉰 개까지 연속으로 넘길 수 있게 되었어요.","체육 대회 전날, 나연이는 마침내 백 개를 한 번도 걸리지 않고 넘기는 데 성공했어요.","대회 당일, 긴장한 나연이는 반 친구들의 응원 속에서 힘차게 줄을 돌렸어요.","나연이는 끝까지 집중하며 목표했던 개수를 무사히 채워 냈어요.","시합이 끝난 뒤 친구들은 나연이에게 몰려와 뜨거운 박수를 보내 주었어요.","나연이는 매일의 작은 연습이 모여 큰 성과를 만든다는 것을 몸소 깨달았어요."]'::jsonb, '[{"word":"부담감","meaning":"어떤 일을 해야 한다는 무거운 마음"},{"word":"몰려오다","meaning":"여러 사람이 한꺼번에 밀려오다"},{"word":"몸소","meaning":"직접 자기 몸으로"}]'::jsonb, '[{"answer":false,"statement":"나연이는 처음부터 줄넘기를 아주 잘했어요."},{"answer":true,"statement":"나연이는 반 대표로 줄넘기 시합에 나가게 되었어요."},{"answer":false,"statement":"나연이는 연습을 시작한 첫날 바로 백 개를 넘겼어요."},{"answer":true,"statement":"나연이는 매일 아침 꾸준히 줄넘기를 연습했어요."}]'::jsonb, '{"choices":["줄넘기는 원래 재능이 있는 사람만 잘할 수 있어요","체육 대회는 참가하지 않는 것이 마음이 편해요","매일 꾸준히 연습하면 작은 실력도 큰 성과로 이어질 수 있어요","실수를 하면 바로 포기하는 것이 좋아요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"부담감","choices":["아무 걱정이 없는 편안한 마음","어떤 일을 해야 한다는 무거운 마음","즐겁고 신나는 마음","몹시 지루한 마음"],"answerIndex":1},{"type":"vocab","word":"몰려오다","choices":["한 명씩 조용히 사라지다","천천히 걸어 나가다","가만히 자리를 지키다","여러 사람이 한꺼번에 밀려오다"],"answerIndex":3},{"type":"proverb","word":"열 번 찍어 안 넘어가는 나무 없다","choices":["꾸준히 여러 번 노력하면 결국 뜻한 바를 이룰 수 있다는 말이에요","나무는 한 번만 찍어도 쉽게 넘어간다는 말이에요","힘든 일은 아예 시작하지 않는 것이 낫다는 말이에요","나무를 베는 일은 위험하다는 말이에요"],"answerIndex":0},{"type":"synonym","word":"부담감","choices":["안도감","즐거움","압박감","자신감"],"answerIndex":2},{"type":"antonym","word":"몰려오다","choices":["모이다","다가오다","쌓이다","흩어지다"],"answerIndex":3}]'::jsonb, 18)
