insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('daily-reading', '📚', '매일 열 페이지의 힘', '["하람이는 책 읽기를 그다지 좋아하지 않아서 한 권을 다 읽는 데도 오랜 시간이 걸렸어요.","담임 선생님은 반 아이들에게 \"매일 딱 열 페이지씩만 읽어보자\"라는 작은 목표를 내주셨어요.","하람이는 ''겨우 열 페이지쯤이야''라는 생각으로 별다른 기대 없이 시작했어요.","처음 며칠은 열 페이지를 읽는 것도 지루하고 힘들게만 느껴졌어요.","하지만 매일 같은 시간에 책을 펼치다 보니, 어느새 습관처럼 자연스러워졌어요.","한 달이 지나자 하람이는 자신도 모르는 사이에 책 두 권을 다 읽어냈다는 것을 깨달았어요.","\"가랑비에 옷 젖는 줄 모른다더니, 매일 조금씩 읽은 게 이렇게 쌓였구나.\" 하람이는 스스로도 놀랐어요.","책을 많이 읽다 보니 하람이는 몰랐던 낱말의 뜻도 자연스럽게 많이 알게 되었어요.","국어 시간에 발표할 때도 예전보다 훨씬 다양한 표현을 사용할 수 있게 되었어요.","친구들은 하람이가 어느새 책을 술술 읽어 나가는 모습을 보고 깜짝 놀랐어요.","하람이는 이제 열 페이지라는 목표를 넘어 스스로 더 읽고 싶은 책을 찾아 나서게 되었어요.","작은 습관 하나가 하람이의 하루를 완전히 바꾸어 놓은 것이었어요."]'::jsonb, '[{"word":"습관","meaning":"오랫동안 되풀이하여 몸에 익은 행동"},{"word":"자연스럽다","meaning":"억지로 꾸미지 않아 편안하고 어색하지 않다"},{"word":"놀랍다","meaning":"뜻밖의 일로 정신이 번쩍 들 만큼 이상하거나 신기하다"}]'::jsonb, '[{"answer":true,"statement":"하람이는 처음에는 책 읽기를 그다지 좋아하지 않았어요."},{"answer":true,"statement":"선생님은 매일 열 페이지씩 읽자는 목표를 내주셨어요."},{"answer":false,"statement":"하람이는 첫날부터 책 읽기가 아주 재미있었어요."},{"answer":false,"statement":"한 달이 지나도 하람이의 독서 습관은 전혀 달라지지 않았어요."}]'::jsonb, '{"choices":["책은 두꺼운 책부터 읽어야 실력이 늘어요","작은 습관도 꾸준히 이어가면 어느새 큰 변화를 만들어 낼 수 있어요","독서는 재미있는 사람만 할 수 있는 취미예요","목표는 항상 크게 세워야 의미가 있어요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"습관","choices":["오랫동안 되풀이하여 몸에 익은 행동","한 번도 해본 적 없는 낯선 행동","우연히 딱 한 번 일어난 일","다른 사람이 대신 해 주는 일"],"answerIndex":0},{"type":"vocab","word":"자연스럽다","choices":["매우 딱딱하고 불편하다","몹시 화려하고 요란하다","억지로 꾸미지 않아 편안하고 어색하지 않다","급하고 정신없다"],"answerIndex":2},{"type":"proverb","word":"가랑비에 옷 젖는 줄 모른다","choices":["비가 올 때는 꼭 우산을 챙겨야 한다는 말이에요","작은 일도 꾸준히 계속되면 나중에는 큰 결과가 된다는 말이에요","가랑비는 옷을 전혀 적시지 못한다는 말이에요","작은 일은 신경 쓰지 않아도 된다는 말이에요"],"answerIndex":1},{"type":"synonym","word":"놀랍다","choices":["지루하다","평범하다","답답하다","신기하다"],"answerIndex":3},{"type":"antonym","word":"자연스럽다","choices":["편안하다","화려하다","어색하다","조용하다"],"answerIndex":2}]'::jsonb, 19)
