insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('relay-race', '🏃', '네 명이 하나 되어', '["가을 운동회의 마지막 순서는 학급 대항 계주 이어달리기였어요.","4학년 3반은 결승선까지 늘 아깝게 지곤 해서, 이번에는 반드시 우승하고 싶었어요.","첫 번째 주자 민호는 스타트가 조금 늦어 다른 반에게 뒤처지고 말았어요.","하지만 두 번째 주자인 하은이가 온 힘을 다해 달려 순식간에 순위를 끌어올렸어요.","세 번째 주자 준서는 바통을 놓칠까 봐 조마조마했지만, 하은이가 건넨 바통을 놓치지 않고 꽉 잡았어요.","마지막 주자 은채가 바통을 받았을 때, 반 아이들은 목이 터져라 응원의 함성을 질렀어요.","은채는 앞서가는 친구를 바짝 뒤쫓으며 있는 힘껏 팔다리를 뻗었어요.","결승선을 코앞에 두고 은채는 온몸을 던지듯 마지막 스퍼트를 냈어요.","결국 4학년 3반은 아주 근소한 차이로 1등을 차지했어요.","네 사람 모두 우승의 주인공은 자신이 아니라 서로라며 얼싸안고 기뻐했어요.","담임 선생님은 \"혼자서는 낼 수 없는 기록이었지. 마치 일심동체처럼 움직였구나\"라며 흐뭇해하셨어요.","아이들은 각자의 자리에서 최선을 다했을 때 비로소 함께 만들어 낼 수 있는 결과가 있다는 것을 깨달았어요."]'::jsonb, '[{"word":"뒤처지다","meaning":"어떤 정도나 수준에 이르지 못하고 뒤로 처지다"},{"word":"근소하다","meaning":"정도가 얼마 되지 않을 만큼 아주 적다"},{"word":"스퍼트","meaning":"마지막에 힘을 다해 속도를 내는 것"}]'::jsonb, '[{"answer":false,"statement":"4학년 3반은 이번 계주에서 처음부터 끝까지 가장 앞서 달렸어요."},{"answer":false,"statement":"첫 번째 주자 민호는 다른 반보다 훨씬 앞서 출발했어요."},{"answer":true,"statement":"하은이는 순위를 끌어올리기 위해 온 힘을 다해 달렸어요."},{"answer":true,"statement":"4학년 3반은 아주 작은 차이로 1등을 했어요."}]'::jsonb, '{"choices":["각자 맡은 역할에 최선을 다할 때 팀 전체가 좋은 결과를 만들 수 있어요","계주에서는 마지막 주자가 가장 중요해요","운동회는 이기지 못하면 의미가 없어요","달리기를 잘하는 사람만 계주에 나가야 해요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"뒤처지다","choices":["다른 사람보다 앞서 나가다","제자리에서 가만히 있다","어떤 정도나 수준에 이르지 못하고 뒤로 처지다","힘차게 뛰어오르다"],"answerIndex":2},{"type":"vocab","word":"근소하다","choices":["정도가 얼마 되지 않을 만큼 아주 적다","차이가 매우 크고 뚜렷하다","전혀 차이가 없다","끝없이 이어지다"],"answerIndex":0},{"type":"proverb","word":"일심동체","choices":["한 사람의 마음이 자주 바뀐다는 뜻이에요","몸이 하나뿐이라 힘들다는 뜻이에요","마음과 몸은 서로 관계가 없다는 뜻이에요","여러 사람이 한마음 한몸처럼 힘을 합친다는 뜻이에요"],"answerIndex":3},{"type":"synonym","word":"근소하다","choices":["막대하다","미세하다","분명하다","확실하다"],"answerIndex":1},{"type":"antonym","word":"뒤처지다","choices":["앞서다","멈추다","숨다","쉬다"],"answerIndex":0}]'::jsonb, 20)
