insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('stray-cat', '🐱', '길고양이와의 약속', '["학교 뒤편 화단 근처에 언제부턴가 비쩍 마른 길고양이 한 마리가 나타나기 시작했어요.","다연이는 고양이가 안쓰러워 보여 매일 급식에서 남은 우유를 몰래 가져다주었어요.","소문을 들은 친구들이 하나둘 모여들어 \"우리가 매일 밥을 챙겨주자\"라고 의견을 냈어요.","하지만 막상 \"그럼 누가 매일 아침에 밥을 줄 거야?\"라고 묻자 아무도 선뜻 나서지 않았어요.","\"고양이 목에 방울 달기라더니, 다들 좋다고만 하고 정작 하겠다는 사람은 없네.\" 다연이는 속으로 한숨을 쉬었어요.","결국 다연이가 \"그럼 내가 먼저 해볼게\"라고 손을 들었고, 짝꿍 재민이도 함께 돕기로 했어요.","둘은 매일 아침 조금 일찍 등교해 정해진 자리에 사료와 물을 가져다 놓았어요.","처음에는 사람을 보면 숨기 바빴던 고양이도 점점 다연이와 재민이를 알아보고 가까이 다가오기 시작했어요.","이 모습을 지켜보던 다른 친구들도 하나둘 당번을 정해 돌아가며 돕기 시작했어요.","어느새 반 전체가 함께 고양이를 돌보는 작은 규칙을 만들게 되었어요.","겨울이 되자 고양이는 처음 발견했을 때보다 훨씬 튼튼하고 윤기 나는 모습으로 자랐어요.","다연이는 누군가 먼저 나서서 행동하면 다른 사람의 마음도 움직일 수 있다는 것을 깨달았어요."]'::jsonb, '[{"word":"안쓰럽다","meaning":"손 쓸 형편이 안 되어 딱하고 마음이 아프다"},{"word":"선뜻","meaning":"동작이 빠르고 시원스러운 모양"},{"word":"윤기","meaning":"반질반질하고 매끄러운 기운"}]'::jsonb, '[{"answer":true,"statement":"다연이는 길고양이가 안쓰러워 몰래 우유를 챙겨주었어요."},{"answer":false,"statement":"친구들은 밥 주는 일을 서로 하겠다고 앞다투어 나섰어요."},{"answer":true,"statement":"재민이는 다연이와 함께 고양이 돌보기를 도왔어요."},{"answer":false,"statement":"결국 아무도 고양이를 계속 돌보지 않았어요."}]'::jsonb, '{"choices":["누군가 먼저 용기를 내어 행동하면 주변 사람들의 마음도 함께 움직일 수 있어요","동물은 학교에서 키우면 안 돼요","모든 일은 혼자 해내야 값진 것이에요","의견을 내는 사람이 가장 중요한 사람이에요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"안쓰럽다","choices":["손 쓸 형편이 안 되어 딱하고 마음이 아프다","몹시 즐겁고 신난다","전혀 관심이 없다","화가 나서 억울하다"],"answerIndex":0},{"type":"vocab","word":"선뜻","choices":["느리고 조심스러운 모양","동작이 빠르고 망설임 없이 시원스러운 모양","시끄럽고 요란한 모양","조용하고 잠잠한 모양"],"answerIndex":1},{"type":"proverb","word":"고양이 목에 방울 달기","choices":["고양이는 방울 소리를 좋아한다는 뜻이에요","위험한 일은 절대 하지 말라는 뜻이에요","실행하기 어려운 일을 두고 말로만 의견을 내는 것을 뜻해요","방울을 달면 소원이 이루어진다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"윤기","choices":["먼지","상처","그림자","광택"],"answerIndex":3},{"type":"antonym","word":"선뜻","choices":["머뭇머뭇","재빠르게","활발하게","즐겁게"],"answerIndex":0}]'::jsonb, 21)
