insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('group-project', '📋', '우리 동네 지도 만들기', '["사회 시간, 선생님은 네 명씩 모둠을 만들어 \"우리 동네 지도 만들기\" 과제를 내주셨어요.","준영이네 모둠은 첫 회의부터 서로 다른 의견을 쏟아내며 시끌벅적했어요.","\"나는 그림을 그릴래\", \"나는 조사를 할래\" 저마다 하고 싶은 일만 말하다 보니 정작 역할 분담이 되지 않았어요.","\"사공이 많으면 배가 산으로 간다더니, 이러다 아무것도 못 끝내겠어.\" 모둠장을 맡은 준영이는 걱정이 되었어요.","그러던 중 모둠원 하은이는 \"나는 바쁘니까 너희가 알아서 해\"라며 슬쩍 발을 빼려 했어요.","준영이는 하은이에게 서운했지만, 화를 내는 대신 하은이가 할 수 있는 쉬운 부분을 조심스레 제안했어요.","\"그럼 우리 동네 사진만 찍어 와 줄래? 그것도 큰 도움이 될 거야.\" 준영이의 말에 하은이는 조금 놀란 표정을 지었어요.","준영이는 나머지 모둠원들과도 각자 잘할 수 있는 역할을 하나씩 정리해 나갔어요.","역할이 명확해지자 모둠원들은 저마다 맡은 일에 집중하기 시작했고, 다툼도 눈에 띄게 줄었어요.","하은이도 약속한 사진을 성실히 찍어 와서 지도 만들기에 보탰어요.","완성된 지도를 발표하는 날, 선생님은 \"역할을 나누어 협력한 모둠이 가장 짜임새 있었다\"라고 칭찬해 주셨어요.","준영이는 각자의 몫을 존중하며 나누는 것이 다투는 것보다 훨씬 좋은 결과를 만든다는 것을 배웠어요."]'::jsonb, '[{"word":"시끌벅적하다","meaning":"많은 사람이 모여 소란스럽게 떠드는 소리가 나다"},{"word":"짜임새","meaning":"계획이나 조직 등이 잘 이루어진 상태"},{"word":"보태다","meaning":"모자라는 것을 더하여 채우다"}]'::jsonb, '[{"answer":false,"statement":"준영이네 모둠은 첫 회의부터 역할이 딱 정해져 있었어요."},{"answer":true,"statement":"하은이는 처음에 모둠 일에서 발을 빼려고 했어요."},{"answer":false,"statement":"준영이는 하은이에게 화를 내며 다그쳤어요."},{"answer":true,"statement":"완성된 지도는 선생님께 짜임새 있다는 칭찬을 받았어요."}]'::jsonb, '{"choices":["모둠 과제는 한 사람이 다 맡아야 편해요","역할을 알맞게 나누어 협력하면 더 좋은 결과를 만들 수 있어요","의견이 다르면 절대 타협할 수 없어요","바쁜 친구는 모둠 활동에서 빼주는 것이 좋아요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"시끌벅적하다","choices":["아주 조용하고 잠잠하다","많은 사람이 모여 소란스럽게 떠드는 소리가 나다","슬프고 우울하다","졸리고 나른하다"],"answerIndex":1},{"type":"vocab","word":"짜임새","choices":["아무렇게나 뒤섞인 상태","텅 비어 있는 상태","계획이나 조직 등이 잘 이루어진 상태","낡고 허름한 상태"],"answerIndex":2},{"type":"proverb","word":"사공이 많으면 배가 산으로 간다","choices":["배는 사공이 많을수록 빨리 간다는 말이에요","산에서는 배를 탈 수 없다는 말이에요","혼자 하는 일이 가장 위험하다는 말이에요","주장하는 사람이 너무 많으면 일이 엉뚱한 방향으로 흘러간다는 말이에요"],"answerIndex":3},{"type":"synonym","word":"보태다","choices":["더하다","줄이다","감추다","빼앗다"],"answerIndex":0},{"type":"antonym","word":"시끌벅적하다","choices":["활기차다","고요하다","즐겁다","분주하다"],"answerIndex":1}]'::jsonb, 22)
