insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('silent-witness', '🙋', '작은 용기의 힘', '["쉬는 시간, 정후는 복도 구석에서 몇몇 아이들이 같은 반 태민이를 둘러싸고 놀리는 모습을 보게 되었어요.","태민이는 아무 말도 못 하고 고개만 푹 숙인 채 서 있었어요.","정후는 순간 눈이 마주쳤지만, 괜히 나섰다가 자기도 놀림감이 될까 봐 슬쩍 고개를 돌렸어요.","교실로 돌아온 정후는 마음이 무거워 수업 내내 태민이의 처진 어깨가 자꾸 떠올랐어요.","''모르는 척 지나가는 게 제일 편한 걸까.'' 정후는 스스로에게 물었지만 답이 쉽게 나오지 않았어요.","집에 돌아온 정후는 결국 언니에게 오늘 있었던 일을 조심스레 털어놓았어요.","언니는 \"발 없는 말이 천리 간다잖아. 네가 선생님께 알리면 그 마음이 태민이에게도 분명 전해질 거야\"라고 말해 주었어요.","다음 날 아침, 정후는 용기를 내어 담임 선생님을 찾아가 어제 본 일을 조용히 말씀드렸어요.","선생님은 정후의 이야기를 진지하게 들어주셨고, 그날 이후 반 분위기를 세심하게 살피기 시작하셨어요.","며칠 뒤 태민이는 정후에게 다가와 \"그때 말해줘서 고마워\"라고 작게 속삭였어요.","정후는 그 말을 듣고서야 자신이 옳은 일을 했다는 것을 확신할 수 있었어요.","정후는 모르는 척 지나치는 것보다 작은 용기를 내는 것이 훨씬 값지다는 것을 깨달았어요."]'::jsonb, '[{"word":"놀림감","meaning":"남에게 놀림을 받는 대상"},{"word":"처지다","meaning":"아래로 축 늘어지다"},{"word":"세심하다","meaning":"작은 부분까지 꼼꼼하게 주의를 기울이다"}]'::jsonb, '[{"answer":false,"statement":"정후는 태민이가 놀림당하는 모습을 처음부터 끝까지 못 본 척했어요."},{"answer":true,"statement":"언니는 정후에게 선생님께 알려보라고 조언했어요."},{"answer":true,"statement":"정후는 다음 날 바로 담임 선생님께 이 일을 말씀드렸어요."},{"answer":false,"statement":"태민이는 정후가 도와준 것에 대해 전혀 고마워하지 않았어요."}]'::jsonb, '{"choices":["괴롭힘을 본 사람은 절대 나서면 안 돼요","문제는 시간이 지나면 저절로 해결돼요","옳지 않은 일을 보았을 때 용기를 내어 알리는 것이 중요해요","어른에게 알리는 것은 고자질이라 나쁜 행동이에요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"놀림감","choices":["모두에게 사랑받는 사람","아무도 모르는 비밀","남에게 놀림을 받는 대상","크게 칭찬받는 일"],"answerIndex":2},{"type":"vocab","word":"세심하다","choices":["아무렇게나 대충 처리하다","전혀 관심을 두지 않다","크고 대담하게 행동하다","작은 부분까지 꼼꼼하게 주의를 기울이다"],"answerIndex":3},{"type":"proverb","word":"발 없는 말이 천리 간다","choices":["말은 발이 없어도 순식간에 멀리까지 퍼져나간다는 뜻이에요","말은 아무리 해도 퍼지지 않는다는 뜻이에요","천리 길도 한 걸음부터 시작한다는 뜻이에요","발이 없으면 걸을 수 없다는 뜻이에요"],"answerIndex":0},{"type":"synonym","word":"처지다","choices":["솟아오르다","늘어지다","펴지다","뻗치다"],"answerIndex":1},{"type":"antonym","word":"놀림감","choices":["걱정거리","고민거리","칭찬거리","말썽거리"],"answerIndex":2}]'::jsonb, 23)
