insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('new-friend-classmate', '🌏', '새로 온 친구, 리엔이', '["3월 새 학기, 우리 반에 베트남에서 온 리엔이라는 친구가 전학을 왔어요.","리엔이는 한국어가 아직 서툴러서 쉬는 시간에도 혼자 조용히 책만 들여다보았어요.","몇몇 아이들은 \"말도 잘 안 통하는데 괜히 어울리지 말자\"라며 리엔이를 멀리했어요.","서현이도 처음에는 ''가재는 게 편이라는데, 낯선 친구랑 친해지기는 좀 그렇지''라고 생각했어요.","하지만 미술 시간, 짝이 된 서현이는 리엔이가 그림을 정말 섬세하게 그린다는 것을 알게 되었어요.","서현이는 손짓과 그림을 섞어가며 리엔이와 조금씩 이야기를 나누기 시작했어요.","알고 보니 리엔이도 베트남에서 친구들과 그림 그리기를 무척 좋아했다고 했어요.","서현이는 쉬는 시간마다 리엔이에게 간단한 한국어 단어를 하나씩 가르쳐 주었어요.","리엔이도 서현이에게 베트남 인사말을 알려주며 둘은 점점 가까워졌어요.","다른 친구들도 둘이 즐겁게 어울리는 모습을 보고 하나둘 리엔이에게 말을 걸기 시작했어요.","한 달이 지나자 리엔이는 쉬는 시간마다 친구들에게 둘러싸여 웃는 얼굴로 지내게 되었어요.","서현이는 처음의 낯섦을 넘어서면 새로운 친구에게서 배울 점이 정말 많다는 것을 깨달았어요."]'::jsonb, '[{"word":"서투르다","meaning":"익숙하지 못하여 다루는 것이 미숙하다"},{"word":"섬세하다","meaning":"매우 곱고 세밀하다"},{"word":"낯설다","meaning":"익숙하지 않아 어색하다"}]'::jsonb, '[{"answer":false,"statement":"리엔이는 처음부터 한국어를 아주 능숙하게 했어요."},{"answer":true,"statement":"몇몇 아이들은 리엔이와 어울리지 말자고 말했어요."},{"answer":true,"statement":"서현이는 미술 시간에 리엔이의 그림 솜씨를 알게 되었어요."},{"answer":false,"statement":"반 친구들은 끝까지 리엔이와 어울리지 않았어요."}]'::jsonb, '{"choices":["말이 통하지 않으면 친구가 될 수 없어요","전학생은 스스로 적응할 때까지 혼자 두는 것이 좋아요","그림을 잘 그리는 친구만 사귀어야 해요","낯설다고 멀리하기보다 다가가 보면 서로에게서 좋은 점을 배울 수 있어요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"서투르다","choices":["아주 능숙하고 자연스럽다","빠르고 정확하다","조용하고 차분하다","익숙하지 못하여 다루는 것이 미숙하다"],"answerIndex":3},{"type":"vocab","word":"섬세하다","choices":["매우 곱고 세밀하다","거칠고 투박하다","크고 단순하다","흐릿하고 어둡다"],"answerIndex":0},{"type":"proverb","word":"가재는 게 편","choices":["가재와 게는 서로 원수 사이라는 뜻이에요","비슷한 처지에 있는 사람끼리 서로 편을 든다는 뜻이에요","바다 생물은 모두 친구라는 뜻이에요","편을 나누면 안 된다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"낯설다","choices":["익숙하다","친근하다","생소하다","편안하다"],"answerIndex":2},{"type":"antonym","word":"서투르다","choices":["어색하다","조급하다","서먹하다","능숙하다"],"answerIndex":3}]'::jsonb, 24)
