insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('kept-promise', '🤞', '미뤄둔 약속', '["여름 방학이 되기 전, 시윤이는 가장 친한 친구 도영이에게 \"방학 숙제 다 하면 같이 자전거 타러 가자\"라고 약속했어요.","하지만 방학이 시작되자 시윤이는 게임에 푹 빠져 숙제를 자꾸 뒤로 미루었어요.","도영이는 약속한 날짜가 다가올수록 설레는 마음으로 자전거를 손질하며 기다렸어요.","약속한 날 아침, 도영이가 연락하자 시윤이는 \"숙제를 아직 못 끝냈어. 다음에 가자\"라며 약속을 미뤄버렸어요.","도영이는 크게 실망했지만 \"그래, 알겠어\"라고 애써 담담하게 대답했어요.","시윤이는 전화를 끊고 나서야 도영이의 목소리가 얼마나 가라앉아 있었는지를 뒤늦게 깨달았어요.","''말과 행동이 다르면 결국 친구를 잃을 수도 있겠구나.'' 시윤이는 언행일치라는 말을 떠올리며 반성했어요.","그날부터 시윤이는 매일 시간을 정해 놓고 숙제를 조금씩 해 나가기 시작했어요.","사흘 뒤, 시윤이는 마침내 밀렸던 숙제를 모두 끝마쳤어요.","시윤이는 도영이에게 먼저 전화를 걸어 \"이번엔 진짜야, 내일 같이 타러 가자\"라고 다시 약속했어요.","다음 날, 시윤이는 도영이와의 약속 시간보다 십 분이나 일찍 나가 기다렸어요.","두 사람은 그동안 미뤄두었던 약속을 시원하게 지키며 즐거운 오후를 보냈어요.","시윤이는 한 번 미룬 약속도 진심으로 지키려 노력하면 다시 신뢰를 얻을 수 있다는 것을 배웠어요."]'::jsonb, '[{"word":"설레다","meaning":"마음이 가라앉지 않고 들떠서 두근거리다"},{"word":"담담하다","meaning":"차분하고 평온하다"},{"word":"신뢰","meaning":"굳게 믿고 의지함"}]'::jsonb, '[{"answer":false,"statement":"시윤이는 방학 숙제를 미리 끝내고 여유롭게 지냈어요."},{"answer":true,"statement":"도영이는 약속한 날 자전거를 타지 못해 실망했어요."},{"answer":false,"statement":"시윤이는 도영이와의 약속을 끝까지 지키지 않았어요."},{"answer":true,"statement":"시윤이는 약속 시간보다 일찍 나가 도영이를 기다렸어요."}]'::jsonb, '{"choices":["한 번 어긴 약속도 진심으로 지키려 노력하면 다시 신뢰를 회복할 수 있어요","약속은 한 번 어기면 절대 되돌릴 수 없어요","숙제보다 노는 것이 항상 우선이에요","친구 사이에는 약속을 지키지 않아도 괜찮아요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"설레다","choices":["마음이 가라앉지 않고 들떠서 두근거리다","마음이 차분히 가라앉다","몹시 화가 나다","아무 감정이 없다"],"answerIndex":0},{"type":"vocab","word":"담담하다","choices":["몹시 흥분하고 들뜨다","차분하고 평온하다","크게 서럽게 울다","정신없이 바쁘다"],"answerIndex":1},{"type":"proverb","word":"언행일치","choices":["말은 행동보다 중요하지 않다는 뜻이에요","행동보다 말을 앞세우라는 뜻이에요","말과 행동이 서로 같아야 한다는 뜻이에요","말과 행동은 원래 다를 수밖에 없다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"신뢰","choices":["오해","의심","불안","믿음"],"answerIndex":3},{"type":"antonym","word":"설레다","choices":["차분하다","들뜨다","즐겁다","흥분하다"],"answerIndex":0}]'::jsonb, 25)
