insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('good-sportsmanship', '⚽', '아쉬운 결승전', '["축구 반 대항전 결승, 우리 반은 마지막 순간 상대 팀에게 역전골을 허용하며 아깝게 패하고 말았어요.","골키퍼를 맡았던 진우는 자신이 막지 못한 그 한 골이 자꾸 떠올라 고개를 들 수가 없었어요.","몇몇 아이들은 분한 마음에 심판 판정이 불공평했다며 큰 소리로 항의했어요.","진우도 처음에는 억울한 마음에 함께 항의하고 싶었지만, 이내 마음을 가라앉히고 상대 팀을 바라보았어요.","상대 팀 아이들도 땀에 흠뻑 젖은 채 지친 얼굴로 서로를 격려하고 있었어요.","''지는 것이 이기는 것이다라는 말도 있잖아. 결과에 승복하는 것도 중요한 거야.'' 진우는 스스로를 다독였어요.","진우는 씩씩하게 상대 팀 주장에게 다가가 손을 내밀며 \"좋은 경기였어, 축하해\"라고 말했어요.","상대 팀 주장도 놀란 표정으로 \"너희 골키퍼 정말 대단했어\"라며 진우의 손을 맞잡았어요.","그 모습을 본 우리 반 아이들도 하나둘 흥분을 가라앉히고 상대 팀에게 박수를 보내기 시작했어요.","담임 선생님은 \"경기에서 진 것보다 결과에 깨끗하게 승복하는 태도가 더 값지단다\"라고 칭찬해 주셨어요.","진우는 패배가 부끄러운 것이 아니라, 결과를 인정하지 못하는 태도가 부끄러운 것임을 깨달았어요.","다음 시합에서 우리 반은 승패와 상관없이 서로를 격려하는 팀이 되기로 다짐했어요."]'::jsonb, '[{"word":"역전골","meaning":"경기에서 지고 있다가 이기게 되는 결정적인 골"},{"word":"승복하다","meaning":"남의 의견이나 결정에 옳다고 인정하여 따르다"},{"word":"격려하다","meaning":"용기나 힘을 북돋워 주다"}]'::jsonb, '[{"answer":true,"statement":"우리 반은 결승에서 마지막 순간 역전골을 허용해 졌어요."},{"answer":false,"statement":"진우는 처음부터 끝까지 침착하게 결과를 받아들였어요."},{"answer":true,"statement":"진우는 경기가 끝난 뒤 상대 팀 주장과 악수를 나누었어요."},{"answer":false,"statement":"선생님은 이기지 못한 것을 크게 꾸짖으셨어요."}]'::jsonb, '{"choices":["경기는 무조건 이기는 것이 가장 중요해요","경기에서 진 결과도 깨끗하게 받아들이는 태도가 중요해요","심판의 판정에는 항상 큰 소리로 항의해야 해요","진 팀은 이긴 팀을 축하해줄 필요가 없어요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"역전골","choices":["경기 시작을 알리는 신호","경기에서 지고 있다가 이기게 되는 결정적인 골","아무 의미 없는 골","경기를 무효로 만드는 규칙"],"answerIndex":1},{"type":"vocab","word":"승복하다","choices":["끝까지 인정하지 않고 반대하다","자기 뜻만 고집하다","남의 의견이나 결정에 옳다고 인정하여 따르다","결과를 무시하고 넘어가다"],"answerIndex":2},{"type":"proverb","word":"지는 것이 이기는 것이다","choices":["경기는 항상 이겨야 의미가 있다는 뜻이에요","지는 사람이 실력이 더 좋다는 뜻이에요","승패는 아무 상관이 없다는 뜻이에요","때로는 다투지 않고 양보하거나 결과를 받아들이는 것이 더 나은 선택이라는 뜻이에요"],"answerIndex":3},{"type":"synonym","word":"격려하다","choices":["북돋우다","비난하다","무시하다","방해하다"],"answerIndex":0},{"type":"antonym","word":"승복하다","choices":["수긍하다","반발하다","동의하다","따르다"],"answerIndex":1}]'::jsonb, 26)
