insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('borrowed-money', '💰', '천 원의 무게', '["문구점 앞에서 정민이는 갖고 싶던 필통을 발견했지만 용돈이 조금 모자랐어요.","옆에 있던 친구 유빈이는 선뜻 \"내가 천 원 빌려줄게, 다음 주에 갚아\"라며 돈을 건넸어요.","정민이는 고마운 마음에 \"당연히 다음 주에 꼭 갚을게\"라고 약속했어요.","하지만 다음 주가 되어도, 그다음 주가 되어도 정민이는 자꾸 깜빡했다며 돈을 갚지 않았어요.","유빈이는 몇 번이나 갚아 달라는 말을 꺼내려다가도 괜히 쪼잔해 보일까 봐 망설였어요.","\"믿는 도끼에 발등 찍힌다더니, 그깟 천 원 때문에 마음이 이렇게 상할 줄이야.\" 유빈이는 속상했어요.","결국 유빈이는 용기를 내어 정민이에게 조용히 \"저번에 빌려준 천 원, 혹시 잊은 거야?\"라고 물었어요.","정민이는 그제야 화들짝 놀라며 \"미안해, 정말 깜빡하고 있었어\"라고 얼굴이 빨개졌어요.","정민이는 곧바로 지갑에서 천 원을 꺼내 유빈이에게 건네며 진심으로 사과했어요.","유빈이는 정민이의 사과를 받아들이면서도, 앞으로는 빌린 돈을 적어두는 습관을 들이자고 제안했어요.","정민이도 그 뒤로는 작은 약속이라도 수첩에 적어 두고 꼭 지키려 노력했어요.","두 사람은 작은 약속이라도 소홀히 하지 않는 것이 우정을 오래 지키는 방법임을 깨달았어요."]'::jsonb, '[{"word":"쪼잔하다","meaning":"성격이 좁고 인색하다"},{"word":"화들짝","meaning":"갑자기 몹시 놀라는 모양"},{"word":"소홀히","meaning":"대수롭지 않게 여겨 정성이나 조심하는 마음이 부족하게"}]'::jsonb, '[{"answer":true,"statement":"유빈이는 정민이에게 천 원을 빌려주었어요."},{"answer":false,"statement":"정민이는 약속한 날짜에 바로 돈을 갚았어요."},{"answer":false,"statement":"유빈이는 끝까지 아무 말도 하지 않고 참기만 했어요."},{"answer":true,"statement":"정민이는 사과하며 빌린 돈을 갚았어요."}]'::jsonb, '{"choices":["돈을 빌려준 사람이 항상 참아야 해요","작은 약속은 지키지 않아도 우정에 문제가 없어요","아무리 작은 약속이라도 소홀히 하지 않고 지키는 것이 중요해요","친구 사이에는 돈 이야기를 꺼내면 안 돼요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"쪼잔하다","choices":["마음이 넓고 너그럽다","매우 씩씩하고 용감하다","성격이 좁고 인색하다","조용하고 차분하다"],"answerIndex":2},{"type":"vocab","word":"화들짝","choices":["천천히 조심스러운 모양","차분하고 태연한 모양","느긋하고 여유로운 모양","갑자기 몹시 놀라는 모양"],"answerIndex":3},{"type":"proverb","word":"믿는 도끼에 발등 찍힌다","choices":["믿었던 사람에게 뜻밖에 배신을 당하거나 피해를 입는다는 뜻이에요","도끼는 항상 조심해서 다뤄야 한다는 뜻이에요","믿음이 강할수록 좋은 결과만 생긴다는 뜻이에요","발등을 다치면 걷기 힘들다는 뜻이에요"],"answerIndex":0},{"type":"synonym","word":"소홀히","choices":["꼼꼼히","대충","정성껏","철저히"],"answerIndex":1},{"type":"antonym","word":"쪼잔하다","choices":["인색하다","까다롭다","너그럽다","냉정하다"],"answerIndex":2}]'::jsonb, 27)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('grandma-visit', '👵', '할머니 댁에서 배운 것', '["추석 연휴, 은우는 오랜만에 시골 할머니 댁에 가족과 함께 가게 되었어요.","은우는 와이파이도 잘 안 터지는 할머니 댁이 지루하게만 느껴져 내내 시무룩한 표정이었어요.","할머니는 그런 은우에게 텃밭에서 갓 딴 옥수수를 삶아 주시며 \"우리 은우, 심심하지\"라며 웃으셨어요.","은우는 마지못해 할머니를 따라 텃밭에 나갔다가, 할머니가 손수 채소를 가꾸시는 모습을 처음으로 자세히 보게 되었어요.","할머니는 손이 흙투성이가 되면서도 힘든 기색 없이 콧노래를 부르며 일하셨어요.","\"할머니, 힘들지 않으세요?\"라고 묻자 할머니는 \"일하면서 은우 생각하니까 하나도 안 힘들어\"라고 대답하셨어요.","그날 저녁, 할머니는 은우에게 어릴 적 힘들었던 시절 이야기를 두런두런 들려주셨어요.","\"어른 말을 들으면 자다가도 떡이 생긴다는 말이 있잖니. 옛날얘기라도 새겨들으면 다 도움이 된단다.\" 할머니가 말씀하셨어요.","은우는 처음에는 흘려듣다가, 할머니의 이야기 속에서 자신이 몰랐던 지혜를 하나둘 발견하게 되었어요.","다음 날 아침, 은우는 먼저 나서서 할머니의 텃밭 일을 거들어 드렸어요.","집으로 돌아가는 날, 은우는 할머니를 꼭 안아 드리며 \"다음에 또 놀러 올게요\"라고 약속했어요.","은우는 지루하다고만 여겼던 할머니 댁에서 오히려 소중한 것들을 많이 배웠다는 것을 깨달았어요."]'::jsonb, '[{"word":"시무룩하다","meaning":"마음에 못마땅하여 부루퉁한 표정을 짓다"},{"word":"두런두런","meaning":"여럿이 나직한 목소리로 서로 이야기하는 소리"},{"word":"거들다","meaning":"남이 하는 일을 함께 도와주다"}]'::jsonb, '[{"answer":false,"statement":"은우는 처음부터 할머니 댁에 가는 것을 매우 좋아했어요."},{"answer":true,"statement":"할머니는 텃밭에서 채소를 손수 가꾸셨어요."},{"answer":false,"statement":"은우는 할머니의 옛이야기를 끝까지 하나도 듣지 않았어요."},{"answer":true,"statement":"은우는 다음 날 아침 할머니의 텃밭 일을 거들었어요."}]'::jsonb, '{"choices":["시골은 항상 지루하고 재미없는 곳이에요","어른들의 옛날이야기는 들을 필요가 없어요","명절에는 집에서 쉬는 것이 가장 좋아요","어른들과 시간을 보내며 귀 기울이면 소중한 지혜를 배울 수 있어요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"시무룩하다","choices":["기쁘고 즐거운 표정을 짓다","차분하고 평온한 표정을 짓다","깜짝 놀란 표정을 짓다","마음에 못마땅하여 부루퉁한 표정을 짓다"],"answerIndex":3},{"type":"vocab","word":"거들다","choices":["남이 하는 일을 함께 도와주다","모르는 척 지나치다","방해하고 훼방을 놓다","혼자서만 하려 하다"],"answerIndex":0},{"type":"proverb","word":"어른 말을 들으면 자다가도 떡이 생긴다","choices":["떡을 먹으려면 잠을 자야 한다는 뜻이에요","어른들의 말을 잘 들으면 자신에게 이롭다는 뜻이에요","어른들의 말은 지킬 필요가 없다는 뜻이에요","잠을 많이 자야 떡을 만들 수 있다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"두런두런","choices":["우당탕탕","쿵쾅쿵쾅","도란도란","와글와글"],"answerIndex":2},{"type":"antonym","word":"시무룩하다","choices":["서운하다","씁쓸하다","우울하다","환하다"],"answerIndex":3}]'::jsonb, 28)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('science-fair-retry', '🔬', '다시 도전한 발명품', '["과학 발명품 대회를 앞두고 하윤이는 빗물을 모아 화분에 자동으로 물을 주는 장치를 만들기로 했어요.","며칠 동안 밤늦게까지 설계도를 그리고 재료를 모아 정성껏 장치를 완성했어요.","발표 당일, 하윤이는 자신 있게 장치를 시연했지만 호스가 새면서 물이 엉뚱한 곳으로 흘러버렸어요.","심사위원들 앞에서 장치가 제대로 작동하지 않자 하윤이는 얼굴이 새빨갛게 달아올랐어요.","결국 그해 대회에서 하윤이는 상을 받지 못한 채 씁쓸한 마음으로 자리에 돌아왔어요.","속상한 마음에 장치를 창고에 처박아 두려던 하윤이에게 담임 선생님이 다가오셨어요.","\"실패는 성공의 어머니라는 말이 있잖니. 무엇이 문제였는지 살펴보면 다음엔 더 잘할 수 있을 거야.\" 선생님이 말씀하셨어요.","하윤이는 그 말에 힘을 얻어 장치를 다시 꺼내 문제점을 하나씩 찾아보기 시작했어요.","살펴보니 호스를 연결한 부분의 접착이 헐거웠던 것이 문제였다는 것을 알게 되었어요.","하윤이는 방학 내내 접착 방식을 바꾸어 가며 몇 번이고 다시 시험해 보았어요.","다음 해 대회에서 하윤이의 장치는 물 한 방울 새지 않고 완벽하게 작동했어요.","하윤이는 그날의 실패가 있었기에 더 튼튼한 장치를 만들 수 있었다는 것을 깨달았어요.","실패를 두려워하기보다 원인을 찾아 고쳐 나가는 것이 진짜 실력이라는 것을 알게 되었어요."]'::jsonb, '[{"word":"시연하다","meaning":"무엇을 실제로 해 보이다"},{"word":"헐겁다","meaning":"끼울 것이 끼워질 자리보다 커서 여유가 있다"},{"word":"처박다","meaning":"아무렇게나 쑤셔 넣거나 넣어 두다"}]'::jsonb, '[{"answer":false,"statement":"하윤이의 장치는 대회 당일 완벽하게 작동했어요."},{"answer":true,"statement":"하윤이는 첫 대회에서 상을 받지 못했어요."},{"answer":false,"statement":"하윤이는 실패한 뒤 장치를 다시는 손대지 않았어요."},{"answer":true,"statement":"다음 해 대회에서 하윤이의 장치는 문제없이 작동했어요."}]'::jsonb, '{"choices":["실패의 원인을 찾아 고쳐 나가면 더 나은 결과를 만들 수 있어요","한 번 실패하면 다시 도전하지 않는 것이 좋아요","발명은 처음부터 완벽해야만 가치가 있어요","상을 받지 못한 노력은 의미가 없어요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"시연하다","choices":["무엇을 실제로 해 보이다","계획만 세우고 실행하지 않다","전혀 준비하지 않다","다른 사람에게 미루다"],"answerIndex":0},{"type":"vocab","word":"헐겁다","choices":["꽉 끼어 움직이지 않다","끼울 것이 자리보다 커서 여유가 있다","매우 뜨겁고 단단하다","아주 가볍고 부드럽다"],"answerIndex":1},{"type":"proverb","word":"실패는 성공의 어머니","choices":["한 번 실패하면 다시는 성공할 수 없다는 뜻이에요","성공한 사람은 실패를 해본 적이 없다는 뜻이에요","실패를 통해 배우고 고쳐 나가면 결국 성공할 수 있다는 뜻이에요","어머니는 항상 실패한다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"처박다","choices":["가지런히 놓다","정성껏 꾸미다","소중히 간직하다","쑤셔 넣다"],"answerIndex":3},{"type":"antonym","word":"헐겁다","choices":["꽉 끼다","느슨하다","헝클어지다","흔들리다"],"answerIndex":0}]'::jsonb, 29)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('library-book-honesty', '📖', '숨긴 만화책', '["도서관에서 빌린 만화책을 읽던 아린이는 실수로 물컵을 엎질러 책 몇 페이지를 흠뻑 적시고 말았어요.","깜짝 놀란 아린이는 얼른 휴지로 닦았지만 종이는 이미 울퉁불퉁하게 우글쭈글해져 있었어요.","''사서 선생님께 혼나면 어떡하지.'' 아린이는 겁이 나서 젖은 페이지를 몰래 책가방 깊숙이 숨겨 버렸어요.","반납일이 다가올수록 아린이는 책을 낼 생각만 하면 가슴이 콩닥콩닥 뛰고 마음이 불편해졌어요.","결국 아린이는 반납일에 아무 말 없이 훼손된 책을 책 반납함에 슬쩍 넣고 도망치듯 나왔어요.","며칠 뒤, 사서 선생님은 훼손된 책을 발견하고 대출 기록을 확인해 아린이를 조용히 불렀어요.","\"낮말은 새가 듣고 밤말은 쥐가 듣는다더니, 숨긴다고 될 일이 아니었구나.\" 아린이는 부끄러움에 얼굴이 화끈거렸어요.","아린이는 결국 사서 선생님께 물을 엎질렀던 상황을 사실대로 솔직하게 털어놓았어요.","사서 선생님은 \"실수는 누구나 할 수 있지만, 숨기지 않고 말해줘서 고맙다\"라며 아린이를 다독여 주셨어요.","아린이는 용돈을 모아 같은 책을 새로 사서 도서관에 가져다드렸어요.","그 뒤로 아린이는 실수를 했을 때 숨기기보다 바로 솔직하게 말하는 것이 마음이 훨씬 편하다는 것을 알게 되었어요.","아린이는 작은 실수보다 그것을 숨기려 했던 것이 더 부끄러운 일이었다는 것을 깨달았어요."]'::jsonb, '[{"word":"우글쭈글하다","meaning":"물체의 표면이 고르지 않게 자꾸 주름이 잡히다"},{"word":"훼손되다","meaning":"헐리거나 깨져서 못 쓰게 되다"},{"word":"다독이다","meaning":"남을 격려하고 위로하다"}]'::jsonb, '[{"answer":true,"statement":"아린이는 실수로 도서관 책에 물을 엎질렀어요."},{"answer":false,"statement":"아린이는 곧바로 사서 선생님께 사실대로 말씀드렸어요."},{"answer":true,"statement":"사서 선생님은 훼손된 책을 발견하고 아린이를 불렀어요."},{"answer":false,"statement":"아린이는 끝까지 자신의 실수를 숨기고 넘어갔어요."}]'::jsonb, '{"choices":["실수는 무조건 숨기는 것이 가장 안전해요","실수를 숨기기보다 솔직하게 말하는 것이 훨씬 떳떳한 방법이에요","도서관 책은 훼손되어도 상관없어요","들키지만 않으면 거짓말을 해도 괜찮아요"],"question":"이 이야기가 전하고 싶은 중심 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"우글쭈글하다","choices":["반듯하고 매끈하다","물체의 표면이 고르지 않게 자꾸 주름이 잡히다","아주 반짝반짝 빛나다","부드럽고 폭신하다"],"answerIndex":1},{"type":"vocab","word":"훼손되다","choices":["새것처럼 깨끗하게 유지되다","더 크고 튼튼해지다","헐리거나 깨져서 못 쓰게 되다","원래보다 좋아지다"],"answerIndex":2},{"type":"proverb","word":"낮말은 새가 듣고 밤말은 쥐가 듣는다","choices":["새와 쥐는 사람의 말을 알아듣지 못한다는 뜻이에요","낮에는 말을 하면 안 된다는 뜻이에요","비밀은 절대 새어나가지 않는다는 뜻이에요","아무리 조심스럽게 한 말이라도 결국은 남에게 알려지기 마련이라는 뜻이에요"],"answerIndex":3},{"type":"synonym","word":"다독이다","choices":["위로하다","꾸짖다","비웃다","외면하다"],"answerIndex":0},{"type":"antonym","word":"훼손되다","choices":["파손되다","보존되다","손상되다","낡아지다"],"answerIndex":1}]'::jsonb, 30)
