insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('mountain-trail-litter', '🥾', '산길에서 주운 쓰레기', '["태호네 반은 토요일마다 뒷산으로 함께 등산을 갑니다.","어느 날 선생님께서 산길에 떨어진 작은 쓰레기를 하나씩만 주워 보자고 하셨어요.","태호는 \"이렇게 작은 것 하나 줍는다고 뭐가 달라질까?\" 하고 속으로 생각했어요.","하지만 반 친구 스무 명이 저마다 쓰레기를 줍기 시작하자 봉지가 금세 묵직해졌어요.","정상에 도착했을 때 봉지 세 개가 가득 찼고, 산길은 몰라보게 깨끗해져 있었어요.","태호는 작은 실천도 여럿이 모이면 커다란 변화를 만든다는 것을 깨달았어요.","그날 이후 태호는 길을 걸을 때마다 눈에 띄는 쓰레기를 그냥 지나치지 않게 되었어요."]'::jsonb, '[{"word":"실천","meaning":"생각한 것을 실제로 행동으로 옮기는 것"},{"word":"묵직하다","meaning":"다소 무겁게 느껴지다"},{"word":"몰라보다","meaning":"전과 달라져서 알아보기 어렵다"}]'::jsonb, '[{"answer":true,"statement":"태호네 반은 토요일마다 뒷산으로 등산을 간다."},{"answer":false,"statement":"선생님은 쓰레기를 최대한 많이 주우라고 하셨다."},{"answer":false,"statement":"정상에 도착했을 때 쓰레기봉지는 하나도 차지 않았다."}]'::jsonb, '{"choices":["등산은 힘드니 되도록 하지 않는 것이 좋다","쓰레기는 어차피 다시 생기니 주울 필요가 없다","산길은 원래 깨끗하니 신경 쓰지 않아도 된다","작은 실천도 여럿이 모이면 큰 변화를 만들 수 있다"],"question":"이 이야기가 전하고 싶은 마음으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"실천","choices":["아무 일도 하지 않고 쉬는 것","다른 사람을 미워하는 마음","생각한 것을 실제로 행동으로 옮기는 것","물건을 잃어버리는 것"],"answerIndex":2},{"type":"proverb","word":"티끌 모아 태산","choices":["한번 실수하면 다시 되돌릴 수 없다","아무리 노력해도 소용이 없다","가까이 있는 것을 오히려 알아보지 못한다","작은 것이라도 꾸준히 모으면 큰 것이 된다"],"answerIndex":3},{"type":"synonym","word":"묵직하다","choices":["무겁다","가볍다","빠르다","차갑다"],"answerIndex":0},{"type":"antonym","word":"몰라보다","choices":["못보다","버리다","숨다","알아보다"],"answerIndex":3},{"type":"spelling","word":"며칠","choices":["며칟","몇일","몇 일","며칠"],"answerIndex":3}]'::jsonb, 31)
