insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('carrying-desks-together', '🪑', '무거운 책상, 가벼운 마음', '["체육관 대청소를 하는 날, 선생님은 무거운 책상을 옆 반 교실로 옮겨야 한다고 하셨어요.","민서는 혼자 책상 하나를 낑낑대며 옮기려 했지만 꼼짝도 하지 않았어요.","그 모습을 본 짝꿍 도윤이가 다가와 반대쪽을 함께 들어 주었어요.","둘이 힘을 합치자 책상은 놀랍도록 가볍게 움직였고, 금세 여러 개를 옮길 수 있었어요.","민서는 혼자였다면 한 시간이 걸렸을 일이 함께하니 십 분 만에 끝난 것을 보고 놀랐어요.","민서는 힘든 일도 함께 나누면 훨씬 수월해진다는 것을 마음 깊이 느꼈어요."]'::jsonb, '[{"word":"낑낑대다","meaning":"힘든 일을 하느라 애를 쓰며 앓는 소리를 내다"},{"word":"수월하다","meaning":"어렵지 않고 하기 쉽다"},{"word":"나누다","meaning":"한 가지 일을 여럿이 함께 맡아 하다"}]'::jsonb, '[{"answer":true,"statement":"민서는 처음에 책상을 혼자 옮기려 했다."},{"answer":false,"statement":"도윤이는 민서를 도와주지 않고 지나갔다."},{"answer":true,"statement":"둘이 힘을 합치자 책상 옮기는 일이 훨씬 빨라졌다."}]'::jsonb, '{"choices":["책상은 원래 옮기기 쉬운 물건이다","친구에게 도움을 청하는 것은 부끄러운 일이다","힘든 일도 함께 나누면 훨씬 쉬워진다","무거운 일은 혼자 해내야 진짜 실력이 는다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"수월하다","choices":["어렵지 않고 하기 쉽다","몹시 무섭고 두렵다","시간이 오래 걸리다","매우 지저분하다"],"answerIndex":0},{"type":"proverb","word":"백지장도 맞들면 낫다","choices":["아무리 쉬운 일도 협력하면 더 낫다","일을 미루면 나중에 더 힘들어진다","종이는 가벼워서 다루기 쉽다","한 사람의 의견이 가장 정확하다"],"answerIndex":0},{"type":"synonym","word":"수월하다","choices":["무겁다","쉽다","느리다","어렵다"],"answerIndex":1},{"type":"antonym","word":"나누다","choices":["혼자 하다","도와주다","거들다","함께 하다"],"answerIndex":0},{"type":"spelling","word":"웬일","choices":["웬닐","왠닐","왠일","웬일"],"answerIndex":3}]'::jsonb, 32)
