insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('blank-page-fear', '📝', '하얀 원고지 앞에서', '["독서 감상문 대회를 앞두고 은유는 며칠째 원고지 첫 줄도 쓰지 못하고 있었어요.","멋진 문장으로 시작해야 한다는 부담 때문에 자꾸만 연필을 내려놓았어요.","엄마는 \"완벽한 첫 문장을 고민하지 말고, 그냥 떠오르는 대로 한 줄만 써 보렴\" 하고 말씀하셨어요.","은유는 못 미더워하면서도 \"이 책에서 가장 인상 깊었던 장면은\"이라고 짧게 적어 보았어요.","신기하게도 한 줄을 쓰고 나니 다음 문장들이 술술 이어졌어요.","은유는 시작하기 전이 가장 두려웠을 뿐, 막상 시작하니 절반은 이미 해낸 것과 같다는 것을 알게 되었어요."]'::jsonb, '[{"word":"부담","meaning":"어떤 일을 해야 한다는 마음의 무거운 짐"},{"word":"못 미더워하다","meaning":"어떤 일이 잘될지 믿음이 가지 않다"},{"word":"술술","meaning":"일이 막힘없이 잘 풀려 나가는 모양"}]'::jsonb, '[{"answer":true,"statement":"은유는 원고지 첫 줄을 며칠째 쓰지 못하고 있었다."},{"answer":false,"statement":"엄마는 완벽한 첫 문장부터 고민하라고 하셨다."},{"answer":true,"statement":"한 줄을 쓰고 나자 다음 문장이 쉽게 이어졌다."}]'::jsonb, '{"choices":["무슨 일이든 일단 시작하면 절반은 해낸 것과 같다","독서 감상문은 짧게 쓸수록 좋다","글쓰기는 누구에게나 어려운 일이다","완벽한 문장을 쓸 때까지 기다려야 한다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"부담","choices":["아주 즐겁고 신나는 기분","몸이 가볍고 편안한 상태","갑자기 화가 나는 마음","어떤 일을 해야 한다는 마음의 무거운 짐"],"answerIndex":3},{"type":"proverb","word":"시작이 반이다","choices":["반쯤 하다가 그만두는 것이 낫다","준비만 오래 하면 실패하지 않는다","무슨 일이든 일단 시작하면 절반은 이룬 것이나 다름없다","처음 계획이 끝까지 그대로 지켜져야 한다"],"answerIndex":2},{"type":"synonym","word":"부담","choices":["기쁨","자유","휴식","짐"],"answerIndex":3},{"type":"antonym","word":"못 미더워하다","choices":["두려워하다","망설이다","믿음직스러워하다","걱정하다"],"answerIndex":2},{"type":"spelling","word":"왠지","choices":["웬지","왠지","웬쥐","왠쥐"],"answerIndex":1}]'::jsonb, 33)
