insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('glasses-on-head', '👓', '머리 위의 안경', '["할아버지는 안경을 찾는다며 온 집 안을 이십 분 넘게 뒤지고 다니셨어요.","서랍도 열어 보고, 소파 밑도 살펴보았지만 안경은 어디에도 없었어요.","그 모습을 보던 손녀 유나가 웃음을 참으며 \"할아버지, 안경 머리 위에 계세요\" 하고 말했어요.","할아버지는 머리를 만져 보고서야 안경이 이마 위에 얹혀 있는 것을 알고 껄껄 웃으셨어요.","유나는 정작 가장 가까운 곳에 있는 것을 못 알아챌 때가 있다는 것을 새삼 깨달았어요.","그날 이후 유나는 물건을 찾을 때마다 먼저 자기 주변부터 찬찬히 살펴보는 버릇이 생겼어요."]'::jsonb, '[{"word":"뒤지다","meaning":"무엇을 찾으려고 이곳저곳을 살펴보다"},{"word":"껄껄","meaning":"유쾌하게 크게 웃는 소리나 모양"},{"word":"찬찬히","meaning":"동작이나 태도가 급하지 않고 차분하게"}]'::jsonb, '[{"answer":false,"statement":"할아버지는 안경을 소파 밑에서 바로 찾으셨다."},{"answer":true,"statement":"안경은 할아버지의 이마 위에 얹혀 있었다."},{"answer":true,"statement":"유나는 그 일 이후로 물건을 찾을 때 주변부터 살펴보게 되었다."}]'::jsonb, '{"choices":["안경은 항상 서랍에 보관해야 한다","나이가 들면 물건을 자주 잃어버린다","정작 가까이 있는 것을 오히려 알아보지 못할 때가 있다","집을 정리하면 물건을 잃어버리지 않는다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"찬찬히","choices":["아무렇게나 대충","매우 빠르고 급하게","큰 소리로 시끄럽게","급하지 않고 차분하게"],"answerIndex":3},{"type":"proverb","word":"등잔 밑이 어둡다","choices":["등잔불은 밝을수록 좋다","멀리 있는 것일수록 눈에 잘 띈다","어두운 곳에서는 물건을 찾기 쉽다","가까이 있는 것을 오히려 잘 알아채지 못한다"],"answerIndex":3},{"type":"synonym","word":"찬찬히","choices":["거칠게","시끄럽게","차분히","급하게"],"answerIndex":2},{"type":"antonym","word":"찬찬히","choices":["천천히","나란히","허둥지둥","조용히"],"answerIndex":2},{"type":"spelling","word":"오랜만","choices":["오랫만","오랫밤","오랜밤","오랜만"],"answerIndex":3}]'::jsonb, 34)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('gymnastics-fall', '🤸', '체조왕의 실수', '["지훈이는 학교 체조부에서 가장 뛰어난 실력을 가진 선수로 유명했어요.","전교생이 지켜보는 학예회 무대에서 지훈이는 마루운동을 선보이기로 했어요.","자신만만하게 뛰어오르던 지훈이는 그만 발이 미끄러져 엉덩방아를 찧고 말았어요.","몇몇 아이들이 웃음을 터뜨렸지만, 지훈이는 얼굴이 빨개진 채로 다시 일어나 마지막까지 연기를 마쳤어요.","선생님은 \"아무리 뛰어난 사람도 실수할 수 있다\"며 끝까지 포기하지 않은 지훈이를 칭찬해 주셨어요.","지훈이는 실수했다고 부끄러워만 할 게 아니라, 다시 일어서는 것이 더 중요하다는 것을 배웠어요."]'::jsonb, '[{"word":"자신만만하다","meaning":"어떤 일을 잘할 수 있다고 스스로 굳게 믿다"},{"word":"엉덩방아를 찧다","meaning":"중심을 잃고 엉덩이로 세게 넘어지다"},{"word":"포기하다","meaning":"하려던 일을 도중에 그만두다"}]'::jsonb, '[{"answer":true,"statement":"지훈이는 학교 체조부에서 실력이 뛰어난 선수였다."},{"answer":false,"statement":"지훈이는 넘어진 뒤 바로 무대에서 내려갔다."},{"answer":true,"statement":"선생님은 지훈이가 끝까지 포기하지 않은 것을 칭찬했다."}]'::jsonb, '{"choices":["실력이 뛰어난 사람은 절대 실수하지 않는다","아무리 뛰어난 사람도 실수할 수 있고, 다시 일어서는 것이 중요하다","체조는 위험하니 하지 않는 것이 좋다","무대에서 넘어지면 다시 도전하지 않는 것이 좋다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"자신만만하다","choices":["아무 관심이 없다","남을 부러워하다","몹시 두려워하며 망설이다","잘할 수 있다고 스스로 굳게 믿다"],"answerIndex":3},{"type":"proverb","word":"원숭이도 나무에서 떨어진다","choices":["한번 실수하면 다시는 성공할 수 없다","나무에 오르는 것은 위험한 일이다","동물은 사람보다 재주가 뛰어나다","아무리 뛰어난 사람도 실수할 때가 있다"],"answerIndex":3},{"type":"synonym","word":"포기하다","choices":["시작하다","그만두다","계속하다","도전하다"],"answerIndex":1},{"type":"antonym","word":"자신만만하다","choices":["자랑스러워하다","자신 없어하다","뿌듯해하다","기뻐하다"],"answerIndex":1},{"type":"spelling","word":"설거지","choices":["설걷이","설것이","설거지","설겆이"],"answerIndex":2}]'::jsonb, 35)
