insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('classroom-rumor', '🗣️', '한 마디가 부풀려질 때', '["수아는 짝꿍에게 장난삼아 \"나 오늘 시험 하나도 못 봤어\"라고 작게 말했어요.","그 말은 옆자리 친구를 거쳐, 다음 시간에는 \"수아가 시험을 완전히 망쳐서 울었대\"로 바뀌어 있었어요.","쉬는 시간이 되자 반 아이들 모두가 걱정스러운 얼굴로 수아를 쳐다보았어요.","수아는 깜짝 놀라 \"나 안 울었고, 시험도 그냥 평범하게 봤어!\"라고 서둘러 말해야 했어요.","작은 말 한마디가 여러 사람을 거치며 눈덩이처럼 부풀려질 수 있다는 것을 수아는 그제야 실감했어요.","그날 이후 수아는 확인되지 않은 이야기를 함부로 옮기지 않기로 마음먹었어요."]'::jsonb, '[{"word":"장난삼다","meaning":"진지하지 않게 재미로 어떤 행동을 하다"},{"word":"부풀리다","meaning":"실제보다 크거나 과장되게 하다"},{"word":"실감하다","meaning":"실제로 겪는 듯한 느낌을 받다"}]'::jsonb, '[{"answer":true,"statement":"수아는 처음에 \"시험을 하나도 못 봤다\"고 작게 말했다."},{"answer":true,"statement":"소문은 반 아이들을 거치면서 점점 부풀려졌다."},{"answer":false,"statement":"수아는 소문이 사실이라고 인정했다."}]'::jsonb, '{"choices":["작은 말 한마디도 옮겨지며 크게 부풀려질 수 있으니 조심해야 한다","소문은 시간이 지나면 저절로 사라진다","시험을 못 보는 것은 부끄러운 일이 아니다","친구에게는 어떤 이야기든 솔직히 말해야 한다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"부풀리다","choices":["실제보다 크거나 과장되게 하다","있는 그대로 정확히 전하다","작고 볼품없게 만들다","조용히 감추다"],"answerIndex":0},{"type":"proverb","word":"발 없는 말이 천리 간다","choices":["조용히 있으면 소문이 나지 않는다","말을 잘하면 어디서나 인정받는다","발이 있어야 멀리 갈 수 있다","말은 순식간에 멀리까지 퍼져 나간다"],"answerIndex":3},{"type":"synonym","word":"실감하다","choices":["느끼다","잊다","숨기다","외면하다"],"answerIndex":0},{"type":"antonym","word":"부풀리다","choices":["줄이다","더하다","키우다","늘리다"],"answerIndex":0},{"type":"spelling","word":"개수","choices":["개쑤","개수","갯쑤","갯수"],"answerIndex":1}]'::jsonb, 36)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('harsh-words-echo', '💬', '가시 돋친 말 한마디', '["체육 시간에 공을 놓친 준영이에게 짝꿍 하윤이가 \"그것도 못 받아?\" 하고 톡 쏘아붙였어요.","기분이 상한 준영이는 다음 놀이에서 하윤이의 실수를 보고 똑같이 날카롭게 놀렸어요.","둘은 결국 서로에게 뾰족한 말만 주고받다가 놀이를 다 망치고 말았어요.","다음 날, 하윤이가 먼저 다가와 \"어제 내가 심하게 말해서 미안해\" 하고 사과했어요.","준영이도 \"나도 똑같이 말해서 미안해\" 하며 웃었고, 둘은 예전처럼 사이좋게 놀 수 있었어요.","하윤이는 자신이 건넨 말이 결국 자신에게 비슷한 모양으로 돌아온다는 것을 느꼈어요."]'::jsonb, '[{"word":"쏘아붙이다","meaning":"날카롭고 매섭게 말하다"},{"word":"뾰족하다","meaning":"말이나 태도가 부드럽지 않고 날카롭다"},{"word":"건네다","meaning":"말이나 물건을 상대에게 전하다"}]'::jsonb, '[{"answer":true,"statement":"하윤이는 준영이가 공을 놓치자 날카롭게 말했다."},{"answer":false,"statement":"준영이는 하윤이에게 화내지 않고 곧바로 웃어넘겼다."},{"answer":true,"statement":"다음 날 하윤이가 먼저 사과하며 화해가 이루어졌다."}]'::jsonb, '{"choices":["운동을 잘 못하면 놀림을 받아도 어쩔 수 없다","사과는 실수를 저지른 사람만 하면 된다","고운 말을 건네야 나에게도 고운 말이 돌아온다","한번 상한 사이는 다시 회복되기 어렵다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"쏘아붙이다","choices":["재미있게 농담하다","조용하고 부드럽게 말하다","날카롭고 매섭게 말하다","작게 속삭이다"],"answerIndex":2},{"type":"proverb","word":"가는 말이 고와야 오는 말이 곱다","choices":["내가 남에게 좋게 말해야 상대도 좋게 말해 준다","말은 예쁘게 꾸며야 인기가 많다","오고 가는 말은 서로 다를 수밖에 없다","먼 길을 갈 때는 말을 아껴야 한다"],"answerIndex":0},{"type":"synonym","word":"뾰족하다","choices":["둥글다","부드럽다","날카롭다","따뜻하다"],"answerIndex":2},{"type":"antonym","word":"뾰족하다","choices":["부드럽다","차갑다","단단하다","날카롭다"],"answerIndex":0},{"type":"spelling","word":"찌개","choices":["찌개","찌겟","찌계","찌게"],"answerIndex":0}]'::jsonb, 37)
