insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('messy-desk-habit', '🗂️', '책상이 알려 주는 것', '["수업이 끝날 때마다 도현이의 책상 서랍은 구겨진 종이와 부러진 연필로 가득했어요.","숙제를 낼 때도 도현이는 구겨진 종이 뭉치 속에서 필요한 것을 한참 찾아야 했어요.","선생님은 도현이의 어질러진 서랍을 보시고는 \"정리하는 습관이 다른 일에도 영향을 준단다\"라고 말씀하셨어요.","도현이는 반신반의하며 그날부터 서랍과 사물함을 매일 조금씩 정리해 보기로 했어요.","며칠이 지나자 신기하게도 준비물을 챙기는 것도, 숙제를 제때 내는 것도 한결 수월해졌어요.","도현이는 작은 습관 하나가 여러 가지 일에 두루 영향을 미친다는 것을 몸소 느꼈어요."]'::jsonb, '[{"word":"반신반의하다","meaning":"어느 정도는 믿으면서도 한편으로는 의심하다"},{"word":"두루","meaning":"빠짐없이 여러 곳에 널리"},{"word":"몸소","meaning":"자기 몸으로 직접"}]'::jsonb, '[{"answer":false,"statement":"도현이의 서랍은 항상 깔끔하게 정리되어 있었다."},{"answer":true,"statement":"도현이는 선생님의 말씀을 듣고 서랍을 정리해 보기로 했다."},{"answer":false,"statement":"정리를 시작한 뒤에도 숙제를 내는 것은 여전히 어려웠다."}]'::jsonb, '{"choices":["연필이 부러지면 새로 사면 된다","책상 정리는 시간 낭비이다","숙제는 정리와 아무 상관이 없다","작은 습관 하나가 여러 가지 일에 영향을 줄 수 있다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"반신반의하다","choices":["어느 정도 믿으면서도 한편으로 의심하다","완전히 확신하다","매우 기뻐하다","전혀 관심이 없다"],"answerIndex":0},{"type":"proverb","word":"하나를 보면 열을 안다","choices":["열 가지를 다 겪어야 하나를 알 수 있다","무엇이든 여러 번 봐야 정확히 안다","한 가지 모습을 보면 그 사람의 다른 면도 짐작할 수 있다","한 가지 일에만 집중해야 성공한다"],"answerIndex":2},{"type":"synonym","word":"두루","choices":["가끔","전혀","몰래","골고루"],"answerIndex":3},{"type":"antonym","word":"수월하다","choices":["쉽다","편하다","간단하다","까다롭다"],"answerIndex":3},{"type":"spelling","word":"육개장","choices":["육게짱","육개장","육게장","육개짱"],"answerIndex":1}]'::jsonb, 38)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('nail-biting-habit', '💅', '손톱 깨무는 버릇', '["서윤이는 어릴 때부터 긴장하면 손톱을 깨무는 버릇이 있었어요.","유치원 때는 아무도 신경 쓰지 않았지만, 고학년이 되자 친구들이 하나둘 그 버릇을 눈치채기 시작했어요.","발표를 앞두고 손톱을 깨물던 서윤이를 본 친구가 \"그거 고치기 힘들지?\" 하고 물었어요.","서윤이는 몇 번이나 고치려 했지만 자기도 모르게 손이 입으로 갈 때가 많다고 털어놓았어요.","선생님은 어릴 때 생긴 작은 버릇은 시간이 지날수록 고치기 어려워진다며, 지금부터라도 조금씩 노력해 보자고 격려해 주셨어요.","서윤이는 손톱 대신 만질 수 있는 작은 공을 주머니에 넣고 다니며 버릇을 조금씩 줄여 나갔어요."]'::jsonb, '[{"word":"눈치채다","meaning":"남이 겉으로 드러내지 않은 마음이나 사실을 알아차리다"},{"word":"털어놓다","meaning":"마음속에 있는 사실이나 생각을 숨김없이 말하다"},{"word":"격려하다","meaning":"용기나 힘을 북돋아 주다"}]'::jsonb, '[{"answer":true,"statement":"서윤이는 긴장하면 손톱을 깨무는 버릇이 있었다."},{"answer":false,"statement":"서윤이는 유치원 때부터 그 버릇을 완전히 고쳤다."},{"answer":true,"statement":"선생님은 서윤이에게 조금씩 노력해 보자고 격려해 주셨다."}]'::jsonb, '{"choices":["어릴 때 생긴 버릇은 시간이 지날수록 고치기 어려우니 미리 신경 써야 한다","긴장하는 것은 부끄러운 일이다","손톱은 짧게 자를수록 좋다","버릇은 저절로 사라지니 신경 쓰지 않아도 된다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"격려하다","choices":["조용히 지켜보기만 하다","무관심하게 지나치다","용기나 힘을 북돋아 주다","심하게 나무라다"],"answerIndex":2},{"type":"proverb","word":"세 살 버릇 여든까지 간다","choices":["버릇은 어릴 때만 조심하면 충분하다","어릴 때 생긴 버릇은 나이가 들어도 쉽게 고쳐지지 않는다","여든 살이 되면 모든 버릇이 사라진다","나이가 들수록 버릇이 자꾸 바뀐다"],"answerIndex":1},{"type":"synonym","word":"털어놓다","choices":["고백하다","외면하다","잊어버리다","숨기다"],"answerIndex":0},{"type":"antonym","word":"눈치채다","choices":["깨닫다","짐작하다","알아차리다","모르다"],"answerIndex":3},{"type":"spelling","word":"가르치다","choices":["가리치다","가르키다","가르치다","가르케다"],"answerIndex":2}]'::jsonb, 39)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('marathon-training', '🏃', '오 킬로미터의 기록', '["체육 대회 마라톤 종목에 나가기로 한 준희는 매일 아침 오 킬로미터를 뛰기로 마음먹었어요.","처음 며칠은 다리가 아파서 걷다시피 겨우 완주했고, 그만두고 싶은 마음이 굴뚝같았어요.","그래도 준희는 하루도 빠짐없이 운동화 끈을 묶고 집을 나섰어요.","한 달이 지나자 숨이 덜 차올랐고, 두 달이 지나자 처음보다 오 분이나 빠르게 완주할 수 있었어요.","대회 날, 준희는 마침내 목표했던 기록을 세우고 결승선을 통과했어요.","숨을 몰아쉬며 웃는 준희의 얼굴에는 그동안의 고단함을 잊게 하는 기쁨이 가득했어요."]'::jsonb, '[{"word":"굴뚝같다","meaning":"어떤 마음이 매우 간절하다"},{"word":"완주하다","meaning":"목표한 거리를 끝까지 다 달리다"},{"word":"고단하다","meaning":"몸이 지쳐서 힘들다"}]'::jsonb, '[{"answer":true,"statement":"준희는 매일 아침 오 킬로미터를 뛰기로 마음먹었다."},{"answer":false,"statement":"준희는 처음부터 빠르게 완주할 수 있었다."},{"answer":false,"statement":"대회 날 준희는 목표했던 기록을 세우지 못했다."}]'::jsonb, '{"choices":["기록은 노력과 상관없이 정해져 있다","힘든 과정을 꾸준히 견디면 결국 기쁨이 찾아온다","마라톤은 타고난 사람만 잘할 수 있다","운동은 힘드니 적당히 하는 것이 좋다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"고단하다","choices":["기분이 아주 상쾌하다","매우 재미있다","몹시 지루하다","몸이 지쳐서 힘들다"],"answerIndex":3},{"type":"proverb","word":"고생 끝에 낙이 온다","choices":["힘든 일을 견디고 나면 결국 즐거운 일이 찾아온다","낙은 노력 없이 저절로 온다","고생은 아무리 해도 보람이 없다","즐거운 일 뒤에는 반드시 고생이 따른다"],"answerIndex":0},{"type":"synonym","word":"고단하다","choices":["지치다","가뿐하다","즐겁다","상쾌하다"],"answerIndex":0},{"type":"antonym","word":"완주하다","choices":["중도에 포기하다","천천히 걷다","빠르게 달리다","끝까지 달리다"],"answerIndex":0},{"type":"spelling","word":"담그다","choices":["담구다","담다","담기다","담그다"],"answerIndex":3}]'::jsonb, 40)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('hallway-whisper', '👂', '복도에서 나눈 귓속말', '["지우와 하은이는 복도 구석에서 다른 친구의 흉을 작은 목소리로 나누고 있었어요.","아무도 듣지 못했을 거라 생각했지만, 마침 지나가던 선생님이 그 말을 들으셨어요.","선생님은 두 사람을 조용히 불러 \"아무도 없다고 생각한 곳에서도 말은 새어 나갈 수 있단다\"라고 타이르셨어요.","지우와 하은이는 얼굴이 빨개진 채로 그 친구에게 진심으로 사과했어요.","그 뒤로 두 사람은 누군가에 대한 이야기를 할 때마다 한 번 더 생각하고 조심하게 되었어요.","지우는 아무리 조용한 곳이라도 말은 언젠가 전해질 수 있다는 것을 마음에 새겼어요."]'::jsonb, '[{"word":"흉","meaning":"남의 결점이나 잘못을 흉보아 말하는 것"},{"word":"타이르다","meaning":"잘 깨닫도록 부드럽게 말하여 가르치다"},{"word":"새기다","meaning":"잊지 않도록 마음속에 깊이 기억하다"}]'::jsonb, '[{"answer":false,"statement":"지우와 하은이는 복도에서 큰 소리로 이야기했다."},{"answer":true,"statement":"선생님은 두 사람이 나눈 이야기를 들으셨다."},{"answer":false,"statement":"지우와 하은이는 사과하지 않고 그냥 넘어갔다."}]'::jsonb, '{"choices":["선생님은 학생들의 대화를 엿들으면 안 된다","친구의 흉을 보는 것은 재미있는 놀이이다","아무도 없다고 생각한 곳에서도 말은 새어 나갈 수 있으니 말을 조심해야 한다","복도에서는 어떤 이야기를 해도 괜찮다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"타이르다","choices":["잘 깨닫도록 부드럽게 말하여 가르치다","아무 말 없이 무시하다","재미있는 이야기를 들려주다","큰 소리로 심하게 화를 내다"],"answerIndex":0},{"type":"proverb","word":"낮말은 새가 듣고 밤말은 쥐가 듣는다","choices":["아무리 조심스럽게 말해도 남의 말은 결국 전해지기 쉽다","낮에는 새소리 때문에 말이 잘 들리지 않는다","밤에 하는 말은 절대 새어 나가지 않는다","동물들은 사람의 말을 알아듣지 못한다"],"answerIndex":0},{"type":"synonym","word":"타이르다","choices":["놀리다","외면하다","일깨우다","나무라다"],"answerIndex":2},{"type":"antonym","word":"새기다","choices":["기억하다","되새기다","깨닫다","잊어버리다"],"answerIndex":3},{"type":"spelling","word":"치르다","choices":["치리다","치르다","치루다","치라다"],"answerIndex":1}]'::jsonb, 41)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('exam-recheck', '✏️', '다시 확인한 시험지', '["시험이 끝나기 십 분 전, 재민이는 이미 모든 문제를 다 풀고 자신만만하게 손을 놓았어요.","짝꿍 서아는 다 풀었는데도 남은 시간 동안 문제를 처음부터 다시 꼼꼼히 확인했어요.","재민이는 \"다 맞았는데 뭘 그렇게 다시 봐?\" 하며 의아해했어요.","시험지를 돌려받은 날, 재민이는 계산 실수로 두 문제를 틀렸고, 서아는 검토 덕분에 실수를 미리 고쳐 만점을 받았어요.","재민이는 다 아는 문제라고 방심했던 것이 실수로 이어졌다는 것을 깨달았어요.","그날 이후 재민이도 시험이 끝나면 반드시 한 번 더 검산하는 습관을 들이기로 했어요."]'::jsonb, '[{"word":"의아해하다","meaning":"뜻밖의 일로 이상하게 여기다"},{"word":"검토하다","meaning":"내용을 자세히 따져서 살펴보다"},{"word":"방심하다","meaning":"마음을 놓고 주의를 기울이지 않다"}]'::jsonb, '[{"answer":false,"statement":"재민이는 문제를 다 풀고 남은 시간에 다시 확인했다."},{"answer":true,"statement":"서아는 다 풀고도 처음부터 다시 확인했다."},{"answer":true,"statement":"재민이는 계산 실수로 두 문제를 틀렸다."}]'::jsonb, '{"choices":["시험은 빨리 푸는 것이 가장 중요하다","다 아는 문제라도 방심하지 말고 다시 확인하는 태도가 필요하다","실수는 누구나 하니 신경 쓸 필요 없다","검토하는 시간은 낭비이다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"방심하다","choices":["기쁘게 웃다","마음을 놓고 주의를 기울이지 않다","몹시 슬퍼하다","매우 조심스럽게 행동하다"],"answerIndex":1},{"type":"proverb","word":"돌다리도 두들겨 보고 건너라","choices":["급할수록 서둘러야 한다","튼튼한 다리는 확인할 필요가 없다","잘 아는 일이라도 다시 한번 확인하고 조심해야 한다","돌다리는 나무다리보다 위험하다"],"answerIndex":2},{"type":"synonym","word":"검토하다","choices":["무시하다","살펴보다","외면하다","잊다"],"answerIndex":1},{"type":"antonym","word":"방심하다","choices":["자만하다","게을리하다","주의하다","느긋하다"],"answerIndex":2},{"type":"spelling","word":"사귀었다","choices":["사귀였다","사귀었다","사겼다","사귔다"],"answerIndex":1}]'::jsonb, 42)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('mountain-climbing-again', '⛰️', '봉우리 너머 또 봉우리', '["가족 등산에서 하영이는 첫 번째 봉우리에 오르면 정상인 줄 알았어요.","하지만 봉우리에 올라서니 그 너머로 더 높은 봉우리가 또 이어져 있었어요.","하영이는 다리가 후들거려서 그 자리에 주저앉을 뻔했지만, 아빠는 \"한 걸음씩 가다 보면 결국 닿게 된단다\"라고 격려해 주셨어요.","두 번째 봉우리를 넘자 세 번째 봉우리가 나타났고, 하영이는 잠시 한숨이 나왔어요.","그래도 포기하지 않고 걸음을 옮긴 끝에, 하영이는 마침내 진짜 정상에 올라 시원한 바람을 맞을 수 있었어요.","하영이는 어려움이 하나 끝나면 새로운 어려움이 또 나타날 수 있지만, 포기하지 않으면 결국 끝에 다다른다는 것을 배웠어요."]'::jsonb, '[{"word":"후들거리다","meaning":"다리나 몸이 힘이 빠져 떨리다"},{"word":"다다르다","meaning":"목적한 곳에 이르러 닿다"},{"word":"한숨","meaning":"근심이나 피로로 내쉬는 숨"}]'::jsonb, '[{"answer":true,"statement":"하영이는 첫 번째 봉우리가 정상인 줄 알았다."},{"answer":false,"statement":"두 번째 봉우리를 넘은 뒤 더 이상 오를 곳이 없었다."},{"answer":false,"statement":"하영이는 결국 포기하고 산을 내려왔다."}]'::jsonb, '{"choices":["첫 번째 성공이 가장 중요하다","어려움이 계속 이어지더라도 포기하지 않으면 결국 목표에 다다를 수 있다","등산은 위험하니 가족과 함께 가면 안 된다","산은 낮을수록 오르기 좋다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"다다르다","choices":["중간에 멈추다","길을 잃고 헤매다","목적한 곳에 이르러 닿다","뒤로 물러나다"],"answerIndex":2},{"type":"proverb","word":"산 넘어 산","choices":["높은 산일수록 오르기 쉽다","산은 넘을수록 낮아진다","어려운 일이 끝났다고 여겼는데 또 다른 어려움이 이어진다","한 번 산을 넘으면 다시는 힘든 일이 없다"],"answerIndex":2},{"type":"synonym","word":"다다르다","choices":["도달하다","벗어나다","멀어지다","피하다"],"answerIndex":0},{"type":"antonym","word":"포기하다","choices":["체념하다","단념하다","도전하다","그만두다"],"answerIndex":2},{"type":"spelling","word":"삼가 주세요","choices":["삼가고 주세요","삼가 주세요","삼가서 주세요","삼가해 주세요"],"answerIndex":1}]'::jsonb, 43)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('garden-harvest', '🌱', '텃밭에서 배운 정직', '["봄이 되자 5학년 아이들은 학교 텃밭에 저마다 씨앗을 심었어요.","재하는 물 주기가 귀찮아서 며칠씩 건너뛰었고, 도윤이는 매일 아침 꼬박꼬박 물을 주었어요.","한 달 뒤, 재하의 화분에는 시든 싹만 겨우 남아 있었지만, 도윤이의 화분에는 튼튼한 잎이 무성하게 자라 있었어요.","재하는 속상해하며 \"왜 내 것만 이렇게 됐지?\" 하고 중얼거렸어요.","선생님은 \"심은 만큼, 돌본 만큼 자라는 것이 식물이란다\"라고 웃으며 말씀해 주셨어요.","재하는 그 말을 듣고 다음 학기에는 매일 물을 주기로 다짐했어요."]'::jsonb, '[{"word":"건너뛰다","meaning":"차례나 순서를 거치지 않고 넘어가다"},{"word":"무성하다","meaning":"풀이나 나무 등이 우거져 있다"},{"word":"다짐하다","meaning":"마음을 굳게 정하다"}]'::jsonb, '[{"answer":false,"statement":"재하는 매일 텃밭에 물을 주었다."},{"answer":true,"statement":"도윤이의 화분에는 잎이 무성하게 자랐다."},{"answer":false,"statement":"재하는 자신의 화분이 잘 자란 것에 만족했다."}]'::jsonb, '{"choices":["노력하고 돌본 만큼 결과가 따라온다","텃밭 가꾸기는 어른들이 해야 할 일이다","식물은 물을 많이 줄수록 좋다","씨앗은 아무렇게나 심어도 잘 자란다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"무성하다","choices":["땅이 메마르고 척박하다","색이 흐릿하고 옅다","풀이나 나무 등이 우거져 있다","크기가 아주 작다"],"answerIndex":2},{"type":"proverb","word":"콩 심은 데 콩 나고 팥 심은 데 팥 난다","choices":["원인에 맞는 결과가 나타난다","콩과 팥은 같은 식물이다","무엇을 심든 결과는 항상 같다","농사는 날씨에만 좌우된다"],"answerIndex":0},{"type":"synonym","word":"다짐하다","choices":["망설이다","후회하다","포기하다","결심하다"],"answerIndex":3},{"type":"antonym","word":"무성하다","choices":["풍성하다","울창하다","빽빽하다","앙상하다"],"answerIndex":3},{"type":"spelling","word":"편지를 부치다","choices":["편지를 부치이다","편지를 붙이다","편지를 붇이다","편지를 부치다"],"answerIndex":3}]'::jsonb, 44)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('field-trip-two-birds', '🦆', '체험학습에서 얻은 두 가지', '["학교에서 간 생태 체험학습은 원래 봉사 활동으로 계획된 것이었어요.","아이들은 습지에서 쓰레기를 줍는 동안 물새와 물고기, 곤충들을 가까이에서 관찰할 수 있었어요.","재이는 처음에는 봉사 활동이라 지루할 줄 알았는데, 도감에서만 보던 새를 직접 보게 되어 신이 났어요.","봉사도 하고 자연 관찰 숙제도 자연스럽게 끝낸 재이는 일석이조라는 말이 실감 났어요.","집에 돌아와 재이는 관찰한 새와 곤충을 그림으로 그려 관찰 일기를 완성했어요.","재이는 한 가지 활동으로 두 가지 보람을 얻은 그날의 체험학습을 오래 기억하기로 했어요."]'::jsonb, '[{"word":"습지","meaning":"물기가 많고 축축한 땅"},{"word":"도감","meaning":"동식물 등을 그림이나 사진으로 설명한 책"},{"word":"보람","meaning":"어떤 일을 한 뒤에 얻는 좋은 결과나 만족감"}]'::jsonb, '[{"answer":true,"statement":"체험학습은 원래 봉사 활동으로 계획된 것이었다."},{"answer":false,"statement":"아이들은 습지에서 아무 동물도 보지 못했다."},{"answer":true,"statement":"재이는 체험학습 덕분에 관찰 일기 숙제까지 끝낼 수 있었다."}]'::jsonb, '{"choices":["한 가지 활동으로 두 가지 보람을 얻을 수도 있다","자연 관찰은 도감으로만 해야 한다","숙제는 미리미리 끝내야 한다","봉사 활동은 항상 지루하고 힘들다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"보람","choices":["아무 의미 없는 헛수고","어떤 일을 한 뒤에 얻는 좋은 결과나 만족감","몹시 지치고 피곤한 느낌","갑작스럽게 놀라는 마음"],"answerIndex":1},{"type":"proverb","word":"꿩 먹고 알 먹기","choices":["꿩과 알은 맛이 서로 다르다","한 가지 일에만 집중해야 한다","욕심을 부리면 아무것도 얻지 못한다","한 가지 일을 하고 두 가지 이익을 얻는다"],"answerIndex":3},{"type":"synonym","word":"보람","choices":["지루함","허무함","성취감","두려움"],"answerIndex":2},{"type":"antonym","word":"습지","choices":["산지","건조지","평지","농지"],"answerIndex":1},{"type":"spelling","word":"웃어른","choices":["위어른","웃어른","웃웃어른","윗어른"],"answerIndex":1}]'::jsonb, 45)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('easy-quiz-surprise', '🧩', '식은 죽 먹기라던 문제', '["수학 단원평가를 앞두고 은재는 \"이 단원은 쉬워서 공부 안 해도 돼\"라며 자신 있어 했어요.","친구들이 문제집을 풀 때도 은재는 게임을 하며 여유롭게 시간을 보냈어요.","막상 시험지를 받아 보니 응용문제 몇 개가 생각보다 훨씬 까다로웠어요.","은재는 당황해서 손이 떨렸고, 결국 쉬울 거라 여겼던 단원에서 가장 낮은 점수를 받고 말았어요.","집에 돌아온 은재는 \"쉬워 보인다고 방심하면 안 되는구나\" 하고 스스로를 돌아보았어요.","다음 시험부터 은재는 어떤 단원이든 미리 꼼꼼하게 준비하기로 마음먹었어요."]'::jsonb, '[{"word":"여유롭다","meaning":"시간이나 마음에 넉넉함이 있다"},{"word":"까다롭다","meaning":"조건이 복잡하고 다루기 어렵다"},{"word":"돌아보다","meaning":"지나온 일을 다시 생각해 보다"}]'::jsonb, '[{"answer":false,"statement":"은재는 시험 전에 열심히 공부했다."},{"answer":true,"statement":"시험 문제 중 응용문제가 생각보다 어려웠다."},{"answer":false,"statement":"은재는 그 단원에서 가장 높은 점수를 받았다."}]'::jsonb, '{"choices":["게임은 공부에 도움이 된다","시험 점수는 운에 달려 있다","쉬워 보이는 일도 방심하지 말고 꼼꼼히 준비해야 한다","수학은 원래 어려운 과목이다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"까다롭다","choices":["조건이 복잡하고 다루기 어렵다","기분이 아주 좋다","크기가 아담하다","매우 간단하고 쉽다"],"answerIndex":0},{"type":"proverb","word":"식은 죽 먹기","choices":["차갑고 맛없는 음식","매우 쉽게 할 수 있는 일","오래 걸리는 힘든 작업","몹시 어렵고 힘든 일"],"answerIndex":1},{"type":"synonym","word":"까다롭다","choices":["단순하다","간단하다","복잡하다","수월하다"],"answerIndex":2},{"type":"antonym","word":"여유롭다","choices":["빠듯하다","넉넉하다","한가하다","느긋하다"],"answerIndex":0},{"type":"spelling","word":"윗사람","choices":["윗사람","웃사람","윗쌈","위사람"],"answerIndex":0}]'::jsonb, 46)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('small-village-champion', '🏆', '작은 마을에서 온 챔피언', '["전국 어린이 바둑 대회 우승자는 놀랍게도 인구 오백 명이 채 안 되는 작은 산골 마을 출신이었어요.","많은 사람들이 \"그런 작은 마을에서 어떻게 저런 실력이 나왔지?\" 하며 신기해했어요.","알고 보니 그 아이는 마을 도서관에서 매일 두 시간씩 혼자 바둑 책을 읽고 연습해 왔다고 해요.","변변한 바둑 학원 하나 없는 곳이었지만, 아이는 인터넷 강의와 책만으로 꾸준히 실력을 쌓아 왔어요.","기자가 비결을 묻자 아이는 \"환경이 좋지 않아도 매일 조금씩 하면 된다고 생각했어요\"라고 답했어요.","사람들은 그 대답을 듣고 환경보다 중요한 것은 꾸준한 노력이라는 것을 새삼 깨달았어요."]'::jsonb, '[{"word":"산골","meaning":"외지고 산이 많은 시골"},{"word":"변변하다","meaning":"제대로 갖추어져 충분하다"},{"word":"비결","meaning":"남이 알지 못하는 자기만의 뛰어난 방법"}]'::jsonb, '[{"answer":false,"statement":"우승자는 큰 도시에서 자란 아이였다."},{"answer":true,"statement":"그 아이는 마을 도서관에서 혼자 바둑을 연습했다."},{"answer":false,"statement":"아이는 값비싼 바둑 학원에 다니며 실력을 쌓았다."}]'::jsonb, '{"choices":["바둑은 도시에 사는 아이들이 더 잘한다","대회에서 우승하려면 학원에 다녀야 한다","환경이 좋지 않아도 꾸준한 노력이 있으면 큰 성취를 이룰 수 있다","좋은 환경이 없으면 실력을 쌓을 수 없다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"비결","choices":["오래된 전통 놀이","누구나 다 아는 평범한 사실","남이 알지 못하는 자기만의 뛰어난 방법","실패하는 원인"],"answerIndex":2},{"type":"proverb","word":"개천에서 용 난다","choices":["좋은 환경에서만 훌륭한 인물이 나온다","개천은 위험하니 가까이 가면 안 된다","용은 항상 물이 많은 곳에서만 산다","어려운 환경에서도 훌륭한 인물이 나올 수 있다"],"answerIndex":3},{"type":"synonym","word":"비결","choices":["평범","실수","비법","우연"],"answerIndex":2},{"type":"antonym","word":"변변하다","choices":["충분하다","풍족하다","부족하다","넉넉하다"],"answerIndex":2},{"type":"spelling","word":"넉넉지","choices":["너넉지","넉넙지","넉넉치","넉넉지"],"answerIndex":3}]'::jsonb, 47)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('five-fingers-love', '✋', '열 손가락 깨물어 안 아픈 손가락', '["막내인 도희는 늘 \"엄마는 언니만 예뻐해\"라며 투정을 부리곤 했어요.","어느 날 도희가 넘어져 무릎을 다치자 엄마는 하던 일을 멈추고 한걸음에 달려와 도희를 살폈어요.","그 모습을 본 언니가 \"저번에 나 넘어졌을 때도 엄마 저렇게 놀라셨었어\" 하고 말해 주었어요.","도희는 그제야 엄마가 자신에게만 소홀했던 것이 아니라는 것을 깨달았어요.","엄마는 도희를 꼭 안아 주며 \"너희 둘 다 나에게는 하나같이 소중해서 비교할 수가 없어\"라고 말씀하셨어요.","도희는 그 말을 듣고 나서야 마음속 서운함이 스르르 녹아내리는 것을 느꼈어요."]'::jsonb, '[{"word":"투정을 부리다","meaning":"자기 뜻에 맞지 않아 떼를 쓰며 조르다"},{"word":"소홀하다","meaning":"중요하게 여기지 않아 정성이 부족하다"},{"word":"서운하다","meaning":"마음에 아쉽고 섭섭하다"}]'::jsonb, '[{"answer":true,"statement":"도희는 늘 엄마가 언니만 예뻐한다고 투정을 부렸다."},{"answer":false,"statement":"도희가 다쳤을 때 엄마는 신경 쓰지 않으셨다."},{"answer":true,"statement":"언니는 엄마가 자신에게도 놀라셨던 적이 있다고 말해 주었다."}]'::jsonb, '{"choices":["부모님은 자녀 중 한 명만 더 아낀다","형제자매는 서로 비교하며 자라야 한다","막내는 늘 서운함을 느낄 수밖에 없다","부모님에게는 자녀 모두가 똑같이 소중한 존재이다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"소홀하다","choices":["몹시 화가 나 있다","기쁘고 즐겁다","중요하게 여기지 않아 정성이 부족하다","매우 정성스럽고 세심하다"],"answerIndex":2},{"type":"proverb","word":"열 손가락 깨물어 안 아픈 손가락 없다","choices":["부모에게는 자녀 모두가 다 소중하고 귀하다","손가락은 열 개 모두 크기가 같다","아픈 손가락일수록 더 조심해야 한다","자녀 중 한 명이 가장 중요하다"],"answerIndex":0},{"type":"synonym","word":"서운하다","choices":["뿌듯하다","든든하다","섭섭하다","기쁘다"],"answerIndex":2},{"type":"antonym","word":"소홀하다","choices":["부족하다","정성스럽다","무관심하다","소극적이다"],"answerIndex":1},{"type":"spelling","word":"익숙지","choices":["익숙찌","익슥지","익숙지","익숙치"],"answerIndex":2}]'::jsonb, 48)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('short-kid-wrestling', '🤼', '작은 씨름 선수의 우승', '["체육 대회 씨름 경기에서 반에서 가장 키가 작은 태오가 출전하겠다고 나섰어요.","몇몇 친구들은 \"네가 이길 수 있겠어?\"라며 걱정 섞인 말을 건넸어요.","하지만 태오는 낮은 무게 중심을 이용해 상대의 다리를 재빠르게 걸어 넘겼어요.","큰 덩치의 상대 선수들은 태오의 날쌘 몸놀림에 번번이 균형을 잃고 쓰러졌어요.","결국 태오는 결승까지 올라가 그 누구도 예상하지 못했던 우승을 차지했어요.","친구들은 몸집이 작다고 실력까지 작은 것은 아니라는 사실을 그날 확실히 알게 되었어요."]'::jsonb, '[{"word":"무게 중심","meaning":"물체의 무게가 균형을 이루는 중심점"},{"word":"날쌔다","meaning":"움직임이 빠르고 재빠르다"},{"word":"번번이","meaning":"매번, 그때마다 다름없이"}]'::jsonb, '[{"answer":true,"statement":"태오는 반에서 가장 키가 작은 편이었다."},{"answer":false,"statement":"친구들은 모두 태오가 반드시 이길 거라고 믿었다."},{"answer":true,"statement":"태오는 결국 씨름 대회에서 우승했다."}]'::jsonb, '{"choices":["작은 사람은 운동 경기에 나가지 않는 것이 좋다","체육 대회는 승부보다 참여가 중요하다","씨름은 몸집이 큰 사람만 잘할 수 있다","몸집이 작아도 실력과 기술로 큰 상대를 이길 수 있다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"날쌔다","choices":["몸집이 아주 크다","조용하고 차분하다","동작이 굼뜨고 느리다","움직임이 빠르고 재빠르다"],"answerIndex":3},{"type":"proverb","word":"작은 고추가 더 맵다","choices":["고추는 작을수록 맛이 없다","매운 음식은 몸에 좋지 않다","큰 사람이 항상 더 강하다","몸집이 작아도 재주나 능력은 오히려 더 뛰어날 수 있다"],"answerIndex":3},{"type":"synonym","word":"날쌔다","choices":["무겁다","느리다","재빠르다","둔하다"],"answerIndex":2},{"type":"antonym","word":"날쌔다","choices":["굼뜨다","날렵하다","재빠르다","민첩하다"],"answerIndex":0},{"type":"spelling","word":"서슴지","choices":["서슴찌","서슴지","서승지","서슴치"],"answerIndex":1}]'::jsonb, 49)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('well-frog-trip', '🐸', '우물 밖으로 나간 첫걸음', '["건우는 태어나서 한 번도 살던 동네를 벗어나 본 적이 없었어요.","건우는 늘 \"우리 동네가 세상에서 가장 크고 좋은 곳\"이라고 자신 있게 말하곤 했어요.","그러던 어느 여름, 가족과 함께 처음으로 큰 도시에 있는 박물관 견학을 가게 되었어요.","건우는 끝없이 늘어선 높은 건물과 수많은 사람들을 보고 입을 다물지 못했어요.","박물관에서는 세계 여러 나라의 유물을 보며 자신이 알던 세상이 얼마나 좁았는지 실감했어요.","집으로 돌아온 건우는 앞으로 더 넓은 세상을 보고 배우고 싶다는 마음이 생겼어요."]'::jsonb, '[{"word":"견학","meaning":"실제로 보고 배우기 위해 어떤 곳을 찾아가는 것"},{"word":"유물","meaning":"옛사람들이 남긴 물건"},{"word":"실감하다","meaning":"실제로 겪는 듯한 느낌을 받다"}]'::jsonb, '[{"answer":false,"statement":"건우는 예전에도 여러 번 다른 도시를 다녀온 적이 있다."},{"answer":true,"statement":"건우는 박물관에서 세계 여러 나라의 유물을 보았다."},{"answer":false,"statement":"건우는 견학을 다녀온 뒤에도 생각이 전혀 바뀌지 않았다."}]'::jsonb, '{"choices":["박물관은 지루한 곳이다","살던 동네가 세상에서 가장 좋은 곳이다","넓은 세상을 직접 경험하면 시야가 넓어질 수 있다","여행은 시간 낭비이니 하지 않는 것이 좋다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"유물","choices":["살아 있는 동물","옛사람들이 남긴 물건","요리에 쓰는 재료","새로 만들어진 물건"],"answerIndex":1},{"type":"proverb","word":"우물 안 개구리","choices":["누구보다 지식이 풍부한 사람","물속에서 사는 것을 좋아하는 사람","넓은 세상을 보지 못하고 자기가 아는 것이 전부라고 여기는 사람","여행을 자주 다니는 사람"],"answerIndex":2},{"type":"synonym","word":"실감하다","choices":["잊다","외면하다","무시하다","느끼다"],"answerIndex":3},{"type":"antonym","word":"넓다","choices":["좁다","길다","크다","깊다"],"answerIndex":0},{"type":"spelling","word":"하마터면","choices":["하마트믄","하마더면","하마트면","하마터면"],"answerIndex":3}]'::jsonb, 50)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('bike-lock-forgotten', '🚲', '자물쇠를 채우지 않은 자전거', '["준서는 새로 산 자전거를 학교 앞에 세워 두고 자물쇠 채우는 것을 깜빡 잊었어요.","\"금방 나올 건데 뭐 어때\" 하며 준서는 대수롭지 않게 여기고 교실로 들어갔어요.","수업이 끝나고 나와 보니 세워 둔 자리에 자전거가 감쪽같이 사라져 있었어요.","준서는 그제야 부랴부랴 자물쇠를 사러 문구점으로 달려갔지만 이미 늦은 뒤였어요.","아빠는 \"자물쇠는 잃어버리기 전에 채워야 소용이 있는 거란다\"라고 안타까워하며 말씀하셨어요.","준서는 미리 대비하지 않으면 나중에 아무리 애써도 소용없다는 것을 뼈아프게 배웠어요."]'::jsonb, '[{"word":"대수롭지 않다","meaning":"중요하게 여길 만하지 않다"},{"word":"부랴부랴","meaning":"매우 서둘러 급하게 행동하는 모양"},{"word":"대비하다","meaning":"앞으로 일어날 일에 대응하기 위해 미리 준비하다"}]'::jsonb, '[{"answer":true,"statement":"준서는 자전거에 자물쇠를 채우는 것을 잊었다."},{"answer":false,"statement":"준서는 수업이 끝난 뒤에도 자전거를 그대로 찾았다."},{"answer":true,"statement":"아빠는 준서에게 미리 준비하는 것이 중요하다고 말씀하셨다."}]'::jsonb, '{"choices":["학교 앞은 안전한 곳이니 걱정할 필요 없다","자물쇠는 굳이 채우지 않아도 된다","일이 벌어진 뒤에 대비해 봤자 소용없으니 미리 준비해야 한다","자전거는 비싼 것을 사면 안 된다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"대비하다","choices":["남을 부러워하다","앞으로 일어날 일에 대응하기 위해 미리 준비하다","아무 계획 없이 행동하다","지나간 일을 후회하다"],"answerIndex":1},{"type":"proverb","word":"소 잃고 외양간 고친다","choices":["일이 이미 벌어진 뒤에야 뒤늦게 대책을 세운다","소는 외양간 안에서만 키워야 한다","무엇이든 서두르면 실수하기 마련이다","미리 준비하면 오히려 손해를 본다"],"answerIndex":0},{"type":"synonym","word":"부랴부랴","choices":["여유롭게","서둘러","느긋하게","천천히"],"answerIndex":1},{"type":"antonym","word":"대수롭지 않다","choices":["흔하다","사소하다","가볍다","중요하다"],"answerIndex":3},{"type":"spelling","word":"통틀어","choices":["통뜰어","통털어","통틀어","통털워"],"answerIndex":2}]'::jsonb, 51)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('talk-of-the-tiger', '🐯', '호랑이도 제 말 하면 온다더니', '["점심시간, 아이들은 얼마 전 전학 간 민준이 이야기를 나누고 있었어요.","\"민준이는 요즘 잘 지내고 있을까?\" 하고 궁금해하던 그 순간, 교실 문이 열리며 민준이가 깜짝 인사를 하러 나타났어요.","아이들은 너무 놀라 한동안 말을 잇지 못하다가 이내 반갑게 민준이를 맞이했어요.","누군가 \"우리가 방금 네 얘기 하고 있었는데 진짜 신기하다!\" 하고 소리쳤어요.","민준이는 새 학교 이야기를 신나게 들려주었고, 교실은 오랜만에 웃음소리로 가득 찼어요.","아이들은 그날의 우연한 만남을 두고두고 신기해하며 이야기했어요."]'::jsonb, '[{"word":"전학","meaning":"다니던 학교를 옮겨 다른 학교로 가는 것"},{"word":"말을 잇다","meaning":"끊어졌던 이야기를 계속 이어서 하다"},{"word":"우연하다","meaning":"뜻하지 않게 저절로 일어나다"}]'::jsonb, '[{"answer":true,"statement":"아이들은 민준이 이야기를 나누고 있었다."},{"answer":false,"statement":"민준이는 그날 학교에 나타나지 않았다."},{"answer":true,"statement":"아이들은 민준이를 반갑게 맞이했다."}]'::jsonb, '{"choices":["민준이는 친구들과 사이가 좋지 않았다","누군가에 대해 이야기하던 중에 그 사람이 우연히 나타나 모두가 놀라고 반가워했다","아이들은 민준이가 오는 것을 미리 알고 있었다","아이들은 민준이 이야기를 하다가 다투었다"],"question":"이 이야기가 전하고 싶은 분위기로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"우연하다","choices":["뜻하지 않게 저절로 일어나다","전혀 일어나지 않다","자주 반복해서 일어나다","미리 계획하여 일어나다"],"answerIndex":0},{"type":"proverb","word":"호랑이도 제 말 하면 온다","choices":["누군가에 대해 이야기하고 있을 때 마침 그 사람이 나타난다","동물 이야기는 하지 않는 것이 좋다","남을 험담하면 반드시 벌을 받는다","호랑이는 자기 이름을 부르면 무서워한다"],"answerIndex":0},{"type":"synonym","word":"우연하다","choices":["의도적이다","뜻밖이다","당연하다","계획적이다"],"answerIndex":1},{"type":"antonym","word":"우연하다","choices":["느닷없다","필연적이다","뜻밖이다","갑작스럽다"],"answerIndex":1},{"type":"spelling","word":"희한하다","choices":["희안하다","희한하다","희환하다","희한다하다"],"answerIndex":1}]'::jsonb, 52)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('group-project-chaos', '🚣', '의견이 너무 많았던 모둠 과제', '["네 명이 함께하는 환경 포스터 모둠 과제에서 저마다 자기 생각을 밀어붙였어요.","한 명은 그림을 크게 그리자 했고, 다른 한 명은 글자를 많이 넣자 했으며, 또 다른 친구는 색을 화려하게 쓰자고 우겼어요.","각자의 의견을 조금씩 다 반영하려다 보니 포스터는 이도 저도 아닌 모습이 되어 버렸어요.","결국 마감 시간이 다가와도 포스터는 정리되지 않은 채 어수선하기만 했어요.","모둠장을 맡은 지안이는 \"이러다간 완성도 못 하겠다\" 싶어 친구들에게 한 사람씩 역할을 나누자고 제안했어요.","역할을 나누고 나서야 아이들은 의견을 하나로 모아 마감 직전에 겨우 포스터를 완성할 수 있었어요."]'::jsonb, '[{"word":"밀어붙이다","meaning":"자기 생각이나 의견을 계속 강하게 주장하다"},{"word":"어수선하다","meaning":"정신이 없을 정도로 뒤섞여 있어 어지럽다"},{"word":"제안하다","meaning":"어떤 일을 하자고 의견을 내놓다"}]'::jsonb, '[{"answer":false,"statement":"모둠 친구들은 처음부터 의견이 하나로 모아졌다."},{"answer":true,"statement":"포스터는 여러 의견이 섞여 어수선한 모습이 되었다."},{"answer":true,"statement":"역할을 나누고 나서야 포스터를 완성할 수 있었다."}]'::jsonb, '{"choices":["모둠 과제는 항상 개인 과제보다 쉽다","저마다 의견만 내세우면 오히려 일을 그르칠 수 있으니 역할을 정해 협력해야 한다","포스터는 화려할수록 좋은 평가를 받는다","모둠장은 혼자서 모든 것을 결정해야 한다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"어수선하다","choices":["깔끔하게 잘 정리되어 있다","텅 비어 있다","조용하고 차분하다","정신이 없을 정도로 뒤섞여 있어 어지럽다"],"answerIndex":3},{"type":"proverb","word":"사공이 많으면 배가 산으로 간다","choices":["주장하는 사람이 너무 많으면 오히려 일이 엉뚱한 방향으로 흘러간다","의견은 많을수록 무조건 좋다","뱃사공이 많을수록 배가 빨리 간다","산으로 가는 배가 가장 안전하다"],"answerIndex":0},{"type":"synonym","word":"제안하다","choices":["건의하다","거절하다","반대하다","무시하다"],"answerIndex":0},{"type":"antonym","word":"어수선하다","choices":["뒤섞이다","복잡하다","정돈되다","혼란스럽다"],"answerIndex":2},{"type":"spelling","word":"얘기","choices":["예그","예기","얘그","얘기"],"answerIndex":3}]'::jsonb, 53)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('quick-fix-tape', '🩹', '테이프로 감은 자전거 바퀴', '["지호의 자전거 바퀴에 작은 구멍이 생겨 바람이 조금씩 빠지고 있었어요.","지호는 정비소에 가는 대신 테이프를 둘둘 감아 임시로 때우고 계속 자전거를 탔어요.","며칠은 괜찮은 듯했지만, 결국 등굣길에 바퀴가 완전히 터져 주저앉고 말았어요.","지호는 무거운 자전거를 끌고 한참을 걸어야 했고, 결국 학교에도 지각하고 말았어요.","아빠는 \"그때 제대로 고쳤더라면 이렇게 큰 문제로 번지지 않았을 텐데\" 하며 안타까워하셨어요.","지호는 눈앞의 문제를 대충 넘기면 나중에 더 큰 어려움으로 돌아온다는 것을 깨달았어요."]'::jsonb, '[{"word":"때우다","meaning":"구멍 나거나 상한 곳을 임시로 고치다"},{"word":"번지다","meaning":"작은 일이 점점 크게 퍼져 나가다"},{"word":"지각하다","meaning":"정해진 시간보다 늦게 도착하다"}]'::jsonb, '[{"answer":false,"statement":"지호는 바퀴 구멍을 정비소에서 제대로 고쳤다."},{"answer":true,"statement":"결국 등굣길에 바퀴가 완전히 터졌다."},{"answer":false,"statement":"지호는 학교에 제시간에 도착했다."}]'::jsonb, '{"choices":["지각은 큰 문제가 아니다","자전거는 매일 점검할 필요가 없다","테이프는 어떤 물건이든 완벽하게 고칠 수 있다","문제를 임시방편으로만 넘기면 나중에 더 큰 어려움이 될 수 있다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"번지다","choices":["문제가 저절로 해결되다","있던 자리에서 사라지다","조용히 가라앉다","작은 일이 점점 크게 퍼져 나가다"],"answerIndex":3},{"type":"proverb","word":"언 발에 오줌 누기","choices":["작은 문제는 아예 무시하는 것이 낫다","급한 일은 빨리 해결할수록 좋다","추운 날에는 몸을 따뜻하게 해야 한다","임시방편으로 문제를 해결하면 잠깐은 나아 보여도 결국 상황이 더 나빠진다"],"answerIndex":3},{"type":"synonym","word":"때우다","choices":["완전히 새로 만들다","오래 보관하다","깨끗이 버리다","임시로 고치다"],"answerIndex":3},{"type":"antonym","word":"지각하다","choices":["급히 뛰다","일찍 도착하다","천천히 걷다","늦게 도착하다"],"answerIndex":1},{"type":"spelling","word":"금세","choices":["금새","금세","금서","금쇄"],"answerIndex":1}]'::jsonb, 54)
