insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('loud-empty-boast', '📢', '요란했던 빈 수레', '["학급 회장 선거에서 현우는 \"내가 되면 매점을 학교 안에 만들겠다\"며 큰소리로 공약을 외쳤어요.","반면 소은이는 조용히 \"숙제 게시판을 만들어 준비물을 잊지 않게 돕겠다\"는 작은 공약을 내놓았어요.","현우의 화려한 말에 처음에는 아이들의 관심이 쏠렸지만, 실제로 지킬 수 있는 공약인지 의문을 갖는 친구들도 있었어요.","투표 결과 아이들은 실현 가능하고 꾸준히 도움이 될 소은이의 공약에 더 많은 표를 주었어요.","현우는 \"요란하게 말만 앞세운다고 좋은 게 아니었구나\" 하고 스스로를 돌아보았어요.","소은이는 회장이 된 뒤 약속했던 게시판을 꾸준히 관리하며 반 친구들의 신뢰를 얻었어요."]'::jsonb, '[{"word":"공약","meaning":"선거에서 실행하겠다고 국민이나 유권자에게 약속하는 일"},{"word":"내놓다","meaning":"생각이나 의견 등을 겉으로 드러내어 말하다"},{"word":"신뢰","meaning":"굳게 믿고 의지함"}]'::jsonb, '[{"answer":true,"statement":"현우는 화려하고 큰 공약을 내세웠다."},{"answer":false,"statement":"소은이는 실현 가능성이 낮은 공약을 내놓았다."},{"answer":true,"statement":"투표 결과 아이들은 소은이의 공약을 더 지지했다."}]'::jsonb, '{"choices":["겉으로 요란하게 내세우는 것보다 진실하고 실현 가능한 약속이 더 중요하다","말이 화려할수록 믿을 수 있는 사람이다","회장은 무조건 목소리가 큰 사람이 되어야 한다","작은 공약은 아이들의 관심을 끌지 못한다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"신뢰","choices":["갑작스럽게 놀람","서로 다투고 미워함","굳게 믿고 의지함","아무 관심이 없음"],"answerIndex":2},{"type":"proverb","word":"빈 수레가 요란하다","choices":["조용한 사람은 아는 것이 적다","실속 없이 겉치레만 요란하게 내세우는 사람일수록 시끄럽다","요란한 소리는 항상 위험을 알린다","수레는 짐이 많을수록 소리가 크다"],"answerIndex":1},{"type":"synonym","word":"내놓다","choices":["제시하다","감추다","숨기다","거두다"],"answerIndex":0},{"type":"antonym","word":"신뢰","choices":["확신","의지","믿음","불신"],"answerIndex":3},{"type":"spelling","word":"안절부절못하다","choices":["안절부절함하다","안절부절해하다","안절부절하다","안절부절못하다"],"answerIndex":3}]'::jsonb, 55)
