insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('ten-tries-tree', '🪓', '열 번째 도전에서 이룬 성공', '["수영을 배우던 정민이는 아홉 번이나 접영에 도전했지만 번번이 물을 먹고 실패했어요.","함께 배우던 친구들은 하나둘 접영을 익혀 갔지만, 정민이만 자꾸 뒤처지는 것 같아 속상했어요.","코치 선생님은 \"포기하지 않고 계속 도전하는 사람은 결국 해내기 마련이란다\"라며 정민이를 다독여 주셨어요.","정민이는 이를 악물고 열 번째로 다시 팔을 저어 물살을 갈랐어요.","이번에는 신기하게도 몸의 리듬이 딱 맞아떨어지며 처음으로 매끄럽게 접영을 완성해 냈어요.","정민이는 아홉 번의 실패가 있었기에 열 번째 성공이 가능했다는 것을 깊이 느꼈어요."]'::jsonb, '[{"word":"뒤처지다","meaning":"다른 사람보다 늦거나 뒤에 남게 되다"},{"word":"다독이다","meaning":"따뜻한 말이나 행동으로 마음을 달래 주다"},{"word":"매끄럽다","meaning":"동작이나 일의 진행이 거침없이 부드럽다"}]'::jsonb, '[{"answer":false,"statement":"정민이는 첫 시도에서 바로 접영에 성공했다."},{"answer":false,"statement":"코치 선생님은 정민이에게 포기하라고 말씀하셨다."},{"answer":true,"statement":"정민이는 열 번째 시도에서 접영을 완성해 냈다."}]'::jsonb, '{"choices":["한 번 실패하면 다시 도전하지 않는 것이 좋다","꾸준히 계속 도전하면 결국 해낼 수 있다","친구보다 뒤처지면 그만두는 것이 낫다","수영은 재능이 있어야만 배울 수 있다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"다독이다","choices":["무시하고 지나치다","따뜻한 말이나 행동으로 마음을 달래 주다","큰 소리로 재촉하다","심하게 나무라며 혼내다"],"answerIndex":1},{"type":"proverb","word":"열 번 찍어 안 넘어가는 나무 없다","choices":["꾸준히 노력하면 결국 뜻을 이룰 수 있다","나무는 한 번에 쉽게 넘어간다","노력보다 운이 더 중요하다","열 번 넘게 시도하면 오히려 나빠진다"],"answerIndex":0},{"type":"synonym","word":"매끄럽다","choices":["어색하다","거칠다","순조롭다","서투르다"],"answerIndex":2},{"type":"antonym","word":"뒤처지다","choices":["처지다","밀리다","앞서다","늦다"],"answerIndex":2},{"type":"spelling","word":"깨끗이","choices":["깨끗히","깨끗시","깨끗이","깨끄시"],"answerIndex":2}]'::jsonb, 56)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('thank-you-letter-power', '✉️', '편지 한 장이 바꾼 마음', '["전학생 리안이는 몇 주가 지나도록 반 친구들과 쉽게 어울리지 못해 늘 혼자 지냈어요.","어느 날 짝꿍 하율이가 리안이의 책상 위에 짧은 편지 한 장을 몰래 올려 두었어요.","편지에는 \"네가 그린 그림 정말 멋있더라, 같이 그림 그리자\"라는 짧은 한마디가 적혀 있었어요.","그 한마디에 리안이의 얼굴에는 오랜만에 환한 웃음이 번졌어요.","리안이는 용기를 내어 하율이에게 다가갔고, 둘은 그날부터 그림 친구가 되었어요.","하율이는 짧은 편지 한 장이 한 사람의 마음을 이렇게 크게 움직일 수 있다는 것을 깨달았어요."]'::jsonb, '[{"word":"어울리다","meaning":"다른 사람과 사이좋게 잘 지내다"},{"word":"번지다","meaning":"감정이나 표정이 점점 넓게 퍼지다"},{"word":"용기를 내다","meaning":"두려움을 이기고 씩씩한 마음을 갖다"}]'::jsonb, '[{"answer":false,"statement":"리안이는 전학 온 지 얼마 안 되어 친구들과 쉽게 친해졌다."},{"answer":true,"statement":"하율이는 리안이에게 편지를 써 주었다."},{"answer":true,"statement":"리안이와 하율이는 편지를 계기로 그림 친구가 되었다."}]'::jsonb, '{"choices":["그림을 잘 그려야 친구를 사귈 수 있다","따뜻한 말 한마디가 누군가의 마음을 크게 움직일 수 있다","편지보다는 직접 말하는 것이 항상 낫다","전학생과는 친해지기 어렵다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"어울리다","choices":["남을 미워하고 피하다","다른 사람과 사이좋게 잘 지내다","큰 소리로 다투다","혼자 조용히 지내다"],"answerIndex":1},{"type":"proverb","word":"말 한마디에 천 냥 빚도 갚는다","choices":["빚은 말로 갚을 수 없다","따뜻하고 좋은 말 한마디가 큰 힘을 발휘할 수 있다","돈이 있어야 사람의 마음을 얻을 수 있다","말을 많이 할수록 손해를 본다"],"answerIndex":1},{"type":"synonym","word":"번지다","choices":["줄어들다","퍼지다","사라지다","멈추다"],"answerIndex":1},{"type":"antonym","word":"어울리다","choices":["사귀다","가까워지다","친해지다","외면하다"],"answerIndex":3},{"type":"spelling","word":"오뚝이","choices":["오뚝이","오뚜끼","오똑이","오뚜기"],"answerIndex":0}]'::jsonb, 57)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('seedling-talent', '🌳', '떡잎부터 남달랐던 아이', '["유치원 시절부터 서준이는 다른 아이들보다 유난히 궁금한 것이 많았어요.","개미를 발견하면 몇 시간이고 쪼그려 앉아 개미의 움직임을 관찰하곤 했어요.","초등학교에 들어와서도 그 호기심은 그대로 이어져, 서준이는 곤충 관찰 일기를 벌써 다섯 권째 쓰고 있었어요.","담임 선생님은 서준이의 꾸준한 관찰 기록을 보고 \"어릴 때부터 남다른 씨앗을 가진 아이였구나\" 하고 감탄하셨어요.","결국 서준이는 전국 어린이 과학 탐구 대회에서 곤충 생태 보고서로 대상을 받았어요.","사람들은 어릴 적 보였던 작은 관심이 결국 큰 재능으로 자라났다는 것에 고개를 끄덕였어요."]'::jsonb, '[{"word":"유난히","meaning":"보통과 아주 다르게 두드러지게"},{"word":"쪼그려 앉다","meaning":"무릎을 굽혀 몸을 낮추고 앉다"},{"word":"감탄하다","meaning":"매우 훌륭하다고 느껴 마음속 깊이 놀라다"}]'::jsonb, '[{"answer":true,"statement":"서준이는 어릴 때부터 궁금한 것이 유난히 많았다."},{"answer":false,"statement":"서준이는 초등학생이 되면서 곤충에 대한 관심을 잃었다."},{"answer":true,"statement":"서준이는 전국 과학 탐구 대회에서 대상을 받았다."}]'::jsonb, '{"choices":["곤충을 관찰하는 것은 시간 낭비이다","재능은 타고나는 것이라 노력이 필요 없다","대회에서 상을 받아야만 의미 있는 노력이다","어릴 때 보이던 관심과 재능은 자라면서 꾸준히 큰 성취로 이어질 수 있다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"감탄하다","choices":["매우 훌륭하다고 느껴 마음속 깊이 놀라다","슬퍼서 눈물을 흘리다","몹시 화가 나서 소리치다","전혀 관심이 없다"],"answerIndex":0},{"type":"proverb","word":"될성부른 나무는 떡잎부터 알아본다","choices":["떡잎은 나무의 미래와 아무 상관이 없다","크게 될 사람은 어릴 때부터 남다른 모습을 보인다","무슨 일이든 나중에 판단해야 한다","나무는 잎이 커야 잘 자란다"],"answerIndex":1},{"type":"synonym","word":"유난히","choices":["흔하게","특별히","평범하게","보통으로"],"answerIndex":1},{"type":"antonym","word":"감탄하다","choices":["감동하다","실망하다","놀라다","탄복하다"],"answerIndex":1},{"type":"spelling","word":"떡볶이","choices":["떡볶이","떡뽂이","떡볶끼","떡볶기"],"answerIndex":0}]'::jsonb, 58)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('neighbors-bigger-kite', '🪁', '옆집 아이의 더 커 보인 연', '["설날에 삼촌에게 연을 선물 받은 재윤이는 뛸 듯이 기뻤어요.","그런데 옆집 아이가 가진 연을 보는 순간, 재윤이의 연이 갑자기 작고 초라해 보이기 시작했어요.","재윤이는 하늘로 연을 날려 보지도 않은 채 \"내 연은 별로야\"라며 시무룩해졌어요.","아빠는 재윤이의 연을 대신 하늘로 띄워 주셨는데, 놀랍게도 재윤이의 연이 훨씬 더 높이, 더 오래 날았어요.","옆집 아이의 연은 크기만 컸을 뿐 균형이 맞지 않아 자꾸 땅으로 곤두박질쳤어요.","재윤이는 남의 것이 커 보인다고 무작정 부러워할 필요는 없다는 것을 깨달았어요."]'::jsonb, '[{"word":"초라하다","meaning":"겉모양이나 모습이 보잘것없다"},{"word":"시무룩하다","meaning":"마음에 못마땅하여 말이 없고 얼굴에 언짢은 기색이 있다"},{"word":"곤두박질치다","meaning":"갑자기 세게 거꾸로 떨어지다"}]'::jsonb, '[{"answer":true,"statement":"재윤이는 삼촌에게 연을 선물 받았다."},{"answer":true,"statement":"재윤이는 자신의 연이 옆집 아이의 연보다 못하다고 생각했다."},{"answer":true,"statement":"실제로 날려 보니 재윤이의 연이 더 높이, 더 오래 날았다."}]'::jsonb, '{"choices":["연은 클수록 잘 난다","남의 것이 무조건 더 좋아 보이지만 실제로는 그렇지 않을 수 있다","겉모습만 보고도 물건의 가치를 정확히 알 수 있다","선물은 비쌀수록 좋은 선물이다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"초라하다","choices":["겉모양이나 모습이 보잘것없다","겉모습이 화려하고 멋지다","크기가 매우 크다","색이 밝고 화사하다"],"answerIndex":0},{"type":"proverb","word":"남의 떡이 더 커 보인다","choices":["떡은 나눠 먹을 때 더 맛있다","남에게 음식을 나눠 주면 복이 온다","자기가 가진 것보다 남이 가진 것이 더 좋아 보인다","떡은 클수록 맛이 없다"],"answerIndex":2},{"type":"synonym","word":"시무룩하다","choices":["풀이 죽다","신이 나다","들뜨다","즐거워하다"],"answerIndex":0},{"type":"antonym","word":"초라하다","choices":["소박하다","화려하다","허름하다","보잘것없다"],"answerIndex":1},{"type":"spelling","word":"어이없다","choices":["어위없다","어리없다","어이없다","어의없다"],"answerIndex":2}]'::jsonb, 59)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('shipping-cost-more-than-gift', '📦', '선물보다 비쌌던 택배비', '["나연이는 친구 생일에 오백 원짜리 작은 열쇠고리를 온라인으로 주문했어요.","결제 화면을 보던 나연이는 물건값보다 배송비가 훨씬 더 비싼 것을 보고 깜짝 놀랐어요.","\"배보다 배꼽이 더 크다더니 딱 이런 경우구나\" 하고 나연이는 헛웃음이 나왔어요.","결국 나연이는 근처 문구점에 직접 가서 비슷한 열쇠고리를 배송비 없이 훨씬 싸게 살 수 있었어요.","나연이는 무엇을 살지 정할 때 물건값만이 아니라 전체 비용을 꼼꼼히 따져 봐야 한다는 것을 배웠어요.","그 뒤로 나연이는 물건을 살 때마다 가격표 옆의 작은 글씨까지 살펴보는 습관이 생겼어요."]'::jsonb, '[{"word":"결제","meaning":"물건값을 내고 거래를 끝내는 것"},{"word":"헛웃음","meaning":"어이가 없어서 나오는 웃음"},{"word":"따지다","meaning":"옳고 그름이나 이익과 손해 등을 자세히 살펴보다"}]'::jsonb, '[{"answer":true,"statement":"나연이가 주문한 열쇠고리는 오백 원이었다."},{"answer":false,"statement":"배송비는 물건값보다 훨씬 저렴했다."},{"answer":true,"statement":"나연이는 결국 문구점에서 열쇠고리를 더 싸게 샀다."}]'::jsonb, '{"choices":["물건을 살 때는 물건값만이 아니라 전체 비용을 꼼꼼히 따져야 한다","온라인 쇼핑은 절대 이용하지 않는 것이 좋다","배송비는 항상 물건값보다 저렴하다","작은 물건일수록 값이 비싸다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"따지다","choices":["아무 생각 없이 결정하다","기분 좋게 웃다","물건을 정리하다","옳고 그름이나 이익과 손해 등을 자세히 살펴보다"],"answerIndex":3},{"type":"proverb","word":"배보다 배꼽이 더 크다","choices":["몸이 클수록 힘이 세다","배는 배꼽보다 항상 커야 정상이다","작은 것은 큰 것보다 소중하지 않다","기본이 되는 것보다 부수적인 것이 더 크거나 많다"],"answerIndex":3},{"type":"synonym","word":"따지다","choices":["넘기다","외면하다","살피다","무시하다"],"answerIndex":2},{"type":"antonym","word":"저렴하다","choices":["값싸다","비싸다","알뜰하다","싸다"],"answerIndex":1},{"type":"spelling","word":"눈살을 찌푸리다","choices":["눈살을 찌푸리다","눈쌀을 찌푸리다","눈쌀을 찌뿌리다","눈살을 찌뿌리다"],"answerIndex":0}]'::jsonb, 60)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('one-well-focus', '⛏️', '이곳저곳 파 본 우물', '["민재는 학교 대표로 과학 발명품 대회에 나가기로 했어요.","처음엔 로봇 청소기를 만들다가, 친구가 드론이 멋있다고 하자 드론으로 바꾸고, 또 다른 친구가 자동 물주기 장치를 추천하자 그쪽으로 또 바꿨어요.","이것저것 손대다 보니 대회 날짜가 다가와도 완성된 것은 하나도 없었어요.","결국 민재는 발표할 작품이 없어서 속상한 얼굴로 대회장을 지켜만 봐야 했어요.","선생님은 \"하나를 진득하게 끝까지 해 보는 게 중요하단다\" 하고 다독여 주셨어요.","민재는 다음 대회에는 한 가지 아이디어만 정해서 끝까지 밀고 나가기로 다짐했어요."]'::jsonb, '[{"word":"진득하다","meaning":"성질이나 태도가 검질기게 끈기가 있다"},{"word":"손대다","meaning":"어떤 일을 시작하거나 관여하다"},{"word":"밀고 나가다","meaning":"어려움이 있어도 계속 해내다"}]'::jsonb, '[{"answer":false,"statement":"민재는 로봇 청소기 하나만 끝까지 완성했다."},{"answer":true,"statement":"민재는 대회 날까지 완성된 작품이 없었다."},{"answer":true,"statement":"선생님은 하나를 끝까지 해 보라고 조언하셨다."}]'::jsonb, '{"choices":["아이디어는 자주 바꿀수록 좋다","발명품 대회는 참가만 해도 의미가 있다","이것저것 손대기보다 한 가지를 끝까지 해내는 것이 중요하다","다른 사람의 조언은 듣지 않는 것이 좋다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"진득하다","choices":["매우 화를 잘 내다","금방 싫증을 내다","아주 수줍어하다","성질이나 태도가 검질기게 끈기가 있다"],"answerIndex":3},{"type":"proverb","word":"우물을 파도 한 우물을 파라","choices":["여러 가지를 동시에 하는 것이 효율적이다","우물은 마을 한가운데 파야 한다","한 가지 일을 정했으면 끝까지 해내야 한다","우물물은 깊을수록 맛있다"],"answerIndex":2},{"type":"synonym","word":"진득하다","choices":["급하다","변덕스럽다","끈기 있다","가볍다"],"answerIndex":2},{"type":"antonym","word":"진득하다","choices":["꾸준하다","차분하다","끈기있다","변덕스럽다"],"answerIndex":3},{"type":"spelling","word":"봬요","choices":["뵈요","봬요","봬여요","뵈여요"],"answerIndex":1}]'::jsonb, 61)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('tadpole-forgets', '🐸', '올챙이 시절을 잊은 개구리', '["수영을 아주 잘하게 된 5학년 지호는 얼마 전까지만 해도 물에 뜨는 것조차 무서워했어요.","그런데 요즘 지호는 아직 헤엄을 못 치는 후배를 보면 \"그것도 못하냐\"며 답답해했어요.","코치 선생님은 지호에게 \"너도 처음엔 물이 무서워서 울었던 거 기억하니?\" 하고 물으셨어요.","지호는 그제야 자기가 처음 수영장에 왔을 때 얼마나 두려웠는지 떠올렸어요.","부끄러워진 지호는 후배에게 다가가 자신이 배웠던 방법을 천천히 알려 주었어요.","후배는 지호 덕분에 조금씩 물에 익숙해지며 자신감을 얻어 갔어요."]'::jsonb, '[{"word":"답답해하다","meaning":"일이 뜻대로 되지 않아 마음이 갑갑하다"},{"word":"두렵다","meaning":"무서워서 마음이 불안하다"},{"word":"익숙해지다","meaning":"자주 겪어서 편해지다"}]'::jsonb, '[{"answer":false,"statement":"지호는 처음부터 수영을 잘했다."},{"answer":true,"statement":"코치 선생님은 지호에게 처음 배울 때를 떠올리게 했다."},{"answer":false,"statement":"지호는 후배를 끝까지 답답해하기만 했다."}]'::jsonb, '{"choices":["수영은 누구나 처음부터 잘할 수 있다","잘하는 사람은 못하는 사람을 이해할 필요가 없다","후배는 스스로 알아서 배워야 한다","자신의 서툴렀던 시절을 기억하며 남을 이해해야 한다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"두렵다","choices":["즐겁고 신나다","무서워서 마음이 불안하다","아주 지루하다","몹시 화가 나다"],"answerIndex":1},{"type":"proverb","word":"개구리 올챙이 적 생각 못한다","choices":["형편이 나아진 사람이 예전에 힘들었던 때를 잊고 남을 무시한다","누구나 한 번은 실수를 한다","개구리는 올챙이보다 힘이 세다","작은 것도 소중히 여겨야 한다"],"answerIndex":0},{"type":"synonym","word":"두렵다","choices":["편안하다","무섭다","즐겁다","지루하다"],"answerIndex":1},{"type":"antonym","word":"두렵다","choices":["불안하다","무섭다","편안하다","조마조마하다"],"answerIndex":2},{"type":"spelling","word":"요컨대","choices":["요컨대서","요컨대","요컨대는","요컨데"],"answerIndex":1}]'::jsonb, 62)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('dog-after-three-years', '📚', '삼 년 만에 시 읊은 강아지', '["민서네 가족은 매일 저녁 온 가족이 모여 앉아 책을 소리 내어 읽는 시간을 가졌어요.","집에서 기르는 강아지 콩이는 늘 그 곁에서 얌전히 엎드려 듣기만 했어요.","그런데 몇 년이 지나자 놀랍게도 콩이는 \"책 읽자\"라는 말만 들으면 스스로 방석 자리로 달려와 앉았어요.","가족들은 매일 반복해서 보고 들은 것이 콩이에게도 자연스러운 습관이 되었다는 것을 깨달았어요.","민서는 \"꾸준히 곁에서 보고 들으면 자기도 모르게 배우게 되는구나\" 하고 신기해했어요.","그날 이후 민서는 무엇이든 꾸준히 반복하는 것의 힘을 믿게 되었어요."]'::jsonb, '[{"word":"얌전하다","meaning":"성격이나 태도가 온순하고 조용하다"},{"word":"꾸준히","meaning":"한결같이 계속하여"},{"word":"자연스럽다","meaning":"억지로 꾸미지 않아 편안하다"}]'::jsonb, '[{"answer":false,"statement":"콩이는 처음부터 책 읽는 자리를 알고 있었다."},{"answer":true,"statement":"가족들은 매일 저녁 소리 내어 책을 읽었다."},{"answer":false,"statement":"콩이는 몇 년이 지나도 아무 변화가 없었다."}]'::jsonb, '{"choices":["꾸준히 보고 들으면 자기도 모르게 배우게 된다","책은 소리 내어 읽지 않아도 된다","습관은 하루 만에 만들어진다","동물은 사람의 말을 절대 알아듣지 못한다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"얌전하다","choices":["성격이나 태도가 온순하고 조용하다","몹시 시끄럽고 사납다","아주 게으르다","지나치게 활발하다"],"answerIndex":0},{"type":"proverb","word":"서당개 삼년이면 풍월을 읊는다","choices":["개는 삼 년을 키워야 정이 든다","서당에서는 삼 년을 배워야 졸업한다","무엇이든 배우려면 스승이 필요하다","오래 보고 들으면 자연스레 그 일을 할 줄 알게 된다"],"answerIndex":3},{"type":"synonym","word":"꾸준히","choices":["대충","갑작스럽게","가끔씩","한결같이"],"answerIndex":3},{"type":"antonym","word":"얌전하다","choices":["사납다","조용하다","차분하다","온순하다"],"answerIndex":0},{"type":"spelling","word":"뒤처지다","choices":["뒤쳐저다","뒤처저다","뒤처지다","뒤쳐지다"],"answerIndex":2}]'::jsonb, 63)
