insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('ask-even-known-path', '🗺️', '아는 길도 다시 물어본 등산객', '["해준이네 가족은 지난주에도 다녀왔던 뒷산으로 다시 등산을 가기로 했어요.","아빠는 \"저번에 가 봤으니까 그냥 가면 되지\" 하며 자신 있게 앞장섰어요.","하지만 해준이는 혹시 몰라 관리사무소에 들러 요즘 등산로 상태를 여쭤보자고 했어요.","알고 보니 최근 비로 인해 늘 다니던 길 일부가 통제되고 있었어요.","덕분에 가족은 미리 다른 길로 안전하게 돌아갈 수 있었어요.","아빠는 \"안다고 생각한 것도 한 번 더 확인하길 잘했구나\" 하며 해준이를 칭찬했어요."]'::jsonb, '[{"word":"앞장서다","meaning":"남보다 먼저 나아가 이끌다"},{"word":"통제되다","meaning":"길이나 행동이 제한을 받다"},{"word":"확인하다","meaning":"틀림이 없는지 알아보다"}]'::jsonb, '[{"answer":false,"statement":"해준이 가족은 처음 가 보는 산으로 등산을 갔다."},{"answer":true,"statement":"해준이는 관리사무소에 들러 길 상태를 물어봤다."},{"answer":true,"statement":"늘 다니던 등산로 일부가 통제되고 있었다."}]'::jsonb, '{"choices":["등산은 항상 위험하니 하지 않는 것이 좋다","길을 물어보는 것은 부끄러운 일이다","아는 길은 절대 다시 확인할 필요가 없다","잘 안다고 생각하는 일도 다시 한번 확인하는 것이 안전하다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"통제되다","choices":["길이나 행동이 제한을 받다","사람들로 붐비다","아주 깨끗해지다","자유롭게 열려 있다"],"answerIndex":0},{"type":"proverb","word":"아는 길도 물어가라","choices":["길을 자주 물으면 예의가 없다","아는 사람에게만 길을 물어야 한다","모르는 길은 가지 않는 것이 좋다","잘 아는 일이라도 다시 한번 확인하며 조심해야 한다"],"answerIndex":3},{"type":"synonym","word":"확인하다","choices":["점검하다","잊어버리다","포기하다","무시하다"],"answerIndex":0},{"type":"antonym","word":"앞장서다","choices":["주도하다","이끌다","뒤따르다","앞서다"],"answerIndex":2},{"type":"spelling","word":"웬만하면","choices":["왠만하면","웬만하믄","웬만하면","왠만하믄"],"answerIndex":2}]'::jsonb, 64)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('beads-must-be-strung', '📿', '꿰지 않은 구슬 상자', '["유나는 몇 년 동안 여행할 때마다 예쁜 구슬을 하나씩 사 모았어요.","서랍 속 상자에는 색색의 구슬이 가득했지만, 유나는 그저 바라보기만 할 뿐이었어요.","어느 날 할머니께서 \"그 구슬들로 팔찌를 만들어 보는 건 어떠니?\" 하고 제안하셨어요.","유나는 귀찮다는 생각도 들었지만, 용기를 내어 실에 구슬을 하나하나 꿰기 시작했어요.","며칠 뒤, 서랍 속에서 잠자던 구슬들은 반짝이는 팔찌 여러 개로 다시 태어났어요.","유나는 그냥 모아 두기만 했던 구슬이 이렇게 예쁘게 쓰일 수 있다는 것에 뿌듯해했어요."]'::jsonb, '[{"word":"모으다","meaning":"한데 합쳐 두다"},{"word":"제안하다","meaning":"어떤 일을 하자고 의견을 내다"},{"word":"뿌듯하다","meaning":"마음이 흐뭇하고 자랑스럽다"}]'::jsonb, '[{"answer":true,"statement":"유나는 구슬을 여행할 때마다 하나씩 모았다."},{"answer":false,"statement":"유나는 처음부터 구슬로 팔찌를 만들었다."},{"answer":true,"statement":"할머니의 제안으로 구슬을 팔찌로 만들었다."}]'::jsonb, '{"choices":["팔찌는 사서 쓰는 것이 더 좋다","아무리 좋은 것도 쓸모 있게 완성해야 진짜 가치가 생긴다","여행은 물건을 모으기 위해 가는 것이다","구슬은 모으기만 해도 충분히 값지다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"뿌듯하다","choices":["마음이 흐뭇하고 자랑스럽다","몹시 화가 나다","너무 슬프고 속상하다","아주 지루하다"],"answerIndex":0},{"type":"proverb","word":"구슬이 서 말이라도 꿰어야 보배","choices":["구슬은 비쌀수록 좋다","보배는 하늘에서 저절로 떨어진다","많이 모으는 것이 가장 중요하다","아무리 좋은 것도 다듬고 완성해야 값어치가 있다"],"answerIndex":3},{"type":"synonym","word":"뿌듯하다","choices":["심심하다","흐뭇하다","지루하다","속상하다"],"answerIndex":1},{"type":"antonym","word":"모으다","choices":["수집하다","흩뜨리다","쌓다","모아두다"],"answerIndex":1},{"type":"spelling","word":"설렘","choices":["설레음","설레","설레임","설렘"],"answerIndex":3}]'::jsonb, 65)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('drink-kimchi-soup-first', '🍲', '떡 먹기 전에 마신 김칫국', '["체육 대회 계주 대표로 뽑힐 것이라고 확신한 정우는 이미 친구들에게 자랑을 하고 다녔어요.","\"나 이번엔 무조건 대표야\" 하며 응원 문구까지 미리 준비했어요.","하지만 발표 날, 대표로 뽑힌 사람은 정우가 아니라 같은 반 다른 친구였어요.","정우는 너무 창피해서 준비했던 응원 문구를 슬며시 가방 속에 숨겼어요.","짝꿍은 \"결과가 나오기 전에 너무 확신하면 이럴 수도 있어\" 하며 다독여 주었어요.","정우는 다음부터는 결과가 나올 때까지 차분히 기다리기로 마음먹었어요."]'::jsonb, '[{"word":"확신하다","meaning":"틀림없다고 굳게 믿다"},{"word":"창피하다","meaning":"부끄러워 낯이 뜨겁다"},{"word":"다독이다","meaning":"따뜻한 말로 마음을 달래다"}]'::jsonb, '[{"answer":true,"statement":"정우는 결과가 나오기 전부터 자신이 대표라고 확신했다."},{"answer":false,"statement":"정우는 실제로 계주 대표로 뽑혔다."},{"answer":false,"statement":"짝꿍은 정우를 놀리기만 했다."}]'::jsonb, '{"choices":["응원 문구는 미리 준비할 필요가 없다","결과가 나오기 전에 미리 확신하고 김칫국부터 마시면 안 된다","자신감을 갖는 것은 항상 나쁜 일이다","대표로 뽑히지 못하면 계속 속상해해야 한다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"확신하다","choices":["아무 관심이 없다","전혀 믿지 못하다","자꾸 잊어버리다","틀림없다고 굳게 믿다"],"answerIndex":3},{"type":"proverb","word":"김칫국부터 마신다","choices":["무슨 일이든 준비를 철저히 해야 한다","김칫국은 몸에 아주 좋다","음식은 순서대로 먹어야 한다","일이 확실해지기도 전에 미리 다 된 것처럼 행동한다"],"answerIndex":3},{"type":"synonym","word":"창피하다","choices":["자랑스럽다","부끄럽다","즐겁다","뿌듯하다"],"answerIndex":1},{"type":"antonym","word":"확신하다","choices":["믿다","장담하다","단정하다","의심하다"],"answerIndex":3},{"type":"spelling","word":"케첩","choices":["케첩","케첩쓰","케찹","케찹쓰"],"answerIndex":0}]'::jsonb, 66)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('ash-on-finished-rice', '🍚', '거의 다 된 모둠 발표에 뿌린 재', '["수아네 모둠은 일주일 내내 준비한 환경 발표 자료를 드디어 완성했어요.","발표 전날, 같은 모둠인 하준이가 장난삼아 컴퓨터 파일을 함부로 만지다가 자료의 절반을 지워 버렸어요.","모둠 친구들은 다 된 발표를 망친 것 같아 크게 속상해했어요.","하준이는 자신의 장난이 얼마나 큰 피해를 주는지 그제야 깨닫고 진심으로 사과했어요.","모둠 친구들은 밤늦게까지 힘을 모아 자료를 다시 만들어 발표를 무사히 마쳤어요.","수아는 \"거의 다 된 일을 망치는 장난은 절대 하면 안 되는구나\" 하고 마음에 새겼어요."]'::jsonb, '[{"word":"장난삼다","meaning":"진지하지 않게 재미로 어떤 행동을 하다"},{"word":"함부로","meaning":"조심하지 않고 마구"},{"word":"마음에 새기다","meaning":"잊지 않도록 깊이 기억하다"}]'::jsonb, '[{"answer":false,"statement":"하준이는 일부러 자료를 다 지웠다."},{"answer":true,"statement":"모둠 친구들은 힘을 모아 자료를 다시 만들었다."},{"answer":false,"statement":"하준이는 끝까지 사과하지 않았다."}]'::jsonb, '{"choices":["장난은 언제 쳐도 괜찮다","발표 자료는 한 사람이 혼자 만드는 것이 낫다","거의 다 이루어진 일을 망치는 행동은 절대 하지 말아야 한다","실수는 사과할 필요가 없다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"함부로","choices":["정성을 다해","매우 조심스럽게","조심하지 않고 마구","아주 천천히"],"answerIndex":2},{"type":"proverb","word":"다 된 밥에 재 뿌리기","choices":["재는 밥맛을 좋게 한다","무슨 일이든 끝까지 확인해야 한다","거의 다 이루어진 일을 망쳐 버린다","밥은 뜸을 잘 들여야 맛있다"],"answerIndex":2},{"type":"synonym","word":"함부로","choices":["조심스레","마구","차분히","정성껏"],"answerIndex":1},{"type":"antonym","word":"함부로","choices":["거칠게","아무렇게나","마구","조심스레"],"answerIndex":3},{"type":"spelling","word":"반드시","choices":["반듯이","반드시이","반듯시","반드시"],"answerIndex":3}]'::jsonb, 67)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('egg-against-rock', '🥚', '바위에 던진 달걀', '["전교 팔씨름 대회에서 몸집이 작은 은우가 학교에서 가장 힘센 형과 맞붙게 되었어요.","친구들은 \"저건 달걀로 바위를 치는 거나 다름없어\" 하며 은우가 질 것이라 예상했어요.","하지만 은우는 포기하지 않고 그동안 연습한 손목 기술을 침착하게 사용했어요.","힘으로는 밀렸지만 기술 덕분에 은우는 예상외로 팽팽한 접전을 펼쳤어요.","비록 아깝게 지긴 했지만, 은우는 온 힘을 다해 최선을 다한 자신이 자랑스러웠어요.","지켜보던 친구들도 결과와 상관없이 은우에게 큰 박수를 보내 주었어요."]'::jsonb, '[{"word":"맞붙다","meaning":"서로 마주하여 겨루다"},{"word":"침착하다","meaning":"흥분하지 않고 차분하다"},{"word":"접전","meaning":"실력이 비슷하여 팽팽하게 다투는 싸움"}]'::jsonb, '[{"answer":false,"statement":"은우는 몸집이 가장 큰 학생이었다."},{"answer":true,"statement":"은우는 손목 기술을 사용해 접전을 펼쳤다."},{"answer":false,"statement":"은우는 결국 팔씨름에서 이겼다."}]'::jsonb, '{"choices":["이기기 힘든 상대라도 최선을 다하는 것 자체가 의미가 있다","힘이 센 사람이 항상 옳다","팔씨름은 기술보다 힘이 전부다","이길 수 없는 싸움은 아예 하지 않는 것이 좋다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"침착하다","choices":["몹시 당황하다","흥분하지 않고 차분하다","아주 시끄럽다","쉽게 포기하다"],"answerIndex":1},{"type":"proverb","word":"달걀로 바위 치기","choices":["바위는 절대 깨지지 않는다","달걀은 삶아 먹어야 맛있다","약한 사람은 도전하면 안 된다","턱없이 약한 힘으로 강한 상대에 맞서는 것"],"answerIndex":3},{"type":"synonym","word":"침착하다","choices":["차분하다","흥분하다","조급하다","당황하다"],"answerIndex":0},{"type":"antonym","word":"침착하다","choices":["당황하다","태연하다","냉정하다","차분하다"],"answerIndex":0},{"type":"spelling","word":"낭떠러지","choices":["낭떨러지","낭떠러지","낭떨어지","낭떠어지"],"answerIndex":1}]'::jsonb, 68)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('acorn-height-comparing', '🌰', '도토리들의 키 재기', '["반에서 그림을 가장 잘 그리는 두 친구, 라온이와 세아는 늘 서로의 그림을 두고 비교했어요.","\"내가 더 잘 그렸어\", \"아니야, 내가 더 나아\" 하며 사소한 차이로도 자주 다퉜어요.","사실 둘의 실력은 반에서 단연 돋보일 만큼 이미 훌륭했어요.","미술 선생님은 \"두 사람 다 훌륭한데, 도토리 키 재기 하듯 다툴 필요가 있을까?\" 하고 웃으며 말씀하셨어요.","라온이와 세아는 서로 비슷한 실력을 두고 다투기보다 서로에게 배우기로 했어요.","둘은 그 뒤로 더 좋은 그림 친구가 되어 함께 실력을 키워 나갔어요."]'::jsonb, '[{"word":"사소하다","meaning":"보잘것없이 작거나 적다"},{"word":"단연","meaning":"확실히 두드러지게"},{"word":"돋보이다","meaning":"남보다 뛰어나 눈에 띄다"}]'::jsonb, '[{"answer":true,"statement":"라온이와 세아는 그림 실력이 서로 비슷했다."},{"answer":false,"statement":"선생님은 둘의 다툼을 부추기셨다."},{"answer":false,"statement":"라온이와 세아는 끝까지 사이가 나빴다."}]'::jsonb, '{"choices":["실력이 비슷한 사람끼리 사소한 차이로 다투는 것은 의미가 없다","경쟁은 무조건 나쁜 것이다","그림은 항상 한 사람이 더 잘 그리기 마련이다","비교는 자주 할수록 실력이 는다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"사소하다","choices":["전혀 관계가 없다","아주 놀랍다","매우 중요하고 크다","보잘것없이 작거나 적다"],"answerIndex":3},{"type":"proverb","word":"도토리 키재기","choices":["도토리는 다람쥐가 좋아하는 열매다","나무는 자랄수록 열매가 많아진다","키가 큰 사람이 항상 이긴다","비슷한 정도의 사람들끼리 서로 비교하며 다투는 것"],"answerIndex":3},{"type":"synonym","word":"사소하다","choices":["중대하다","엄청나다","자잘하다","거대하다"],"answerIndex":2},{"type":"antonym","word":"사소하다","choices":["중대하다","하찮다","자잘하다","보잘것없다"],"answerIndex":0},{"type":"spelling","word":"알맞은","choices":["알맞은","알맞은은","알맞이","알맞는"],"answerIndex":0}]'::jsonb, 69)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('crab-eyes-south-wind', '🦀', '순식간에 없어진 간식', '["체육 시간이 끝난 뒤, 친구들은 매점에서 산 빵과 과자를 나눠 먹기로 했어요.","누구보다 배가 고팠던 도윤이는 자기 몫이 나오자마자 순식간에 다 먹어 치웠어요.","옆에 있던 친구가 \"마파람에 게 눈 감추듯 먹네\" 하며 웃었어요.","도윤이는 민망해하며 너무 급하게 먹으면 체할 수도 있다는 것을 깨달았어요.","다음부터 도윤이는 아무리 배가 고파도 천천히 꼭꼭 씹어 먹기로 다짐했어요.","친구들과 이야기를 나누며 천천히 먹으니 간식 시간이 훨씬 더 즐거워졌어요."]'::jsonb, '[{"word":"순식간","meaning":"아주 짧은 시간"},{"word":"민망하다","meaning":"낯이 뜨겁고 부끄럽다"},{"word":"체하다","meaning":"먹은 음식이 잘 소화되지 않다"}]'::jsonb, '[{"answer":false,"statement":"도윤이는 간식을 아주 천천히 먹었다."},{"answer":true,"statement":"도윤이는 급하게 먹는 자신을 반성했다."},{"answer":false,"statement":"도윤이는 그 뒤에도 계속 빨리 먹었다."}]'::jsonb, '{"choices":["간식은 빨리 먹을수록 맛있다","아무리 배가 고파도 음식은 천천히 먹는 것이 좋다","배가 고프면 예의를 지킬 필요가 없다","친구들과 나눠 먹으면 항상 다투게 된다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"순식간","choices":["아주 짧은 시간","알 수 없는 시간","적당한 시간","아주 긴 시간"],"answerIndex":0},{"type":"proverb","word":"마파람에 게 눈 감추듯","choices":["남풍이 불면 비가 온다","급하게 먹으면 맛을 못 느낀다는 뜻이 아니다","음식을 아주 빨리 먹어 치우는 모습","게는 눈을 자주 깜빡인다"],"answerIndex":2},{"type":"synonym","word":"순식간","choices":["눈깜짝할사이","며칠","한나절","오랜시간"],"answerIndex":0},{"type":"antonym","word":"순식간","choices":["찰나","순간","오랜시간","단시간"],"answerIndex":2},{"type":"spelling","word":"걸맞은","choices":["걸맞은은","걸맞이","걸맞은","걸맞는"],"answerIndex":2}]'::jsonb, 70)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('thirsty-digs-well', '⛲', '목마른 사람이 판 우물', '["학급 문고에 새 책장이 필요했지만 아무도 먼저 나서지 않았어요.","평소 책을 가장 좋아하던 도현이는 낡은 책장 때문에 책이 자꾸 쌓여 넘어지는 게 몹시 불편했어요.","결국 도현이가 직접 선생님께 건의하고, 방과 후 남아 목수 아저씨와 함께 책장을 정리했어요.","처음엔 귀찮아하던 다른 친구들도 하나둘 도현이를 도와주기 시작했어요.","새 책장이 생기자 반 전체가 훨씬 편하게 책을 읽을 수 있게 되었어요.","친구들은 \"정말 필요했던 사람이 먼저 움직이니 다 같이 좋아졌네\" 하며 도현이에게 고마워했어요."]'::jsonb, '[{"word":"건의하다","meaning":"의견이나 바람을 내놓다"},{"word":"나서다","meaning":"어떤 일에 적극적으로 앞장서다"},{"word":"불편하다","meaning":"어떤 일을 하는 데 편하지 않고 괴롭다"}]'::jsonb, '[{"answer":true,"statement":"도현이는 책장 문제로 가장 불편함을 느꼈다."},{"answer":false,"statement":"반 친구들은 처음부터 적극적으로 도왔다."},{"answer":true,"statement":"결국 학급에는 새 책장이 생겼다."}]'::jsonb, '{"choices":["책장 정리는 어른들만 할 수 있는 일이다","건의는 하지 않는 것이 예의 바른 태도다","필요한 사람이 있어도 누군가 대신 나서 줄 때까지 기다려야 한다","어떤 일이 가장 필요한 사람이 먼저 나서서 움직이면 좋은 결과로 이어질 수 있다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"건의하다","choices":["의견이나 바람을 내놓다","남의 의견을 무시하다","이미 정해진 것을 따르다","아무 말 없이 지켜보다"],"answerIndex":0},{"type":"proverb","word":"목마른 사람이 우물 판다","choices":["우물을 파는 일은 위험하다","우물물은 누구나 마실 수 있다","목이 마르면 참는 것이 좋다","가장 필요하고 급한 사람이 먼저 나서서 일을 하게 된다"],"answerIndex":3},{"type":"synonym","word":"나서다","choices":["숨다","망설이다","앞장서다","물러서다"],"answerIndex":2},{"type":"antonym","word":"불편하다","choices":["괴롭다","편안하다","거북하다","어색하다"],"answerIndex":1},{"type":"spelling","word":"도저히","choices":["도저히","도저이히","도저이","도저히이"],"answerIndex":0}]'::jsonb, 71)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('no-news-good-news', '✉️', '소식 없는 날들', '["해외로 캠프를 떠난 형에게서 며칠째 연락이 오지 않아 은채는 걱정이 됐어요.","엄마는 \"무소식이 희소식이라잖니, 잘 지내고 있을 거야\" 하며 은채를 안심시키셨어요.","은채는 그래도 계속 마음이 쓰여서 매일 휴대폰을 확인했어요.","캠프가 끝나는 날, 형은 활짝 웃는 얼굴로 돌아와 그동안 너무 즐거워서 연락할 틈이 없었다고 했어요.","은채는 괜한 걱정을 했다는 생각에 피식 웃음이 났어요.","은채는 엄마의 말처럼 소식이 없다고 꼭 나쁜 일이 있는 것은 아니라는 걸 알게 되었어요."]'::jsonb, '[{"word":"안심시키다","meaning":"걱정을 덜어 마음을 편하게 하다"},{"word":"마음이 쓰이다","meaning":"자꾸 신경이 쓰이고 걱정되다"},{"word":"괜하다","meaning":"아무 까닭이나 실속이 없다"}]'::jsonb, '[{"answer":false,"statement":"은채는 형에게서 매일 연락을 받았다."},{"answer":true,"statement":"엄마는 은채를 안심시키려 하셨다."},{"answer":true,"statement":"형은 캠프에서 즐거운 시간을 보냈다."}]'::jsonb, '{"choices":["연락이 없으면 반드시 안 좋은 일이 생긴 것이다","캠프는 위험하니 가지 않는 것이 좋다","가족과는 매일 연락해야만 한다","소식이 없다고 해서 꼭 나쁜 일이 생긴 것은 아니다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"안심시키다","choices":["더 불안하게 만들다","화를 나게 하다","걱정을 덜어 마음을 편하게 하다","신경 쓰지 않게 하다"],"answerIndex":2},{"type":"proverb","word":"무소식이 희소식","choices":["희소식은 항상 편지로 온다","연락이 없으면 꼭 나쁜 일이 생긴 것이다","연락이 없는 것은 별일 없이 잘 지내고 있다는 뜻일 수 있다","소식은 빠를수록 좋다"],"answerIndex":2},{"type":"synonym","word":"괜하다","choices":["중요하다","값지다","쓸데없다","필요하다"],"answerIndex":2},{"type":"antonym","word":"안심시키다","choices":["위로하다","불안하게하다","진정시키다","달래다"],"answerIndex":1},{"type":"spelling","word":"일부러","choices":["일부로서","일부러서","일부러","일부로"],"answerIndex":2}]'::jsonb, 72)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('jar-with-no-bottom', '🏺', '밑 빠진 독에 물 붓는 화분', '["지우는 베란다에 화분을 두고 매일 물을 듬뿍 주었지만 식물은 자꾸만 시들어 갔어요.","아무리 물을 많이 줘도 소용이 없어서 지우는 답답한 마음이 들었어요.","식물을 잘 키우는 이웃 아저씨께 여쭤보니, 화분 바닥에 금이 가 물이 다 새고 있었어요.","지우는 그동안 헛되이 물만 부었다는 것을 깨닫고 허탈해했어요.","금 간 화분을 새것으로 바꾸자 신기하게도 식물은 금세 싱그러워졌어요.","지우는 문제의 원인을 먼저 찾는 것이 중요하다는 것을 몸소 배웠어요."]'::jsonb, '[{"word":"듬뿍","meaning":"넘칠 정도로 매우 많이"},{"word":"헛되다","meaning":"아무런 보람이나 효과가 없다"},{"word":"허탈하다","meaning":"기운이 빠지고 몹시 허전하다"}]'::jsonb, '[{"answer":false,"statement":"지우의 화분은 물을 주지 않아도 잘 자랐다."},{"answer":true,"statement":"화분 바닥에 금이 가 물이 새고 있었다."},{"answer":true,"statement":"화분을 바꾼 뒤 식물이 다시 싱그러워졌다."}]'::jsonb, '{"choices":["노력이 소용없을 땐 먼저 근본적인 원인을 찾아야 한다","노력은 결과와 상관없이 항상 의미가 있다","식물은 물을 많이 줄수록 무조건 잘 자란다","화분은 자주 바꾸지 않는 것이 좋다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"허탈하다","choices":["차분하고 편안하다","기운이 빠지고 몹시 허전하다","매우 기쁘고 즐겁다","자랑스럽고 뿌듯하다"],"answerIndex":1},{"type":"proverb","word":"밑 빠진 독에 물 붓기","choices":["화분은 매일 물을 줘야 한다","독은 깨지면 다시 못 쓴다","물은 아껴 써야 한다","아무리 힘을 써도 보람 없이 헛수고로 끝나는 일"],"answerIndex":3},{"type":"synonym","word":"헛되다","choices":["유익하다","무의미하다","보람있다","값지다"],"answerIndex":1},{"type":"antonym","word":"허탈하다","choices":["뿌듯하다","맥빠지다","허전하다","공허하다"],"answerIndex":0},{"type":"spelling","word":"웬만큼","choices":["왠만큼","웬만큼","웬만큼이","왠만큼이"],"answerIndex":1}]'::jsonb, 73)
