insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('seeing-is-believing', '🔭', '백 번 듣기보다 한 번 보기', '["과학 시간에 태양계에 대해 배우던 지안이는 행성의 크기 차이가 잘 와닿지 않았어요.","아무리 설명을 들어도 목성이 지구보다 얼마나 큰지 상상이 되지 않았어요.","주말에 아빠와 천문대에 가서 커다란 망원경으로 직접 목성을 관찰하게 되었어요.","눈으로 직접 본 목성의 줄무늬와 위성들은 책에서 본 것과는 비교할 수 없이 생생했어요.","지안이는 그날 이후 태양계에 대한 내용이 머릿속에 훨씬 또렷하게 남았어요.","지안이는 \"역시 직접 보는 게 최고구나\" 하며 다음에 또 천문대에 가고 싶어졌어요."]'::jsonb, '[{"word":"와닿다","meaning":"어떤 느낌이나 내용이 마음에 실감 나게 다가오다"},{"word":"생생하다","meaning":"눈앞에 보이는 듯 명확하다"},{"word":"또렷하다","meaning":"엉기지 않고 분명하다"}]'::jsonb, '[{"answer":false,"statement":"지안이는 설명만 듣고도 행성 크기를 쉽게 이해했다."},{"answer":true,"statement":"지안이는 천문대에서 직접 목성을 관찰했다."},{"answer":false,"statement":"지안이는 그 뒤로도 내용이 잘 기억나지 않았다."}]'::jsonb, '{"choices":["행성은 크기가 다 똑같다","천문대는 위험한 곳이라 가면 안 된다","책으로 배우는 것은 아무 소용이 없다","여러 번 듣는 것보다 한 번 직접 보고 경험하는 것이 더 확실하다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"생생하다","choices":["아무 느낌이 없다","지루하고 재미없다","눈앞에 보이는 듯 명확하다","희미하고 흐릿하다"],"answerIndex":2},{"type":"proverb","word":"백문이 불여일견","choices":["듣는 것이 보는 것보다 정확하다","무엇이든 여러 번 물어봐야 한다","백 번 듣는 것보다 한 번 직접 보는 것이 더 낫다","눈으로 보는 것은 믿을 수 없다"],"answerIndex":2},{"type":"synonym","word":"또렷하다","choices":["모호하다","흐릿하다","분명하다","희미하다"],"answerIndex":2},{"type":"antonym","word":"생생하다","choices":["뚜렷하다","또렷하다","희미하다","선명하다"],"answerIndex":2},{"type":"spelling","word":"어쭙잖다","choices":["어쭙잔다","어줍잖다","어줍잔다","어쭙잖다"],"answerIndex":3}]'::jsonb, 74)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('wound-then-medicine', '🩹', '상처 주고 약 준 짓궂은 장난', '["체육 시간에 재윤이는 친구를 놀리려고 몰래 신발끈을 묶어 놓았다가 그 친구가 넘어지고 말았어요.","깜짝 놀란 재윤이는 곧바로 달려가 다친 무릎에 반창고를 붙여 주며 미안하다고 했어요.","친구는 \"네가 그런 장난만 안 쳤어도 안 다쳤을 텐데\" 하며 서운함을 감추지 못했어요.","재윤이는 자신의 장난이 먼저 문제를 일으켰다는 걸 인정하고 진심으로 사과했어요.","재윤이는 그 뒤로 남을 놀리는 장난은 아무리 재미있어 보여도 하지 않기로 결심했어요.","두 친구는 시간이 지나며 다시 예전처럼 사이좋게 지내게 되었어요."]'::jsonb, '[{"word":"짓궂다","meaning":"장난이 심하여 남을 곤란하게 하다"},{"word":"서운하다","meaning":"마음에 아쉽고 섭섭하다"},{"word":"인정하다","meaning":"어떤 사실을 옳다고 받아들이다"}]'::jsonb, '[{"answer":false,"statement":"재윤이는 일부러 친구를 다치게 하려 했다."},{"answer":true,"statement":"재윤이는 다친 친구에게 반창고를 붙여 주었다."},{"answer":false,"statement":"친구는 재윤이의 사과를 듣고도 계속 화만 냈다."}]'::jsonb, '{"choices":["넘어진 것은 전적으로 친구의 잘못이다","장난을 친 뒤 도와주면 아무 문제가 없다","먼저 문제를 일으키고 나중에 도와주는 행동보다 애초에 조심하는 것이 중요하다","사과는 하지 않아도 상관없다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"짓궂다","choices":["매우 친절하고 다정하다","조용하고 얌전하다","장난이 심하여 남을 곤란하게 하다","성실하고 부지런하다"],"answerIndex":2},{"type":"proverb","word":"병 주고 약 준다","choices":["아플 때는 약을 먹어야 한다","약은 정해진 시간에 먹어야 한다","남을 해롭게 해 놓고 도와주는 척한다","병은 미리 예방하는 것이 좋다"],"answerIndex":2},{"type":"synonym","word":"서운하다","choices":["반갑다","기쁘다","만족스럽다","섭섭하다"],"answerIndex":3},{"type":"antonym","word":"짓궂다","choices":["다정하다","심술궂다","짓궂다","얄궂다"],"answerIndex":0},{"type":"spelling","word":"발자국","choices":["발자국","발짜국","발자옥","발자욱"],"answerIndex":0}]'::jsonb, 75)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('fanning-burning-house', '🔥', '불난 집에 부채질한 댓글', '["온라인 학급 게시판에서 두 친구가 사소한 오해로 다투기 시작했어요.","지켜보던 몇몇 친구들은 재미있다는 듯 자꾸 자극적인 댓글을 달며 싸움을 부추겼어요.","작았던 다툼은 순식간에 반 전체가 아는 큰 갈등으로 번지고 말았어요.","결국 선생님이 나서서야 두 친구는 서로 오해를 풀고 화해할 수 있었어요.","선생님은 \"다투는 걸 부추기는 댓글이 오히려 상황을 더 나쁘게 만든다\"고 말씀하셨어요.","지켜보던 친구들은 그제야 자신들의 댓글이 불난 집에 부채질한 것과 같았다는 걸 깨달았어요."]'::jsonb, '[{"word":"부추기다","meaning":"남을 이리저리 들쑤셔서 어떤 일을 하게 만들다"},{"word":"자극적","meaning":"강한 반응을 일으키는"},{"word":"번지다","meaning":"작은 일이 크게 퍼져 나가다"}]'::jsonb, '[{"answer":true,"statement":"처음 다툼은 사소한 오해에서 시작되었다."},{"answer":false,"statement":"친구들의 댓글은 갈등을 가라앉히는 데 도움이 되었다."},{"answer":true,"statement":"결국 선생님이 나서서 화해를 도왔다."}]'::jsonb, '{"choices":["다툼은 지켜보는 사람과는 아무 상관이 없다","온라인에서는 무슨 말을 해도 괜찮다","댓글은 자극적일수록 재미있다","이미 힘든 상황에서 부추기는 말은 문제를 더 크게 만든다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"부추기다","choices":["남을 이리저리 들쑤셔서 어떤 일을 하게 만들다","차분히 위로하다","조용히 말리다","가만히 지켜보다"],"answerIndex":0},{"type":"proverb","word":"불난 집에 부채질","choices":["집은 불에 잘 타지 않게 지어야 한다","불은 물로 꺼야 한다","이미 어려운 상황을 더 나쁘게 만드는 행동","부채는 더운 날 유용하다"],"answerIndex":2},{"type":"synonym","word":"부추기다","choices":["말리다","진정시키다","자극하다","달래다"],"answerIndex":2},{"type":"antonym","word":"부추기다","choices":["들쑤시다","충동질하다","말리다","자극하다"],"answerIndex":2},{"type":"spelling","word":"뒤꿈치","choices":["뒤꿈치","뒷꿈치","뒷꿉치","뒤꿉치"],"answerIndex":0}]'::jsonb, 76)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('ground-hardens-after-rain', '🌦️', '비 온 뒤 굳어진 우정', '["나윤이와 하은이는 사소한 말다툼으로 며칠간 서로 말도 하지 않았어요.","반 친구들도 둘 사이의 냉랭한 분위기를 눈치챌 정도였어요.","결국 나윤이가 먼저 용기를 내어 하은이에게 다가가 진심으로 사과했어요.","둘은 그동안 쌓였던 서운한 마음을 솔직하게 털어놓으며 오해를 풀었어요.","신기하게도 화해한 뒤 둘의 우정은 다투기 전보다 훨씬 더 단단해졌어요.","나윤이는 \"다투고 화해하면서 서로를 더 잘 알게 됐구나\" 하고 느꼈어요."]'::jsonb, '[{"word":"냉랭하다","meaning":"태도가 정답지 않고 차갑다"},{"word":"털어놓다","meaning":"마음속의 생각을 숨김없이 말하다"},{"word":"단단해지다","meaning":"연하지 않고 굳고 튼튼해지다"}]'::jsonb, '[{"answer":true,"statement":"나윤이와 하은이는 며칠간 서로 말을 하지 않았다."},{"answer":true,"statement":"나윤이가 먼저 사과하며 다가갔다."},{"answer":false,"statement":"화해한 뒤 둘의 사이는 오히려 더 나빠졌다."}]'::jsonb, '{"choices":["한번 다툰 친구와는 다시 가까워질 수 없다","다툼은 무조건 피해야 하는 나쁜 일이다","다툼을 잘 풀고 나면 오히려 관계가 더 단단해질 수 있다","먼저 사과하는 사람이 지는 것이다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"냉랭하다","choices":["매우 다정하고 따뜻하다","아주 활발하고 신나다","조용하고 차분하다","태도가 정답지 않고 차갑다"],"answerIndex":3},{"type":"proverb","word":"비 온 뒤에 땅이 굳어진다","choices":["날씨는 예측하기 어렵다","힘든 일을 겪고 나면 오히려 사이가 더 좋아지거나 단단해진다","비가 오면 땅이 질척거려 걷기 힘들다","비 온 뒤에는 무지개가 뜬다"],"answerIndex":1},{"type":"synonym","word":"단단해지다","choices":["무뎌지다","약해지다","흐트러지다","견고해지다"],"answerIndex":3},{"type":"antonym","word":"냉랭하다","choices":["다정하다","차갑다","냉정하다","쌀쌀하다"],"answerIndex":0},{"type":"spelling","word":"곱빼기","choices":["곱뱌기","곱빼기","곱뻬기","곱배기"],"answerIndex":1}]'::jsonb, 77)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('carpenter-blames-tools', '🔨', '연장 탓하는 목수처럼', '["목공 수업에서 만든 작품이 삐뚤빼뚤하게 나오자 준서는 \"이 톱이 낡아서 그래\" 하며 투덜댔어요.","옆에서 지켜보던 선생님은 조용히 다른 톱을 건네주며 다시 해 보라고 하셨어요.","새 톱으로도 결과는 크게 다르지 않았고, 준서는 자신의 손놀림이 서툴렀다는 것을 인정할 수밖에 없었어요.","선생님은 \"연장 탓을 하기 전에 자신의 실력을 먼저 돌아보는 게 중요하단다\" 하고 말씀하셨어요.","준서는 부끄러워하면서도 그날부터 꾸준히 연습해 손놀림을 익혀 나갔어요.","몇 주 뒤, 준서는 낡은 도구로도 반듯한 작품을 만들 수 있게 되었어요."]'::jsonb, '[{"word":"삐뚤빼뚤하다","meaning":"이리저리 몹시 비뚤어져 있다"},{"word":"투덜대다","meaning":"불평을 자꾸 중얼거리다"},{"word":"손놀림","meaning":"손을 움직이는 모양이나 솜씨"}]'::jsonb, '[{"answer":true,"statement":"준서는 처음에 톱 탓을 했다."},{"answer":false,"statement":"새 톱으로 바꾸자 결과가 완전히 달라졌다."},{"answer":true,"statement":"준서는 꾸준히 연습해 실력을 키웠다."}]'::jsonb, '{"choices":["실력이 부족하면 다른 일을 하는 것이 낫다","결과가 좋지 않을 때는 도구보다 자신의 실력을 먼저 돌아봐야 한다","좋은 도구만 있으면 누구나 잘 만들 수 있다","목공 수업은 위험하니 조심해야 한다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"투덜대다","choices":["불평을 자꾸 중얼거리다","큰 소리로 응원하다","밝게 웃으며 칭찬하다","조용히 집중하다"],"answerIndex":0},{"type":"proverb","word":"서투른 목수가 연장 탓한다","choices":["목수는 연장을 아껴 써야 한다","실력이 부족한 사람이 애꿎은 도구나 조건을 탓한다","나무마다 단단한 정도가 다르다","좋은 도구는 비쌀수록 좋다"],"answerIndex":1},{"type":"synonym","word":"투덜대다","choices":["만족하다","격려하다","칭찬하다","불평하다"],"answerIndex":3},{"type":"antonym","word":"서투르다","choices":["능숙하다","미숙하다","어설프다","서투르다"],"answerIndex":0},{"type":"spelling","word":"몹쓸","choices":["못쓸","몹쓸","못슬","몹슬"],"answerIndex":1}]'::jsonb, 78)
