insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('time-is-medicine', '⏳', '시간이 약이 되어 준 이별', '["가장 친했던 친구가 다른 지역으로 이사를 가게 되어 서아는 몹시 슬펐어요.","한동안 서아는 학교에서도 자주 우울한 얼굴을 하고 있었어요.","엄마는 \"지금은 많이 힘들겠지만 시간이 지나면 마음이 조금씩 편해질 거야\" 하고 다독여 주셨어요.","몇 주가 지나자 서아는 조금씩 새로운 일상에 적응하며 다른 친구들과도 가까워졌어요.","여전히 친구가 그립긴 했지만, 처음처럼 마음이 아프지는 않았어요.","서아는 영상통화로 안부를 전하며 멀리서도 우정을 이어 갔어요."]'::jsonb, '[{"word":"몹시","meaning":"더할 수 없이 심하게"},{"word":"적응하다","meaning":"새로운 환경에 익숙해지다"},{"word":"안부","meaning":"편안하게 잘 지내는지 묻는 인사"}]'::jsonb, '[{"answer":true,"statement":"서아의 친구는 다른 지역으로 이사를 갔다."},{"answer":false,"statement":"서아는 시간이 지나도 전혀 나아지지 않았다."},{"answer":true,"statement":"서아는 영상통화로 친구와 연락을 이어 갔다."}]'::jsonb, '{"choices":["이별의 슬픔은 절대 나아지지 않는다","슬플 때는 아무것도 하지 않고 참아야 한다","친구가 떠나면 다시는 연락하지 않는 것이 좋다","힘든 마음도 시간이 지나면 조금씩 나아질 수 있다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"적응하다","choices":["새로운 환경에 익숙해지다","아무 관심이 없다","전혀 익숙해지지 못하다","계속 낯설어하다"],"answerIndex":0},{"type":"proverb","word":"세월이 약이다","choices":["슬픔은 참는 것이 가장 좋다","힘들었던 마음도 시간이 지나면 점차 나아진다","세월이 지나면 모든 것을 잊어야 한다","약은 정해진 시간에 먹어야 한다"],"answerIndex":1},{"type":"synonym","word":"몹시","choices":["매우","조금","약간","살짝"],"answerIndex":0},{"type":"antonym","word":"적응하다","choices":["익숙해지다","길들다","순응하다","낯설어하다"],"answerIndex":3},{"type":"spelling","word":"안성맞춤","choices":["안성마춤","안성맞흠","안성맏춤","안성맞춤"],"answerIndex":3}]'::jsonb, 79)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('sail-with-tailwind', '⛵', '순풍에 돛 단 듯한 첫날', '["전학 온 첫날, 태오는 걱정했던 것과 달리 모든 일이 순조롭게 풀려 나갔어요.","반장이 먼저 다가와 친절하게 학교 이곳저곳을 안내해 주었고, 짝꿍도 살갑게 말을 걸어 주었어요.","급식 시간에도 마침 태오가 좋아하는 반찬이 나와 기분 좋게 점심을 먹었어요.","수업 시간에 발표한 내용도 술술 잘 풀려 선생님께 칭찬까지 들었어요.","태오는 \"순풍에 돛을 단 것처럼 오늘 하루가 술술 풀렸어\" 하며 기쁜 마음으로 집에 돌아갔어요.","태오는 새로운 학교생활에 대한 걱정이 조금씩 사라지는 것을 느꼈어요."]'::jsonb, '[{"word":"순조롭다","meaning":"아무 탈 없이 순탄하게 되어 가다"},{"word":"살갑다","meaning":"마음씨가 부드럽고 친절하다"},{"word":"술술","meaning":"일이 막힘없이 잘 풀리는 모양"}]'::jsonb, '[{"answer":false,"statement":"태오는 전학 첫날 힘든 일만 겪었다."},{"answer":true,"statement":"반장이 먼저 다가와 학교를 안내해 주었다."},{"answer":false,"statement":"태오는 발표를 하다 실수해서 혼이 났다."}]'::jsonb, '{"choices":["새로운 환경에서는 절대 마음을 놓으면 안 된다","전학은 항상 힘들고 어려운 일이다","걱정했던 일도 뜻밖에 순조롭게 잘 풀릴 수 있다","반장은 항상 새로 온 친구를 도와줄 의무가 있다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"순조롭다","choices":["몹시 힘들고 어렵다","아무 탈 없이 순탄하게 되어 가다","자꾸 문제가 생기다","전혀 진행되지 않다"],"answerIndex":1},{"type":"proverb","word":"순풍에 돛을 단 듯","choices":["일이 조건이 잘 맞아 순조롭게 진행되는 모습","돛은 튼튼하게 만들어야 한다","순풍은 예측하기 어렵다","배는 바람이 없으면 갈 수 없다"],"answerIndex":0},{"type":"synonym","word":"순조롭다","choices":["까다롭다","순탄하다","험난하다","순탄치않다"],"answerIndex":1},{"type":"antonym","word":"순조롭다","choices":["순탄하다","수월하다","험난하다","평탄하다"],"answerIndex":2},{"type":"spelling","word":"넓적하다","choices":["넓적하다","넓쩍하다","넙쩍하다","넙적하다"],"answerIndex":0}]'::jsonb, 80)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('failure-mother-success', '🔬', '실패는 성공의 어머니', '["로봇 동아리에서 준비한 자동 청소 로봇이 대회 예선에서 그만 멈춰 서 버렸어요.","몇 달간 공들여 만든 로봇이 작동하지 않자 동아리 친구들은 크게 낙담했어요.","지도 선생님은 \"이번 실패에서 원인을 찾으면 다음엔 더 좋은 로봇을 만들 수 있어\" 하고 격려해 주셨어요.","친구들은 실패 원인을 하나하나 분석하며 배선 연결에 문제가 있었다는 것을 알아냈어요.","다음 대회에서 친구들은 개선된 로봇으로 마침내 좋은 성적을 거두었어요.","친구들은 \"그때 실패하지 않았다면 이렇게 배우지 못했을 거야\" 하며 웃었어요."]'::jsonb, '[{"word":"공들이다","meaning":"어떤 일을 이루려고 정성과 힘을 많이 쓰다"},{"word":"낙담하다","meaning":"바라던 일이 어긋나 마음이 상하다"},{"word":"분석하다","meaning":"얽힌 것을 풀어 자세히 나누어 살피다"}]'::jsonb, '[{"answer":true,"statement":"로봇은 예선에서 멈춰 서 버렸다."},{"answer":false,"statement":"친구들은 실패 원인을 찾으려 하지 않았다."},{"answer":true,"statement":"다음 대회에서 좋은 성적을 거두었다."}]'::jsonb, '{"choices":["로봇 대회는 운이 전부다","실패하면 바로 포기하는 것이 현명하다","실패의 원인을 잘 살펴보면 다음에 더 좋은 결과로 이어질 수 있다","한번 실패한 일은 다시 도전하지 않는 것이 좋다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"낙담하다","choices":["바라던 일이 어긋나 마음이 상하다","자신만만해하다","크게 기뻐하다","아무 느낌이 없다"],"answerIndex":0},{"type":"proverb","word":"실패는 성공의 어머니","choices":["성공하려면 절대 실패하면 안 된다","실패를 통해 배우면 결국 성공으로 이어질 수 있다","실패는 아무 의미가 없는 일이다","어머니는 항상 옳은 말씀을 하신다"],"answerIndex":1},{"type":"synonym","word":"낙담하다","choices":["실망하다","만족하다","뿌듯해하다","기뻐하다"],"answerIndex":0},{"type":"antonym","word":"낙담하다","choices":["좌절하다","기뻐하다","실망하다","상심하다"],"answerIndex":1},{"type":"spelling","word":"널브러지다","choices":["널부러지다","널부러저다","널브러저다","널브러지다"],"answerIndex":3}]'::jsonb, 81)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('word-choice-nuance', '💬', '아 다르고 어 다른 한마디', '["모둠 활동에서 실수를 한 친구에게 두 사람이 각각 다르게 말을 건넸어요.","한 친구는 \"그것도 못 하냐\"며 툭 쏘아붙였고, 다른 친구는 \"괜찮아, 다시 해 보자\"라고 다정하게 말했어요.","같은 상황이었지만 실수한 친구는 첫 번째 말에는 크게 상처받았고, 두 번째 말에는 오히려 힘을 얻었어요.","이를 지켜본 선생님은 \"같은 뜻이라도 표현 방식에 따라 마음이 다르게 느껴진단다\" 하고 설명해 주셨어요.","친구들은 그날 이후로 말을 할 때 표현을 조금 더 신경 써서 골랐어요.","반 분위기는 서로를 배려하는 말들로 훨씬 더 따뜻해졌어요."]'::jsonb, '[{"word":"쏘아붙이다","meaning":"날카롭고 매섭게 말하다"},{"word":"상처받다","meaning":"마음에 아픔이나 괴로움을 느끼다"},{"word":"배려하다","meaning":"남을 돌보아 주려고 마음을 쓰다"}]'::jsonb, '[{"answer":false,"statement":"두 친구는 완전히 똑같은 방식으로 말했다."},{"answer":true,"statement":"실수한 친구는 다정한 말에 힘을 얻었다."},{"answer":false,"statement":"선생님은 표현 방식이 중요하지 않다고 하셨다."}]'::jsonb, '{"choices":["같은 뜻이라도 어떻게 표현하느냐에 따라 상대의 마음이 달라진다","위로하는 말은 오히려 도움이 되지 않는다","말은 뜻만 통하면 표현 방식은 중요하지 않다","실수한 사람에게는 엄격하게 말해야 한다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"쏘아붙이다","choices":["재미있게 농담하다","조용히 속삭이다","부드럽고 다정하게 말하다","날카롭고 매섭게 말하다"],"answerIndex":3},{"type":"proverb","word":"아 다르고 어 다르다","choices":["한글 자음은 소리가 다양하다","말은 크게 할수록 잘 전달된다","같은 말이라도 표현하는 방식에 따라 느낌이 크게 달라진다","말은 짧을수록 좋다"],"answerIndex":2},{"type":"synonym","word":"배려하다","choices":["헤아리다","방치하다","무시하다","외면하다"],"answerIndex":0},{"type":"antonym","word":"쏘아붙이다","choices":["쏘아붙이다","날카롭게말하다","다정하게말하다","매섭게말하다"],"answerIndex":2},{"type":"spelling","word":"상추","choices":["상치","상칫","상추","상추이"],"answerIndex":2}]'::jsonb, 82)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('crying-baby-gets-milk', '🙋', '우는 아이 젖 준다', '["학급 회의에서 체육 시간에 하고 싶은 운동을 정하고 있었어요.","다연이는 피구를 하고 싶었지만 소극적인 성격이라 말을 꺼내지 못하고 조용히 있었어요.","반면 몇몇 친구들은 계속 큰 목소리로 자기가 원하는 운동을 이야기했어요.","결국 계속 의견을 낸 친구들이 원하는 축구로 정해졌어요.","다연이는 속으로 아쉬워하다가, 다음 회의부터는 원하는 것을 용기 내어 말해 보기로 다짐했어요.","다음 회의에서 다연이가 손을 들고 의견을 말하자 반 친구들이 귀 기울여 들어 주었어요."]'::jsonb, '[{"word":"소극적","meaning":"스스로 앞에 나서지 않는 성격이나 태도"},{"word":"꺼내다","meaning":"말이나 의견을 밖으로 드러내다"},{"word":"귀기울이다","meaning":"남의 말을 주의 깊게 듣다"}]'::jsonb, '[{"answer":true,"statement":"다연이는 처음에 자기 의견을 말하지 못했다."},{"answer":false,"statement":"체육 시간 운동은 결국 다연이가 원하는 것으로 정해졌다."},{"answer":true,"statement":"다연이는 다음 회의에서 용기 내어 말했다."}]'::jsonb, '{"choices":["말을 많이 하는 사람은 이기적인 것이다","회의에서는 조용히 있는 것이 예의다","자기 생각을 적극적으로 표현해야 원하는 것을 얻을 가능성이 커진다","의견은 한 번 말하면 절대 바뀌지 않는다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"소극적","choices":["매우 시끄러운","적극적이고 활발한","자신감이 넘치는","스스로 앞에 나서지 않는 성격이나 태도"],"answerIndex":3},{"type":"proverb","word":"우는 아이 젖 준다","choices":["자기 요구를 적극적으로 표현해야 원하는 것을 얻을 수 있다","젖은 정해진 시간에 줘야 한다","조용한 아이가 더 사랑받는다","아이는 울면 안 된다"],"answerIndex":0},{"type":"synonym","word":"소극적","choices":["적극적","활동적","능동적","수동적"],"answerIndex":3},{"type":"antonym","word":"소극적","choices":["소심한","수동적","적극적","내성적"],"answerIndex":2},{"type":"spelling","word":"재떨이","choices":["재털이이","재떨이","재털이","재떨이이"],"answerIndex":1}]'::jsonb, 83)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('rivals-meet-narrow-bridge', '🌉', '외나무다리에서 만난 원수', '["작년에 달리기 시합에서 크게 다퉜던 우진이와 시안이는 그동안 서로를 피해 다녔어요.","그런데 이번 학년 체육대회 계주에서 하필 두 사람이 같은 팀으로 뽑히고 말았어요.","둘 다 어색해하며 서로 눈도 마주치지 않으려 했어요.","하지만 함께 훈련하며 손발을 맞추다 보니 자연스럽게 대화가 늘어났어요.","결국 둘은 예전 다툼에 대해 솔직히 이야기하며 오해를 풀고 화해했어요.","계주 날, 우진이와 시안이는 완벽한 호흡으로 팀에 좋은 결과를 안겨 주었어요."]'::jsonb, '[{"word":"피하다","meaning":"어떤 대상을 만나지 않으려고 하다"},{"word":"손발을 맞추다","meaning":"함께 일할 때 서로 뜻이나 행동을 맞추다"},{"word":"호흡","meaning":"함께 일할 때 서로 맞는 정도"}]'::jsonb, '[{"answer":true,"statement":"우진이와 시안이는 작년에 크게 다툰 적이 있다."},{"answer":false,"statement":"둘은 계주에서 각자 다른 팀이 되었다."},{"answer":true,"statement":"둘은 훈련하며 오해를 풀고 화해했다."}]'::jsonb, '{"choices":["계주는 팀워크와 상관없는 개인 경기다","피하고 싶은 상대라도 뜻밖에 다시 만나 화해할 기회가 생길 수 있다","화해는 시간이 지나면 저절로 이루어진다","한번 다툰 사람과는 절대 같은 팀이 되면 안 된다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"호흡","choices":["숨을 쉬는 방법","함께 일할 때 서로 맞는 정도","혼자 일하는 방식","경기의 규칙"],"answerIndex":1},{"type":"proverb","word":"원수는 외나무다리에서 만난다","choices":["피하고 싶은 대상을 피할 수 없는 좁은 상황에서 다시 마주치게 된다","외나무다리는 위험하니 건너지 말아야 한다","원수와는 절대 화해할 수 없다","다리는 튼튼하게 지어야 한다"],"answerIndex":0},{"type":"synonym","word":"피하다","choices":["맞서다","멀리하다","마주하다","다가가다"],"answerIndex":1},{"type":"antonym","word":"피하다","choices":["멀리하다","피하다","외면하다","맞서다"],"answerIndex":3},{"type":"spelling","word":"얼룩덜룩","choices":["얼룩덜럭","얼룩털룩","얼룩털럭","얼룩덜룩"],"answerIndex":3}]'::jsonb, 84)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('worm-wriggles-when-stepped', '🪱', '밟히면 꿈틀하는 지렁이', '["평소 순하기로 유명한 하율이는 친구들의 짓궂은 장난도 늘 웃으며 넘겼어요.","그런데 한 친구가 도를 넘어 하율이의 소중한 그림을 함부로 낙서해 버렸어요.","평소와 달리 하율이는 정색을 하며 단호하게 그만하라고 말했어요.","깜짝 놀란 친구는 \"네가 이렇게까지 화낼 줄 몰랐어\" 하며 당황했어요.","하율이는 \"아무리 순한 사람도 계속 참기만 할 수는 없어\"라고 차분히 말했어요.","그 친구는 진심으로 사과했고, 그 뒤로는 하율이를 함부로 대하지 않았어요."]'::jsonb, '[{"word":"도를 넘다","meaning":"정도가 지나치게 심하다"},{"word":"정색하다","meaning":"얼굴빛을 바르게 하고 태도를 엄정히 하다"},{"word":"단호하다","meaning":"결심이나 태도가 흔들림 없이 엄격하다"}]'::jsonb, '[{"answer":false,"statement":"하율이는 평소 화를 잘 내는 성격이었다."},{"answer":true,"statement":"한 친구가 하율이의 그림에 낙서를 했다."},{"answer":false,"statement":"하율이는 끝까지 아무 말도 하지 않았다."}]'::jsonb, '{"choices":["순한 사람은 어떤 장난을 쳐도 괜찮다","아무리 순한 사람도 지나친 행동에는 화를 낼 수 있다","소중한 물건은 함부로 다뤄도 상관없다","화를 내는 것은 항상 나쁜 행동이다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"단호하다","choices":["결심이나 태도가 흔들림 없이 엄격하다","무관심하고 냉담하다","우유부단하고 흔들리다","아주 부드럽고 유순하다"],"answerIndex":0},{"type":"proverb","word":"지렁이도 밟으면 꿈틀한다","choices":["지렁이는 땅속에서 산다","순한 사람은 절대 화를 내지 않는다","아무리 순한 사람이라도 지나치게 괴롭히면 반발한다","작은 동물도 소중히 여겨야 한다"],"answerIndex":2},{"type":"synonym","word":"단호하다","choices":["흐리멍텅하다","우유부단하다","확고하다","애매하다"],"answerIndex":2},{"type":"antonym","word":"단호하다","choices":["엄격하다","우유부단하다","확고하다","결연하다"],"answerIndex":1},{"type":"spelling","word":"안쓰럽다","choices":["안스렵다","안스럽다","안쓰럽다","안쓰렵다"],"answerIndex":2}]'::jsonb, 85)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('first-spoonful-full', '🥄', '한 술 밥에 배부를 리 없다', '["줄넘기를 처음 배우기 시작한 하빈이는 딱 하루 연습하고는 여전히 잘 안 된다며 속상해했어요.","\"나는 재능이 없나 봐\" 하며 금방 포기하려는 하빈이에게 언니가 다가왔어요.","언니는 \"첫술에 배부를 수 없듯이, 하루 만에 잘하는 사람은 없어\" 하고 말해 주었어요.","하빈이는 언니의 말을 듣고 조급한 마음을 내려놓기로 했어요.","매일 조금씩 꾸준히 연습한 끝에 한 달 후 하빈이는 백 개도 거뜬히 뛸 수 있게 되었어요.","하빈이는 \"처음부터 잘하기를 바랐던 내가 성급했구나\" 하고 웃으며 돌아봤어요."]'::jsonb, '[{"word":"조급하다","meaning":"참을성 없이 몹시 급하다"},{"word":"내려놓다","meaning":"마음의 부담이나 욕심을 버리다"},{"word":"거뜬히","meaning":"무엇을 하는 것이 매우 쉽게"}]'::jsonb, '[{"answer":false,"statement":"하빈이는 첫날부터 줄넘기를 아주 잘했다."},{"answer":true,"statement":"언니는 하빈이에게 조급해하지 말라고 말해 주었다."},{"answer":true,"statement":"한 달 뒤 하빈이는 줄넘기를 백 개도 뛸 수 있게 되었다."}]'::jsonb, '{"choices":["재능이 없으면 아무리 연습해도 소용없다","노력보다 타고난 재능이 훨씬 중요하다","무슨 일이든 한 번에 잘되기를 바라지 말고 꾸준히 연습해야 한다","줄넘기는 하루 만에 배울 수 있는 쉬운 운동이다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"조급하다","choices":["여유롭고 느긋하다","꾸준하고 성실하다","차분하고 침착하다","참을성 없이 몹시 급하다"],"answerIndex":3},{"type":"proverb","word":"첫술에 배부르랴","choices":["밥은 천천히 먹어야 소화가 잘된다","배가 부르면 그만 먹어야 한다","첫 숟가락이 가장 맛있다","무슨 일이든 처음부터 큰 성과를 기대할 수 없다"],"answerIndex":3},{"type":"synonym","word":"조급하다","choices":["여유롭다","성급하다","느긋하다","태연하다"],"answerIndex":1},{"type":"antonym","word":"조급하다","choices":["성급하다","급하다","느긋하다","초조하다"],"answerIndex":2},{"type":"spelling","word":"통째로","choices":["통채로","통체로","통째로","통쨰로"],"answerIndex":2}]'::jsonb, 86)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('follow-friend-blindly', '🎸', '친구 따라 나선 학원', '["가장 친한 친구가 기타 학원에 등록하자 서준이도 별 고민 없이 곧장 따라 등록했어요.","하지만 막상 다녀 보니 서준이는 악기에 큰 흥미를 느끼지 못했어요.","반면 친구는 진심으로 기타를 좋아해서 매일 신나게 연습했어요.","몇 주 뒤 서준이는 억지로 다니는 학원이 즐겁지 않다는 것을 깨닫고 부모님과 상의했어요.","서준이는 자신이 정말 좋아하는 그림 그리기 수업으로 바꾸었고, 훨씬 즐겁게 배울 수 있었어요.","서준이는 \"친구를 따라가기보다 내가 좋아하는 걸 찾는 게 중요하구나\" 하고 느꼈어요."]'::jsonb, '[{"word":"등록하다","meaning":"문서나 명부에 이름을 올리다"},{"word":"흥미","meaning":"어떤 것에 마음이 끌리는 관심"},{"word":"상의하다","meaning":"어떤 일을 함께 의논하다"}]'::jsonb, '[{"answer":false,"statement":"서준이는 기타 학원에서 큰 흥미를 느꼈다."},{"answer":true,"statement":"서준이는 친구를 따라 별 고민 없이 학원에 등록했다."},{"answer":true,"statement":"서준이는 결국 그림 수업으로 바꾸었다."}]'::jsonb, '{"choices":["친구가 하는 것은 무조건 따라 하는 것이 좋다","학원은 한번 등록하면 끝까지 다녀야 한다","남을 무작정 따라 하기보다 자신이 진짜 좋아하는 것을 찾아야 한다","악기는 누구나 배우기 어려운 것이다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"흥미","choices":["몹시 지루한 느낌","어떤 것에 마음이 끌리는 관심","전혀 관심이 없는 상태","깊은 슬픔의 감정"],"answerIndex":1},{"type":"proverb","word":"친구 따라 강남 간다","choices":["친구와는 항상 같은 것을 배워야 한다","자기 생각 없이 남이 하는 대로 따라 한다","강남은 아주 먼 곳이다","여행은 친구와 함께 가는 것이 좋다"],"answerIndex":1},{"type":"synonym","word":"상의하다","choices":["혼자정하다","무시하다","숨기다","의논하다"],"answerIndex":3},{"type":"antonym","word":"흥미","choices":["재미","호기심","관심","무관심"],"answerIndex":3},{"type":"spelling","word":"껍질째","choices":["껍질체","껍질채","껍질째","껍질찌"],"answerIndex":2}]'::jsonb, 87)
