insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('arm-bends-inward', '🤝', '안으로 굽은 팔', '["반 대항 축구 경기에서 심판을 보게 된 하늘이는 실수로 같은 반 친구의 반칙을 못 본 척 넘어갔어요.","상대 팀 친구들은 \"저건 명백한 반칙이었잖아\" 하며 억울해했어요.","하늘이도 마음속으로는 팔이 안으로 굽는 것처럼 자기 반 편을 들고 싶었다는 걸 인정했어요.","경기가 끝난 뒤 하늘이는 상대 팀에게 진심으로 사과하고, 다음부터는 공정하게 판정하겠다고 약속했어요.","다음 경기에서 하늘이는 어느 팀에도 치우치지 않고 공정하게 심판을 봤어요.","양 팀 친구들 모두 하늘이의 공정한 판정에 고마워했어요."]'::jsonb, '[{"word":"명백하다","meaning":"의심할 여지없이 아주 뚜렷하다"},{"word":"편을 들다","meaning":"한쪽 편이 되어 도와주다"},{"word":"치우치다","meaning":"균형을 잃고 한쪽으로 쏠리다"}]'::jsonb, '[{"answer":false,"statement":"하늘이는 상대 팀의 반칙을 정확히 판정했다."},{"answer":true,"statement":"하늘이는 자신의 실수를 인정하고 사과했다."},{"answer":true,"statement":"다음 경기에서 하늘이는 공정하게 심판을 봤다."}]'::jsonb, '{"choices":["심판은 항상 자기 편을 들어도 괜찮다","반칙은 크게 문제 되지 않는다","가까운 사람 편을 들고 싶은 마음이 들어도 공정함을 지키려 노력해야 한다","경기 결과보다 친한 사이가 더 중요하다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"치우치다","choices":["정확하게 맞다","고르게 퍼지다","공평하게 나뉘다","균형을 잃고 한쪽으로 쏠리다"],"answerIndex":3},{"type":"proverb","word":"팔은 안으로 굽는다","choices":["심판은 경기 규칙을 잘 알아야 한다","사람은 자연히 자기와 가까운 쪽에 마음이 기울게 된다","운동은 몸에 좋은 습관이다","팔을 다치면 조심해야 한다"],"answerIndex":1},{"type":"synonym","word":"명백하다","choices":["뚜렷하다","애매하다","모호하다","희미하다"],"answerIndex":0},{"type":"antonym","word":"치우치다","choices":["기울다","편중되다","쏠리다","공평하다"],"answerIndex":3},{"type":"spelling","word":"얽히고설키다","choices":["얽히고섥이다","얼키고섥이다","얼키고설키다","얽히고설키다"],"answerIndex":3}]'::jsonb, 88)
