insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('no-grave-without-excuse', '📢', '핑계 없는 무덤 없다', '["준영이는 준비물을 챙겨 오지 않을 때마다 매번 그럴듯한 이유를 댔어요.","\"어제 늦게 자서요\", \"가방을 헷갈려서요\" 등 이유는 매번 달랐지만 준비물은 늘 빠져 있었어요.","선생님은 \"핑계 없는 무덤 없다더니, 준영이는 이유도 참 다양하구나\" 하며 웃으셨어요.","준영이는 부끄러움을 느끼고 그날부터 전날 밤 미리 가방을 챙기는 습관을 들이기로 했어요.","알람을 맞춰 놓고 체크리스트를 만들어 확인하니 실수가 눈에 띄게 줄었어요.","준영이는 \"핑계를 대는 대신 미리 준비하는 게 훨씬 마음이 편하구나\" 하고 느꼈어요."]'::jsonb, '[{"word":"그럴듯하다","meaning":"제법 그렇다고 여길 만하다"},{"word":"헷갈리다","meaning":"여러 가지가 뒤섞여 정신이 혼란스럽다"},{"word":"체크리스트","meaning":"확인해야 할 항목을 적어 둔 목록"}]'::jsonb, '[{"answer":true,"statement":"준영이는 준비물을 잊을 때마다 다른 이유를 댔다."},{"answer":false,"statement":"준영이는 끝까지 준비물을 챙기지 않았다."},{"answer":true,"statement":"준영이는 체크리스트를 만들어 확인하기 시작했다."}]'::jsonb, '{"choices":["준비물은 학교에서 빌리면 된다","핑계를 대는 것은 매우 좋은 습관이다","핑계를 대기보다 실수를 줄일 방법을 스스로 찾는 것이 낫다","이유가 그럴듯하면 실수해도 괜찮다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"그럴듯하다","choices":["너무 뻔히 거짓이다","제법 그렇다고 여길 만하다","아무 의미가 없다","전혀 말이 안 되다"],"answerIndex":1},{"type":"proverb","word":"핑계 없는 무덤 없다","choices":["무덤은 조용한 곳에 만든다","누구나 잘못을 저지르면 그럴듯한 핑계를 대기 마련이다","핑계를 대면 용서받을 수 있다","실수는 누구나 한 번쯤 한다"],"answerIndex":1},{"type":"synonym","word":"헷갈리다","choices":["분명하다","또렷하다","혼동되다","명확하다"],"answerIndex":2},{"type":"antonym","word":"그럴듯하다","choices":["납득되다","터무니없다","그럴싸하다","적절하다"],"answerIndex":1},{"type":"spelling","word":"등쌀","choices":["등살","등쌀","등살이","등쌀이"],"answerIndex":1}]'::jsonb, 89)
