insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('sky-falls-hole-appears', '🕳️', '하늘이 무너져도 솟아날 구멍', '["가족 여행을 앞두고 갑자기 태풍 소식이 전해지자 지호는 여행이 취소될까 봐 크게 실망했어요.","\"이번 여행 완전히 망했다\"며 울상을 짓는 지호에게 아빠가 다가왔어요.","아빠는 \"하늘이 무너져도 솟아날 구멍이 있다잖니, 다른 방법을 찾아보자\" 하며 다독여 주셨어요.","가족은 태풍이 지나가지 않는 다른 지역으로 여행지를 바꾸기로 했어요.","오히려 새로 정한 곳에서 예상치 못한 즐거운 추억을 많이 만들 수 있었어요.","지호는 \"힘든 일이 생겨도 포기하지 않으면 길이 있구나\" 하고 깨달았어요."]'::jsonb, '[{"word":"울상","meaning":"울려고 하는 얼굴 표정"},{"word":"다독이다","meaning":"따뜻한 말이나 행동으로 마음을 달래다"},{"word":"예상치 못하다","meaning":"미리 짐작하지 못하다"}]'::jsonb, '[{"answer":false,"statement":"태풍 소식에 가족 여행이 완전히 취소됐다."},{"answer":true,"statement":"가족은 여행지를 다른 곳으로 바꾸었다."},{"answer":true,"statement":"지호는 새 여행지에서 즐거운 추억을 만들었다."}]'::jsonb, '{"choices":["아무리 힘든 상황이라도 포기하지 않으면 해결할 방법을 찾을 수 있다","태풍이 오면 아무것도 할 수 없다","계획이 어긋나면 무조건 포기하는 것이 낫다","여행은 날씨가 좋을 때만 가야 한다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"울상","choices":["아무 감정 없는 표정","화가 잔뜩 난 표정","울려고 하는 얼굴 표정","활짝 웃는 밝은 표정"],"answerIndex":2},{"type":"proverb","word":"하늘이 무너져도 솟아날 구멍이 있다","choices":["아무리 힘든 상황에서도 살아나갈 방법은 있다","구멍은 위험하니 조심해야 한다","어려운 일은 피하는 것이 상책이다","하늘은 절대 무너지지 않는다"],"answerIndex":0},{"type":"synonym","word":"예상치못하다","choices":["짐작하다","뜻밖이다","당연하다","예측하다"],"answerIndex":1},{"type":"antonym","word":"울상","choices":["울먹임","눈물","함박웃음","찡그림"],"answerIndex":2},{"type":"spelling","word":"삐끗하다","choices":["삐긑하다","삐긋하다","삐끗하다","삐끝하다"],"answerIndex":2}]'::jsonb, 90)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('hoe-turns-into-shovel', '⛏️', '호미로 막을 것을 가래로', '["자전거 바퀴에서 이상한 소리가 났지만 서진이는 \"괜찮겠지\" 하며 그냥 계속 탔어요.","작은 문제를 대수롭지 않게 여기고 며칠을 더 그대로 탔더니 결국 바퀴가 완전히 망가지고 말았어요.","결국 서진이는 처음보다 훨씬 큰 비용을 들여 바퀴 전체를 새로 갈아야 했어요.","아빠는 \"호미로 막을 것을 가래로 막았구나, 작은 문제는 바로바로 손봐야 한단다\" 하고 말씀하셨어요.","서진이는 다음부터는 작은 이상이라도 발견하면 바로 점검받기로 다짐했어요.","이후 자전거에서 조금만 이상한 소리가 나도 서진이는 곧바로 살펴보는 습관을 들였어요."]'::jsonb, '[{"word":"대수롭지 않다","meaning":"중요하게 여길 만하지 않다"},{"word":"손보다","meaning":"고장 나거나 허름한 것을 손질하다"},{"word":"점검받다","meaning":"살펴서 검사받다"}]'::jsonb, '[{"answer":false,"statement":"서진이는 이상한 소리를 바로 점검받았다."},{"answer":true,"statement":"결국 자전거 바퀴가 완전히 망가졌다."},{"answer":false,"statement":"서진이는 그 뒤로도 자전거를 점검하지 않았다."}]'::jsonb, '{"choices":["문제가 커진 뒤에 고치는 것이 더 경제적이다","작은 문제는 커지기 전에 미리 손보는 것이 현명하다","작은 문제는 그냥 두어도 저절로 해결된다","자전거는 자주 타지 않는 것이 좋다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"대수롭지 않다","choices":["중요하게 여길 만하지 않다","매우 심각하고 중요하다","몹시 걱정스럽다","전혀 이해할 수 없다"],"answerIndex":0},{"type":"proverb","word":"호미로 막을 것을 가래로 막는다","choices":["작을 때 처리했으면 될 일을 방치해서 크게 힘들여 해결하게 된다","농기구는 종류가 다양하다","호미는 가래보다 작다","문제는 미루면 저절로 사라진다"],"answerIndex":0},{"type":"synonym","word":"대수롭지않다","choices":["사소하다","엄중하다","심각하다","중대하다"],"answerIndex":0},{"type":"antonym","word":"대수롭지않다","choices":["하찮다","사소하다","경미하다","심각하다"],"answerIndex":3},{"type":"spelling","word":"나았어요","choices":["나섰어요","낳았어요","났아요","나았어요"],"answerIndex":3}]'::jsonb, 91)
