insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('flowing-water-never-rots', '💧', '흐르는 물은 썩지 않는다', '["방학 동안 아무것도 하지 않고 지내던 도윤이는 개학이 다가오자 몸도 마음도 축 처져 있었어요.","반면 매일 아침 운동하고 책도 꾸준히 읽던 사촌 형은 활기가 넘쳐 보였어요.","도윤이는 형에게 비결을 물었고, 형은 \"가만히 있지 않고 계속 움직이니까 그런 것 같아\" 하고 답했어요.","도윤이는 그날부터 매일 조금씩이라도 운동하고 책을 읽기로 마음먹었어요.","몇 주가 지나자 도윤이도 몸이 가벼워지고 생각도 훨씬 또렷해지는 것을 느꼈어요.","도윤이는 \"흐르는 물이 썩지 않는다더니, 꾸준히 움직이는 게 정말 중요하구나\" 하고 느꼈어요."]'::jsonb, '[{"word":"축 처지다","meaning":"기운이 없이 아래로 늘어지다"},{"word":"활기","meaning":"활동력이 있거나 활발한 기운"},{"word":"비결","meaning":"남이 알지 못하는 뛰어난 방법"}]'::jsonb, '[{"answer":false,"statement":"도윤이는 방학 동안 매일 활발히 움직였다."},{"answer":true,"statement":"사촌 형은 매일 운동하고 책을 읽었다."},{"answer":true,"statement":"도윤이는 형을 따라 꾸준히 움직이기로 했다."}]'::jsonb, '{"choices":["운동을 많이 하면 오히려 몸이 힘들어진다","방학에는 아무것도 하지 않고 쉬는 것이 가장 좋다","독서와 운동은 개학 전에만 하면 된다","가만히 있지 않고 꾸준히 움직이며 노력하는 것이 활기를 준다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"활기","choices":["아무 기운이 없는 상태","조용하고 차분한 상태","활동력이 있거나 활발한 기운","몹시 지친 상태"],"answerIndex":2},{"type":"proverb","word":"흐르는 물은 썩지 않는다","choices":["흐르는 물소리는 마음을 편하게 한다","가만히 있는 것이 체력을 아끼는 방법이다","꾸준히 움직이고 노력하는 사람은 정체되지 않고 발전한다","물은 깨끗할수록 좋다"],"answerIndex":2},{"type":"synonym","word":"활기","choices":["나른함","피로","무기력","생기"],"answerIndex":3},{"type":"antonym","word":"활기","choices":["활력","무기력","기운","생기"],"answerIndex":1},{"type":"spelling","word":"오랫동안","choices":["오랫동안이","오랬동안이","오랬동안","오랫동안"],"answerIndex":3}]'::jsonb, 92)
