insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('market-day-coincidence', '🎪', '하필 장날이었던 소풍날', '["오랫동안 기다려 온 봄 소풍 날, 하필이면 학교 앞 도로에서 대규모 공사가 시작되었어요.","평소라면 십 분이면 갈 거리를 버스가 돌고 돌아 삼십 분이나 걸려서야 도착했어요.","반 친구들은 \"왜 하필 오늘 이런 일이 생기지\" 하며 아쉬워했어요.","늦게 도착했지만 선생님은 일정을 조금 조정해 예정했던 활동을 모두 무사히 마칠 수 있게 해 주셨어요.","친구들은 예상치 못한 일에도 당황하지 않고 유연하게 대처하는 법을 배웠어요.","그날 저녁 친구들은 \"그래도 결국 재미있었다\"며 웃으며 하루를 마무리했어요."]'::jsonb, '[{"word":"대규모","meaning":"아주 크고 넓은 규모"},{"word":"조정하다","meaning":"알맞게 맞추어 바로잡다"},{"word":"유연하다","meaning":"상황에 따라 부드럽게 잘 대처하다"}]'::jsonb, '[{"answer":true,"statement":"소풍 날 학교 앞에서 공사가 시작되었다."},{"answer":false,"statement":"버스는 평소보다 빠르게 도착했다."},{"answer":true,"statement":"선생님은 일정을 조정해 활동을 마쳤다."}]'::jsonb, '{"choices":["예상치 못한 일이 생겨도 유연하게 대처하면 좋은 결과로 이어질 수 있다","소풍은 날씨가 좋을 때만 가야 한다","예상치 못한 일이 생기면 그날 일정을 모두 취소해야 한다","공사는 학교 근처에서 절대 하면 안 된다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"유연하다","choices":["상황에 따라 부드럽게 잘 대처하다","고집스럽고 완고하다","아무 생각이 없다","몹시 서두르다"],"answerIndex":0},{"type":"proverb","word":"가는 날이 장날","choices":["어떤 일을 하려는데 뜻하지 않은 일이 공교롭게 겹쳐 일어난다","소풍은 봄에 가는 것이 좋다","장날에는 시장이 매우 붐빈다","버스는 정해진 시간에 온다"],"answerIndex":0},{"type":"synonym","word":"조정하다","choices":["조절하다","고정하다","무시하다","방치하다"],"answerIndex":0},{"type":"antonym","word":"유연하다","choices":["융통성있다","완고하다","부드럽다","탄력적이다"],"answerIndex":1},{"type":"spelling","word":"우연히","choices":["우연희","우연히","우연이","우연에"],"answerIndex":1}]'::jsonb, 93)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('bell-on-cat-neck', '🐱', '고양이 목에 방울 달기', '["학급 회의에서 친구들은 시끄러운 쉬는 시간 소음을 줄이자는 좋은 의견을 냈어요.","\"조용히 하자고 말할 사람이 필요해\"라는 데는 모두 동의했지만, 정작 나서겠다는 사람은 아무도 없었어요.","서로 눈치만 보며 \"네가 해\", \"아니 네가 해\" 하고 미루기만 했어요.","결국 반장이 용기를 내어 직접 나서서 친구들에게 부드럽게 부탁하기 시작했어요.","좋은 의견도 실제로 행동하는 사람이 있어야 이루어진다는 것을 모두가 깨달았어요.","친구들은 반장의 용기에 고마워하며 함께 조용한 교실 만들기에 동참했어요."]'::jsonb, '[{"word":"동의하다","meaning":"의견이 같다고 인정하다"},{"word":"눈치를 보다","meaning":"남의 마음이나 태도를 살피다"},{"word":"동참하다","meaning":"어떤 일에 함께 참여하다"}]'::jsonb, '[{"answer":true,"statement":"모두 조용한 교실을 만들자는 의견에 동의했다."},{"answer":false,"statement":"처음부터 나서서 부탁한 사람이 있었다."},{"answer":true,"statement":"결국 반장이 용기를 내어 나섰다."}]'::jsonb, '{"choices":["좋은 생각도 실제로 행동에 옮길 사람이 있어야 이루어진다","어려운 일은 누구도 나서지 않는 것이 좋다","회의에서는 의견을 내지 않는 것이 안전하다","좋은 의견은 말만 해도 저절로 이루어진다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"동참하다","choices":["어떤 일에 함께 참여하다","반대하며 방해하다","전혀 관심을 두지 않다","혼자서만 하다"],"answerIndex":0},{"type":"proverb","word":"고양이 목에 방울 달기","choices":["고양이는 조용한 동물이다","고양이는 방울 소리를 싫어한다","방울은 예쁘게 장식할 수 있다","좋은 생각이라도 실제로 실행하기는 어려운 일"],"answerIndex":3},{"type":"synonym","word":"동의하다","choices":["거부하다","반대하다","찬성하다","부인하다"],"answerIndex":2},{"type":"antonym","word":"동의하다","choices":["반대하다","동감하다","찬성하다","수긍하다"],"answerIndex":0},{"type":"spelling","word":"일찍이","choices":["일찍히","일찌기","일찍이","일찍기"],"answerIndex":2}]'::jsonb, 94)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('painting-of-rice-cake', '🖼️', '그림 속 떡', '["민경이는 인기 있는 신형 태블릿을 너무나 갖고 싶어서 매일 광고 사진만 들여다봤어요.","하지만 가격이 너무 비싸서 지금 당장은 살 수 없는 그림의 떡 같은 물건이었어요.","민경이는 무작정 부러워만 하는 대신 용돈을 조금씩 모으기로 계획을 세웠어요.","매달 받는 용돈의 일부를 저금통에 꾸준히 모으기 시작했어요.","반년 뒤, 민경이는 스스로 모은 돈으로 마침내 원하던 태블릿을 살 수 있었어요.","민경이는 \"부러워만 하지 않고 계획을 세우길 잘했다\"며 뿌듯해했어요."]'::jsonb, '[{"word":"신형","meaning":"새로 나온 형식이나 모델"},{"word":"무작정","meaning":"아무런 계획이나 준비 없이"},{"word":"꾸준히","meaning":"한결같이 계속하여"}]'::jsonb, '[{"answer":false,"statement":"민경이는 태블릿을 살 돈이 처음부터 충분했다."},{"answer":true,"statement":"민경이는 용돈을 모으기로 계획을 세웠다."},{"answer":true,"statement":"반년 뒤 민경이는 스스로 태블릿을 샀다."}]'::jsonb, '{"choices":["용돈은 모으지 않고 바로 쓰는 것이 좋다","갖고 싶은 것이 있어도 부러워만 하기보다 계획을 세워 노력해야 한다","갖고 싶은 물건은 부모님이 사 주셔야 한다","비싼 물건은 처음부터 포기하는 것이 낫다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"무작정","choices":["충분히 고민한 뒤에","아무런 계획이나 준비 없이","철저한 계획에 따라","차근차근 순서대로"],"answerIndex":1},{"type":"proverb","word":"그림의 떡","choices":["떡은 그림보다 맛있다","떡은 명절에 자주 먹는 음식이다","아무리 마음에 들어도 가지거나 이용할 수 없는 것","그림은 실물보다 아름답다"],"answerIndex":2},{"type":"synonym","word":"무작정","choices":["체계적으로","막연히","치밀하게","계획적으로"],"answerIndex":1},{"type":"antonym","word":"무작정","choices":["막연히","즉흥적으로","계획적으로","무턱대고"],"answerIndex":2},{"type":"spelling","word":"따뜻이","choices":["따듯히","따듯이","따뜻히","따뜻이"],"answerIndex":3}]'::jsonb, 95)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('illiterate-of-basics', '🔤', '기역 자도 몰랐던 첫걸음', '["해외에서 막 전학 온 리암은 한글을 전혀 읽지 못해 교실에서 잔뜩 주눅이 들어 있었어요.","친구들이 쉽게 읽는 안내문조차 리암에게는 낯선 그림처럼 느껴졌어요.","짝꿍 유진이는 매일 쉬는 시간마다 리암 옆에서 자음과 모음부터 차근차근 가르쳐 주었어요.","처음엔 정말 아무것도 몰랐던 리암이었지만 몇 달이 지나자 짧은 문장도 곧잘 읽게 되었어요.","리암은 유진이 덕분에 학교생활에 자신감이 생겼다며 고마워했어요.","유진이도 누군가를 가르치며 자신도 많은 것을 배웠다는 걸 느꼈어요."]'::jsonb, '[{"word":"주눅 들다","meaning":"기가 죽어 움츠러들다"},{"word":"낯설다","meaning":"전에 본 기억이 없어 익숙하지 않다"},{"word":"곧잘","meaning":"제법 잘"}]'::jsonb, '[{"answer":false,"statement":"리암은 전학 온 첫날부터 한글을 잘 읽었다."},{"answer":true,"statement":"유진이는 리암에게 한글을 가르쳐 주었다."},{"answer":true,"statement":"몇 달 뒤 리암은 짧은 문장을 읽을 수 있게 되었다."}]'::jsonb, '{"choices":["한글을 모르면 전학을 오면 안 된다","누구나 처음부터 잘 알아야 한다","가르쳐 주는 것은 시간 낭비다","아무것도 모르는 사람도 곁에서 도와주면 차근차근 배워 나갈 수 있다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"낯설다","choices":["매우 친숙하고 익숙하다","지루하고 심심하다","아주 반갑고 기쁘다","전에 본 기억이 없어 익숙하지 않다"],"answerIndex":3},{"type":"proverb","word":"낫 놓고 기역자도 모른다","choices":["아주 쉬운 글자도 모를 만큼 배우지 못한 상태를 이른다","글을 배우려면 오랜 시간이 필요하다","낫은 농사지을 때 쓰는 도구다","기역은 한글의 첫 자음이다"],"answerIndex":0},{"type":"synonym","word":"낯설다","choices":["익숙하다","생소하다","정겹다","친숙하다"],"answerIndex":1},{"type":"antonym","word":"낯설다","choices":["익숙하다","어색하다","생소하다","서먹하다"],"answerIndex":0},{"type":"spelling","word":"곰곰이","choices":["곰곰치","곰곰이이","곰곰히","곰곰이"],"answerIndex":3}]'::jsonb, 96)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('good-for-both-sides', '🤲', '나도 좋고 너도 좋은 나눔 장터', '["학교 나눔 장터에서 하윤이는 더 이상 쓰지 않는 로봇 장난감을 팔기로 했어요.","한 저학년 동생이 그 장난감을 몹시 갖고 싶어 했지만 가진 용돈이 부족해 보였어요.","하윤이는 잠시 고민하다가 동생이 가진 만큼만 받고 장난감을 건네주었어요.","동생은 뛸 듯이 기뻐하며 몇 번이고 고맙다고 인사했어요.","하윤이도 필요 없던 물건이 누군가에게 소중히 쓰이는 것을 보니 마음이 뿌듯했어요.","두 사람 모두 만족스러운 마음으로 나눔 장터를 떠날 수 있었어요."]'::jsonb, '[{"word":"건네다","meaning":"남에게 무엇을 옮겨 주다"},{"word":"뛸 듯이","meaning":"몹시 기뻐서 펄쩍펄쩍 뛰는 모양으로"},{"word":"만족스럽다","meaning":"마음에 흡족하여 부족함이 없다"}]'::jsonb, '[{"answer":true,"statement":"동생은 로봇 장난감을 갖고 싶어 했다."},{"answer":false,"statement":"하윤이는 동생에게 장난감을 그냥 빼앗아 왔다."},{"answer":true,"statement":"두 사람 모두 만족스러운 마음이 들었다."}]'::jsonb, '{"choices":["어린 동생에게는 물건을 팔지 않는 것이 좋다","물건은 가장 비싼 값에 팔아야 한다","나눔 장터에서는 무조건 이익을 남겨야 한다","서로를 배려하면 양쪽 모두에게 좋은 결과가 생길 수 있다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"만족스럽다","choices":["몹시 아쉽고 서운하다","불만이 가득하다","마음에 흡족하여 부족함이 없다","전혀 관심이 없다"],"answerIndex":2},{"type":"proverb","word":"누이 좋고 매부 좋고","choices":["가족끼리는 사이가 좋아야 한다","나눔은 손해 보는 일이다","매부는 누이의 남편을 뜻한다","어떤 일이 양쪽 모두에게 다 이롭다"],"answerIndex":3},{"type":"synonym","word":"만족스럽다","choices":["흡족하다","서운하다","아쉽다","불만족스럽다"],"answerIndex":0},{"type":"antonym","word":"만족스럽다","choices":["흡족하다","뿌듯하다","충분하다","불만족스럽다"],"answerIndex":3},{"type":"spelling","word":"틈틈이","choices":["틈틈이이","틈틔이","틈틈이","틈틈히"],"answerIndex":2}]'::jsonb, 97)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('extra-rice-cake-for-hated-child', '🍡', '미운 아이 떡 하나 더', '["체육 시간마다 얄밉게 규칙을 어기던 친구가 있어서 하람이는 그 친구가 못마땅했어요.","그런데 그 친구가 준비물을 깜빡 잊고 못 가져온 날, 하람이는 왠지 모르게 자기 것을 나눠 주었어요.","친구는 뜻밖의 배려에 놀라며 진심으로 고마워했어요.","그 뒤로 그 친구는 하람이에게는 유난히 다정하게 대하며 규칙도 더 잘 지키려 노력했어요.","하람이는 미운 사람일수록 더 따뜻하게 대하면 관계가 좋아질 수 있다는 것을 경험했어요.","둘은 시간이 지나며 서로를 이해하는 좋은 친구가 되어 갔어요."]'::jsonb, '[{"word":"얄밉다","meaning":"말이나 행동이 자꾸 밉게 느껴지다"},{"word":"못마땅하다","meaning":"마음에 들지 않아 좋지 않다"},{"word":"뜻밖","meaning":"생각하지 못한 일"}]'::jsonb, '[{"answer":false,"statement":"하람이는 그 친구를 처음부터 좋아했다."},{"answer":true,"statement":"하람이는 준비물을 못 챙겨 온 친구에게 나눠 주었다."},{"answer":true,"statement":"그 뒤로 친구는 하람이에게 더 다정하게 대했다."}]'::jsonb, '{"choices":["준비물은 절대 빌려주면 안 된다","얄미운 행동을 하는 친구와는 어울리지 말아야 한다","미운 사람은 계속 미워하는 것이 당연하다","미운 사람에게도 따뜻하게 대하면 관계가 좋아질 수 있다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"못마땅하다","choices":["마음에 들지 않아 좋지 않다","아주 반갑고 기쁘다","매우 흡족하고 좋다","전혀 관심이 없다"],"answerIndex":0},{"type":"proverb","word":"미운 아이 떡 하나 더 준다","choices":["떡은 명절에 먹는 음식이다","미운 사람과는 어울리지 않는 것이 좋다","미울수록 더 잘 대해 주어야 관계가 나아진다","아이는 떡을 좋아한다"],"answerIndex":2},{"type":"synonym","word":"얄밉다","choices":["다정하다","사랑스럽다","밉살스럽다","귀엽다"],"answerIndex":2},{"type":"antonym","word":"못마땅하다","choices":["흡족하다","못마땅하다","언짢다","불만스럽다"],"answerIndex":0},{"type":"spelling","word":"나름대로","choices":["나름되로","나름데로","나름대료","나름대로"],"answerIndex":3}]'::jsonb, 98)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('small-bird-follows-stork', '🐦', '황새 따라가다 가랑이 찢어진 뱁새', '["피아노를 갓 배우기 시작한 다인이는 오래 배운 언니가 치는 어려운 곡을 무리하게 따라 치려 했어요.","손가락이 잘 벌어지지 않는데도 억지로 무리한 코드를 짚다가 결국 손목이 아파 왔어요.","선생님은 \"지금 실력에 맞는 곡부터 차근차근 연습하는 게 좋겠다\"고 조언해 주셨어요.","다인이는 자신의 수준에 맞는 쉬운 곡부터 다시 연습하기 시작했어요.","무리하지 않고 차근차근 연습하니 실력이 오히려 더 안정적으로 늘었어요.","몇 달 뒤 다인이는 자연스럽게 언니가 치던 곡도 무리 없이 칠 수 있게 되었어요."]'::jsonb, '[{"word":"무리하다","meaning":"정도에 지나치게 힘을 쓰다"},{"word":"짚다","meaning":"손가락으로 무엇을 눌러 짚어 내다"},{"word":"안정적","meaning":"흔들림 없이 편안하고 확실한"}]'::jsonb, '[{"answer":false,"statement":"다인이는 처음부터 자기 수준에 맞는 곡만 연습했다."},{"answer":true,"statement":"무리한 연습으로 다인이는 손목이 아팠다."},{"answer":true,"statement":"몇 달 뒤 다인이는 어려운 곡도 칠 수 있게 되었다."}]'::jsonb, '{"choices":["연습은 힘들수록 효과가 좋다","피아노는 손이 큰 사람만 잘 칠 수 있다","어려운 곡을 무조건 먼저 연습해야 실력이 는다","자기 수준을 넘어서는 무리한 도전보다 차근차근 실력을 쌓는 것이 낫다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"무리하다","choices":["적당히 알맞게 하다","여유롭게 즐기다","전혀 힘을 쓰지 않다","정도에 지나치게 힘을 쓰다"],"answerIndex":3},{"type":"proverb","word":"뱁새가 황새 따라가다 가랑이 찢어진다","choices":["무엇이든 열심히 하면 잘된다","황새는 다리가 길어 잘 걷는다","새는 종류가 매우 다양하다","자기 능력에 맞지 않게 남을 따라 하다가 도리어 해를 입는다"],"answerIndex":3},{"type":"synonym","word":"무리하다","choices":["알맞다","과하다","여유롭다","적당하다"],"answerIndex":1},{"type":"antonym","word":"무리하다","choices":["무리하다","지나치다","과하다","적당히하다"],"answerIndex":3},{"type":"spelling","word":"그러고 나서","choices":["그러고 나서","그러고나서서","그리고 나서","그리고나서서"],"answerIndex":0}]'::jsonb, 99)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('blood-of-bird-leg', '🩸', '새 발의 피 같은 실수', '["수학 시험에서 계산 실수로 한 문제를 틀린 지완이는 며칠 동안 계속 속상해했어요.","짝꿍은 \"겨우 한 문제인데 왜 그렇게까지 속상해해?\" 하며 의아해했어요.","알고 보니 지완이는 그 실수가 전체 성적에 새 발의 피만큼 작은 영향이라는 것을 모르고 있었어요.","선생님도 \"이번 실수는 전체로 보면 아주 작은 부분이니 너무 걱정하지 말렴\" 하고 다독여 주셨어요.","지완이는 그제야 마음을 놓고 다음 시험 준비에 집중할 수 있었어요.","지완이는 작은 실수에 너무 오래 매달리지 않는 법을 배웠어요."]'::jsonb, '[{"word":"의아해하다","meaning":"의심스럽고 이상하게 여기다"},{"word":"마음을 놓다","meaning":"걱정을 덜고 편안해지다"},{"word":"매달리다","meaning":"어떤 일에 몹시 집착하다"}]'::jsonb, '[{"answer":true,"statement":"지완이는 시험에서 계산 실수를 했다."},{"answer":false,"statement":"그 실수는 전체 성적에 아주 큰 영향을 주었다."},{"answer":true,"statement":"지완이는 결국 마음을 놓고 다음 시험을 준비했다."}]'::jsonb, '{"choices":["작은 실수라도 절대 용서받을 수 없다","아주 작은 실수에 너무 오래 매달려 걱정할 필요는 없다","시험 점수는 인생에서 가장 중요하다","실수하면 다음 시험 준비를 포기해야 한다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"매달리다","choices":["깨끗이 잊고 넘어가다","전혀 신경 쓰지 않다","가볍게 웃어넘기다","어떤 일에 몹시 집착하다"],"answerIndex":3},{"type":"proverb","word":"새 발의 피","choices":["몹시 하찮고 작은 정도의 양이나 영향","작은 것도 소중히 여겨야 한다","새는 발이 작아서 걷기 힘들다","피는 몸에서 매우 중요한 역할을 한다"],"answerIndex":0},{"type":"synonym","word":"의아해하다","choices":["갸우뚱하다","이해하다","납득하다","확신하다"],"answerIndex":0},{"type":"antonym","word":"마음을놓다","choices":["걱정하다","진정되다","안심하다","편안해지다"],"answerIndex":0},{"type":"spelling","word":"덤터기","choices":["덤퇴기","덤퉁이","덤테기","덤터기"],"answerIndex":3}]'::jsonb, 100)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('ox-needs-hill', '🐂', '언덕이 있어야 비비는 소', '["그림 대회에서 상을 받고 싶었던 채원이는 혼자서 무작정 연습만 반복했어요.","실력은 좀처럼 늘지 않았고, 채원이는 답답한 마음에 속만 태웠어요.","미술 선생님은 \"혼자 애쓰기보다 기초부터 차근차근 배울 곳이 필요해 보이는구나\" 하고 조언해 주셨어요.","채원이는 미술 학원에 다니며 기본기부터 제대로 배우기 시작했어요.","기댈 곳이 생기자 채원이의 실력은 눈에 띄게 좋아졌어요.","채원이는 \"역시 기댈 언덕이 있어야 더 잘할 수 있구나\" 하고 느꼈어요."]'::jsonb, '[{"word":"무작정","meaning":"아무런 계획이나 준비 없이"},{"word":"속을 태우다","meaning":"몹시 걱정하여 마음을 졸이다"},{"word":"기본기","meaning":"가장 기초가 되는 기술이나 능력"}]'::jsonb, '[{"answer":false,"statement":"채원이는 처음부터 학원에서 기초를 배웠다."},{"answer":true,"statement":"선생님은 채원이에게 배울 곳을 찾아보라고 조언했다."},{"answer":true,"statement":"학원에 다닌 뒤 채원이의 실력이 좋아졌다."}]'::jsonb, '{"choices":["기초를 배우는 것은 시간 낭비다","모든 일은 반드시 혼자 힘으로만 해내야 한다","무언가를 이루려면 기댈 수 있는 바탕이나 도움이 필요할 때가 있다","학원에 다니면 그림 실력이 떨어진다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"기본기","choices":["가장 기초가 되는 기술이나 능력","전혀 필요 없는 지식","우연히 얻은 재능","가장 어려운 고급 기술"],"answerIndex":0},{"type":"proverb","word":"소도 언덕이 있어야 비빈다","choices":["혼자 하는 일이 가장 값지다","소는 풀을 먹고 산다","무슨 일이든 의지하거나 기댈 곳이 있어야 이룰 수 있다","언덕은 오르기 힘든 곳이다"],"answerIndex":2},{"type":"synonym","word":"무작정","choices":["차근차근","막연히","계획적으로","체계적으로"],"answerIndex":1},{"type":"antonym","word":"무작정","choices":["즉흥적으로","계획적으로","무턱대고","막연히"],"answerIndex":1},{"type":"spelling","word":"그다지","choices":["그닥히","그닥이","그다지","그다지이"],"answerIndex":2}]'::jsonb, 101)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('covering-sky-with-palm', '🖐️', '손바닥으로 하늘 가리기', '["급식실 유리창을 깬 승민이는 아무도 못 봤을 거라 생각하고 조용히 지나가려 했어요.","하지만 이미 여러 친구들이 그 장면을 목격했고, 소문은 금세 반 전체에 퍼졌어요.","승민이가 끝까지 아니라고 잡아떼자 오히려 친구들의 실망은 더 커졌어요.","결국 승민이는 손바닥으로 하늘을 가릴 수 없다는 것을 깨닫고 선생님께 사실대로 말씀드렸어요.","솔직하게 인정하고 사과하자 친구들도 오히려 승민이를 다시 믿어 주었어요.","승민이는 \"숨기려 할수록 더 커진다는 걸 이제 알겠다\"며 반성했어요."]'::jsonb, '[{"word":"목격하다","meaning":"눈으로 직접 보다"},{"word":"잡아떼다","meaning":"자기와 관계된 사실을 모른다고 딱 잡아서 부인하다"},{"word":"반성하다","meaning":"자신의 잘못을 돌아보다"}]'::jsonb, '[{"answer":false,"statement":"아무도 승민이가 유리창을 깬 것을 보지 못했다."},{"answer":true,"statement":"승민이는 처음에 사실을 숨기려 했다."},{"answer":true,"statement":"승민이는 결국 선생님께 사실대로 말씀드렸다."}]'::jsonb, '{"choices":["잘못은 끝까지 숨기는 것이 최선이다","유리창은 깨져도 신경 쓸 필요가 없다","이미 드러난 사실을 억지로 숨기려 하면 오히려 상황이 더 나빠진다","거짓말은 들키지 않으면 문제 되지 않는다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"잡아떼다","choices":["자기와 관계된 사실을 모른다고 딱 잡아서 부인하다","자세히 설명하다","솔직하게 인정하다","기꺼이 도와주다"],"answerIndex":0},{"type":"proverb","word":"손바닥으로 하늘 가리기","choices":["손바닥은 하늘보다 크다","하늘은 맑을수록 좋다","이미 다 드러난 잘못을 억지로 숨기려는 어리석은 행동","잘못은 누구나 저지를 수 있다"],"answerIndex":2},{"type":"synonym","word":"목격하다","choices":["놓치다","지켜보다","외면하다","못보다"],"answerIndex":1},{"type":"antonym","word":"잡아떼다","choices":["발뺌하다","인정하다","잡아떼다","부인하다"],"answerIndex":1},{"type":"spelling","word":"느지막이","choices":["느지막히","느지막이","느즈막이","느즈막히"],"answerIndex":1}]'::jsonb, 102)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('watermelon-surface-lick', '🍉', '겉만 핥은 수박', '["독서록 숙제를 위해 진서는 두꺼운 책을 딱 한 시간 만에 다 읽었다며 자랑했어요.","하지만 막상 내용을 물어보니 진서는 줄거리도 제대로 설명하지 못했어요.","너무 빨리 읽느라 대충 훑어보기만 했다는 것을 스스로도 깨달았어요.","선생님은 \"수박 겉핥기로 읽으면 진짜 재미와 의미를 놓치게 된단다\" 하고 알려 주셨어요.","진서는 그날 저녁 다시 처음부터 천천히, 꼼꼼하게 책을 읽었어요.","천천히 읽으니 처음엔 몰랐던 이야기의 깊은 의미까지 이해할 수 있었어요."]'::jsonb, '[{"word":"훑어보다","meaning":"전체를 대강 죽 살펴보다"},{"word":"꼼꼼하다","meaning":"빈틈이 없이 자세하고 차분하다"},{"word":"깊다","meaning":"생각이나 뜻이 넓고 크다"}]'::jsonb, '[{"answer":false,"statement":"진서는 책을 꼼꼼하게 읽고 내용을 잘 설명했다."},{"answer":true,"statement":"진서는 책을 다시 천천히 읽었다."},{"answer":true,"statement":"천천히 읽자 이야기의 깊은 의미를 이해할 수 있었다."}]'::jsonb, '{"choices":["독서록은 대충 써도 상관없다","겉만 대충 보기보다 꼼꼼히 살펴야 진짜 의미를 알 수 있다","줄거리를 모르는 것은 큰 문제가 아니다","책은 빨리 읽을수록 좋다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"꼼꼼하다","choices":["아무 관심이 없다","빈틈이 없이 자세하고 차분하다","대충대충 성의 없다","몹시 급하고 서두르다"],"answerIndex":1},{"type":"proverb","word":"수박 겉핥기","choices":["음식은 천천히 먹어야 소화가 잘된다","내용은 제대로 모르고 겉만 대충 훑어보는 것","수박은 여름에 인기 있는 과일이다","겉과 속이 같은 사람이 되어야 한다"],"answerIndex":1},{"type":"synonym","word":"꼼꼼하다","choices":["대충하다","세심하다","엉성하다","허술하다"],"answerIndex":1},{"type":"antonym","word":"꼼꼼하다","choices":["허술하다","세심하다","면밀하다","치밀하다"],"answerIndex":0},{"type":"spelling","word":"오도카니","choices":["오도카니","오두카니","오두커니","오도커니"],"answerIndex":0}]'::jsonb, 103)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('no-smoke-without-fire', '💨', '아니 땐 굴뚝에 연기 날까', '["반에 이상한 소문이 돌자 소문의 주인공인 예린이는 \"말도 안 되는 소리\"라며 무시하려 했어요.","하지만 소문의 시작을 따라가 보니 예린이가 무심코 했던 말이 조금씩 부풀려져 퍼진 것이었어요.","예린이는 자신의 말 한마디가 이렇게 큰 소문의 씨앗이 될 줄은 몰랐다며 당황했어요.","예린이는 오해를 풀기 위해 친구들에게 정확한 사실을 차분히 설명했어요.","친구들도 소문을 그대로 믿기보다 직접 확인하는 것이 중요하다는 것을 깨달았어요.","예린이는 그 뒤로 말을 할 때 좀 더 신중하게 생각하고 말하게 되었어요."]'::jsonb, '[{"word":"무심코","meaning":"아무 생각 없이 문득"},{"word":"부풀려지다","meaning":"실제보다 크게 과장되다"},{"word":"신중하다","meaning":"매우 조심스럽다"}]'::jsonb, '[{"answer":false,"statement":"소문은 아무 이유 없이 완전히 저절로 생겨났다."},{"answer":true,"statement":"예린이가 무심코 한 말이 소문의 시작이었다."},{"answer":true,"statement":"예린이는 오해를 풀기 위해 노력했다."}]'::jsonb, '{"choices":["모든 소문은 완전히 근거 없는 거짓말이다","말은 조심하지 않고 자유롭게 해도 된다","소문이 나면 아무것도 할 수 없다","소문에는 대개 그럴 만한 원인이나 시작점이 있기 마련이다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"신중하다","choices":["아무 생각이 없다","매우 조심스럽다","매우 경솔하고 급하다","몹시 시끄럽다"],"answerIndex":1},{"type":"proverb","word":"아니 땐 굴뚝에 연기 날까","choices":["불은 조심해서 다뤄야 한다","원인 없이는 결과나 소문이 생기지 않는다","굴뚝은 연기를 내보내는 통로다","소문은 절대 사실이 아니다"],"answerIndex":1},{"type":"synonym","word":"무심코","choices":["계획적으로","일부러","문득","의도적으로"],"answerIndex":2},{"type":"antonym","word":"신중하다","choices":["세심하다","경솔하다","신중하다","조심스럽다"],"answerIndex":1},{"type":"spelling","word":"도맡다","choices":["도맡다","도맏다","도맏따","도맡따"],"answerIndex":0}]'::jsonb, 104)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('quiet-cat-first-on-stove', '🐈', '얌전한 고양이 부뚜막에', '["평소 말없이 조용하기만 했던 도현이가 갑자기 학급 장기자랑에서 놀라운 마술 실력을 선보였어요.","친구들은 \"쟤가 저런 재주가 있었어?\" 하며 깜짝 놀랐어요.","알고 보니 도현이는 몇 년 동안 혼자 조용히 마술을 연습해 온 것이었어요.","조용한 성격 때문에 아무도 도현이의 숨은 재능을 눈치채지 못했던 것이었어요.","그날 이후 도현이는 학급 행사마다 마술 공연을 선보이며 큰 인기를 얻었어요.","친구들은 겉으로 조용하다고 해서 재능이 없는 것은 아니라는 걸 배웠어요."]'::jsonb, '[{"word":"선보이다","meaning":"처음으로 보여 주다"},{"word":"재주","meaning":"무엇을 잘하는 타고난 능력"},{"word":"숨은","meaning":"겉으로 드러나지 않은"}]'::jsonb, '[{"answer":false,"statement":"도현이는 평소에도 매우 활발하고 시끄러웠다."},{"answer":true,"statement":"도현이는 몇 년간 혼자 마술을 연습해 왔다."},{"answer":false,"statement":"친구들은 도현이의 재능을 미리 알고 있었다."}]'::jsonb, '{"choices":["장기자랑은 인기 있는 사람만 나가야 한다","재능은 시끄럽고 활발한 사람만 가진다","조용한 사람은 아무 재능이 없다","조용해 보이는 사람도 뜻밖의 숨은 재능을 가지고 있을 수 있다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"재주","choices":["무엇을 잘하는 타고난 능력","전혀 할 줄 모르는 일","아주 지루한 일과","누구나 쉽게 하는 일"],"answerIndex":0},{"type":"proverb","word":"얌전한 고양이가 부뚜막에 먼저 올라간다","choices":["겉으로 얌전해 보이는 사람이 뜻밖의 행동으로 놀라게 한다","얌전한 사람은 절대 실수하지 않는다","부뚜막은 불을 때는 곳이다","고양이는 따뜻한 곳을 좋아한다"],"answerIndex":0},{"type":"synonym","word":"재주","choices":["미숙함","서투름","무능함","재능"],"answerIndex":3},{"type":"antonym","word":"선보이다","choices":["공개하다","드러내다","보여주다","숨기다"],"answerIndex":3},{"type":"spelling","word":"칠칠맞다","choices":["칠칠맞다","칠칠맏다","칠칠맞따","칠칠맏따"],"answerIndex":0}]'::jsonb, 105)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('dont-eye-impossible-tree', '🌲', '오르지 못할 나무는 쳐다도 마라', '["전교 회장 선거를 앞두고 은우는 인기 많은 6학년 선배에게 도전할지 고민했어요.","친구들은 \"그 형은 워낙 인기가 많아서 이길 가능성이 거의 없어\"라며 말렸어요.","은우는 처음엔 아예 포기하려 했지만, 곰곰이 생각한 끝에 다른 방식으로 접근하기로 했어요.","대신 자신이 잘할 수 있는 학급 부회장 자리에 도전하기로 목표를 바꾸었어요.","은우는 자신 있는 분야에 집중해 성실히 선거운동을 했고, 결국 부회장으로 뽑혔어요.","은우는 \"무리한 목표보다 내게 맞는 목표를 찾는 게 더 현명했다\"고 생각했어요."]'::jsonb, '[{"word":"말리다","meaning":"하지 못하게 막다"},{"word":"접근하다","meaning":"어떤 문제나 대상에 다가가다"},{"word":"성실히","meaning":"정성스럽고 참되게"}]'::jsonb, '[{"answer":false,"statement":"은우는 전교 회장 선거에 그대로 도전했다."},{"answer":true,"statement":"은우는 목표를 부회장으로 바꾸었다."},{"answer":true,"statement":"은우는 결국 부회장으로 뽑혔다."}]'::jsonb, '{"choices":["한번 정한 목표는 절대 바꾸면 안 된다","이루기 힘든 목표에 매달리기보다 자신에게 맞는 현실적인 목표를 찾는 것이 지혜롭다","이길 수 없는 상대에게는 처음부터 도전하지 말아야 한다","선거는 인기 있는 사람만 나가야 한다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"성실히","choices":["몹시 불성실하게","정성스럽고 참되게","대충대충 게으르게","아무렇게나"],"answerIndex":1},{"type":"proverb","word":"오르지 못할 나무는 쳐다보지도 마라","choices":["나무는 높이 자랄수록 좋다","이룰 수 없는 일에는 처음부터 욕심을 내지 않는 것이 낫다","나무에 오르는 것은 위험한 놀이다","무엇이든 도전해 봐야 결과를 안다"],"answerIndex":1},{"type":"synonym","word":"접근하다","choices":["회피하다","다가가다","피하다","멀어지다"],"answerIndex":1},{"type":"antonym","word":"성실히","choices":["정성껏","불성실하게","착실히","꾸준히"],"answerIndex":1},{"type":"spelling","word":"얄따랗다","choices":["얄따랗다","얇다랖다","얄따랖다","얇다랗다"],"answerIndex":0}]'::jsonb, 106)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('smiling-face-no-spit', '😊', '웃는 낯에 침 못 뱉는다', '["체육 시간에 실수로 공을 세게 던져 친구의 발을 맞힌 하진이는 잔뜩 긴장했어요.","화가 날 만한 상황이었지만, 맞은 친구는 오히려 밝게 웃으며 \"괜찮아, 일부러 그런 거 아니잖아\" 하고 말했어요.","화를 낼 준비를 하고 있던 하진이는 그 웃는 얼굴에 오히려 마음이 누그러졌어요.","하진이는 진심을 담아 사과했고, 둘은 금세 다시 웃으며 놀 수 있었어요.","하진이는 \"웃으면서 대해 주니 오히려 더 미안하고 고마운 마음이 들었다\"고 느꼈어요.","그날 이후 하진이도 누군가 실수했을 때 먼저 웃으며 넘기려 노력했어요."]'::jsonb, '[{"word":"맞히다","meaning":"쏘거나 던진 것이 목표에 닿다"},{"word":"누그러지다","meaning":"심하던 것이 부드러워지다"},{"word":"금세","meaning":"지금 바로"}]'::jsonb, '[{"answer":false,"statement":"맞은 친구는 하진이에게 화를 크게 냈다."},{"answer":true,"statement":"맞은 친구는 웃으며 괜찮다고 말했다."},{"answer":true,"statement":"하진이는 진심으로 사과했다."}]'::jsonb, '{"choices":["사과는 필요 없는 행동이다","너그럽고 부드러운 태도는 상대의 화를 누그러뜨리는 힘이 있다","웃는 얼굴은 진심이 아닐 때가 많다","실수를 한 사람에게는 반드시 화를 내야 한다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"누그러지다","choices":["전혀 변화가 없다","더욱 격해지고 심해지다","갑자기 사라지다","심하던 것이 부드러워지다"],"answerIndex":3},{"type":"proverb","word":"웃는 낯에 침 못 뱉는다","choices":["웃음은 전염되기 쉽다","화가 나면 무조건 참아야 한다","웃으며 부드럽게 대하는 사람에게는 화를 내기 어렵다","침은 뱉으면 안 되는 행동이다"],"answerIndex":2},{"type":"synonym","word":"누그러지다","choices":["가라앉다","거세지다","격해지다","심해지다"],"answerIndex":0},{"type":"antonym","word":"누그러지다","choices":["격해지다","가라앉다","완화되다","진정되다"],"answerIndex":0},{"type":"spelling","word":"짤따랗다","choices":["짤따랗다","짤따랖다","짧다랖다","짧다랗다"],"answerIndex":0}]'::jsonb, 107)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('thousand-mile-first-step', '👣', '천 리 길도 한 걸음부터', '["방학 동안 태권도 검은 띠를 따고 싶었던 유겸이는 갈 길이 너무 멀어 보여 시작조차 망설였어요.","\"언제 다 배우지\" 하며 지레 겁을 먹고 있는 유겸이에게 사범님이 다가오셨어요.","사범님은 \"천 리 길도 한 걸음부터야, 오늘 배울 동작 하나에만 집중해 보렴\" 하고 말씀하셨어요.","유겸이는 그날부터 하루하루 배운 동작 하나씩에만 집중하며 연습했어요.","까마득해 보이던 목표는 매일의 작은 걸음이 쌓이며 어느새 눈앞에 다가와 있었어요.","방학이 끝날 무렵, 유겸이는 마침내 검은 띠 심사에 도전할 수 있게 되었어요."]'::jsonb, '[{"word":"망설이다","meaning":"이리저리 생각만 하고 결정을 하지 못하다"},{"word":"지레 겁먹다","meaning":"어떤 일이 일어나기도 전에 미리 두려워하다"},{"word":"까마득하다","meaning":"아득히 멀어서 상상하기 어렵다"}]'::jsonb, '[{"answer":false,"statement":"유겸이는 처음부터 자신 있게 시작했다."},{"answer":true,"statement":"사범님은 오늘 배울 동작에만 집중하라고 하셨다."},{"answer":true,"statement":"방학이 끝날 무렵 유겸이는 검은 띠 심사에 도전하게 되었다."}]'::jsonb, '{"choices":["목표는 한 번에 다 이루어야 의미가 있다","큰 목표는 처음부터 포기하는 것이 낫다","검은 띠는 짧은 시간에 딸 수 있는 것이다","아무리 멀어 보이는 목표도 오늘의 작은 한 걸음부터 시작해야 한다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"까마득하다","choices":["아득히 멀어서 상상하기 어렵다","아주 가깝고 뚜렷하다","전혀 어렵지 않다","금방 이룰 수 있다"],"answerIndex":0},{"type":"proverb","word":"천리 길도 한 걸음부터","choices":["천 리는 매우 먼 거리를 뜻한다","아무리 큰 일도 작은 시작에서부터 이루어진다","걸음은 빠를수록 좋다","길은 곧게 뻗어 있어야 걷기 좋다"],"answerIndex":1},{"type":"synonym","word":"망설이다","choices":["결단하다","단행하다","주저하다","결심하다"],"answerIndex":2},{"type":"antonym","word":"까마득하다","choices":["요원하다","멀다","가깝다","아득하다"],"answerIndex":2},{"type":"spelling","word":"다다르다","choices":["다달르다","다달으다","다다르다","다다러다"],"answerIndex":2}]'::jsonb, 108)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('young-puppy-fears-nothing', '🐶', '호랑이 무서운 줄 모르는 강아지', '["태권도를 배운 지 겨우 한 달 된 로운이는 자신만만하게 검은 띠 선배에게 겨루기를 신청했어요.","주변 친구들은 \"아직 실력 차이가 큰데 괜찮겠어?\" 하며 걱정스러워했어요.","로운이는 자신 있게 나섰지만 몇 번의 대련 끝에 실력 차이를 확실히 느끼게 되었어요.","하지만 로운이는 좌절하지 않고 오히려 좋은 자극을 받았다며 더 열심히 연습하기 시작했어요.","몇 달 뒤 로운이는 몰라보게 실력이 늘어 후배들에게 존경받는 선배가 되었어요.","로운이는 \"그때의 겁 없는 도전이 지금의 나를 만들었다\"며 웃었어요."]'::jsonb, '[{"word":"겨루기","meaning":"서로 실력을 견주어 다투는 것"},{"word":"대련","meaning":"무예를 실제로 익히기 위해 서로 겨루는 일"},{"word":"자극","meaning":"어떤 느낌이나 반응을 일으키게 하는 일"}]'::jsonb, '[{"answer":false,"statement":"로운이는 실력 차이를 두려워해 도전을 포기했다."},{"answer":true,"statement":"로운이는 대련에서 실력 차이를 느꼈다."},{"answer":true,"statement":"몇 달 뒤 로운이는 실력이 몰라보게 늘었다."}]'::jsonb, '{"choices":["겁이 없는 것은 항상 무모하고 나쁜 것이다","실력이 부족하면 절대 도전하면 안 된다","선배에게 도전하는 것은 예의가 아니다","두려움 없는 용감한 도전이 오히려 성장의 계기가 될 수 있다"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"자극","choices":["조용히 쉬는 시간","아무 반응이 없는 상태","어떤 느낌이나 반응을 일으키게 하는 일","완전히 지친 상태"],"answerIndex":2},{"type":"proverb","word":"하룻강아지 범 무서운 줄 모른다","choices":["경험이 적어 두려움 없이 겁 없이 덤빈다","강아지는 호랑이를 무서워한다","태권도는 오래 배워야 잘한다","나이가 어릴수록 겁이 많다"],"answerIndex":0},{"type":"synonym","word":"겨루기","choices":["화해","대결","협력","양보"],"answerIndex":1},{"type":"antonym","word":"자신만만하다","choices":["자신있다","당당하다","떳떳하다","주눅들다"],"answerIndex":3},{"type":"spelling","word":"웬걸","choices":["웬거","웬걸","왠거","왠걸"],"answerIndex":1}]'::jsonb, 109)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('heungbu-swallow-gourd', '🐦', '흥부와 놀부', '["옛날 어느 마을에 마음씨 착한 흥부와 욕심 많은 형 놀부가 살았어요.","놀부는 재산을 모두 차지하고 동생 흥부를 집에서 쫓아냈어요.","흥부는 가난했지만 다리 다친 제비를 정성껏 치료해 주었어요.","다음 해 봄, 제비는 고마움의 표시로 흥부에게 박씨 하나를 물어다 주었어요.","흥부가 박씨를 심었더니 커다란 박이 주렁주렁 열렸어요.","박을 갈랐더니 안에서 금은보화가 쏟아져 나와 흥부는 부자가 되었어요.","이 소식을 들은 놀부는 일부러 제비 다리를 다치게 한 뒤 억지로 고쳐 주었어요.","놀부도 박씨를 심어 박을 갈랐지만, 그 안에서는 도깨비들이 나와 놀부를 혼내주었어요.","놀부는 크게 뉘우치고 흥부와 화해하며 사이좋게 살았어요."]'::jsonb, '[{"word":"정성껏","meaning":"온 마음을 다해서"},{"word":"뉘우치다","meaning":"잘못을 깨닫고 반성하다"},{"word":"화해하다","meaning":"다툼을 멈추고 다시 사이좋게 지내다"}]'::jsonb, '[{"answer":true,"statement":"흥부는 다리 다친 제비를 치료해 주었어요."},{"answer":false,"statement":"놀부는 처음부터 제비를 정성껏 도와주었어요."},{"answer":true,"statement":"흥부의 박에서는 금은보화가 나왔어요."},{"answer":false,"statement":"놀부의 박에서도 금은보화가 쏟아졌어요."}]'::jsonb, '{"choices":["착한 마음으로 베풀면 복을 받고, 욕심을 부리면 화를 입어요","제비는 봄에만 날아와요","형제는 재산을 똑같이 나눠야 해요","박씨는 아무나 심을 수 있어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"정성껏","choices":["화가 나서","귀찮아하며","온 마음을 다해서","무섭게"],"answerIndex":2},{"type":"proverb","word":"콩 심은 데 콩 나고 팥 심은 데 팥 난다","choices":["콩과 팥은 같은 곡식이라는 뜻이에요","모든 일에는 원인에 맞는 결과가 따른다는 뜻이에요","농사는 봄에 지어야 한다는 뜻이에요","밥을 골고루 먹어야 한다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"화해하다","choices":["다투다","싸우다","등지다","화합하다"],"answerIndex":3},{"type":"antonym","word":"화해하다","choices":["화합하다","사이좋다","다투다","정답다"],"answerIndex":2},{"type":"spelling","word":"며칠","choices":["며칠","몇일","며츨","멷칠"],"answerIndex":0}]'::jsonb, 110)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('kongjwi-lost-golden-shoe', '👠', '콩쥐팥쥐', '["옛날 콩쥐라는 착한 소녀가 새어머니와 새언니 팥쥐와 함께 살았어요.","새어머니는 콩쥐에게만 힘든 일을 시키고 팥쥐만 예뻐했어요.","어느 날 마을에 큰 잔치가 열렸는데, 새어머니는 콩쥐에게 물 항아리를 채우고 밭을 다 매야 갈 수 있다고 했어요.","두꺼비가 항아리의 구멍을 막아 주고, 참새들이 날아와 밭일을 도와주었어요.","덕분에 콩쥐는 잔치에 갈 수 있었지만, 서둘러 돌아오다가 꽃신 한 짝을 물에 빠뜨리고 말았어요.","그 꽃신을 주운 원님은 신발의 주인을 찾아 마을을 돌아다녔어요.","신발은 콩쥐의 발에 꼭 맞았고, 원님은 콩쥐의 착한 마음씨에 반해 청혼했어요.","그동안 미안했다고 사과하는 새어머니와 팥쥐에게 콩쥐는 웃으며 용서한다고 말했어요.","콩쥐는 착한 마음을 잃지 않고 모두와 사이좋게 지냈어요."]'::jsonb, '[{"word":"항아리","meaning":"물이나 곡식을 담는 둥근 그릇"},{"word":"청혼하다","meaning":"결혼하자고 부탁하다"},{"word":"용서하다","meaning":"잘못을 꾸짖지 않고 너그럽게 봐주다"}]'::jsonb, '[{"answer":true,"statement":"새어머니는 콩쥐에게 힘든 일을 많이 시켰어요."},{"answer":true,"statement":"콩쥐는 서두르다가 꽃신 한 짝을 잃어버렸어요."},{"answer":false,"statement":"원님은 팥쥐와 결혼했어요."}]'::jsonb, '{"choices":["신발은 항상 꽉 끼게 신어야 해요","착한 마음씨는 결국 좋은 결과로 돌아와요","잔치에는 늦게 가는 것이 좋아요","동물은 사람을 도와줄 수 없어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"항아리","choices":["날아다니는 새","딱딱한 나무 의자","빛나는 보석","물이나 곡식을 담는 둥근 그릇"],"answerIndex":3},{"type":"proverb","word":"고생 끝에 낙이 온다","choices":["고생은 되도록 피해야 한다는 뜻이에요","낙엽은 가을에 진다는 뜻이에요","힘든 일을 이겨내면 좋은 일이 생긴다는 뜻이에요","잔치는 자주 열어야 한다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"용서하다","choices":["꾸짖다","너그럽게 봐주다","다그치다","의심하다"],"answerIndex":1},{"type":"antonym","word":"용서하다","choices":["꾸짖다","이해하다","봐주다","감싸다"],"answerIndex":0},{"type":"spelling","word":"왠지","choices":["웬지","왠짓","웬짓","왠지"],"answerIndex":3}]'::jsonb, 111)
