insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('sun-moon-siblings-rope', '🪢', '해와 달이 된 오누이', '["옛날 어느 산골에 어머니와 오누이가 살았어요.","어머니는 떡을 팔러 갔다가 늦은 밤 산길에서 커다란 호랑이를 만났어요.","호랑이는 어머니 옷을 빼앗아 입고 어머니인 척하며 오누이의 집으로 찾아갔어요.","오누이는 문틈으로 본 손이 어머니 손과 다르게 거칠고 털이 많은 것을 눈치챘어요.","오누이는 얼른 마당의 커다란 나무 위로 올라가 숨었어요.","호랑이가 쫓아오자 오누이는 하늘을 향해 튼튼한 동아줄을 내려 달라고 빌었어요.","하늘에서 금빛 동아줄이 내려와 오누이는 하늘로 올라가 무사히 살았어요.","호랑이도 동아줄을 달라고 빌었지만, 썩은 동아줄이 내려와 뚝 끊어지고 말았어요.","오누이는 하늘로 올라가 각각 해와 달이 되었답니다."]'::jsonb, '[{"word":"눈치채다","meaning":"남이 모르게 하는 것을 알아차리다"},{"word":"동아줄","meaning":"굵고 튼튼하게 꼰 줄"},{"word":"무사히","meaning":"아무 탈 없이 편안하게"}]'::jsonb, '[{"answer":true,"statement":"오누이는 손을 보고 호랑이가 어머니가 아님을 알아챘어요."},{"answer":true,"statement":"오누이에게는 튼튼한 금빛 동아줄이 내려왔어요."},{"answer":false,"statement":"호랑이에게도 튼튼한 동아줄이 내려왔어요."}]'::jsonb, '{"choices":["밤에는 절대 떡을 팔면 안 돼요","나무는 아무나 올라갈 수 없어요","위험한 순간에도 침착하게 살피면 지혜롭게 벗어날 수 있어요","동아줄은 항상 썩어 있어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"눈치채다","choices":["큰 소리로 노래하다","남이 모르게 하는 것을 알아차리다","깊이 잠들다","멀리 도망가다"],"answerIndex":1},{"type":"vocab","word":"동아줄","choices":["얇고 가벼운 종이","작고 둥근 돌멩이","부드러운 천 조각","굵고 튼튼하게 꼰 줄"],"answerIndex":3},{"type":"synonym","word":"무사히","choices":["안전하게","위험하게","시끄럽게","초조하게"],"answerIndex":0},{"type":"antonym","word":"무사히","choices":["안전하게","위태롭게","편안하게","조용히"],"answerIndex":1},{"type":"spelling","word":"웬만하면","choices":["왠만하면","웬만함","웬만하면","왠만함"],"answerIndex":2}]'::jsonb, 112)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('fairy-and-woodcutter', '🦌', '선녀와 나무꾼', '["산속에 사는 착한 나무꾼이 어느 날 사냥꾼에게 쫓기는 사슴을 만났어요.","나무꾼은 사슴을 나뭇더미 속에 숨겨 주어 목숨을 구해 주었어요.","사슴은 고마움의 표시로 나무꾼에게 산속 연못의 비밀을 알려주었어요.","보름달이 뜨는 밤이면 하늘에서 선녀들이 내려와 연못에서 목욕을 한다고 했어요.","나무꾼은 연못가에서 선녀 한 명과 마주쳤고, 둘은 이야기를 나누며 친구가 되었어요.","선녀는 하늘 나라 이야기를, 나무꾼은 땅 위의 이야기를 들려주며 즐거운 시간을 보냈어요.","시간이 흘러 선녀는 하늘로 돌아가야 했지만, 사슴은 나무꾼이 선녀를 다시 만날 수 있도록 두레박을 타고 하늘에 오르는 방법을 알려주었어요.","나무꾼과 선녀는 그렇게 가끔씩 서로를 찾아가며 오랫동안 우정을 이어갔어요."]'::jsonb, '[{"word":"목숨을 구하다","meaning":"죽을 위기에서 살려 주다"},{"word":"마주치다","meaning":"우연히 만나다"},{"word":"우정","meaning":"친구 사이의 정"}]'::jsonb, '[{"answer":true,"statement":"나무꾼은 위험에 빠진 사슴을 구해 주었어요."},{"answer":true,"statement":"사슴은 나무꾼에게 연못의 비밀을 알려주었어요."},{"answer":false,"statement":"선녀는 나무꾼과 다시는 만나지 않았어요."}]'::jsonb, '{"choices":["사슴은 사람과 이야기할 수 없어요","보름달이 뜨면 항상 위험한 일이 생겨요","하늘 나라와 땅은 절대 만날 수 없어요","누군가에게 베푼 친절은 돌고 돌아 좋은 인연으로 이어져요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"마주치다","choices":["일부러 피하다","크게 다투다","우연히 만나다","멀리 떠나다"],"answerIndex":2},{"type":"vocab","word":"우정","choices":["친구 사이의 정","가족 간의 다툼","낯선 사람에 대한 두려움","혼자 있는 시간"],"answerIndex":0},{"type":"synonym","word":"목숨을 구하다","choices":["잠을 깨우다","생명을 살리다","길을 알려주다","밥을 나누다"],"answerIndex":1},{"type":"antonym","word":"마주치다","choices":["피하다","만나다","스치다","부딪히다"],"answerIndex":0},{"type":"spelling","word":"어떡해","choices":["어떻해","어떠케","어떠캐","어떡해"],"answerIndex":3}]'::jsonb, 113)
