insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('snail-bride-secret', '🐌', '우렁각시', '["혼자 사는 가난한 농부가 논에서 커다란 우렁이 하나를 주워 항아리에 넣어 두었어요.","그날부터 농부가 밭에 나갔다 오면 부엌에 맛있는 밥상이 차려져 있었어요.","궁금해진 농부는 어느 날 몰래 숨어서 지켜보았어요.","우렁이 속에서 예쁜 색시가 나와 정성껏 밥을 짓고 있었어요.","농부는 깜짝 놀랐지만, 색시에게 함께 살자고 진심으로 부탁했어요.","색시도 농부의 부지런하고 착한 마음이 좋아서 함께 살기로 했어요.","둘은 서로 도우며 열심히 일해 마을에서 가장 정답게 사는 부부가 되었어요.","사람들은 두 사람의 성실함과 다정함을 보고 모두 부러워했답니다."]'::jsonb, '[{"word":"정성껏","meaning":"온 마음을 다해서"},{"word":"부지런하다","meaning":"게으르지 않고 열심히 일하다"},{"word":"성실하다","meaning":"정성스럽고 참되다"}]'::jsonb, '[{"answer":true,"statement":"농부는 논에서 커다란 우렁이를 주웠어요."},{"answer":true,"statement":"우렁이 속에서 예쁜 색시가 나왔어요."},{"answer":false,"statement":"농부는 색시를 보고도 모르는 척했어요."}]'::jsonb, '{"choices":["성실하고 진심 어린 마음은 좋은 인연을 만들어요","우렁이는 논에서 살 수 없어요","부엌일은 혼자 다 해야 해요","몰래 숨어서 보는 것은 항상 좋은 일이에요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"부지런하다","choices":["크게 화를 내다","게으르지 않고 열심히 일하다","아주 느리게 걷다","조용히 잠만 자다"],"answerIndex":1},{"type":"proverb","word":"지성이면 감천","choices":["밥은 골고루 먹어야 한다는 뜻이에요","하늘은 항상 맑다는 뜻이에요","농사는 봄에만 지어야 한다는 뜻이에요","정성을 다하면 하늘도 감동해 좋은 결과를 준다는 뜻이에요"],"answerIndex":3},{"type":"synonym","word":"성실하다","choices":["게으르고 불성실하다","화가 많고 급하다","정성스럽고 참되다","겁이 많고 소심하다"],"answerIndex":2},{"type":"antonym","word":"부지런하다","choices":["성실하다","정성스럽다","참되다","게으르다"],"answerIndex":3},{"type":"spelling","word":"설거지","choices":["설겆이","설거지","설걷이","설것이"],"answerIndex":1}]'::jsonb, 114)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('golden-axe-silver-axe', '🪓', '금도끼 은도끼', '["가난한 나무꾼이 연못가에서 나무를 베다가 그만 도끼를 물에 빠뜨리고 말았어요.","나무꾼이 엉엉 울고 있는데, 연못에서 산신령이 나타났어요.","산신령은 금도끼를 들고 \"이것이 네 도끼냐\"고 물었어요.","나무꾼은 \"아니에요, 제 도끼는 낡은 쇠도끼예요\"라고 정직하게 대답했어요.","산신령은 은도끼를 들고 다시 물었지만, 나무꾼은 여전히 아니라고 답했어요.","산신령은 나무꾼의 정직함에 감동해 금도끼와 은도끼, 쇠도끼를 모두 선물로 주었어요.","이 소문을 들은 욕심 많은 나무꾼이 일부러 도끼를 연못에 던지고 거짓말을 했어요.","산신령은 거짓말을 한 나무꾼에게는 아무 도끼도 주지 않고 사라져 버렸어요."]'::jsonb, '[{"word":"산신령","meaning":"산을 지킨다는 신"},{"word":"정직하다","meaning":"거짓 없이 마음이 바르고 곧다"},{"word":"감동하다","meaning":"마음이 움직여 크게 느끼다"}]'::jsonb, '[{"answer":true,"statement":"나무꾼은 도끼를 연못에 빠뜨렸어요."},{"answer":true,"statement":"정직한 나무꾼은 세 개의 도끼를 모두 받았어요."},{"answer":false,"statement":"욕심 많은 나무꾼도 도끼를 선물로 받았어요."}]'::jsonb, '{"choices":["도끼는 금으로 만든 것이 가장 좋아요","정직하게 말하면 결국 좋은 결과를 얻을 수 있어요","연못에서는 절대 나무를 베면 안 돼요","산신령은 항상 화가 나 있어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"정직하다","choices":["겁이 많고 소심하다","욕심이 많고 이기적이다","게으르고 느리다","거짓 없이 마음이 바르고 곧다"],"answerIndex":3},{"type":"vocab","word":"감동하다","choices":["크게 화를 내다","마음이 움직여 크게 느끼다","깊이 잠들다","배가 고프다"],"answerIndex":1},{"type":"synonym","word":"정직하다","choices":["거짓되다","게으르다","올바르다","욕심많다"],"answerIndex":2},{"type":"antonym","word":"정직하다","choices":["거짓되다","올바르다","참되다","바르다"],"answerIndex":0},{"type":"spelling","word":"금세","choices":["금새","금쌔","금세","금셰"],"answerIndex":2}]'::jsonb, 115)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('tiger-and-dried-persimmon', '🐯', '호랑이와 곶감', '["어느 겨울밤, 배고픈 호랑이가 마을로 내려와 소를 잡아먹으려고 외양간을 찾았어요.","그때 아기가 자꾸 울자, 방 안에서 엄마가 \"호랑이가 왔다\"라고 해도 아기는 울음을 그치지 않았어요.","엄마가 \"옜다, 곶감!\"이라고 말하자 아기는 신기하게도 울음을 뚝 그쳤어요.","밖에서 듣고 있던 호랑이는 깜짝 놀랐어요. \"곶감이라는 게 나보다 더 무서운 것인가 보다!\"","마침 그때 외양간에 숨어 있던 소도둑이 어둠 속에서 호랑이 등에 올라탔어요.","소도둑은 호랑이를 소인 줄 알고 등에 탔고, 호랑이는 소도둑을 곶감인 줄 알고 깜짝 놀라 마구 도망쳤어요.","날이 밝아서야 서로의 정체를 알게 된 호랑이와 소도둑은 깜짝 놀라 각자 걸음아 날 살려라 도망갔답니다."]'::jsonb, '[{"word":"외양간","meaning":"소를 기르는 곳"},{"word":"정체","meaning":"참된 모습이나 본래의 상태"},{"word":"걸음아 날 살려라","meaning":"있는 힘껏 빨리 도망가는 모습을 이르는 말"}]'::jsonb, '[{"answer":true,"statement":"호랑이는 곶감이 자기보다 더 무서운 것이라고 생각했어요."},{"answer":true,"statement":"소도둑은 어둠 속에서 호랑이를 소인 줄 알고 올라탔어요."},{"answer":false,"statement":"호랑이와 소도둑은 처음부터 서로의 정체를 알고 있었어요."}]'::jsonb, '{"choices":["곶감은 겨울에만 먹을 수 있어요","호랑이는 마을에 절대 내려오지 않아요","잘 알지 못하는 것은 실제보다 더 크게 무섭게 느껴질 수 있어요","아기는 항상 울지 않아야 해요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"외양간","choices":["곡식을 파는 가게","소를 기르는 곳","물고기를 잡는 배","옷을 만드는 공장"],"answerIndex":1},{"type":"vocab","word":"정체","choices":["아주 빠른 속도","달콤한 음식의 맛","커다란 소리","참된 모습이나 본래의 상태"],"answerIndex":3},{"type":"synonym","word":"정체","choices":["겉모습","본모습","이름","소리"],"answerIndex":1},{"type":"antonym","word":"무섭다","choices":["편안하다","두렵다","겁나다","놀랍다"],"answerIndex":0},{"type":"spelling","word":"아무튼","choices":["아뭏든","아뭍든","아뭇든","아무튼"],"answerIndex":3}]'::jsonb, 116)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('porridge-granny-and-tiger', '🍲', '팥죽 할멈과 호랑이', '["산 아래 밭에서 팥 농사를 짓는 할머니에게 호랑이가 나타나 \"팥죽을 쑤어 주면 안 잡아먹겠다\"고 했어요.","할머니는 겨울까지 팥죽을 쑤어 주기로 약속하고 매일 열심히 밭을 가꾸었어요.","겨울이 되어 할머니가 맛있는 팥죽을 끓이며 눈물을 흘리자, 부엌 물건들이 사정을 물었어요.","알밤, 자라, 송곳, 멍석, 지게가 힘을 합쳐 할머니를 돕겠다고 나섰어요.","호랑이가 팥죽을 먹으러 오자, 아궁이 속 알밤이 튀어 올라 뜨겁게 놀래켰어요.","자라는 물통에서 나와 발을 물고, 송곳은 아프게 찌르고, 멍석은 호랑이를 둘둘 말았어요.","마지막으로 지게가 멍석에 말린 호랑이를 번쩍 들어 강물에 풍덩 던져 버렸어요.","할머니는 여러 친구들의 도움 덕분에 무사히 겨울을 넘길 수 있었답니다."]'::jsonb, '[{"word":"사정","meaning":"어떤 일의 형편이나 까닭"},{"word":"나서다","meaning":"어떤 일을 적극적으로 하려고 앞으로 나오다"},{"word":"무사히","meaning":"아무 탈 없이 편안하게"}]'::jsonb, '[{"answer":true,"statement":"호랑이는 할머니에게 팥죽을 쑤어 주면 안 잡아먹겠다고 했어요."},{"answer":true,"statement":"부엌 물건들이 힘을 합쳐 할머니를 도와주었어요."},{"answer":false,"statement":"할머니는 혼자 힘으로 호랑이를 물리쳤어요."}]'::jsonb, '{"choices":["팥죽은 여름에 먹어야 맛있어요","호랑이는 절대 약속을 지키지 않아요","부엌 물건은 말을 할 수 없어요","어려운 일도 여럿이 힘을 합치면 이겨낼 수 있어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"사정","choices":["아주 큰 소리","달콤한 맛","어떤 일의 형편이나 까닭","빠르게 걷는 모습"],"answerIndex":2},{"type":"proverb","word":"백지장도 맞들면 낫다","choices":["쉬운 일도 여럿이 함께하면 더 쉬워진다는 뜻이에요","종이는 혼자 드는 것이 좋다는 뜻이에요","백지는 아무 데도 쓸모가 없다는 뜻이에요","무거운 것은 절대 들면 안 된다는 뜻이에요"],"answerIndex":0},{"type":"synonym","word":"나서다","choices":["물러서다","앞장서다","숨어들다","망설이다"],"answerIndex":1},{"type":"antonym","word":"나서다","choices":["앞장서다","도와주다","힘을 합치다","물러서다"],"answerIndex":3},{"type":"spelling","word":"희한하다","choices":["희한하다","희안하다","희안한다","희한한다"],"answerIndex":0}]'::jsonb, 117)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('goblin-magic-club', '👹', '도깨비 방망이', '["나무를 하러 산에 간 가난하지만 착한 나무꾼이 밤이 늦어 커다란 나무 위에서 잠을 청했어요.","한밤중, 나무 아래에 도깨비들이 모여 방망이를 두드리며 신나게 놀고 있었어요.","\"금 나와라, 뚝딱! 밥 나와라, 뚝딱!\" 방망이를 두드릴 때마다 신기한 것들이 쏟아져 나왔어요.","나무꾼이 밤톨을 씹는 소리에 놀란 도깨비들은 방망이를 놓아둔 채 도망쳤어요.","나무꾼은 방망이를 주워 집으로 가져가 착하게 살면서도 필요한 만큼만 사용했어요.","이 소식을 들은 욕심 많은 이웃도 나무 위에 올라가 밤톨 씹는 소리를 냈어요.","하지만 도깨비들은 지난번 일을 떠올리고 화가 나서 그 이웃을 흠씬 혼내주고 말았어요.","나무꾼은 그 뒤로도 이웃을 도우며 마을에서 존경받는 사람이 되었답니다."]'::jsonb, '[{"word":"청하다","meaning":"무엇을 하도록 부탁하다"},{"word":"존경받다","meaning":"훌륭하다고 여겨져 우러름을 받다"},{"word":"흠씬","meaning":"매우 심하게"}]'::jsonb, '[{"answer":true,"statement":"나무꾼은 도깨비들이 놓고 간 방망이를 주웠어요."},{"answer":true,"statement":"나무꾼은 방망이를 필요한 만큼만 사용했어요."},{"answer":false,"statement":"욕심 많은 이웃도 방망이로 부자가 되었어요."}]'::jsonb, '{"choices":["남의 것을 욕심내어 따라 하면 오히려 화를 입을 수 있어요","도깨비는 낮에만 나타나요","방망이는 아무나 두드리면 소리가 나요","나무 위에서 자는 것이 가장 편해요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"존경받다","choices":["미움을 받아 따돌림당하다","크게 놀라서 도망치다","훌륭하다고 여겨져 우러름을 받다","아무 관심도 받지 못하다"],"answerIndex":2},{"type":"proverb","word":"제 꾀에 제가 넘어간다","choices":["꾀가 많으면 무엇이든 잘된다는 뜻이에요","남을 속이려던 꾀 때문에 오히려 자기가 곤란해진다는 뜻이에요","넘어지면 다시 일어나야 한다는 뜻이에요","방망이는 두 개를 써야 한다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"청하다","choices":["거절하다","명령하다","나무라다","부탁하다"],"answerIndex":3},{"type":"antonym","word":"존경받다","choices":["우러름받다","사랑받다","무시당하다","인정받다"],"answerIndex":2},{"type":"spelling","word":"곰곰이","choices":["곰곰이","곰곰히","곰곰이가","곰곰하게"],"answerIndex":0}]'::jsonb, 118)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('magpie-repays-kindness', '🔔', '은혜 갚은 까치', '["과거를 보러 한양으로 가던 선비가 산길에서 커다란 구렁이가 까치 둥지를 위협하는 것을 보았어요.","선비는 활을 쏘아 구렁이를 물리치고 까치 가족을 위험에서 구해 주었어요.","날이 저물어 선비는 산속의 오래된 절에서 하룻밤을 묵기로 했어요.","그런데 그 절에는 죽은 구렁이의 짝이 선비에게 복수하려고 기다리고 있었어요.","구렁이는 선비에게 새벽닭이 세 번 울기 전에 종이 세 번 울리지 않으면 잡아먹겠다고 했어요.","선비가 절망에 빠져 있을 때, 갑자기 어디선가 종이 세 번 울렸어요.","놀란 구렁이는 약속대로 선비를 살려 주고 사라졌어요.","다음 날 선비가 종탑에 가 보니, 까치 한 마리가 머리로 종을 울리다 목숨을 잃은 채 쓰러져 있었어요.","선비는 자신을 구해 준 까치의 은혜에 깊이 감사하며 정성껏 무덤을 만들어 주었답니다."]'::jsonb, '[{"word":"위협하다","meaning":"힘으로 겁을 주어 두렵게 하다"},{"word":"절망","meaning":"희망이 없어지고 마음이 무너지는 것"},{"word":"은혜","meaning":"도움을 받아 고마운 마음이 드는 일"}]'::jsonb, '[{"answer":true,"statement":"선비는 구렁이에게서 까치 가족을 구해 주었어요."},{"answer":true,"statement":"까치는 종을 울려서 선비의 목숨을 구했어요."},{"answer":false,"statement":"구렁이는 선비를 처음부터 도와주려고 했어요."}]'::jsonb, '{"choices":["산길에서는 절대 활을 쏘면 안 돼요","받은 은혜를 잊지 않고 갚으려는 마음은 큰 감동을 줘요","까치는 사람을 무서워해요","절에서는 잠을 자면 안 돼요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"위협하다","choices":["다정하게 위로하다","크게 칭찬하다","조용히 도와주다","힘으로 겁을 주어 두렵게 하다"],"answerIndex":3},{"type":"vocab","word":"은혜","choices":["크게 화가 나는 일","아무 의미 없는 일","도움을 받아 고마운 마음이 드는 일","심하게 두려운 일"],"answerIndex":2},{"type":"synonym","word":"절망","choices":["희망","좌절","기쁨","안심"],"answerIndex":1},{"type":"antonym","word":"절망","choices":["희망","좌절","낙심","실망"],"answerIndex":0},{"type":"spelling","word":"오랜만","choices":["오랫만","오랜동안","오랫동안에","오랜만"],"answerIndex":3}]'::jsonb, 119)
