insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('donkey-ears-king-secret', '👂', '임금님 귀는 당나귀 귀', '["옛날 어느 임금님은 어느 날부터 귀가 당나귀처럼 커져 버렸어요.","임금님은 부끄러워서 커다란 모자를 써서 귀를 숨기고 아무에게도 비밀을 말하지 못하게 했어요.","모자를 만드는 노인만이 이 비밀을 알게 되었는데, 아무에게도 말하지 말라는 명령을 받았어요.","노인은 비밀을 마음속에만 담아 두려니 답답해서 병이 날 지경이었어요.","결국 노인은 대나무 숲으로 들어가 \"임금님 귀는 당나귀 귀!\"라고 크게 외쳤어요.","그제야 마음이 후련해진 노인은 편안하게 잠들 수 있었어요.","그런데 바람이 불 때마다 대나무 숲에서 \"임금님 귀는 당나귀 귀\"라는 소리가 들리기 시작했어요.","처음에 화가 났던 임금님도 결국 사실을 인정하고 당당하게 살기로 마음먹었어요.","백성들은 오히려 솔직한 임금님을 더욱 믿고 따르게 되었답니다."]'::jsonb, '[{"word":"답답하다","meaning":"속이 막힌 듯이 갑갑하다"},{"word":"후련하다","meaning":"마음속이 시원하고 편안하다"},{"word":"당당하다","meaning":"떳떳하고 자신감이 있다"}]'::jsonb, '[{"answer":true,"statement":"노인은 임금님의 비밀을 지키느라 답답해했어요."},{"answer":true,"statement":"노인은 대나무 숲에서 비밀을 외쳤어요."},{"answer":false,"statement":"임금님은 끝까지 비밀을 숨기고 인정하지 않았어요."}]'::jsonb, '{"choices":["비밀을 숨기기보다 솔직하게 인정하는 것이 마음 편한 길이 될 수 있어요","모자는 항상 크게 만들어야 해요","대나무 숲에서는 소리를 지르면 안 돼요","임금님은 혼자 모든 것을 결정해야 해요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"답답하다","choices":["속이 시원하고 편안하다","속이 막힌 듯이 갑갑하다","크게 화가 나다","아주 기쁘다"],"answerIndex":1},{"type":"vocab","word":"당당하다","choices":["부끄럽고 소심하다","겁이 많고 두렵다","조용하고 차분하다","떳떳하고 자신감이 있다"],"answerIndex":3},{"type":"synonym","word":"후련하다","choices":["시원하다","답답하다","괴롭다","불안하다"],"answerIndex":0},{"type":"antonym","word":"후련하다","choices":["시원하다","편안하다","답답하다","가뿐하다"],"answerIndex":2},{"type":"spelling","word":"안 돼","choices":["안되","안돼","않되","안뒈"],"answerIndex":1}]'::jsonb, 120)
