insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('farting-daughter-in-law', '💨', '방귀쟁이 며느리', '["시집온 지 얼마 안 된 며느리가 방귀를 참느라 얼굴이 노랗게 뜨고 기운이 없었어요.","시아버지가 이유를 묻자 며느리는 부끄러워하며 사실대로 말씀드렸어요.","시아버지는 며느리에게 참지 말고 방귀를 뀌어 보라고 다정하게 말했어요.","며느리가 방귀를 뀌자 집 안 물건들이 흔들릴 만큼 우렁찬 소리가 났어요.","놀란 가족들이 기둥을 꽉 붙잡을 정도였지만, 다행히 아무도 다치지 않았어요.","그 뒤로 며느리는 얼굴에 다시 혈색이 돌고 건강을 되찾았어요.","가족들은 며느리의 솔직함을 탓하지 않고 오히려 다 함께 웃어넘겼어요.","며느리는 편안한 마음으로 시댁 식구들과 사이좋게 지내게 되었답니다."]'::jsonb, '[{"word":"혈색","meaning":"얼굴에 나타나는 핏기와 화색"},{"word":"우렁차다","meaning":"소리가 매우 크고 힘차다"},{"word":"탓하다","meaning":"잘못을 남의 책임으로 돌려 말하다"}]'::jsonb, '[{"answer":true,"statement":"며느리는 방귀를 참느라 기운이 없었어요."},{"answer":true,"statement":"시아버지는 며느리에게 참지 말라고 했어요."},{"answer":false,"statement":"가족들은 며느리를 심하게 혼냈어요."}]'::jsonb, '{"choices":["며느리는 항상 조용히 지내야 해요","솔직하게 마음을 터놓으면 오히려 문제가 편안하게 풀릴 수 있어요","방귀는 아주 위험한 것이에요","시아버지는 화를 잘 내는 사람이에요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"혈색","choices":["큰 목소리","빠른 걸음","얼굴에 나타나는 핏기와 화색","무거운 물건"],"answerIndex":2},{"type":"vocab","word":"우렁차다","choices":["소리가 매우 크고 힘차다","아주 조용하다","향기롭고 달콤하다","부드럽고 가볍다"],"answerIndex":0},{"type":"synonym","word":"우렁차다","choices":["작다","힘차다","약하다","느리다"],"answerIndex":1},{"type":"antonym","word":"우렁차다","choices":["힘차다","크다","세차다","약하다"],"answerIndex":3},{"type":"spelling","word":"며느리","choices":["며늘이","며느니","며느리","며늘리"],"answerIndex":2}]'::jsonb, 121)
