insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('three-year-hill-tumble', '⛰️', '삼년고개', '["옛날 어느 마을에 넘어지면 삼 년밖에 못 산다는 무서운 삼년고개가 있었어요.","어느 날 할아버지가 그 고개를 넘다가 그만 발을 헛디뎌 넘어지고 말았어요.","할아버지는 이제 삼 년밖에 살지 못한다는 생각에 몸져누워 걱정만 했어요.","이웃에 사는 지혜로운 소년이 소식을 듣고 할아버지를 찾아왔어요.","소년은 \"한 번 넘어지면 삼 년이니, 열 번 넘어지면 서른 해를 더 살 수 있는 것 아니겠어요?\"라고 말했어요.","할아버지는 무릎을 탁 치며 그 말이 정말 옳다고 생각했어요.","할아버지는 다시 삼년고개로 가서 일부러 데굴데굴 여러 번 넘어졌어요.","그 뒤로 할아버지는 걱정을 떨쳐내고 건강하게 오래오래 살았답니다."]'::jsonb, '[{"word":"헛디디다","meaning":"발을 잘못 디디다"},{"word":"몸져눕다","meaning":"병이 나서 자리에 눕다"},{"word":"떨쳐내다","meaning":"어떤 생각이나 감정을 없애 버리다"}]'::jsonb, '[{"answer":true,"statement":"할아버지는 삼년고개에서 넘어졌어요."},{"answer":true,"statement":"소년은 여러 번 넘어지면 더 오래 산다고 말했어요."},{"answer":false,"statement":"할아버지는 소년의 말을 듣고도 계속 걱정만 했어요."}]'::jsonb, '{"choices":["고개는 항상 조심해서 걸어야 해요","나이 든 사람의 말은 무조건 따라야 해요","생각을 바꾸면 걱정도 다르게 풀어낼 수 있어요","넘어지는 것은 무조건 나쁜 일이에요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"헛디디다","choices":["발을 잘못 디디다","크게 웃다","깊이 생각하다","빠르게 달리다"],"answerIndex":0},{"type":"vocab","word":"몸져눕다","choices":["신나게 노래하다","힘차게 일어서다","기쁘게 웃다","병이 나서 자리에 눕다"],"answerIndex":3},{"type":"synonym","word":"떨쳐내다","choices":["붙잡다","없애다","키우다","숨기다"],"answerIndex":1},{"type":"antonym","word":"떨쳐내다","choices":["없애다","버리다","붙잡다","지우다"],"answerIndex":2},{"type":"spelling","word":"데굴데굴","choices":["데굴데굴","대굴대굴","데굴대굴","대굴데굴"],"answerIndex":0}]'::jsonb, 122)
