insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('youth-spring-water', '💧', '젊어지는 샘물', '["산속에 사는 마음씨 착한 할아버지와 욕심 많은 할아버지가 이웃해 살았어요.","착한 할아버지는 나무를 하다가 목이 말라 산속 옹달샘의 물을 마셨어요.","신기하게도 물을 마시자 몸이 젊어져 튼튼한 청년의 모습으로 변했어요.","착한 할아버지는 젊어진 몸으로 부지런히 일하며 이웃을 도왔어요.","이 소식을 들은 욕심 많은 할아버지도 샘물을 찾아가 벌컥벌컥 너무 많이 마셨어요.","욕심 많은 할아버지는 그만 너무 어려져 갓난아기가 되어 버렸어요.","착한 할아버지 부부는 놀랐지만 아기를 정성껏 자식처럼 키우기로 했어요.","마을 사람들은 착한 할아버지의 넉넉한 마음씨에 감탄했답니다."]'::jsonb, '[{"word":"옹달샘","meaning":"작고 오목한 샘"},{"word":"벌컥벌컥","meaning":"물 등을 급하게 많이 들이켜는 소리나 모양"},{"word":"넉넉하다","meaning":"마음이 크고 여유가 있다"}]'::jsonb, '[{"answer":true,"statement":"착한 할아버지는 샘물을 마시고 젊어졌어요."},{"answer":true,"statement":"욕심 많은 할아버지는 물을 너무 많이 마셔서 아기가 되었어요."},{"answer":false,"statement":"착한 할아버지 부부는 아기를 내다 버렸어요."}]'::jsonb, '{"choices":["샘물은 아무도 마시면 안 돼요","산에서는 절대 나무를 하면 안 돼요","젊어지는 것은 누구에게나 나쁜 일이에요","무엇이든 지나친 욕심은 화를 부를 수 있어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"옹달샘","choices":["커다란 바다","작고 오목한 샘","높은 산봉우리","넓은 들판"],"answerIndex":1},{"type":"vocab","word":"넉넉하다","choices":["좁고 부족하다","화가 나고 급하다","마음이 크고 여유가 있다","겁이 많고 소심하다"],"answerIndex":2},{"type":"synonym","word":"넉넉하다","choices":["여유롭다","부족하다","급하다","인색하다"],"answerIndex":0},{"type":"antonym","word":"넉넉하다","choices":["여유롭다","풍족하다","넓다","부족하다"],"answerIndex":3},{"type":"spelling","word":"갓난아기","choices":["갖난아기","갓난아기","갓난아이기","갖난아이기"],"answerIndex":1}]'::jsonb, 123)
