insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('lazybones-turned-ox', '🐂', '소가 된 게으름뱅이', '["일하기 싫어하는 게으름뱅이가 산속을 걷다가 소머리 탈을 파는 노인을 만났어요.","노인은 이 탈을 쓰면 일하지 않고도 편하게 지낼 수 있다며 게으름뱅이에게 씌워 주었어요.","탈을 쓰자마자 게으름뱅이는 정말로 커다란 소로 변해 버렸어요.","소가 된 게으름뱅이는 밭에 팔려가 하루 종일 무거운 쟁기를 끌어야 했어요.","힘든 일을 겪으며 게으름뱅이는 그동안 편하게만 살려던 자신을 후회했어요.","노인은 \"무씨를 먹으면 사람으로 돌아갈 수 있지만 딱 한 번뿐\"이라고 알려주었어요.","게으름뱅이는 힘들게 무를 구해 허겁지겁 먹고 겨우 사람으로 돌아왔어요.","그 뒤로 게으름뱅이는 누구보다 부지런한 농부가 되어 열심히 일했답니다."]'::jsonb, '[{"word":"쟁기","meaning":"논밭을 가는 데 쓰는 농기구"},{"word":"후회하다","meaning":"잘못을 뉘우치다"},{"word":"허겁지겁","meaning":"조급하게 서두르는 모양"}]'::jsonb, '[{"answer":true,"statement":"게으름뱅이는 소머리 탈을 쓰고 진짜 소가 되었어요."},{"answer":true,"statement":"소가 된 게으름뱅이는 밭에서 힘든 일을 했어요."},{"answer":false,"statement":"게으름뱅이는 소가 된 것을 아주 좋아했어요."}]'::jsonb, '{"choices":["게으름을 피우기만 하면 결국 더 큰 어려움을 겪을 수 있어요","소는 사람보다 힘이 세요","탈은 항상 조심해서 써야 해요","무는 몸에 아주 좋은 채소예요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"쟁기","choices":["물을 담는 그릇","논밭을 가는 데 쓰는 농기구","옷을 만드는 도구","불을 피우는 도구"],"answerIndex":1},{"type":"vocab","word":"후회하다","choices":["크게 기뻐하다","자랑스러워하다","잘못을 뉘우치다","화를 내다"],"answerIndex":2},{"type":"synonym","word":"후회하다","choices":["기뻐하다","자랑하다","만족하다","뉘우치다"],"answerIndex":3},{"type":"antonym","word":"후회하다","choices":["만족하다","뉘우치다","반성하다","자책하다"],"answerIndex":0},{"type":"spelling","word":"허겁지겁","choices":["허겁직겁","허겁지겁","허급지급","허겁지급"],"answerIndex":1}]'::jsonb, 124)
