insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('brothers-share-rice-stacks', '🌾', '의좋은 형제', '["사이좋은 형과 아우가 각자 논농사를 지으며 나란히 살고 있었어요.","가을이 되어 형제는 볏단을 각자의 마당에 똑같이 나누어 쌓아 두었어요.","형은 결혼해서 살림이 더 필요한 아우가 걱정되어 밤에 몰래 볏단을 아우네로 옮겼어요.","아우도 형네 가족이 많아 더 힘들 거라 생각해 밤마다 볏단을 형네로 옮겼어요.","다음 날 아침, 두 사람은 볏단이 줄지 않은 것을 보고 이상하게 여겼어요.","며칠 뒤 보름달이 뜬 밤, 볏단을 지고 가던 형과 아우가 길 한가운데서 딱 마주쳤어요.","서로의 마음을 알게 된 형제는 볏단을 안고 서로를 꼭 끌어안았어요.","마을 사람들은 이 이야기를 전해 듣고 형제의 우애에 크게 감동했답니다."]'::jsonb, '[{"word":"볏단","meaning":"벼를 베어 묶은 단"},{"word":"살림","meaning":"한 집안을 이루어 살아가는 일"},{"word":"우애","meaning":"형제나 친구 사이의 따뜻한 정"}]'::jsonb, '[{"answer":true,"statement":"형과 아우는 서로 몰래 볏단을 옮겨 주었어요."},{"answer":true,"statement":"형제는 길에서 마주쳐서 서로의 마음을 알게 되었어요."},{"answer":false,"statement":"형제는 볏단 때문에 크게 다투었어요."}]'::jsonb, '{"choices":["농사는 혼자 지어야 편해요","서로를 아끼는 마음은 말하지 않아도 통할 수 있어요","밤에는 절대 밖에 나가면 안 돼요","볏단은 항상 똑같이 나누어야 해요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"볏단","choices":["벼를 베어 묶은 단","물을 담는 항아리","나무로 만든 의자","곡식을 심는 도구"],"answerIndex":0},{"type":"vocab","word":"우애","choices":["차갑고 무서운 마음","서로를 미워하는 마음","혼자 지내고 싶은 마음","형제나 친구 사이의 따뜻한 정"],"answerIndex":3},{"type":"synonym","word":"우애","choices":["미움","다툼","정","오해"],"answerIndex":2},{"type":"antonym","word":"우애","choices":["정","사랑","미움","우정"],"answerIndex":2},{"type":"spelling","word":"끌어안다","choices":["끌어안다","끄러안다","끌어앉다","끄러앉다"],"answerIndex":0}]'::jsonb, 125)
