insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('ondal-and-pyeonggang-princess', '🏹', '바보 온달과 평강공주', '["옛날 고구려에 가난하지만 착한 온달이라는 청년이 눈먼 어머니를 모시고 살았어요.","사람들은 온달을 놀리며 \"바보 온달\"이라고 불렀지만 그는 늘 성실했어요.","어느 날 궁궐에서 나온 평강공주가 온달의 집을 찾아와 함께 살게 해 달라고 부탁했어요.","평강공주는 온달에게 글과 무예를 가르치며 훌륭한 장수로 성장하도록 도왔어요.","온달은 밤낮없이 열심히 훈련하며 몸과 마음을 단련해 나갔어요.","마침내 온달은 나라의 큰 사냥 대회에 나가 뛰어난 실력으로 사람들을 놀라게 했어요.","왕은 온달의 실력을 보고 크게 기뻐하며 그를 훌륭한 장군으로 삼았어요.","온달과 평강공주는 서로 믿고 도우며 나라를 위해 힘썼답니다."]'::jsonb, '[{"word":"무예","meaning":"무술에 관한 재주"},{"word":"단련하다","meaning":"몸과 마음을 굳세게 훈련하다"},{"word":"성장하다","meaning":"자라서 점점 커지다"}]'::jsonb, '[{"answer":true,"statement":"온달은 처음에 사람들에게 놀림을 받았어요."},{"answer":true,"statement":"평강공주는 온달에게 글과 무예를 가르쳤어요."},{"answer":false,"statement":"온달은 노력하지 않고도 저절로 장군이 되었어요."}]'::jsonb, '{"choices":["공주는 궁궐 밖으로 나가면 안 돼요","사냥 대회는 아주 위험해요","꾸준한 노력과 믿음은 사람을 크게 성장시켜요","가난한 사람은 성공할 수 없어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"무예","choices":["그림 그리는 재주","무술에 관한 재주","노래하는 재주","요리하는 재주"],"answerIndex":1},{"type":"vocab","word":"단련하다","choices":["몸과 마음을 굳세게 훈련하다","가만히 앉아 쉬다","깊이 잠들다","크게 웃다"],"answerIndex":0},{"type":"synonym","word":"성장하다","choices":["줄어들다","머무르다","약해지다","자라다"],"answerIndex":3},{"type":"antonym","word":"성장하다","choices":["자라다","크다","줄어들다","발전하다"],"answerIndex":2},{"type":"spelling","word":"훌륭하다","choices":["훌룡하다","훌늉하다","훌륭하다","훌룽하다"],"answerIndex":2}]'::jsonb, 126)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('gyeonu-jiknyeo-magpie-bridge', '🌌', '견우와 직녀', '["하늘 나라에 소를 치는 견우와 베를 짜는 직녀가 서로 사랑하여 부부가 되었어요.","결혼한 뒤 두 사람은 일은 하지 않고 노는 데에만 빠져 지냈어요.","화가 난 옥황상제는 두 사람을 은하수를 사이에 두고 떨어져 살게 했어요.","견우와 직녀는 서로 그리워하며 은하수 이편과 저편에서 눈물을 흘렸어요.","이를 안타깝게 여긴 까마귀와 까치들이 해마다 칠월 칠석에 모여 몸으로 다리를 놓아 주기로 했어요.","두 사람은 까마귀와 까치가 만들어 준 다리를 건너 일 년에 딱 한 번 서로 만날 수 있었어요.","칠석날 비가 내리면 사람들은 견우와 직녀가 기뻐서 흘리는 눈물이라고 이야기했어요.","견우와 직녀는 그 짧은 만남을 소중히 여기며 다시 헤어질 날까지 열심히 일했답니다."]'::jsonb, '[{"word":"은하수","meaning":"밤하늘에 강처럼 보이는 수많은 별의 무리"},{"word":"안타깝다","meaning":"뜻대로 되지 않아 마음이 아프다"},{"word":"소중히","meaning":"매우 귀하고 중요하게"}]'::jsonb, '[{"answer":true,"statement":"견우와 직녀는 결혼한 뒤 일을 게을리했어요."},{"answer":true,"statement":"까마귀와 까치가 몸으로 다리를 놓아 주었어요."},{"answer":false,"statement":"견우와 직녀는 매일 만날 수 있었어요."}]'::jsonb, '{"choices":["은하수는 아무도 건널 수 없어요","옥황상제는 항상 화가 나 있어요","새들은 서로 힘을 합칠 수 없어요","맡은 일을 소홀히 하면 소중한 것을 잃을 수 있어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"은하수","choices":["밤하늘에 강처럼 보이는 수많은 별의 무리","넓고 깊은 바다","높고 험한 산","비가 내리는 구름"],"answerIndex":0},{"type":"vocab","word":"안타깝다","choices":["매우 기쁘다","아주 신난다","뜻대로 되지 않아 마음이 아프다","마음이 편안하다"],"answerIndex":2},{"type":"synonym","word":"소중히","choices":["함부로","귀하게","가볍게","대충"],"answerIndex":1},{"type":"antonym","word":"소중히","choices":["함부로","귀하게","정성껏","곱게"],"answerIndex":0},{"type":"spelling","word":"일부러","choices":["일부로","일부러써","일부로써","일부러"],"answerIndex":3}]'::jsonb, 127)
