insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('stingy-jarin-gobi', '🐟', '구두쇠 자린고비', '["자린고비라는 부자 영감은 돈을 한 푼도 안 쓰려는 지독한 구두쇠였어요.","그는 천장에 굴비 한 마리를 매달아 놓고 밥 한 술에 한 번씩만 쳐다보게 했어요.","어느 날 손자가 굴비를 두 번 쳐다보자 영감은 크게 화를 냈어요.","하루는 부채를 아끼려고 부채는 펴 놓고 고개만 흔들며 부채질을 대신했어요.","마을에 큰 흉년이 들어 사람들이 굶주리자, 자린고비는 곳간을 활짝 열었어요.","그동안 아껴 온 곡식을 마을 사람들에게 아낌없이 나누어 주었어요.","사람들은 평소의 구두쇠 모습과 다른 영감의 모습에 깜짝 놀랐어요.","자린고비는 \"평소에 아껴야 정말 필요한 순간에 나눌 수 있다\"고 말했답니다."]'::jsonb, '[{"word":"구두쇠","meaning":"돈이나 물건을 지나치게 아끼는 사람"},{"word":"곳간","meaning":"곡식이나 물건을 저장해 두는 방이나 창고"},{"word":"흉년","meaning":"농사가 잘되지 않아 굶주리는 해"}]'::jsonb, '[{"answer":true,"statement":"자린고비는 굴비를 천장에 매달아 놓았어요."},{"answer":true,"statement":"흉년이 들자 자린고비는 곳간을 열어 나누어 주었어요."},{"answer":false,"statement":"자린고비는 끝까지 아무에게도 나누어 주지 않았어요."}]'::jsonb, '{"choices":["평소의 검소함은 정말 필요한 순간에 큰 도움이 될 수 있어요","돈은 무조건 많이 써야 좋아요","굴비는 매일 먹어야 하는 생선이에요","부채는 여름에만 필요해요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"구두쇠","choices":["아주 너그러운 사람","돈이나 물건을 지나치게 아끼는 사람","힘이 아주 센 사람","말을 잘하는 사람"],"answerIndex":1},{"type":"vocab","word":"곳간","choices":["잠을 자는 방","손님을 맞는 방","불을 피우는 곳","곡식이나 물건을 저장해 두는 방이나 창고"],"answerIndex":3},{"type":"synonym","word":"구두쇠","choices":["짠돌이","베풂이","넉넉이","후함이"],"answerIndex":0},{"type":"antonym","word":"구두쇠","choices":["짠돌이","알뜰이","마음씨 좋은 사람","깍쟁이"],"answerIndex":2},{"type":"spelling","word":"아낌없이","choices":["아김없이","아낌없이","아끼업이","아낌업이"],"answerIndex":1}]'::jsonb, 128)
