insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('magic-salt-millstone', '🧂', '요술 맷돌', '["옛날 어느 형제 중 형은 부자였고 아우는 몹시 가난했어요.","아우는 어느 날 산속 노인에게 돌리면 무엇이든 나오는 요술 맷돌을 얻었어요.","\"쌀 나와라!\"하고 돌리자 정말로 쌀이 쏟아져 나와 아우는 큰 부자가 되었어요.","이 소식을 들은 욕심 많은 형이 몰래 맷돌을 훔쳐 배에 싣고 바다로 나갔어요.","형은 배 위에서 \"소금 나와라!\"하고 맷돌을 돌렸지만, 멈추는 말을 미처 배우지 못했어요.","맷돌은 멈추지 않고 계속 소금을 쏟아 냈고, 결국 배는 소금의 무게에 가라앉고 말았어요.","그 뒤로 바닷물이 짜게 되었다는 이야기가 전해 내려온답니다.","아우는 착한 마음으로 얻은 맷돌을 이웃과 나누며 오래오래 행복하게 살았어요."]'::jsonb, '[{"word":"요술","meaning":"신기한 재주나 술법"},{"word":"미처","meaning":"아직 거기까지 미치도록"},{"word":"가라앉다","meaning":"물속으로 내려앉다"}]'::jsonb, '[{"answer":true,"statement":"아우는 노인에게서 요술 맷돌을 얻었어요."},{"answer":true,"statement":"형은 맷돌을 멈추는 방법을 배우지 못했어요."},{"answer":false,"statement":"형은 맷돌 덕분에 큰 부자가 되어 행복하게 살았어요."}]'::jsonb, '{"choices":["맷돌은 아무나 돌릴 수 있어요","남의 것을 함부로 욕심내면 오히려 큰 화를 입을 수 있어요","바다에서는 항상 소금이 나요","형제는 항상 사이가 나빠요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"요술","choices":["크고 무거운 도구","단단하고 튼튼한 밧줄","신기한 재주나 술법","넓고 깊은 바다"],"answerIndex":2},{"type":"vocab","word":"가라앉다","choices":["물속으로 내려앉다","하늘로 날아오르다","땅 위로 솟아오르다","빠르게 달려가다"],"answerIndex":0},{"type":"synonym","word":"가라앉다","choices":["떠오르다","솟다","날다","잠기다"],"answerIndex":3},{"type":"antonym","word":"가라앉다","choices":["잠기다","떠오르다","내려앉다","침몰하다"],"answerIndex":1},{"type":"spelling","word":"요술쟁이","choices":["요술장이","요슬쟁이","요술쟁이","요슬장이"],"answerIndex":2}]'::jsonb, 129)
