insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('lump-old-man-goblin-song', '🎤', '혹부리 영감', '["얼굴에 커다란 혹이 달린 할아버지가 나무를 하고 집으로 가다가 산속에서 날이 저물었어요.","할아버지는 빈 집에서 하룻밤을 묵으며 심심함을 달래려고 신나게 노래를 불렀어요.","노랫소리를 듣고 도깨비들이 몰려와 그렇게 좋은 노래가 어디서 나오는지 물었어요.","할아버지는 재치 있게 \"이 혹에서 노래가 나온다\"고 거짓말을 했어요.","도깨비들은 신기해하며 금은보화를 잔뜩 주고 혹을 떼어 가져갔어요.","혹 없이 가벼워진 얼굴로 부자가 되어 돌아온 할아버지의 소식이 마을에 퍼졌어요.","옆 마을의 혹 달린 할아버지도 부러워서 똑같이 도깨비들 앞에서 노래를 불렀어요.","하지만 도깨비들은 \"지난번엔 속았다\"며 화를 내고 오히려 혹을 하나 더 붙여 주었답니다."]'::jsonb, '[{"word":"재치","meaning":"눈치 빠르고 재빠르게 응하는 슬기"},{"word":"몰려오다","meaning":"여럿이 한꺼번에 모여 오다"},{"word":"속다","meaning":"남의 거짓이나 꾀에 넘어가다"}]'::jsonb, '[{"answer":true,"statement":"할아버지는 도깨비들에게 혹에서 노래가 나온다고 말했어요."},{"answer":true,"statement":"옆 마을 할아버지는 혹을 하나 더 붙이게 되었어요."},{"answer":false,"statement":"도깨비들은 두 번째 할아버지에게도 금은보화를 주었어요."}]'::jsonb, '{"choices":["혹은 누구에게나 무거운 짐이에요","도깨비는 노래를 아주 싫어해요","남을 따라 하려는 욕심은 오히려 손해로 돌아올 수 있어요","노래는 밤에만 불러야 해요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"재치","choices":["눈치 빠르고 재빠르게 응하는 슬기","크고 무서운 힘","느리고 서투른 솜씨","깊고 어두운 잠"],"answerIndex":0},{"type":"vocab","word":"몰려오다","choices":["하나씩 흩어지다","조용히 사라지다","천천히 걷다","여럿이 한꺼번에 모여 오다"],"answerIndex":3},{"type":"synonym","word":"속다","choices":["깨닫다","넘어가다","이기다","막다"],"answerIndex":1},{"type":"antonym","word":"속다","choices":["넘어가다","당하다","알아차리다","믿다"],"answerIndex":2},{"type":"spelling","word":"거짓말","choices":["거짓말","거짖말","거짓말이","거짖말이"],"answerIndex":0}]'::jsonb, 130)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('green-frog-always-disobeys', '🐸', '청개구리 이야기', '["옛날 엄마 말을 무엇이든 반대로만 하는 청개구리 아들이 있었어요.","엄마가 \"동쪽으로 가라\"고 하면 아들은 꼭 서쪽으로 가고, \"울지 마라\"고 하면 더 크게 울었어요.","엄마 청개구리는 속이 상했지만, 아들을 끝까지 사랑으로 타이르며 살았어요.","엄마 청개구리는 점점 나이가 들어 몸이 약해졌어요.","어느 날 엄마는 마지막으로 아들에게 \"내가 죽으면 산에 묻지 말고 냇가에 묻어 다오\"라고 말했어요.","사실 엄마는 아들이 늘 반대로 하니, 이번엔 진짜 바람인 산에 묻히기를 바라며 일부러 반대로 말한 것이었어요.","엄마가 돌아가시자 아들은 처음으로 크게 뉘우치며 엄마의 마지막 말씀대로 냇가에 묻어 드렸어요.","그 뒤로 비만 오면 냇물이 불어날까 걱정하며 청개구리들이 슬프게 운다고 전해진답니다."]'::jsonb, '[{"word":"타이르다","meaning":"잘 깨닫도록 부드럽게 말해 주다"},{"word":"뉘우치다","meaning":"잘못을 깨닫고 반성하다"},{"word":"전해지다","meaning":"이야기 등이 다른 사람에게 알려지다"}]'::jsonb, '[{"answer":true,"statement":"청개구리 아들은 엄마 말을 항상 반대로 했어요."},{"answer":true,"statement":"엄마는 일부러 반대로 부탁을 남겼어요."},{"answer":false,"statement":"아들은 엄마의 마지막 말씀도 반대로 했어요."}]'::jsonb, '{"choices":["냇가에는 아무것도 묻으면 안 돼요","비가 오면 항상 슬픈 일이 생겨요","부모님의 말씀은 항상 반대로 들어야 해요","평소에 말을 잘 듣는 것이 후회를 남기지 않는 길이에요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"타이르다","choices":["크게 화를 내다","잘 깨닫도록 부드럽게 말해 주다","무시하고 지나치다","억지로 시키다"],"answerIndex":1},{"type":"vocab","word":"뉘우치다","choices":["기뻐하며 자랑하다","크게 웃다","잘못을 깨닫고 반성하다","깊이 잠들다"],"answerIndex":2},{"type":"synonym","word":"뉘우치다","choices":["반성하다","자랑하다","기뻐하다","무시하다"],"answerIndex":0},{"type":"antonym","word":"뉘우치다","choices":["반성하다","후회하다","자책하다","자랑스러워하다"],"answerIndex":3},{"type":"spelling","word":"깨닫다","choices":["깨닳다","깨닫다","깨다랐다","깨닸다"],"answerIndex":1}]'::jsonb, 131)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('five-talented-brothers', '💪', '재주 많은 오형제', '["옛날 한 어머니에게서 각각 특별한 재주를 가진 다섯 형제가 태어났어요.","첫째는 힘이 장사였고, 둘째는 바다를 다 마실 수 있었고, 셋째는 쇠도 견디는 몸을 가졌어요.","넷째는 다리가 아주 길었고, 막내는 몸을 마음대로 늘였다 줄였다 할 수 있었어요.","못된 사또가 형제의 재주를 시샘해 어려운 시험을 내며 괴롭혔어요.","첫째가 커다란 바위를 번쩍 들어 옮기자 사또는 더 어려운 문제를 냈어요.","둘째는 넘치는 강물을 벌컥벌컥 마셔 마을의 홍수를 막아 주었어요.","형제들은 힘을 모아 사또가 낸 어려운 시험들을 하나씩 지혜롭게 풀어냈어요.","결국 사또도 형제들의 재주와 우애를 인정하고 다시는 괴롭히지 않았답니다."]'::jsonb, '[{"word":"시샘하다","meaning":"남이 잘되는 것을 미워하고 부러워하다"},{"word":"홍수","meaning":"비가 많이 와서 강이 넘치는 것"},{"word":"인정하다","meaning":"확실히 그렇다고 여기다"}]'::jsonb, '[{"answer":true,"statement":"다섯 형제는 각각 다른 재주를 가지고 있었어요."},{"answer":true,"statement":"형제들은 힘을 모아 사또의 시험을 풀어냈어요."},{"answer":false,"statement":"사또는 처음부터 형제들을 도와주었어요."}]'::jsonb, '{"choices":["서로 다른 재주도 힘을 모으면 큰일을 해낼 수 있어요","재주는 한 사람만 가지고 있어야 해요","사또의 말은 무조건 따라야 해요","홍수는 막을 수 없는 재난이에요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"시샘하다","choices":["크게 칭찬하다","남이 잘되는 것을 미워하고 부러워하다","따뜻하게 위로하다","조용히 응원하다"],"answerIndex":1},{"type":"vocab","word":"홍수","choices":["가뭄이 계속되는 것","눈이 많이 내리는 것","바람이 세게 부는 것","비가 많이 와서 강이 넘치는 것"],"answerIndex":3},{"type":"synonym","word":"인정하다","choices":["의심하다","부정하다","받아들이다","무시하다"],"answerIndex":2},{"type":"antonym","word":"인정하다","choices":["부정하다","받아들이다","수긍하다","동의하다"],"answerIndex":0},{"type":"spelling","word":"괴로워하다","choices":["괴로와하다","괴로워하다","괴롭어하다","괴로버하다"],"answerIndex":1}]'::jsonb, 132)
