insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('turtle-and-rabbit-liver', '🐢', '별주부전', '["용궁의 용왕이 큰 병에 걸려 토끼의 간이 약이라는 말을 듣게 되었어요.","용왕은 자라(별주부)에게 육지로 나가 토끼를 데려오라고 명령했어요.","자라는 토끼를 찾아가 \"용궁에 가면 벼슬을 얻고 편하게 살 수 있다\"며 꾀어냈어요.","토끼는 자라의 등을 타고 용궁으로 들어갔다가 간을 내놓으라는 말에 깜짝 놀랐어요.","꾀 많은 토끼는 침착하게 \"간은 중요해서 육지의 나무에 걸어 두고 왔다\"고 둘러댔어요.","용왕은 그 말을 믿고 다시 자라에게 토끼를 육지로 데려다주라고 했어요.","육지에 도착하자마자 토끼는 재빨리 숲속으로 도망쳐 목숨을 구했어요.","자라는 크게 낙심했지만, 토끼의 지혜에 감탄하지 않을 수 없었답니다."]'::jsonb, '[{"word":"꾀다","meaning":"그럴듯한 말로 남을 속이거나 부추기다"},{"word":"둘러대다","meaning":"그럴듯한 말로 슬쩍 넘기다"},{"word":"낙심하다","meaning":"바라던 일이 안 되어 마음이 상하다"}]'::jsonb, '[{"answer":true,"statement":"용왕은 토끼의 간이 약이라는 말을 들었어요."},{"answer":true,"statement":"토끼는 간을 나무에 걸어 두고 왔다고 거짓말했어요."},{"answer":false,"statement":"토끼는 결국 용왕에게 간을 내주었어요."}]'::jsonb, '{"choices":["용궁은 아주 편안한 곳이에요","위기의 순간에도 침착하게 생각하면 지혜롭게 벗어날 수 있어요","자라는 항상 토끼보다 똑똑해요","간은 몸에서 가장 중요하지 않은 부분이에요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"꾀다","choices":["크게 화를 내다","솔직하게 말하다","그럴듯한 말로 남을 속이거나 부추기다","조용히 기다리다"],"answerIndex":2},{"type":"vocab","word":"낙심하다","choices":["바라던 일이 안 되어 마음이 상하다","기쁘고 신나다","용감하고 씩씩하다","편안하고 여유롭다"],"answerIndex":0},{"type":"synonym","word":"둘러대다","choices":["실토하다","고백하다","털어놓다","얼버무리다"],"answerIndex":3},{"type":"antonym","word":"낙심하다","choices":["실망하다","희망을 얻다","좌절하다","포기하다"],"answerIndex":1},{"type":"spelling","word":"침착하다","choices":["침챡하다","침착히다","침착하다","침착나다"],"answerIndex":2}]'::jsonb, 133)
