insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('woodcutter-and-goblin-gold', '🪙', '나무꾼과 도깨비', '["가난한 나무꾼이 산에서 나무를 하다가 우연히 도깨비 무리를 마주쳤어요.","나무꾼은 겁이 났지만 침착하게 도깨비들에게 공손히 인사를 건넸어요.","도깨비들은 예의 바른 나무꾼이 마음에 들어 씨름 한 판을 제안했어요.","나무꾼은 도깨비의 약점이 왼쪽 다리라는 것을 눈치채고 그곳을 공략했어요.","나무꾼은 씨름에서 이겼고, 도깨비는 약속대로 금덩이를 잔뜩 선물로 주었어요.","나무꾼은 금덩이 중 일부를 가난한 이웃들과 아낌없이 나누어 주었어요.","이 소문을 들은 욕심 많은 다른 나무꾼이 일부러 도깨비를 찾아가 무례하게 굴었어요.","화가 난 도깨비들은 그 나무꾼을 혼내주고 아무것도 주지 않았답니다."]'::jsonb, '[{"word":"공손히","meaning":"예의 바르고 겸손하게"},{"word":"공략하다","meaning":"목표로 삼아 힘써 노력하다"},{"word":"무례하다","meaning":"예의가 없다"}]'::jsonb, '[{"answer":true,"statement":"나무꾼은 도깨비들에게 공손히 인사했어요."},{"answer":true,"statement":"나무꾼은 씨름에서 이겨 금덩이를 받았어요."},{"answer":false,"statement":"욕심 많은 나무꾼도 도깨비에게 좋은 선물을 받았어요."}]'::jsonb, '{"choices":["씨름은 아주 위험한 운동이에요","도깨비는 항상 나쁜 존재예요","예의 바르고 겸손한 태도는 좋은 인연을 만들어요","금덩이는 혼자 다 가져야 해요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"공손히","choices":["예의 바르고 겸손하게","거칠고 무례하게","급하고 다급하게","조용하고 차갑게"],"answerIndex":0},{"type":"vocab","word":"무례하다","choices":["부지런하다","성실하다","겸손하다","예의가 없다"],"answerIndex":3},{"type":"synonym","word":"공손히","choices":["거칠게","공경하게","무례하게","냉정하게"],"answerIndex":1},{"type":"antonym","word":"공손히","choices":["겸손하게","예의 바르게","무례하게","정중하게"],"answerIndex":2},{"type":"spelling","word":"저절로","choices":["저절로","저절노","저절러","저절료"],"answerIndex":0}]'::jsonb, 134)
