insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('little-mermaid-sea-voice', '🧜', '인어공주', '["깊은 바닷속 궁전에 사는 막내 인어공주는 늘 파도 위 세상을 궁금해했어요.","열다섯 살이 된 인어공주는 바다 위로 올라갔다가 폭풍우 속에서 배가 뒤집힌 왕자를 구해 주었어요.","인어공주는 왕자를 몰래 지켜보며 사랑에 빠지게 되었어요.","사람이 되고 싶었던 인어공주는 마녀를 찾아가 아름다운 목소리를 주고 다리를 얻었어요.","사람이 된 인어공주는 왕자 곁에서 지냈지만, 목소리가 없어 자신이 생명을 구해 준 사실을 말하지 못했어요.","왕자는 다른 나라의 공주를 자신을 구해 준 사람으로 오해해 결혼을 약속했어요.","인어공주는 슬펐지만 왕자의 행복을 진심으로 빌어 주며 조용히 물거품이 되기로 마음먹었어요.","인어공주의 따뜻한 마음은 바다의 요정들에게 전해져 영원히 기억되었답니다."]'::jsonb, '[{"word":"궁전","meaning":"임금이 사는 큰 집"},{"word":"오해하다","meaning":"잘못 알거나 잘못 생각하다"},{"word":"진심","meaning":"거짓이 없는 참된 마음"}]'::jsonb, '[{"answer":true,"statement":"인어공주는 폭풍우 속에서 왕자를 구해 주었어요."},{"answer":true,"statement":"인어공주는 목소리를 잃고 사람의 다리를 얻었어요."},{"answer":false,"statement":"왕자는 인어공주가 자신을 구해 준 것을 처음부터 알고 있었어요."}]'::jsonb, '{"choices":["바다에는 아무도 살지 않아요","목소리는 아무 쓸모가 없어요","왕자는 항상 진실만을 알아요","누군가를 진심으로 사랑하는 마음은 자신을 희생해서라도 상대의 행복을 바라게 해요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"궁전","choices":["작은 오두막","임금이 사는 큰 집","시끄러운 시장","좁은 골목"],"answerIndex":1},{"type":"vocab","word":"진심","choices":["거짓된 마음","화가 난 마음","거짓이 없는 참된 마음","무서운 마음"],"answerIndex":2},{"type":"synonym","word":"오해하다","choices":["잘못 알다","제대로 알다","정확히 알다","확실히 알다"],"answerIndex":0},{"type":"antonym","word":"오해하다","choices":["잘못 알다","헷갈리다","착각하다","제대로 이해하다"],"answerIndex":3},{"type":"spelling","word":"폭풍우","choices":["폭풍위","폭풍우","폭퐁우","폭풍유"],"answerIndex":1}]'::jsonb, 135)
