insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('cinderella-glass-slipper', '👠', '신데렐라', '["신데렐라는 새어머니와 새언니들 사이에서 온갖 힘든 집안일을 도맡아 했어요.","어느 날 성에서 왕자님이 신붓감을 찾는 큰 무도회가 열린다는 소식이 전해졌어요.","새어머니와 새언니들만 무도회에 가고, 신데렐라는 혼자 남아 눈물을 흘렸어요.","그때 마법사 요정이 나타나 호박을 마차로, 신데렐라의 옷을 아름다운 드레스로 바꾸어 주었어요.","요정은 \"자정이 지나면 마법이 풀린다\"고 신신당부하며 신데렐라를 무도회로 보내 주었어요.","무도회에서 왕자님은 신데렐라와 즐겁게 춤을 추며 첫눈에 사랑에 빠졌어요.","시계가 열두 번 울리자 신데렐라는 급히 도망치다 유리구두 한 짝을 계단에 흘렸어요.","왕자님은 그 유리구두의 주인을 찾아 온 나라를 돌아다녔고, 결국 신데렐라를 찾아내 결혼했답니다."]'::jsonb, '[{"word":"도맡다","meaning":"혼자서 책임을 지고 담당하다"},{"word":"신신당부하다","meaning":"여러 번 간곡히 부탁하다"},{"word":"첫눈에 반하다","meaning":"처음 보자마자 마음이 끌리다"}]'::jsonb, '[{"answer":true,"statement":"신데렐라는 새어머니와 새언니의 집안일을 도맡아 했어요."},{"answer":true,"statement":"신데렐라는 자정이 넘어 유리구두를 흘렸어요."},{"answer":false,"statement":"왕자님은 신데렐라의 새언니와 결혼했어요."}]'::jsonb, '{"choices":["어려운 상황에서도 착한 마음을 잃지 않으면 좋은 일이 찾아올 수 있어요","무도회는 항상 위험한 곳이에요","유리구두는 아주 약한 신발이에요","마법은 영원히 지속돼요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"도맡다","choices":["조금만 돕다","혼자서 책임을 지고 담당하다","전혀 하지 않다","다른 사람에게 미루다"],"answerIndex":1},{"type":"vocab","word":"첫눈에 반하다","choices":["오랫동안 지켜보고 판단하다","전혀 관심이 없다","처음 보자마자 마음이 끌리다","시간이 지나야 좋아지다"],"answerIndex":2},{"type":"synonym","word":"도맡다","choices":["미루다","나누다","떠넘기다","전담하다"],"answerIndex":3},{"type":"antonym","word":"도맡다","choices":["떠넘기다","미루다","전담하다","책임지다"],"answerIndex":0},{"type":"spelling","word":"신붓감","choices":["신부감","신붓감","신붇감","신부깜"],"answerIndex":1}]'::jsonb, 136)
