insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('snow-white-seven-dwarfs', '🍎', '백설공주', '["눈처럼 하얀 피부를 가진 백설공주는 못된 새어머니 왕비의 미움을 받았어요.","왕비는 마법 거울에게 \"세상에서 누가 가장 아름다우냐\"고 물었다가 백설공주라는 답을 듣고 화가 났어요.","왕비는 사냥꾼을 시켜 백설공주를 숲으로 데려가 없애라고 명령했어요.","사냥꾼은 차마 공주를 해치지 못하고 몰래 숲속에 숨겨 주었어요.","백설공주는 숲속을 헤매다 일곱 난쟁이의 작은 오두막을 발견하고 함께 살게 되었어요.","왕비는 마법 거울을 통해 백설공주가 살아 있음을 알고 독이 든 사과로 변장해 찾아갔어요.","독사과를 먹은 백설공주는 깊은 잠에 빠졌지만, 지나가던 왕자님의 도움으로 다시 깨어났어요.","백설공주는 일곱 난쟁이와 왕자님의 도움 덕분에 오래오래 행복하게 살았답니다."]'::jsonb, '[{"word":"미움","meaning":"밉게 여기는 마음"},{"word":"차마","meaning":"마음이 아파서 감히"},{"word":"변장하다","meaning":"다른 사람처럼 보이려고 모습을 바꾸다"}]'::jsonb, '[{"answer":true,"statement":"사냥꾼은 백설공주를 차마 해치지 못했어요."},{"answer":true,"statement":"백설공주는 일곱 난쟁이와 함께 살았어요."},{"answer":false,"statement":"왕비는 백설공주를 진심으로 아꼈어요."}]'::jsonb, '{"choices":["거울은 언제나 진실만 말해요","질투와 욕심은 결국 스스로를 불행하게 만들 수 있어요","숲속에서는 아무도 살 수 없어요","사과는 항상 위험한 과일이에요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"미움","choices":["아끼는 마음","좋아하는 마음","밉게 여기는 마음","반가운 마음"],"answerIndex":2},{"type":"vocab","word":"변장하다","choices":["다른 사람처럼 보이려고 모습을 바꾸다","솔직하게 밝히다","그대로 나타나다","숨김없이 드러내다"],"answerIndex":0},{"type":"synonym","word":"미움","choices":["사랑","애정","호감","증오"],"answerIndex":3},{"type":"antonym","word":"미움","choices":["증오","사랑","혐오","질투"],"answerIndex":1},{"type":"spelling","word":"오두막","choices":["오두막","오두박","오뚜막","오두먁"],"answerIndex":0}]'::jsonb, 137)
