insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('sleeping-beauty-spindle', '🌹', '잠자는 숲속의 공주', '["오랫동안 아이가 없던 왕과 왕비에게 마침내 예쁜 공주가 태어났어요.","공주의 탄생을 축하하는 잔치에 초대받지 못한 마녀가 화가 나서 저주를 걸었어요.","\"공주는 열여섯 살이 되는 해에 물레 바늘에 찔려 깊은 잠에 빠질 것이다.\"","다행히 착한 요정이 저주를 완전히 막을 순 없었지만 \"백 년 뒤 왕자의 입맞춤으로 깨어날 것\"이라고 바꾸어 주었어요.","왕은 나라 안의 물레를 모두 없앴지만, 공주는 열여섯 살 생일에 숨겨진 물레를 찾아 손가락을 찔리고 말았어요.","공주가 잠들자 성 전체가 백 년 동안 깊은 잠에 빠졌고, 성 주위에는 가시덤불이 무성하게 자랐어요.","백 년이 지난 뒤, 이야기를 들은 한 왕자가 가시덤불을 헤치고 성 안으로 들어갔어요.","왕자가 공주에게 다가가자 저주가 풀리며 공주와 성 전체가 다시 깨어났답니다."]'::jsonb, '[{"word":"저주","meaning":"남에게 재앙이나 불행이 일어나도록 비는 것"},{"word":"무성하다","meaning":"풀이나 나무가 우거지다"},{"word":"헤치다","meaning":"방해되는 것을 물리치다"}]'::jsonb, '[{"answer":true,"statement":"마녀는 잔치에 초대받지 못해 화가 났어요."},{"answer":true,"statement":"공주는 물레 바늘에 찔려 깊은 잠에 빠졌어요."},{"answer":false,"statement":"왕자는 성에 들어가지 못하고 돌아갔어요."}]'::jsonb, '{"choices":["어려운 저주 속에서도 희망을 잃지 않으면 좋은 결말을 맞을 수 있어요","물레는 아주 안전한 도구예요","잔치에는 모두를 초대할 필요가 없어요","가시덤불은 아무도 지나갈 수 없어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"저주","choices":["축하하는 마음","남에게 재앙이나 불행이 일어나도록 비는 것","기쁜 소식","따뜻한 인사"],"answerIndex":1},{"type":"vocab","word":"헤치다","choices":["가만히 두다","피해서 돌아가다","그대로 멈추다","방해되는 것을 물리치다"],"answerIndex":3},{"type":"synonym","word":"무성하다","choices":["듬성하다","메마르다","우거지다","앙상하다"],"answerIndex":2},{"type":"antonym","word":"무성하다","choices":["앙상하다","우거지다","빽빽하다","울창하다"],"answerIndex":0},{"type":"spelling","word":"가시덤불","choices":["가시덩불","가시덤불","가시덤블","가시덩블"],"answerIndex":1}]'::jsonb, 138)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('ugly-duckling-swan', '🦢', '미운 오리 새끼', '["오리 마을에서 태어난 한 새끼는 다른 오리들과 생김새가 달라 놀림을 받았어요.","형제들과 마을 오리들은 \"미운 오리 새끼\"라고 부르며 함께 놀아 주지 않았어요.","슬퍼진 새끼 오리는 마을을 떠나 홀로 넓은 세상을 떠돌아다녔어요.","추운 겨울, 새끼 오리는 먹을 것도 없이 힘겹게 눈밭에서 겨울을 견뎌 냈어요.","봄이 되자 새끼 오리는 우연히 호수에 사는 아름다운 백조들을 만났어요.","백조들은 새끼 오리를 반갑게 맞아 주었고, 새끼 오리는 어리둥절했어요.","물에 비친 자신의 모습을 본 새끼 오리는 자신이 사실 아름다운 백조였다는 것을 깨달았어요.","미운 오리 새끼는 마침내 자신의 진짜 모습을 찾고 백조들과 행복하게 살았답니다."]'::jsonb, '[{"word":"떠돌다","meaning":"정처 없이 이곳저곳 돌아다니다"},{"word":"견디다","meaning":"힘든 것을 참고 버티다"},{"word":"어리둥절하다","meaning":"무슨 일인지 몰라 얼떨떨하다"}]'::jsonb, '[{"answer":true,"statement":"새끼 오리는 다른 오리들에게 놀림을 받았어요."},{"answer":true,"statement":"새끼 오리는 사실 백조였다는 것을 깨달았어요."},{"answer":false,"statement":"새끼 오리는 처음부터 자신이 백조인 것을 알고 있었어요."}]'::jsonb, '{"choices":["겉모습이 다르면 함께 지낼 수 없어요","겨울에는 아무것도 견딜 수 없어요","지금 힘들고 다르게 보여도 자신만의 진짜 모습과 가치는 따로 있어요","호수에는 백조만 살아야 해요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"떠돌다","choices":["한곳에 머무르다","정처 없이 이곳저곳 돌아다니다","깊이 잠들다","크게 소리치다"],"answerIndex":1},{"type":"vocab","word":"어리둥절하다","choices":["무슨 일인지 몰라 얼떨떨하다","아주 확신에 차다","화가 나서 씩씩거리다","기쁘고 즐겁다"],"answerIndex":0},{"type":"synonym","word":"견디다","choices":["포기하다","무너지다","도망치다","버티다"],"answerIndex":3},{"type":"antonym","word":"견디다","choices":["버티다","참다","이겨내다","포기하다"],"answerIndex":2},{"type":"spelling","word":"어리둥절하다","choices":["어리둥졀하다","어리둥절하다","어리둥절이다","어리둥절다"],"answerIndex":1}]'::jsonb, 139)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('match-girl-cold-winter-night', '🕯️', '성냥팔이 소녀', '["추운 겨울밤, 가난한 소녀가 맨발로 거리에서 성냥을 팔고 있었어요.","지나가는 사람들은 아무도 소녀의 성냥을 사 주지 않았고, 소녀는 추위에 몸이 꽁꽁 얼었어요.","너무 추운 나머지 소녀는 몸을 녹이려고 성냥 한 개비를 그어 보았어요.","성냥불이 반짝이자 따뜻한 난로와 맛있는 음식이 보이는 것 같았어요.","소녀는 하나씩 성냥을 더 그으며 즐거웠던 옛날과 다정했던 할머니의 모습을 떠올렸어요.","마지막 성냥을 긋자 환하게 웃는 할머니가 나타나 소녀를 따뜻하게 품에 안아 주었어요.","다음 날 아침, 사람들은 성냥이 가득한 채로 편안하게 미소 짓고 있는 소녀를 발견했어요.","이 이야기는 주위의 어려운 이웃을 따뜻하게 보살피는 마음이 얼마나 소중한지 전해 준답니다."]'::jsonb, '[{"word":"개비","meaning":"가늘고 짤막하게 쪼갠 나뭇조각을 세는 단위"},{"word":"그어 보다","meaning":"성냥 등을 문질러 불을 붙이다"},{"word":"보살피다","meaning":"정성을 기울여 보호하며 돌보다"}]'::jsonb, '[{"answer":true,"statement":"소녀는 추운 겨울밤 거리에서 성냥을 팔았어요."},{"answer":true,"statement":"소녀는 성냥불을 켤 때마다 따뜻한 장면을 떠올렸어요."},{"answer":false,"statement":"지나가는 사람들이 소녀의 성냥을 모두 사 주었어요."}]'::jsonb, '{"choices":["성냥은 겨울에만 필요한 물건이에요","우리 주변의 어려운 이웃을 따뜻하게 보살피는 마음이 필요해요","할머니는 항상 무서운 존재예요","혼자 힘으로 모든 것을 해결해야 해요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"개비","choices":["커다란 나무 기둥","깊은 강물","가늘고 짤막하게 쪼갠 나뭇조각을 세는 단위","넓은 들판"],"answerIndex":2},{"type":"vocab","word":"보살피다","choices":["정성을 기울여 보호하며 돌보다","모르는 척 지나치다","심하게 나무라다","멀리 쫓아내다"],"answerIndex":0},{"type":"synonym","word":"보살피다","choices":["방치하다","외면하다","무시하다","돌보다"],"answerIndex":3},{"type":"antonym","word":"보살피다","choices":["돌보다","방치하다","챙기다","살피다"],"answerIndex":1},{"type":"spelling","word":"따뜻하다","choices":["따듯하다","따뜩하다","따뜻하다","땃뜻하다"],"answerIndex":2}]'::jsonb, 140)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('red-riding-hood-grandma-wolf', '🐺', '빨간 모자', '["빨간 모자를 즐겨 쓰는 소녀가 아픈 할머니께 드릴 과자 바구니를 들고 숲길을 나섰어요.","엄마는 \"숲길에서 절대 곁길로 새지 말라\"고 신신당부했어요.","숲에서 늑대를 만난 소녀는 아무것도 모른 채 할머니 댁의 위치를 친절하게 알려주고 말았어요.","늑대는 재빨리 할머니 댁으로 달려가 할머니를 숨기고 대신 침대에 누워 있었어요.","소녀는 할머니의 목소리와 모습이 이상하다고 느꼈지만 늑대에게 속아 가까이 다가갔어요.","늑대가 소녀를 해치려는 순간, 지나가던 사냥꾼이 이상한 소리를 듣고 재빨리 뛰어들어왔어요.","사냥꾼은 늑대를 물리치고 무사히 할머니와 소녀를 구해 주었어요.","그 뒤로 소녀는 낯선 이를 함부로 믿지 않고 엄마의 말씀을 잘 새겨듣게 되었답니다."]'::jsonb, '[{"word":"곁길로 새다","meaning":"원래 가야 할 길에서 벗어나다"},{"word":"해치다","meaning":"다치게 하거나 목숨을 빼앗다"},{"word":"새겨듣다","meaning":"잊지 않도록 마음에 깊이 기억하다"}]'::jsonb, '[{"answer":true,"statement":"소녀는 늑대에게 할머니 댁의 위치를 알려주었어요."},{"answer":true,"statement":"사냥꾼이 나타나 소녀와 할머니를 구해 주었어요."},{"answer":false,"statement":"소녀는 처음부터 늑대가 할머니가 아님을 확신했어요."}]'::jsonb, '{"choices":["숲길은 항상 안전해요","할머니는 늑대를 아주 좋아해요","과자 바구니는 무거우면 안 돼요","낯선 상대를 함부로 믿기보다 조심하는 태도가 필요해요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"곁길로 새다","choices":["원래 가야 할 길에서 벗어나다","목적지에 정확히 도착하다","서둘러 집으로 돌아가다","길을 새로 만들다"],"answerIndex":0},{"type":"vocab","word":"새겨듣다","choices":["듣고 바로 잊어버리다","잊지 않도록 마음에 깊이 기억하다","전혀 듣지 않다","건성으로 듣다"],"answerIndex":1},{"type":"synonym","word":"해치다","choices":["보호하다","돌보다","다치게 하다","살리다"],"answerIndex":2},{"type":"antonym","word":"해치다","choices":["보호하다","다치게 하다","공격하다","위협하다"],"answerIndex":0},{"type":"spelling","word":"낯선","choices":["낫선","낳선","낟선","낯선"],"answerIndex":3}]'::jsonb, 141)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('hansel-gretel-candy-house', '🍬', '헨젤과 그레텔', '["가난한 나무꾼의 남매 헨젤과 그레텔은 숲속에 버려지고 말았어요.","남매는 배가 고픈 채 숲을 헤매다가 과자와 사탕으로 만들어진 신기한 집을 발견했어요.","집 안에는 아이들을 잡아먹으려는 못된 마녀가 숨어 살고 있었어요.","마녀는 남매를 가두고 헨젤을 살찌워 잡아먹으려 했어요.","눈이 나쁜 마녀를 속이려고 헨젤은 뼈다귀를 내밀며 손가락이라고 거짓말했어요.","어느 날 마녀가 화덕을 확인하라고 하자, 그레텔은 꾀를 내어 마녀를 화덕 속으로 밀어 넣었어요.","남매는 마녀의 집에 있던 보물을 챙겨 무사히 집으로 돌아왔어요.","아버지와 다시 만난 남매는 서로 도우며 어려움을 이겨낸 것을 자랑스러워했답니다."]'::jsonb, '[{"word":"헤매다","meaning":"길을 잃고 이리저리 돌아다니다"},{"word":"살찌우다","meaning":"살이 찌게 하다"},{"word":"꾀를 내다","meaning":"어려운 상황을 벗어날 방법을 생각해 내다"}]'::jsonb, '[{"answer":true,"statement":"남매는 과자로 만든 집을 발견했어요."},{"answer":true,"statement":"그레텔은 꾀를 내어 마녀를 물리쳤어요."},{"answer":false,"statement":"마녀는 남매에게 처음부터 친절했어요."}]'::jsonb, '{"choices":["위험한 상황에서도 서로 도우며 지혜를 모으면 어려움을 이겨낼 수 있어요","숲속의 집은 모두 안전해요","낯선 음식은 무엇이든 먹어도 괜찮아요","혼자 해결하는 것이 가장 좋은 방법이에요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"헤매다","choices":["목적지로 곧장 가다","길을 잃고 이리저리 돌아다니다","편안하게 잠들다","빠르게 뛰어가다"],"answerIndex":1},{"type":"vocab","word":"꾀를 내다","choices":["아무 생각 없이 행동하다","크게 소리를 지르다","조용히 숨어 있다","어려운 상황을 벗어날 방법을 생각해 내다"],"answerIndex":3},{"type":"synonym","word":"헤매다","choices":["곧장 가다","도착하다","방황하다","머무르다"],"answerIndex":2},{"type":"antonym","word":"헤매다","choices":["곧장 가다","방황하다","떠돌다","서성이다"],"answerIndex":0},{"type":"spelling","word":"화덕","choices":["화덬","화덕","화덕이","황덕"],"answerIndex":1}]'::jsonb, 142)
