insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('rapunzel-tower-long-hair', '🗼', '라푼젤', '["마녀는 아름다운 소녀 라푼젤을 높은 탑에 가두고 아무도 만나지 못하게 했어요.","라푼젤의 머리카락은 아주 길게 자랐고, 마녀는 그 머리카락을 밟고 탑을 오르내렸어요.","탑 아래를 지나던 왕자는 라푼젤이 부르는 아름다운 노랫소리를 듣게 되었어요.","왕자는 마녀처럼 \"라푼젤, 머리카락을 내려 줘\"라고 외쳐 탑 위로 올라갔어요.","라푼젤과 왕자는 서로 이야기를 나누며 친구가 되었고, 둘은 자주 만나게 되었어요.","이 사실을 안 마녀는 크게 화가 나서 라푼젤을 먼 곳으로 쫓아내 버렸어요.","왕자는 라푼젤을 찾아 오랫동안 헤매다가 결국 다시 만나게 되었어요.","라푼젤과 왕자는 갇혀 있던 탑을 벗어나 넓은 세상에서 자유롭고 행복하게 살았답니다."]'::jsonb, '[{"word":"가두다","meaning":"밖으로 나오지 못하게 안에 두다"},{"word":"밟다","meaning":"발을 대고 누르다"},{"word":"자유롭다","meaning":"무엇에도 얽매이지 않고 자기 뜻대로 할 수 있다"}]'::jsonb, '[{"answer":true,"statement":"라푼젤의 머리카락은 아주 길게 자랐어요."},{"answer":true,"statement":"왕자는 라푼젤의 노랫소리를 듣고 탑에 오게 되었어요."},{"answer":false,"statement":"마녀는 왕자와 라푼젤의 만남을 처음부터 좋아했어요."}]'::jsonb, '{"choices":["머리카락은 절대 길게 기르면 안 돼요","탑 위에서 사는 것이 가장 안전해요","진정한 자유와 행복은 서로를 믿고 함께할 때 찾아와요","노래는 위험한 사람을 부르는 신호예요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"가두다","choices":["밖으로 나오지 못하게 안에 두다","자유롭게 풀어 주다","멀리 떠나보내다","크게 반겨 맞다"],"answerIndex":0},{"type":"vocab","word":"자유롭다","choices":["갇혀서 답답하다","무엇에도 얽매이지 않고 자기 뜻대로 할 수 있다","무섭고 두렵다","조용하고 쓸쓸하다"],"answerIndex":1},{"type":"synonym","word":"자유롭다","choices":["구속되다","갇히다","억눌리다","홀가분하다"],"answerIndex":3},{"type":"antonym","word":"자유롭다","choices":["홀가분하다","벗어나다","구속되다","풀려나다"],"answerIndex":2},{"type":"spelling","word":"얽매이다","choices":["얽매이다","얽메이다","얼매이다","얽매히다"],"answerIndex":0}]'::jsonb, 143)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('pinocchio-nose-grows-lying', '🤥', '피노키오', '["늙은 목수 제페토 할아버지는 나무로 인형을 만들어 피노키오라는 이름을 붙였어요.","어느 날 요정이 나타나 피노키오에게 생명을 불어넣어 진짜 아이처럼 움직이게 해 주었어요.","요정은 \"거짓말을 하면 코가 길어질 것\"이라고 피노키오에게 알려주었어요.","피노키오는 학교에 가지 않고 놀이만 하려고 여러 번 거짓말을 했고, 그때마다 코가 쑥쑥 길어졌어요.","나쁜 친구들의 꾐에 빠져 피노키오는 엉뚱한 곳에서 방황하며 제페토 할아버지를 걱정시켰어요.","자신을 찾아 나선 제페토 할아버지가 큰 고래에게 잡아먹혔다는 소식을 들은 피노키오는 크게 뉘우쳤어요.","피노키오는 용기를 내어 고래의 배 속으로 들어가 할아버지를 무사히 구해 냈어요.","정직하고 용감해진 피노키오는 마침내 진짜 사람 아이가 되었답니다."]'::jsonb, '[{"word":"불어넣다","meaning":"어떤 기운이나 생각을 상대에게 가지게 하다"},{"word":"꾐","meaning":"그럴듯한 말로 남을 속이거나 부추기는 일"},{"word":"방황하다","meaning":"정한 방향 없이 이리저리 헤매다"}]'::jsonb, '[{"answer":true,"statement":"피노키오는 거짓말을 하면 코가 길어졌어요."},{"answer":true,"statement":"피노키오는 고래의 배 속에서 할아버지를 구했어요."},{"answer":false,"statement":"피노키오는 처음부터 정직하고 용감한 아이였어요."}]'::jsonb, '{"choices":["나무 인형은 절대 사람이 될 수 없어요","정직함과 용기를 배워 가면 진정한 성장을 이룰 수 있어요","학교에는 가지 않아도 괜찮아요","고래는 항상 무서운 존재예요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"불어넣다","choices":["빼앗아 가다","억지로 감추다","어떤 기운이나 생각을 상대에게 가지게 하다","조용히 숨기다"],"answerIndex":2},{"type":"vocab","word":"방황하다","choices":["정한 방향 없이 이리저리 헤매다","목표를 향해 곧장 나아가다","한곳에 가만히 머무르다","계획대로 착실히 지내다"],"answerIndex":0},{"type":"synonym","word":"꾐","choices":["충고","경고","조언","유혹"],"answerIndex":3},{"type":"antonym","word":"방황하다","choices":["헤매다","정착하다","떠돌다","서성이다"],"answerIndex":1},{"type":"spelling","word":"뉘우치다","choices":["뉘우치다","뉘웃치다","뉘웇치다","뉘웆치다"],"answerIndex":0}]'::jsonb, 144)
