insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('aladdin-magic-lamp-genie', '🪔', '알라딘', '["가난한 청년 알라딘은 우연히 마법사를 도와 동굴 속 오래된 램프를 가져오게 되었어요.","알라딘이 램프를 문지르자 커다란 지니가 나타나 무엇이든 소원을 들어주겠다고 했어요.","알라딘은 지니의 도움으로 멋진 궁전과 보물을 얻어 공주와 결혼까지 하게 되었어요.","하지만 램프의 비밀을 안 사악한 마법사가 램프를 몰래 훔쳐 가 버렸어요.","마법사는 램프의 힘으로 알라딘의 궁전과 공주를 먼 사막으로 옮겨 버렸어요.","알라딘은 포기하지 않고 지혜를 짜내 마법사를 찾아 나섰어요.","알라딘은 꾀를 내어 램프를 다시 되찾고 사악한 마법사를 물리쳤어요.","알라딘은 공주와 함께 궁전으로 돌아와 예전처럼 행복하게 살았답니다."]'::jsonb, '[{"word":"문지르다","meaning":"무엇을 서로 대고 밀거나 비비다"},{"word":"사악하다","meaning":"마음이 몹시 악하다"},{"word":"지혜를 짜내다","meaning":"어려운 문제를 풀기 위해 깊이 생각해 내다"}]'::jsonb, '[{"answer":true,"statement":"알라딘은 램프를 문질러 지니를 불러냈어요."},{"answer":true,"statement":"사악한 마법사가 램프를 몰래 훔쳐 갔어요."},{"answer":false,"statement":"알라딘은 궁전을 되찾는 것을 포기했어요."}]'::jsonb, '{"choices":["램프는 아무나 가질 수 있어요","마법사는 항상 좋은 사람이에요","궁전이 없으면 절대 행복할 수 없어요","어려운 상황에서도 포기하지 않고 지혜를 모으면 되찾을 수 있어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"문지르다","choices":["멀리 던지다","무엇을 서로 대고 밀거나 비비다","가만히 놓아두다","크게 두드리다"],"answerIndex":1},{"type":"vocab","word":"사악하다","choices":["마음이 몹시 악하다","마음이 매우 착하다","용기가 넘치다","솔직하고 정직하다"],"answerIndex":0},{"type":"synonym","word":"사악하다","choices":["선하다","자비롭다","악랄하다","너그럽다"],"answerIndex":2},{"type":"antonym","word":"사악하다","choices":["악랄하다","흉악하다","못되다","선량하다"],"answerIndex":3},{"type":"spelling","word":"예전처럼","choices":["옛전처럼","예전처럼","옛저처럼","예젼처럼"],"answerIndex":1}]'::jsonb, 145)
