insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('ant-and-grasshopper-winter', '🐜', '개미와 베짱이', '["여름 내내 개미들은 땀을 흘리며 부지런히 먹이를 모아 곳간에 쌓았어요.","베짱이는 시원한 나무 그늘에서 노래만 부르며 개미들을 게으르다고 놀렸어요.","\"왜 그렇게 힘들게 일해? 여름은 즐기라고 있는 계절이야!\"","개미들은 베짱이의 말에도 흔들리지 않고 묵묵히 겨울을 준비했어요.","어느덧 차가운 겨울이 찾아왔고, 먹을 것을 하나도 준비하지 못한 베짱이는 배가 고파졌어요.","베짱이는 추위에 떨며 개미네 집을 찾아가 문을 두드렸어요.","개미들은 지난 여름의 일을 떠올리며 잠시 망설였지만, 결국 따뜻하게 베짱이를 맞아 주었어요.","베짱이는 크게 뉘우치고 다음 해부터는 개미들과 함께 부지런히 일했답니다."]'::jsonb, '[{"word":"묵묵히","meaning":"말없이 잠잠하게"},{"word":"망설이다","meaning":"이리저리 생각만 하고 태도를 정하지 못하다"},{"word":"뉘우치다","meaning":"잘못을 깨닫고 반성하다"}]'::jsonb, '[{"answer":true,"statement":"개미들은 여름 내내 부지런히 먹이를 모았어요."},{"answer":true,"statement":"베짱이는 겨울에 먹을 것이 없어 힘들어했어요."},{"answer":false,"statement":"개미들은 베짱이를 끝까지 매몰차게 내쫓았어요."}]'::jsonb, '{"choices":["미리 준비하는 부지런함은 어려운 때에 큰 힘이 돼요","노래는 겨울에 불러야 더 즐거워요","개미는 절대 남을 도와주지 않아요","여름에는 아무 일도 하지 않아야 해요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"묵묵히","choices":["시끄럽게 떠들며","말없이 잠잠하게","급하게 서두르며","크게 자랑하며"],"answerIndex":1},{"type":"vocab","word":"망설이다","choices":["곧바로 결정하다","확신에 차 행동하다","빠르게 달려가다","이리저리 생각만 하고 태도를 정하지 못하다"],"answerIndex":3},{"type":"synonym","word":"망설이다","choices":["결단하다","확신하다","주저하다","단행하다"],"answerIndex":2},{"type":"antonym","word":"망설이다","choices":["결단하다","주저하다","머뭇거리다","고민하다"],"answerIndex":0},{"type":"spelling","word":"묵묵히","choices":["묵묵이","묵묵히","묵묶이","묵묶히"],"answerIndex":1}]'::jsonb, 146)
