insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('rabbit-and-turtle-race', '🐢', '토끼와 거북이', '["발이 빠른 토끼는 느림보 거북이를 만날 때마다 늘 놀리곤 했어요.","화가 난 거북이는 토끼에게 산꼭대기까지 달리기 경주를 하자고 제안했어요.","경주가 시작되자 토끼는 순식간에 저만치 앞서 나갔어요.","여유만만해진 토끼는 \"거북이가 오려면 한참 걸릴 테니 잠깐 낮잠이나 자자\"며 나무 그늘에 누웠어요.","거북이는 쉬지 않고 느리지만 꾸준하게 한 걸음씩 앞으로 나아갔어요.","토끼가 낮잠에서 깨어났을 때, 거북이는 이미 결승선 가까이에 도착해 있었어요.","토끼는 있는 힘껏 달렸지만 이미 늦어 버렸고, 거북이가 먼저 산꼭대기에 도착했어요.","자만했던 토끼는 크게 부끄러워하며 꾸준함의 소중함을 깨달았답니다."]'::jsonb, '[{"word":"여유만만하다","meaning":"걱정 없이 아주 넉넉하고 태연하다"},{"word":"꾸준하다","meaning":"한결같이 부지런하고 끈기가 있다"},{"word":"자만하다","meaning":"자신을 스스로 뽐내며 잘난 체하다"}]'::jsonb, '[{"answer":true,"statement":"토끼는 경주 중에 낮잠을 잤어요."},{"answer":true,"statement":"거북이는 쉬지 않고 꾸준히 걸어갔어요."},{"answer":false,"statement":"토끼는 낮잠에서 깬 뒤에도 여유롭게 걸어서 이겼어요."}]'::jsonb, '{"choices":["빠른 것이 항상 느린 것보다 좋아요","꾸준하고 성실한 노력은 재능이나 자만을 이길 수 있어요","낮잠은 경주 중에 꼭 필요해요","산꼭대기까지는 아무도 갈 수 없어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"여유만만하다","choices":["몹시 다급해하다","불안해서 떨다","걱정 없이 아주 넉넉하고 태연하다","화가 나서 씩씩거리다"],"answerIndex":2},{"type":"vocab","word":"자만하다","choices":["자신을 스스로 뽐내며 잘난 체하다","자신을 낮추고 겸손해하다","남을 돕고 배려하다","조용히 자신을 반성하다"],"answerIndex":0},{"type":"synonym","word":"꾸준하다","choices":["변덕스럽다","게으르다","성급하다","한결같다"],"answerIndex":3},{"type":"antonym","word":"꾸준하다","choices":["한결같다","변덕스럽다","끈기있다","성실하다"],"answerIndex":1},{"type":"spelling","word":"결승선","choices":["결승선","결승썬","결승신","결승산"],"answerIndex":0}]'::jsonb, 147)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('three-little-pigs-houses', '🐷', '아기 돼지 삼형제', '["엄마 돼지는 세 아기 돼지에게 각자 튼튼한 집을 짓고 독립하라고 말했어요.","첫째 돼지는 귀찮아서 짚으로 대충 집을 지었고, 둘째 돼지는 나뭇가지로 집을 지었어요.","막내 돼지는 시간이 오래 걸려도 벽돌로 튼튼하게 집을 지었어요.","배고픈 늑대가 나타나 첫째 돼지의 짚 집을 훅 불어 단숨에 무너뜨렸어요.","놀란 첫째는 둘째의 나무 집으로 도망쳤지만, 늑대는 그 집마저 부수어 버렸어요.","두 형은 막내의 벽돌집으로 급히 도망쳤고, 늑대가 아무리 불어도 집은 끄떡없었어요.","화가 난 늑대가 굴뚝으로 몰래 들어오려 하자, 막내는 미리 끓여 둔 물을 준비해 놓고 있었어요.","놀란 늑대는 혼비백산 도망쳤고, 삼형제는 튼튼한 벽돌집에서 오래오래 안전하게 살았답니다."]'::jsonb, '[{"word":"독립하다","meaning":"스스로의 힘으로 살아가다"},{"word":"끄떡없다","meaning":"아무 탈이나 문제가 없다"},{"word":"혼비백산하다","meaning":"몹시 놀라 넋을 잃다"}]'::jsonb, '[{"answer":true,"statement":"막내 돼지는 벽돌로 튼튼한 집을 지었어요."},{"answer":true,"statement":"늑대는 짚 집과 나무 집을 무너뜨렸어요."},{"answer":false,"statement":"늑대는 벽돌집도 쉽게 무너뜨렸어요."}]'::jsonb, '{"choices":["집은 빨리 짓는 것이 가장 중요해요","늑대는 항상 굴뚝으로만 다녀요","성실하게 튼튼히 준비하면 위기가 와도 잘 이겨낼 수 있어요","형제는 서로 도와주면 안 돼요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"독립하다","choices":["스스로의 힘으로 살아가다","누군가에게 계속 의지하다","다른 사람을 따라 하다","한곳에 가만히 머무르다"],"answerIndex":0},{"type":"vocab","word":"혼비백산하다","choices":["아주 편안해하다","기쁘게 웃다","차분하게 생각하다","몹시 놀라 넋을 잃다"],"answerIndex":3},{"type":"synonym","word":"끄떡없다","choices":["위태롭다","멀쩡하다","무너지다","약하다"],"answerIndex":1},{"type":"antonym","word":"끄떡없다","choices":["멀쩡하다","튼튼하다","위태롭다","안전하다"],"answerIndex":2},{"type":"spelling","word":"튼튼하다","choices":["튼튼하다","틍튼하다","튼툰하다","튼뚠하다"],"answerIndex":0}]'::jsonb, 148)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('shepherd-boy-cries-wolf', '🐑', '양치기 소년', '["산에서 양을 치는 소년은 하루하루가 너무 심심해서 견딜 수가 없었어요.","소년은 장난삼아 \"늑대가 나타났어요!\"라고 마을 사람들에게 거짓으로 소리쳤어요.","놀란 마을 사람들이 부리나케 달려왔지만, 늑대는 어디에도 없었어요.","소년은 사람들이 헐레벌떡 뛰어오는 모습이 재미있어서 같은 장난을 또다시 쳤어요.","몇 번이나 거짓말이 반복되자 마을 사람들은 점점 소년의 말을 믿지 않게 되었어요.","그러던 어느 날, 진짜로 늑대 떼가 나타나 양들을 위협했어요.","소년은 있는 힘껏 \"늑대가 나타났어요! 진짜예요!\"라고 외쳤지만 아무도 오지 않았어요.","결국 양들은 늑대에게 크게 해를 입었고, 소년은 거짓말의 대가를 뼈저리게 깨달았답니다."]'::jsonb, '[{"word":"부리나케","meaning":"매우 서둘러서 급히"},{"word":"헐레벌떡","meaning":"숨을 가쁘고 거칠게 몰아쉬는 모양"},{"word":"대가","meaning":"어떤 일의 결과로 치르는 값"}]'::jsonb, '[{"answer":true,"statement":"소년은 거짓으로 늑대가 나타났다고 소리쳤어요."},{"answer":true,"statement":"진짜 늑대가 나타났을 때 아무도 오지 않았어요."},{"answer":false,"statement":"마을 사람들은 소년의 거짓말을 끝까지 믿어 주었어요."}]'::jsonb, '{"choices":["거짓말을 반복하면 정작 중요한 순간에 아무도 믿어 주지 않아요","양치기는 늘 심심한 직업이에요","늑대는 절대 나타나지 않아요","장난은 아무리 쳐도 문제가 되지 않아요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"부리나케","choices":["아주 천천히","매우 서둘러서 급히","조용하고 차분하게","가만히 머물러서"],"answerIndex":1},{"type":"vocab","word":"대가","choices":["기쁜 소식","즐거운 놀이","편안한 휴식","어떤 일의 결과로 치르는 값"],"answerIndex":3},{"type":"synonym","word":"부리나케","choices":["느긋하게","천천히","황급히","여유롭게"],"answerIndex":2},{"type":"antonym","word":"부리나케","choices":["느긋하게","황급히","서둘러","급하게"],"answerIndex":0},{"type":"spelling","word":"헐레벌떡","choices":["헐레벌덕","헐레벌떡","헐래벌떡","헐레벌떨"],"answerIndex":1}]'::jsonb, 149)
