insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('fox-and-sour-grapes', '🦊', '여우와 신 포도', '["배고픈 여우가 숲을 걷다가 높은 나뭇가지에 탐스럽게 열린 포도송이를 발견했어요.","여우는 침을 삼키며 포도를 따 먹으려고 힘껏 뛰어올랐어요.","아무리 뛰어올라도 포도는 손이 닿지 않을 만큼 높이 매달려 있었어요.","여우는 몇 번이나 다시 도전했지만 결국 포도를 따는 데 실패하고 말았어요.","지친 여우는 포기하며 \"저 포도는 분명 시고 맛없을 거야\"라며 중얼거렸어요.","여우는 애써 실망을 감추며 아무렇지 않은 척 자리를 떠났어요.","사실 여우는 포도의 맛을 보지도 못했지만 스스로를 위로하려고 그런 핑계를 댄 것이었어요.","이 이야기는 갖지 못한 것을 애써 나쁘게 말하는 태도를 돌아보게 해 준답니다."]'::jsonb, '[{"word":"탐스럽다","meaning":"가지거나 차지하고 싶은 마음이 들 정도로 보기 좋다"},{"word":"중얼거리다","meaning":"낮은 목소리로 혼잣말을 하다"},{"word":"핑계","meaning":"잘못이나 부족한 것을 그럴듯하게 둘러대는 변명"}]'::jsonb, '[{"answer":true,"statement":"여우는 높은 나뭇가지의 포도를 따려고 했어요."},{"answer":true,"statement":"여우는 결국 포도를 따는 데 실패했어요."},{"answer":false,"statement":"여우는 포도를 맛보고 시다는 것을 확인했어요."}]'::jsonb, '{"choices":["포도는 항상 신맛이 나요","가지지 못한 것을 억지로 나쁘게 말하며 자신을 위로하려는 태도를 돌아볼 필요가 있어요","여우는 절대 뛰어오를 수 없어요","실패하면 다시는 도전하면 안 돼요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"탐스럽다","choices":["초라하고 볼품없다","작고 하찮다","가지거나 차지하고 싶은 마음이 들 정도로 보기 좋다","무섭고 위협적이다"],"answerIndex":2},{"type":"vocab","word":"핑계","choices":["잘못이나 부족한 것을 그럴듯하게 둘러대는 변명","솔직한 고백","분명한 사실","따뜻한 위로"],"answerIndex":0},{"type":"synonym","word":"중얼거리다","choices":["크게 외치다","침묵하다","노래하다","혼잣말하다"],"answerIndex":3},{"type":"antonym","word":"탐스럽다","choices":["먹음직스럽다","초라하다","먹음직하다","먹고 싶다"],"answerIndex":1},{"type":"spelling","word":"아무렇지 않다","choices":["아무렇지 않다","아무렇찮다","아무럿지 않다","아뭏지 않다"],"answerIndex":0}]'::jsonb, 150)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('bremen-town-musicians', '🎶', '브레멘 음악대', '["늙어서 쓸모없다는 이유로 쫓겨난 당나귀는 브레멘으로 가서 음악가가 되기로 마음먹었어요.","길을 가던 당나귀는 마찬가지로 버림받은 개, 고양이, 수탉을 차례로 만나 함께 길을 나섰어요.","네 친구는 서로 의지하며 브레멘을 향해 걸어가다가 날이 저물어 숲에서 불빛을 발견했어요.","불빛이 켜진 오두막에는 도둑들이 모여 훔친 보물로 잔치를 벌이고 있었어요.","네 친구는 꾀를 내어 당나귀 위에 개, 고양이, 수탉이 차례로 올라타 커다란 소리로 함께 울었어요.","갑자기 들려온 기이한 소리와 그림자에 놀란 도둑들은 혼비백산하여 도망쳤어요.","네 친구는 도둑들이 두고 간 오두막에서 편안하게 쉬며 맛있는 음식을 나누어 먹었어요.","그 뒤로 네 친구는 굳이 브레멘까지 가지 않고 오두막에서 사이좋게 함께 살았답니다."]'::jsonb, '[{"word":"의지하다","meaning":"다른 것에 마음을 기대어 도움을 받다"},{"word":"기이하다","meaning":"이상하고 묘하다"},{"word":"혼비백산하다","meaning":"몹시 놀라 넋을 잃다"}]'::jsonb, '[{"answer":true,"statement":"당나귀, 개, 고양이, 수탉은 함께 길을 떠났어요."},{"answer":true,"statement":"네 친구는 힘을 합쳐 도둑들을 놀라게 했어요."},{"answer":false,"statement":"네 친구는 브레멘에 도착해서야 함께 살기로 했어요."}]'::jsonb, '{"choices":["늙으면 아무것도 할 수 없어요","도둑은 절대 놀라지 않아요","서로 다른 이들도 힘을 합치면 어려움을 이겨내고 함께 살아갈 곳을 찾을 수 있어요","동물은 사람과 함께 살 수 없어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"의지하다","choices":["다른 것에 마음을 기대어 도움을 받다","혼자 힘으로만 해내다","전혀 신경 쓰지 않다","멀리 도망가다"],"answerIndex":0},{"type":"vocab","word":"기이하다","choices":["평범하고 흔하다","이상하고 묘하다","조용하고 차분하다","크고 우렁차다"],"answerIndex":1},{"type":"synonym","word":"기이하다","choices":["평범하다","흔하다","일상적이다","괴상하다"],"answerIndex":3},{"type":"antonym","word":"기이하다","choices":["괴상하다","별나다","기묘하다","평범하다"],"answerIndex":2},{"type":"spelling","word":"오두막","choices":["오두막","오뚜막","오두먁","오뚜먁"],"answerIndex":0}]'::jsonb, 151)
