insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('golden-egg-goose-greed', '🥚', '황금알을 낳는 거위', '["가난한 농부가 어느 날 신기하게도 매일 황금알을 낳는 거위를 얻게 되었어요.","농부는 거위가 낳아 주는 황금알 덕분에 하루하루 부유해졌어요.","시간이 지나자 농부는 하루에 알 하나로는 만족하지 못하고 더 큰 욕심을 부리기 시작했어요.","\"거위 배 속에는 분명 황금이 가득할 거야. 한 번에 다 꺼내야겠어!\"","농부는 참지 못하고 거위의 배를 갈라 보았지만, 그 안에는 아무 황금도 없었어요.","결국 소중한 거위만 잃고 더 이상 황금알을 얻을 수 없게 되었어요.","농부는 뒤늦게 후회했지만 이미 늦은 뒤였어요.","이 이야기는 지나친 욕심이 가진 것마저 잃게 만들 수 있다는 것을 알려 준답니다."]'::jsonb, '[{"word":"부유하다","meaning":"재물이 넉넉하다"},{"word":"만족하다","meaning":"마음에 흡족하게 여기다"},{"word":"지나치다","meaning":"정도에 넘치다"}]'::jsonb, '[{"answer":true,"statement":"거위는 매일 황금알을 낳아 주었어요."},{"answer":true,"statement":"농부는 욕심을 부려 거위의 배를 갈랐어요."},{"answer":false,"statement":"거위의 배 속에는 황금이 가득 들어 있었어요."}]'::jsonb, '{"choices":["지나친 욕심을 부리면 가진 것마저 잃을 수 있어요","거위는 누구나 쉽게 키울 수 있어요","황금은 배 속에서 만들어져요","농부는 원래부터 부유했어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"부유하다","choices":["가난하고 궁핍하다","재물이 넉넉하다","몸이 약하고 아프다","마음이 슬프고 우울하다"],"answerIndex":1},{"type":"vocab","word":"지나치다","choices":["부족하다","알맞다","모자라다","정도에 넘치다"],"answerIndex":3},{"type":"synonym","word":"만족하다","choices":["흡족하다","불만스럽다","아쉽다","서운하다"],"answerIndex":0},{"type":"antonym","word":"만족하다","choices":["흡족하다","기쁘다","불만스럽다","뿌듯하다"],"answerIndex":2},{"type":"spelling","word":"뒤늦게","choices":["뒤늣게","뒤늦게","뒤늦개","뒤늦계"],"answerIndex":1}]'::jsonb, 152)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('emperors-new-clothes', '👘', '벌거벗은 임금님', '["새 옷을 무엇보다 좋아하는 임금님에게 두 사기꾼이 찾아와 신기한 옷감 이야기를 꺼냈어요.","사기꾼들은 \"이 옷감은 어리석은 사람의 눈에는 보이지 않는 특별한 옷감\"이라고 거짓말했어요.","사실 사기꾼들은 아무것도 짜지 않으면서 옷감을 짜는 척만 하고 있었어요.","신하들은 옷감이 보이지 않았지만, 어리석다는 말을 들을까 봐 모두 멋지다고 칭찬했어요.","임금님도 옷감이 보이지 않았지만 겁이 나서 다른 사람들처럼 감탄하는 척했어요.","임금님은 결국 보이지 않는 새 옷을 입고 온 나라 사람들 앞에서 행진을 했어요.","거리의 한 어린아이가 순수한 눈으로 \"임금님이 벌거벗었어요!\"라고 큰 소리로 외쳤어요.","그제야 사람들은 진실을 깨닫고 술렁였고, 임금님도 부끄러움을 느꼈답니다."]'::jsonb, '[{"word":"사기꾼","meaning":"남을 속여 이익을 챙기는 사람"},{"word":"감탄하다","meaning":"매우 훌륭하다고 느껴 마음속 깊이 칭찬하다"},{"word":"술렁이다","meaning":"여러 사람이 자꾸 소란스럽게 움직이다"}]'::jsonb, '[{"answer":true,"statement":"사기꾼들은 실제로 옷감을 짜지 않았어요."},{"answer":true,"statement":"어린아이가 임금님이 벌거벗었다고 외쳤어요."},{"answer":false,"statement":"신하들은 처음부터 임금님에게 진실을 말했어요."}]'::jsonb, '{"choices":["새 옷은 항상 특별한 힘을 가지고 있어요","임금님은 절대 실수하지 않아요","어린아이의 말은 믿을 수 없어요","체면 때문에 거짓을 따라가기보다 솔직한 눈으로 진실을 말하는 용기가 중요해요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"사기꾼","choices":["남을 속여 이익을 챙기는 사람","성실하게 일하는 사람","남을 돕는 착한 사람","진실만을 말하는 사람"],"answerIndex":0},{"type":"vocab","word":"술렁이다","choices":["조용히 잠들다","차분하게 걷다","여러 사람이 자꾸 소란스럽게 움직이다","혼자 가만히 있다"],"answerIndex":2},{"type":"synonym","word":"감탄하다","choices":["무시하다","경탄하다","비난하다","외면하다"],"answerIndex":1},{"type":"antonym","word":"감탄하다","choices":["비웃다","경탄하다","찬탄하다","탄복하다"],"answerIndex":0},{"type":"spelling","word":"부끄러움","choices":["부끄러웅","부끄러음","부끄러몸","부끄러움"],"answerIndex":3}]'::jsonb, 153)
