insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('thumbelina-tiny-princess', '🌷', '엄지공주', '["아이를 갖고 싶었던 아주머니가 마법의 씨앗을 심자 꽃 속에서 엄지손가락만 한 소녀가 태어났어요.","아주머니는 소녀를 엄지공주라 부르며 호두 껍데기 요람에 눕혀 정성껏 키웠어요.","어느 날 커다란 두꺼비가 엄지공주를 몰래 데려가 아들과 결혼시키려 했어요.","엄지공주는 물고기들의 도움으로 두꺼비에게서 무사히 도망칠 수 있었어요.","이후에도 딱정벌레와 들쥐 등 여러 동물을 만나며 엄지공주는 이곳저곳을 떠돌았어요.","추운 겨울, 엄지공주는 다친 제비를 정성껏 보살펴 건강하게 낫게 해 주었어요.","봄이 되자 제비는 고마움에 엄지공주를 등에 태우고 따뜻한 꽃의 나라로 데려다주었어요.","그곳에서 엄지공주는 자신과 꼭 맞는 작은 꽃의 왕자를 만나 행복하게 살았답니다."]'::jsonb, '[{"word":"요람","meaning":"젖먹이를 눕히거나 앉히고 흔들어 재우는 도구"},{"word":"떠돌다","meaning":"정처 없이 이곳저곳 돌아다니다"},{"word":"정성껏","meaning":"온 마음을 다해서"}]'::jsonb, '[{"answer":true,"statement":"엄지공주는 꽃 속에서 태어났어요."},{"answer":true,"statement":"엄지공주는 다친 제비를 정성껏 보살펴 주었어요."},{"answer":false,"statement":"엄지공주는 두꺼비의 아들과 결혼했어요."}]'::jsonb, '{"choices":["다른 이에게 베푼 따뜻한 마음은 결국 자신에게도 좋은 인연으로 돌아와요","꽃 속에서는 아무도 태어날 수 없어요","두꺼비는 항상 친절한 동물이에요","겨울에는 아무도 도와줄 수 없어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"요람","choices":["큰 책을 보관하는 곳","젖먹이를 눕히거나 앉히고 흔들어 재우는 도구","음식을 만드는 부엌","옷을 넣어 두는 장롱"],"answerIndex":1},{"type":"vocab","word":"떠돌다","choices":["한곳에 머무르다","가만히 서 있다","깊이 잠들다","정처 없이 이곳저곳 돌아다니다"],"answerIndex":3},{"type":"synonym","word":"정성껏","choices":["대충","건성으로","온 마음을 다해","무성의하게"],"answerIndex":2},{"type":"antonym","word":"정성껏","choices":["대충","온 마음을 다해","정성스럽게","진심으로"],"answerIndex":0},{"type":"spelling","word":"꼭 맞는","choices":["똑 맞는","꼭 맞는","꼭맏는","꼭맞은"],"answerIndex":1}]'::jsonb, 154)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('wild-swans-eleven-princes', '🦢', '백조 왕자', '["어느 나라에 열한 명의 왕자와 막내 공주 엘리제가 사이좋게 살고 있었어요.","새어머니인 못된 왕비는 왕자들을 미워해 마법으로 백조로 변하게 만들었어요.","엘리제도 궁전에서 쫓겨나 오빠들을 찾아 먼 길을 떠났어요.","오빠들을 다시 만난 엘리제는 저주를 풀 방법을 요정에게서 전해 들었어요.","\"쐐기풀로 옷 열한 벌을 짜서 입히되, 다 짤 때까지 절대 말을 해서는 안 된다\"는 것이었어요.","엘리제는 손이 따갑고 아팠지만 말없이 참으며 밤낮으로 옷을 짜 나갔어요.","마지막 옷의 소매를 다 짜기도 전에 오빠들이 나타났고, 엘리제는 재빨리 옷을 던져 입혔어요.","저주가 풀려 오빠들은 다시 사람이 되었고, 막냇동생의 사랑과 인내에 크게 감동했답니다."]'::jsonb, '[{"word":"저주","meaning":"남에게 재앙이나 불행이 일어나도록 비는 것"},{"word":"쐐기풀","meaning":"만지면 따갑고 가려운 풀"},{"word":"인내","meaning":"괴로움이나 어려움을 참고 견딤"}]'::jsonb, '[{"answer":true,"statement":"왕비는 마법으로 왕자들을 백조로 만들었어요."},{"answer":true,"statement":"엘리제는 말을 하지 않고 쐐기풀 옷을 짰어요."},{"answer":false,"statement":"엘리제는 옷을 다 짜기도 전에 포기해 버렸어요."}]'::jsonb, '{"choices":["백조는 절대 사람으로 돌아올 수 없어요","가족을 위한 인내와 사랑은 큰 어려움도 이겨내게 해요","쐐기풀은 아무 쓸모가 없는 풀이에요","말을 하지 않는 것은 항상 좋은 일이에요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"저주","choices":["남에게 재앙이나 불행이 일어나도록 비는 것","축하하고 기뻐하는 것","따뜻하게 인사하는 것","서로 돕고 나누는 것"],"answerIndex":0},{"type":"vocab","word":"인내","choices":["급하게 서두름","크게 화를 냄","괴로움이나 어려움을 참고 견딤","마음껏 즐거워함"],"answerIndex":2},{"type":"synonym","word":"인내","choices":["포기","좌절","불평","참을성"],"answerIndex":3},{"type":"antonym","word":"인내","choices":["참을성","끈기","견딤","포기"],"answerIndex":1},{"type":"spelling","word":"재빨리","choices":["재빨리","재빨이","제빨리","재빨의"],"answerIndex":0}]'::jsonb, 155)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('jack-and-beanstalk-giant', '🌱', '잭과 콩나무', '["가난한 잭과 어머니는 마지막 남은 소를 팔러 시장에 나섰어요.","잭은 낯선 노인에게서 소 대신 신비한 콩 몇 알을 받아 왔어요.","어머니는 화가 나서 콩을 창밖으로 던져 버렸지만, 다음 날 아침 하늘까지 닿는 커다란 콩나무가 자라 있었어요.","잭은 호기심에 콩나무를 타고 올라가 구름 위 거인의 성에 다다랐어요.","거인의 아내는 잭을 몰래 숨겨 주었고, 잭은 성 안에서 황금알을 낳는 거위를 발견했어요.","잭은 거위를 안고 재빨리 콩나무를 타고 내려왔고, 화가 난 거인이 뒤쫓아 왔어요.","잭은 재빨리 도끼로 콩나무를 베어 넘어뜨렸고, 거인은 땅으로 떨어져 다시는 나타나지 않았어요.","잭과 어머니는 황금알을 낳는 거위 덕분에 어려움 없이 행복하게 살았답니다."]'::jsonb, '[{"word":"신비하다","meaning":"보통의 이치로는 알 수 없을 만큼 신기하다"},{"word":"호기심","meaning":"새롭고 신기한 것을 좋아하거나 알고 싶어 하는 마음"},{"word":"뒤쫓다","meaning":"급히 뒤를 따라가다"}]'::jsonb, '[{"answer":true,"statement":"잭은 소 대신 신비한 콩을 받아 왔어요."},{"answer":true,"statement":"잭은 콩나무를 베어 거인을 막았어요."},{"answer":false,"statement":"거인은 잭을 끝까지 잡아서 벌을 주었어요."}]'::jsonb, '{"choices":["낯선 사람의 말은 항상 믿어야 해요","콩나무는 아무 데서나 잘 자라요","용기와 지혜를 발휘하면 위기에서도 기회를 만들 수 있어요","거인은 항상 착한 존재예요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"신비하다","choices":["보통의 이치로는 알 수 없을 만큼 신기하다","평범하고 흔하다","무섭고 위험하다","지루하고 재미없다"],"answerIndex":0},{"type":"vocab","word":"뒤쫓다","choices":["앞장서서 이끌다","급히 뒤를 따라가다","가만히 멈춰 있다","조용히 숨어 있다"],"answerIndex":1},{"type":"synonym","word":"호기심","choices":["무관심","싫증","권태","궁금증"],"answerIndex":3},{"type":"antonym","word":"호기심","choices":["궁금증","흥미","관심","무관심"],"answerIndex":2},{"type":"spelling","word":"낯선","choices":["낯선","낫선","낟선","낳선"],"answerIndex":0}]'::jsonb, 156)
