insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('bluebird-of-happiness', '🐦', '파랑새', '["가난한 나무꾼의 아이들인 치르치르와 미치르는 크리스마스 전날, 요정 할머니를 만났어요.","요정 할머니는 아픈 손녀를 위해 행복을 가져다주는 파랑새를 찾아 달라고 부탁했어요.","남매는 파랑새를 찾아 추억의 나라, 밤의 궁전, 미래의 나라 등 신비로운 곳을 여행했어요.","가는 곳마다 파랑새처럼 보이는 새를 잡았지만, 매번 색이 변하거나 죽어 버려 진짜가 아니었어요.","오랜 여행 끝에도 파랑새를 찾지 못한 남매는 지친 몸으로 결국 집으로 돌아왔어요.","다음 날 아침, 남매는 자신들이 늘 기르던 새장 속 새가 파랗게 변해 있는 것을 발견했어요.","남매는 그토록 찾아 헤매던 행복이 사실은 늘 가까운 집 안에 있었다는 것을 깨달았어요.","치르치르와 미치르는 그 파랑새를 요정 할머니의 손녀에게 기쁜 마음으로 나누어 주었답니다."]'::jsonb, '[{"word":"신비롭다","meaning":"신기하고 묘한 느낌이 있다"},{"word":"지치다","meaning":"힘이 다 빠져 고단하다"},{"word":"깨닫다","meaning":"사물의 본질이나 이치를 알게 되다"}]'::jsonb, '[{"answer":true,"statement":"남매는 파랑새를 찾아 여러 신비로운 나라를 여행했어요."},{"answer":true,"statement":"남매는 집에 있던 새가 파랗게 변한 것을 발견했어요."},{"answer":false,"statement":"남매는 여행을 떠나자마자 바로 파랑새를 찾았어요."}]'::jsonb, '{"choices":["행복은 아주 먼 곳에서만 찾을 수 있어요","새는 절대 색이 변하지 않아요","여행은 항상 힘들고 의미가 없어요","진짜 소중한 행복은 의외로 가까운 곳에 있을 수 있어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"신비롭다","choices":["평범하고 단순하다","신기하고 묘한 느낌이 있다","지루하고 따분하다","크고 시끄럽다"],"answerIndex":1},{"type":"vocab","word":"지치다","choices":["힘이 다 빠져 고단하다","기운이 넘쳐 활기차다","마음이 편안하고 여유롭다","기분이 좋고 신나다"],"answerIndex":0},{"type":"synonym","word":"깨닫다","choices":["잊어버리다","모르다","알아차리다","외면하다"],"answerIndex":2},{"type":"antonym","word":"깨닫다","choices":["알아차리다","이해하다","파악하다","모르다"],"answerIndex":3},{"type":"spelling","word":"의외로","choices":["의외로","의왜로","의외러","의왜러"],"answerIndex":0}]'::jsonb, 157)
