insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('happy-prince-and-swallow', '🗿', '행복한 왕자', '["도시 한가운데 서 있는 행복한 왕자 동상은 금과 보석으로 아름답게 꾸며져 있었어요.","남쪽 나라로 가던 제비 한 마리가 밤이 되어 동상 발밑에서 쉬어 가게 되었어요.","왕자 동상은 도시 곳곳의 가난하고 아픈 사람들을 보며 눈물을 흘리고 있었어요.","왕자는 제비에게 자신의 몸에 박힌 보석과 금박을 가난한 사람들에게 나누어 달라고 부탁했어요.","제비는 왕자의 부탁을 들어주느라 남쪽으로 떠나야 할 때를 여러 번 놓치고 말았어요.","왕자의 몸은 점점 볼품없어졌지만, 도시의 많은 사람들은 따뜻한 도움을 받아 행복해졌어요.","결국 겨울이 되어 제비는 추위를 이기지 못하고 왕자의 발밑에서 조용히 눈을 감았어요.","왕자와 제비의 아름다운 마음은 하늘의 천사에게도 전해져 영원히 기억되었답니다."]'::jsonb, '[{"word":"금박","meaning":"금을 아주 얇게 편 조각"},{"word":"볼품없다","meaning":"겉으로 드러나 보이는 모양이 초라하다"},{"word":"영원히","meaning":"끝없이 오래도록"}]'::jsonb, '[{"answer":true,"statement":"왕자 동상은 도시의 가난한 사람들을 보며 눈물을 흘렸어요."},{"answer":true,"statement":"제비는 왕자를 도와주느라 남쪽으로 떠나지 못했어요."},{"answer":false,"statement":"왕자는 자신의 보석을 아무에게도 나누어 주지 않았어요."}]'::jsonb, '{"choices":["다른 이를 위한 나눔과 희생은 진정한 아름다움을 만들어요","동상은 아무 감정도 느끼지 못해요","제비는 겨울에도 항상 따뜻하게 지내요","보석은 몸에 지니고 있어야만 가치가 있어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"금박","choices":["단단한 나무 조각","무거운 쇠 덩어리","금을 아주 얇게 편 조각","부드러운 천 조각"],"answerIndex":2},{"type":"vocab","word":"볼품없다","choices":["아름답고 화려하다","겉으로 드러나 보이는 모양이 초라하다","크고 웅장하다","반짝이고 빛나다"],"answerIndex":1},{"type":"synonym","word":"영원히","choices":["잠시","한때","금방","끝없이"],"answerIndex":3},{"type":"antonym","word":"영원히","choices":["잠시","끝없이","오래도록","영영"],"answerIndex":0},{"type":"spelling","word":"눈을 감다","choices":["눈을 갑다","눈을 감다","눈을 감따","눈을 갑따"],"answerIndex":1}]'::jsonb, 158)
