insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('wizard-of-oz-yellow-brick-road', '🌪️', '오즈의 마법사', '["회오리바람에 휩쓸린 소녀 도로시는 강아지 토토와 함께 낯선 마법의 나라에 떨어졌어요.","집으로 돌아가고 싶은 도로시는 노란 벽돌길을 따라 위대한 오즈의 마법사를 찾아가기로 했어요.","길을 걷던 도로시는 지혜를 갖고 싶어 하는 허수아비를 만나 함께 길을 떠났어요.","이어서 마음을 갖고 싶어 하는 양철 나무꾼과 용기를 갖고 싶어 하는 겁쟁이 사자도 동행하게 되었어요.","네 친구는 서로 의지하며 여러 위험을 이겨내고 마침내 에메랄드 성에 도착했어요.","오즈의 마법사는 사실 대단한 마법사가 아니라 커다란 장치 뒤에 숨은 평범한 사람이었어요.","마법사는 각자에게 필요한 것은 이미 여행 중에 스스로 보여 준 지혜와 마음과 용기였다고 일깨워 주었어요.","도로시도 자신의 힘으로 집에 돌아가는 방법을 깨닫고 다시 가족의 품으로 돌아갔답니다."]'::jsonb, '[{"word":"휩쓸리다","meaning":"무엇에 세게 몰리거나 쏠리다"},{"word":"동행하다","meaning":"어떤 사람과 같이 길을 가다"},{"word":"일깨우다","meaning":"무엇을 깨닫도록 잘 알려 주다"}]'::jsonb, '[{"answer":true,"statement":"도로시는 노란 벽돌길을 따라 오즈의 마법사를 찾아갔어요."},{"answer":true,"statement":"네 친구는 서로 의지하며 여러 위험을 이겨냈어요."},{"answer":false,"statement":"오즈의 마법사는 실제로 아주 강력한 마법을 부렸어요."}]'::jsonb, '{"choices":["마법사는 항상 모든 문제를 대신 해결해 줘요","낯선 나라는 절대 여행하면 안 돼요","지혜와 마음과 용기는 이미 함께한 여정 속에서 스스로 키워 온 것일 수 있어요","강아지는 마법의 나라에 갈 수 없어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"휩쓸리다","choices":["가만히 멈춰 있다","무엇에 세게 몰리거나 쏠리다","천천히 걸어가다","조용히 숨다"],"answerIndex":1},{"type":"vocab","word":"일깨우다","choices":["모르게 숨기다","잊어버리게 하다","혼란스럽게 하다","무엇을 깨닫도록 잘 알려 주다"],"answerIndex":3},{"type":"synonym","word":"동행하다","choices":["함께 가다","혼자 가다","떠나보내다","뒤처지다"],"answerIndex":0},{"type":"antonym","word":"동행하다","choices":["함께하다","같이 가다","혼자 가다","동반하다"],"answerIndex":2},{"type":"spelling","word":"깨닫다","choices":["깨닳다","깨닫다","깨다랐다","깨닸다"],"answerIndex":1}]'::jsonb, 159)
