insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('class-library-duty-responsibility', '📚', '학급문고 지킴이가 된 날', '["이번 학기, 지호는 학급문고를 정리하는 ''책 지킴이''를 맡게 되었어요.","처음에는 그저 귀찮은 일이라고만 생각했어요.","그런데 책이 뒤죽박죽 섞여 있어서 친구들이 원하는 책을 찾지 못해 불평하는 소리를 들었어요.","지호는 쉬는 시간마다 조금씩 책을 종류별로 나누어 정리하기 시작했어요.","처음엔 힘들었지만 하루하루 지날수록 책장이 깔끔해졌어요.","어느 날, 한 친구가 원하는 책을 금방 찾고는 지호에게 고맙다고 인사했어요.","지호는 그 말을 듣고 마음이 뿌듯해졌어요.","이제 지호는 매일 아침 가장 먼저 학급문고를 살피는 습관이 생겼어요.","작은 책임이 지호를 더 성실한 사람으로 만들어 주었어요."]'::jsonb, '[{"word":"뒤죽박죽","meaning":"여러 가지가 마구 섞여 있는 상태"},{"word":"성실하다","meaning":"정성스럽고 참되다"}]'::jsonb, '[{"answer":true,"statement":"지호는 학급문고를 정리하는 책 지킴이를 맡았다."},{"answer":false,"statement":"지호는 처음부터 이 일을 아주 좋아했다."},{"answer":true,"statement":"친구들은 책을 쉽게 찾을 수 없어 불평했다."},{"answer":false,"statement":"지호는 결국 책 정리를 포기했다."}]'::jsonb, '{"choices":["작은 책임을 성실하게 해내면 뿌듯함과 성장을 얻을 수 있어요","귀찮은 일은 하지 않는 것이 좋아요","책 정리는 어른들이 해야 하는 일이에요","친구들의 불평은 무시해도 괜찮아요"],"question":"이 이야기가 주는 교훈은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"뒤죽박죽","choices":["여러 가지가 마구 섞여 있는 상태","가지런히 정돈된 상태","텅 비어 있는 상태","반짝반짝 빛나는 상태"],"answerIndex":0},{"type":"proverb","word":"공든 탑이 무너지랴","choices":["탑은 높을수록 위험하다는 뜻이에요","정성을 들여 이룬 일은 쉽게 무너지지 않는다는 뜻이에요","공사는 빨리 끝내야 한다는 뜻이에요","무너진 탑은 다시 세울 수 없다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"성실하다","choices":["나태하다","무심하다","근면하다","불성실하다"],"answerIndex":2},{"type":"antonym","word":"성실하다","choices":["정직하다","꾸준하다","근면하다","게으르다"],"answerIndex":3},{"type":"spelling","word":"며칠","choices":["며칠","며칟","몇일","멷일"],"answerIndex":0}]'::jsonb, 160)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('birthday-gift-forgotten-letter', '✉️', '깜빡한 생일, 진심을 담은 편지', '["현우는 단짝 친구 유진이의 생일을 까맣게 잊고 있었어요.","학교에서 친구들이 유진이에게 선물을 건네는 모습을 보고 그제야 생일이라는 걸 깨달았어요.","현우는 너무 당황해서 아무 말도 하지 못했어요.","집에 돌아온 현우는 어떻게 사과할지 한참을 고민했어요.","고민 끝에 현우는 정성을 담아 손편지를 쓰기로 했어요.","편지에는 미안한 마음과 유진이에 대한 고마움이 가득 담겨 있었어요.","다음 날 현우는 떨리는 마음으로 편지를 유진이에게 건넸어요.","유진이는 편지를 읽고 눈물을 글썽이며 활짝 웃었어요.","유진이는 선물보다 이 편지가 더 특별하다고 말해 주었어요."]'::jsonb, '[{"word":"당황하다","meaning":"놀랍거나 난처하여 어찌할 바를 모르다"},{"word":"정성","meaning":"온갖 힘을 다하려는 참되고 성실한 마음"}]'::jsonb, '[{"answer":false,"statement":"현우는 유진이의 생일을 미리 알고 준비했다."},{"answer":true,"statement":"현우는 유진이에게 손편지를 써 주었다."},{"answer":false,"statement":"유진이는 편지를 받고 화를 냈다."}]'::jsonb, '{"choices":["선물은 비쌀수록 좋다","진심 어린 마음은 실수를 만회할 수 있다","생일을 잊는 것은 큰 잘못이 아니다","편지보다 선물이 항상 낫다"],"question":"이 이야기가 전하고 싶은 마음은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"당황하다","choices":["즐겁고 신난다","놀랍거나 난처하여 어찌할 바를 모르다","차분하고 편안하다","배가 고프다"],"answerIndex":1},{"type":"proverb","word":"소 잃고 외양간 고친다","choices":["소는 외양간에서 키워야 한다는 뜻이에요","외양간은 튼튼해야 한다는 뜻이에요","일이 이미 잘못된 후에야 손을 쓴다는 뜻이에요","소를 잃으면 안 된다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"정성","choices":["무관심","소홀함","냉담함","성의"],"answerIndex":3},{"type":"antonym","word":"당황하다","choices":["침착하다","허둥대다","쩔쩔매다","놀라다"],"answerIndex":0},{"type":"spelling","word":"왠지","choices":["웬지","왠지","왠짓","웬짓"],"answerIndex":1}]'::jsonb, 161)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('kickball-referee-call-accept', '⚾', '발야구 판정에 승복하기', '["체육 시간, 반 대항 발야구 경기가 한창이었어요.","민서는 힘껏 찬 공이 세이프라고 생각했지만, 심판을 맡은 선생님은 아웃을 선언했어요.","민서는 억울한 마음에 얼굴이 붉어졌어요.","친구들도 세이프라고 우겼지만, 선생님은 규칙을 다시 차분히 설명해 주셨어요.","민서는 잠시 화가 났지만, 곧 심호흡을 하고 판정을 받아들이기로 했어요.","\"괜찮아, 다음 공격 때 더 잘하면 되지\" 하고 스스로를 다독였어요.","결국 민서네 팀은 다음 이닝에서 멋진 역전을 만들어냈어요.","경기가 끝난 뒤 선생님은 민서의 의젓한 태도를 칭찬해 주셨어요.","민서는 판정에 승복한 것이 오히려 더 큰 자신감을 주었다는 것을 깨달았어요."]'::jsonb, '[{"word":"승복하다","meaning":"굴복하여 따르다, 결과를 받아들이다"},{"word":"의젓하다","meaning":"말과 행동이 점잖고 어른스럽다"}]'::jsonb, '[{"answer":true,"statement":"민서는 자신의 판정이 아웃이라는 것에 처음엔 억울해했다."},{"answer":false,"statement":"민서는 끝까지 심판에게 화를 냈다."},{"answer":true,"statement":"민서네 팀은 다음 이닝에서 역전했다."},{"answer":false,"statement":"선생님은 민서의 태도를 나무랐다."}]'::jsonb, '{"choices":["판정은 항상 불공평하다","화가 나면 크게 항의해야 한다","결과에 승복하는 태도가 더 큰 성장을 가져다준다","경기는 이기는 것이 전부다"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"승복하다","choices":["끝까지 반박하다","무시하고 지나가다","굴복하여 따르다","더 크게 화내다"],"answerIndex":2},{"type":"proverb","word":"뛰는 놈 위에 나는 놈 있다","choices":["뛰는 것보다 나는 것이 편하다는 뜻이에요","달리기는 연습이 중요하다는 뜻이에요","높이 나는 새가 멀리 본다는 뜻이에요","아무리 잘해도 더 뛰어난 사람이 있다는 뜻이에요"],"answerIndex":3},{"type":"synonym","word":"의젓하다","choices":["점잖다","유치하다","촐랑대다","산만하다"],"answerIndex":0},{"type":"antonym","word":"의젓하다","choices":["점잖다","유치하다","듬직하다","차분하다"],"answerIndex":1},{"type":"spelling","word":"어이없다","choices":["어의없다","어이업다","어이없다","어의업다"],"answerIndex":2}]'::jsonb, 162)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('art-contest-copy-temptation', '🎨', '미술대회의 유혹', '["교내 미술대회를 앞두고 서준이는 좋은 작품을 만들고 싶은 마음에 초조해졌어요.","인터넷을 뒤지다 우연히 자신이 그리려던 주제와 똑같은 멋진 그림을 발견했어요.","그대로 따라 그리면 쉽게 상을 받을 수 있을 것 같은 유혹이 들었어요.","하지만 서준이는 곧 그건 자신의 그림이 아니라는 생각이 들어 마음이 무거워졌어요.","고민 끝에 서준이는 그 그림을 참고만 하고, 자신만의 아이디어로 새롭게 구상하기로 했어요.","밤늦게까지 스케치를 고치고 색을 입히며 며칠을 꼬박 매달렸어요.","완성된 그림은 처음 본 그림만큼 화려하지는 않았지만, 서준이만의 개성이 담겨 있었어요.","대회에서 큰 상은 받지 못했지만, 선생님은 서준이의 독창성을 크게 칭찬해 주셨어요.","서준이는 정직하게 완성한 작품이 훨씬 더 자랑스럽다고 느꼈어요."]'::jsonb, '[{"word":"초조하다","meaning":"마음이 조마조마하여 불안하다"},{"word":"독창성","meaning":"다른 것을 따라 하지 않고 새로운 것을 만들어 내는 성질"}]'::jsonb, '[{"answer":false,"statement":"서준이는 다른 사람의 그림을 그대로 베껴서 냈다."},{"answer":true,"statement":"서준이는 자신만의 아이디어로 새로 구상했다."},{"answer":false,"statement":"서준이는 대회에서 가장 큰 상을 받았다."}]'::jsonb, '{"choices":["베끼는 것이 가장 효율적인 방법이다","상을 받지 못하면 노력은 의미가 없다","미술대회는 참가하지 않는 것이 좋다","결과보다 정직하게 노력한 과정이 더 값지다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"초조하다","choices":["아주 여유롭고 편안하다","기쁘고 즐겁다","몹시 지루하다","마음이 조마조마하여 불안하다"],"answerIndex":3},{"type":"proverb","word":"고생 끝에 낙이 온다","choices":["힘든 일을 겪고 나면 좋은 일이 온다는 뜻이에요","고생은 절대 하지 않는 것이 좋다는 뜻이에요","낙이 오면 다시 고생이 온다는 뜻이에요","고생과 낙은 관계가 없다는 뜻이에요"],"answerIndex":0},{"type":"synonym","word":"독창성","choices":["모방성","창의성","획일성","의존성"],"answerIndex":1},{"type":"antonym","word":"독창성","choices":["창의성","고유성","모방","참신함"],"answerIndex":2},{"type":"spelling","word":"설거지","choices":["설겆이","설것이","설겄이","설거지"],"answerIndex":3}]'::jsonb, 163)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('confess-breaking-toy', '🧸', '동생 장난감을 부순 뒤', '["예린이는 동생이 아끼는 로봇 장난감을 가지고 놀다가 그만 팔 하나를 부러뜨렸어요.","너무 놀란 예린이는 얼른 로봇을 책상 서랍 깊숙이 숨겨 버렸어요.","동생이 로봇을 찾으며 울먹이는 모습을 보니 예린이는 마음이 불편했어요.","며칠 동안 예린이는 몰래 감춰 둔 로봇 생각에 편히 잠들지 못했어요.","결국 예린이는 용기를 내어 동생에게 사실대로 털어놓기로 했어요.","\"미안해, 내가 실수로 부러뜨렸어. 같이 고쳐 볼까?\" 하고 조심스럽게 말했어요.","동생은 처음엔 속상해했지만, 솔직하게 말해 준 언니에게 고마워했어요.","둘은 함께 접착제로 로봇의 팔을 정성껏 붙였어요.","예린이는 숨기는 것보다 솔직하게 말하는 것이 마음을 훨씬 가볍게 해 준다는 걸 배웠어요."]'::jsonb, '[{"word":"털어놓다","meaning":"마음속에 있는 것을 숨기지 않고 이야기하다"},{"word":"정성껏","meaning":"온 마음을 다해서"}]'::jsonb, '[{"answer":true,"statement":"예린이는 처음에 로봇을 숨겼다."},{"answer":false,"statement":"예린이는 끝까지 사실을 숨겼다."},{"answer":false,"statement":"동생은 사실을 듣고도 전혀 속상해하지 않았다."},{"answer":true,"statement":"둘은 함께 로봇을 고쳤다."}]'::jsonb, '{"choices":["솔직하게 털어놓으면 마음이 편해지고 관계도 회복된다","실수는 절대 들키면 안 된다","동생의 물건은 만지지 않는 것이 좋다","장난감은 비싸지 않은 것이 좋다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"털어놓다","choices":["마음속 이야기를 숨김없이 말하다","끝까지 숨기다","모르는 척하다","화를 내며 소리치다"],"answerIndex":0},{"type":"proverb","word":"하나를 보면 열을 안다","choices":["열 가지를 다 봐야 하나를 알 수 있다는 뜻이에요","작은 부분만 보아도 전체를 미루어 짐작할 수 있다는 뜻이에요","숫자는 정확히 세어야 한다는 뜻이에요","하나씩 차례로 배워야 한다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"정성껏","choices":["대충","아무렇게나","성심껏","무심코"],"answerIndex":2},{"type":"antonym","word":"털어놓다","choices":["고백하다","밝히다","실토하다","숨기다"],"answerIndex":3},{"type":"spelling","word":"오랜만","choices":["오랜만","오랫만","오랜만에","오랫동안만"],"answerIndex":0}]'::jsonb, 164)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('school-newspaper-second-try', '📰', '학교 신문 기자단 재도전', '["다은이는 학교 신문 기자단에 지원해 첫 기사를 써서 제출했어요.","하지만 편집장 선생님은 기사가 너무 딱딱하고 재미없다며 다시 써 보라고 하셨어요.","다은이는 속상한 마음에 그만 포기하고 싶었어요.","그날 밤, 다은이는 자신이 좋아하는 만화책의 재미있는 문체를 떠올렸어요.","다음 날부터 다은이는 학교 곳곳을 다니며 친구들을 직접 인터뷰하기 시작했어요.","생생한 목소리를 담아 기사를 다시 쓰자 훨씬 재미있고 살아있는 글이 되었어요.","두 번째로 제출한 기사는 학교 신문 첫 페이지에 실리게 되었어요.","친구들은 다은이의 기사를 읽고 재미있다며 칭찬해 주었어요.","다은이는 포기하지 않고 다시 도전한 덕분에 값진 결과를 얻었다고 느꼈어요."]'::jsonb, '[{"word":"딱딱하다","meaning":"표현이나 태도가 부드럽지 않고 뻣뻣하다"},{"word":"생생하다","meaning":"바로 눈앞에 보는 것처럼 명확하고 또렷하다"}]'::jsonb, '[{"answer":false,"statement":"다은이의 첫 기사는 단번에 통과되었다."},{"answer":true,"statement":"다은이는 친구들을 직접 인터뷰했다."},{"answer":false,"statement":"다은이는 결국 기사 쓰기를 완전히 포기했다."}]'::jsonb, '{"choices":["글쓰기는 타고난 재능이 전부다","처음에 실패해도 포기하지 않고 다시 도전하면 좋은 결과를 얻을 수 있다","인터뷰는 시간 낭비일 뿐이다","첫 시도에서 실패하면 다시 하지 않는 것이 좋다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"딱딱하다","choices":["아주 부드럽고 유연하다","표현이 부드럽지 않고 뻣뻣하다","즐겁고 유쾌하다","조용하고 차분하다"],"answerIndex":1},{"type":"proverb","word":"뜻이 있는 곳에 길이 있다","choices":["길은 이미 정해져 있다는 뜻이에요","길을 잃으면 뜻도 잃는다는 뜻이에요","간절한 의지가 있으면 방법을 찾을 수 있다는 뜻이에요","뜻은 길보다 중요하지 않다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"생생하다","choices":["희미하다","흐릿하다","애매하다","또렷하다"],"answerIndex":3},{"type":"antonym","word":"딱딱하다","choices":["부드럽다","뻣뻣하다","경직되다","완고하다"],"answerIndex":0},{"type":"spelling","word":"금세","choices":["금새","금세","금세에","금쌔"],"answerIndex":1}]'::jsonb, 165)
