insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('puppy-walk-duty-commitment', '🐶', '강아지 산책 당번이 되어', '["가족이 새로 입양한 강아지 콩이의 산책 담당은 도윤이가 맡기로 했어요.","처음 며칠은 신이 나서 매일 아침 콩이와 씩씩하게 산책을 나갔어요.","하지만 시간이 지나자 아침잠이 많은 도윤이에게는 점점 힘든 일이 되었어요.","어느 날 늦잠을 자서 산책을 건너뛰자, 콩이가 온종일 시무룩해 보였어요.","도윤이는 콩이의 처진 어깨를 보고 마음이 아팠어요.","그날부터 도윤이는 전날 밤 알람을 여러 개 맞춰 놓기로 했어요.","꾸준히 산책을 다니자 콩이는 다시 활기차게 꼬리를 흔들었어요.","도윤이도 규칙적인 아침 산책 덕분에 몸이 훨씬 가뿐해졌다는 걸 느꼈어요.","작은 약속을 꾸준히 지키는 것이 큰 변화를 만든다는 걸 알게 되었어요."]'::jsonb, '[{"word":"시무룩하다","meaning":"마음에 못마땅하여 기분이 언짢은 표정이다"},{"word":"꾸준히","meaning":"한결같이 부지런하고 끈기 있게"}]'::jsonb, '[{"answer":false,"statement":"도윤이는 처음부터 산책을 귀찮아했다."},{"answer":true,"statement":"도윤이가 산책을 건너뛰자 콩이가 시무룩해했다."},{"answer":false,"statement":"도윤이는 결국 산책 당번을 그만두었다."},{"answer":true,"statement":"도윤이는 알람을 맞춰 꾸준히 산책을 다녔다."}]'::jsonb, '{"choices":["반려동물은 가끔 돌봐도 괜찮다","산책은 힘들기만 한 일이다","작은 약속을 꾸준히 지키는 것이 큰 변화를 만든다","강아지는 혼자 두어도 괜찮다"],"question":"이 이야기가 주는 교훈은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"시무룩하다","choices":["아주 신이 난 표정이다","졸린 표정이다","기분이 언짢은 표정이다","놀란 표정이다"],"answerIndex":2},{"type":"proverb","word":"구르는 돌에는 이끼가 안 낀다","choices":["돌은 절대 구르면 안 된다는 뜻이에요","이끼는 돌에 좋은 것이라는 뜻이에요","돌은 무거워서 구르지 않는다는 뜻이에요","부지런히 노력하는 사람은 계속 발전한다는 뜻이에요"],"answerIndex":3},{"type":"synonym","word":"꾸준히","choices":["한결같이","가끔","간혹","때때로"],"answerIndex":0},{"type":"antonym","word":"시무룩하다","choices":["언짢다","명랑하다","침울하다","우울하다"],"answerIndex":1},{"type":"spelling","word":"웬만하면","choices":["왠만하면","웬만하믄","웬만하면","왠만하믄"],"answerIndex":2}]'::jsonb, 166)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('school-lunch-food-waste-campaign', '🍽️', '급식 잔반 줄이기 캠페인', '["급식 시간마다 잔반통에는 손도 안 댄 채소와 밥이 수북이 쌓였어요.","환경 동아리 회장을 맡은 하윤이는 이 모습을 보고 마음이 무거웠어요.","하윤이는 친구들에게 잔반을 줄이자고 말했지만, 처음엔 아무도 크게 신경 쓰지 않았어요.","하윤이는 포스터를 만들고, 잔반을 줄인 반을 칭찬하는 게시판을 만들기로 했어요.","처음 몇 주는 큰 변화가 없어서 하윤이는 조금 실망스러웠어요.","하지만 하윤이는 포기하지 않고 매주 꾸준히 게시판을 관리했어요.","한 달이 지나자 반마다 조금씩 잔반량이 줄어들기 시작했어요.","학기 말에는 급식실 잔반량이 처음의 절반으로 줄어들었어요.","하윤이는 작은 실천이 쌓여 큰 변화를 만든다는 것을 깨달았어요."]'::jsonb, '[{"word":"잔반","meaning":"먹고 남은 음식"},{"word":"실천","meaning":"생각한 것을 실제로 행함"}]'::jsonb, '[{"answer":true,"statement":"하윤이는 환경 동아리 회장이었다."},{"answer":false,"statement":"캠페인은 시작하자마자 바로 큰 효과가 나타났다."},{"answer":false,"statement":"학기 말에는 잔반량이 오히려 늘어났다."}]'::jsonb, '{"choices":["잔반은 줄이기 어려우니 신경 쓰지 않아도 된다","캠페인은 하루 만에 성공해야 의미가 있다","환경 동아리는 필요하지 않다","작은 실천이 꾸준히 쌓이면 큰 변화를 만들 수 있다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"잔반","choices":["새로 만든 음식","가장 맛있는 음식","포장된 음식","먹고 남은 음식"],"answerIndex":3},{"type":"proverb","word":"남의 떡이 커 보인다","choices":["남의 것이 내 것보다 더 좋아 보인다는 뜻이에요","떡은 다른 사람과 나눠 먹어야 한다는 뜻이에요","떡은 클수록 맛있다는 뜻이에요","남의 물건은 함부로 만지면 안 된다는 뜻이에요"],"answerIndex":0},{"type":"synonym","word":"실천","choices":["생각","실행","계획","상상"],"answerIndex":1},{"type":"antonym","word":"실천","choices":["행함","실행","구상","이행"],"answerIndex":2},{"type":"spelling","word":"돼요","choices":["되요","되요","되여요","돼요"],"answerIndex":3}]'::jsonb, 167)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('online-game-time-self-control', '🎮', '게임 시간 스스로 지키기', '["재민이는 부모님과 하루 한 시간만 게임을 하기로 약속했어요.","처음 며칠은 약속을 잘 지켰지만, 재미있는 새 게임이 나오자 자꾸 시간을 넘기게 되었어요.","부모님이 잔소리를 하자 재민이는 짜증을 내며 방문을 닫아 버렸어요.","그날 밤, 재민이는 숙제도 밀리고 잠도 부족해 하루 종일 피곤했던 것을 떠올렸어요.","재민이는 스스로 타이머를 맞추고 알람이 울리면 바로 끄는 규칙을 세워 보기로 했어요.","처음에는 아쉬웠지만, 시간이 지나자 오히려 마음이 홀가분해졌어요.","숙제할 시간도 늘고, 밤에 잠도 푹 잘 수 있게 되었어요.","부모님도 스스로 약속을 지키는 재민이를 보고 흐뭇해하셨어요.","재민이는 규칙을 억지로 따르는 것보다 스스로 지키는 것이 훨씬 뿌듯하다는 걸 알게 되었어요."]'::jsonb, '[{"word":"홀가분하다","meaning":"거추장스럽지 않고 가볍고 편안하다"},{"word":"흐뭇하다","meaning":"마음에 흡족하여 매우 만족스럽다"}]'::jsonb, '[{"answer":false,"statement":"재민이는 처음부터 게임 시간 약속을 완벽히 지켰다."},{"answer":true,"statement":"재민이는 스스로 타이머를 맞추기로 했다."},{"answer":false,"statement":"재민이는 규칙을 지킨 뒤 오히려 더 피곤해졌다."},{"answer":true,"statement":"부모님은 재민이의 변화에 흐뭇해하셨다."}]'::jsonb, '{"choices":["스스로 세운 규칙을 지키면 생활에 여유와 만족이 생긴다","게임은 무조건 하지 말아야 한다","부모님이 정한 규칙은 지킬 필요 없다","타이머는 아무 도움이 되지 않는다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"홀가분하다","choices":["가볍고 편안하다","무겁고 답답하다","복잡하고 어수선하다","지루하고 따분하다"],"answerIndex":0},{"type":"proverb","word":"급할수록 돌아가라","choices":["급하면 아무렇게나 해도 된다는 뜻이에요","급할수록 침착하게 순서를 지키라는 뜻이에요","돌아가는 길이 항상 더 빠르다는 뜻이에요","급한 일은 미루어도 된다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"흐뭇하다","choices":["불만스럽다","서운하다","만족스럽다","속상하다"],"answerIndex":2},{"type":"antonym","word":"홀가분하다","choices":["가뿐하다","산뜻하다","편안하다","답답하다"],"answerIndex":3},{"type":"spelling","word":"안 돼","choices":["안 돼","안 되","안돼요서","않돼"],"answerIndex":0}]'::jsonb, 168)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('taekwondo-belt-test-nerves', '🥋', '태권도 승급 심사의 떨림', '["재우는 몇 달간 연습한 품새로 태권도 빨간 띠 승급 심사를 앞두고 있었어요.","심사 당일 아침, 재우는 긴장한 나머지 아침밥도 제대로 먹지 못했어요.","심사장에 들어서자 손과 다리가 떨려 동작이 자꾸 헷갈렸어요.","품새 중간에 한 동작을 실수해서 재우는 눈앞이 캄캄해졌어요.","하지만 재우는 심호흡을 하고 남은 동작을 끝까지 침착하게 마쳤어요.","심사가 끝난 뒤 관장님은 실수보다 끝까지 포기하지 않은 태도를 칭찬해 주셨어요.","며칠 뒤, 재우는 무사히 빨간 띠를 받게 되었어요.","재우는 완벽하지 않아도 끝까지 최선을 다하는 것이 중요하다는 것을 깨달았어요.","이제 재우는 다음 심사도 자신감 있게 준비하기로 다짐했어요."]'::jsonb, '[{"word":"캄캄하다","meaning":"몹시 놀라거나 당황하여 정신이 아득하다"},{"word":"침착하다","meaning":"행동이 들뜨지 않고 차분하다"}]'::jsonb, '[{"answer":true,"statement":"재우는 심사 중 한 동작을 실수했다."},{"answer":false,"statement":"재우는 실수 후 심사를 중간에 포기했다."},{"answer":true,"statement":"재우는 결국 빨간 띠를 받았다."}]'::jsonb, '{"choices":["실수하면 바로 포기하는 것이 낫다","완벽하지 않아도 끝까지 최선을 다하는 태도가 중요하다","긴장하면 아침밥을 먹지 않아야 한다","심사는 누구나 쉽게 통과한다"],"question":"이 이야기가 주는 교훈은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"캄캄하다","choices":["아주 편안하고 차분하다","매우 놀라 정신이 아득하다","즐겁고 신이 나다","졸리고 나른하다"],"answerIndex":1},{"type":"proverb","word":"우물에 가 숭늉 찾는다","choices":["우물물은 시원하고 맛있다는 뜻이에요","숭늉은 우물에서 만든다는 뜻이에요","일의 순서를 무시하고 너무 성급하게 서두른다는 뜻이에요","물을 아껴 써야 한다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"침착하다","choices":["허둥대다","당황하다","조급하다","차분하다"],"answerIndex":3},{"type":"antonym","word":"침착하다","choices":["허둥대다","차분하다","냉정하다","의젓하다"],"answerIndex":0},{"type":"spelling","word":"개수","choices":["갯수","개수","갯쑤","개쑤"],"answerIndex":1}]'::jsonb, 169)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('stopping-friend-teasing', '🙅', '친구를 놀리는 걸 보고', '["쉬는 시간, 몇몇 아이들이 말이 느린 친구 준호를 흉내 내며 웃고 있었어요.","지켜보던 세아는 마음이 불편했지만, 나서면 자기도 놀림받을까 봐 망설여졌어요.","준호의 얼굴이 점점 빨개지는 것을 보고 세아는 더 이상 참을 수 없었어요.","세아는 용기를 내어 \"그만해, 그런 말은 준호 마음을 아프게 해\" 하고 말했어요.","순간 아이들은 조용해졌고, 몇몇은 머쓱한 표정을 지었어요.","세아는 준호에게 다가가 괜찮냐고 물으며 옆에 앉아 주었어요.","준호는 고마운 마음에 작은 목소리로 \"고마워\"라고 말했어요.","다음 날부터 놀리던 친구들도 준호에게 함부로 말하지 않게 되었어요.","세아는 옳지 않은 일에 목소리를 내는 것이 얼마나 중요한지 깨달았어요."]'::jsonb, '[{"word":"망설이다","meaning":"머뭇거리며 결정을 내리지 못하다"},{"word":"머쓱하다","meaning":"무안하고 어색하다"}]'::jsonb, '[{"answer":false,"statement":"세아는 처음부터 망설임 없이 나섰다."},{"answer":true,"statement":"세아는 결국 놀리는 것을 멈추라고 말했다."},{"answer":false,"statement":"준호는 세아의 말에 화를 냈다."},{"answer":true,"statement":"다음 날부터 아이들은 준호를 놀리지 않게 되었다."}]'::jsonb, '{"choices":["모른 척 지나가는 것이 가장 안전하다","놀림은 장난이니 신경 쓰지 않아도 된다","옳지 않은 일을 보면 용기 내어 말하는 것이 중요하다","말이 느린 친구는 놀림을 받아도 괜찮다"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"망설이다","choices":["곧바로 결정하다","확신에 차 있다","머뭇거리며 결정을 못하다","신나게 행동하다"],"answerIndex":2},{"type":"proverb","word":"가재는 게 편이다","choices":["가재와 게는 서로 싸운다는 뜻이에요","가재는 게보다 크다는 뜻이에요","바다 생물은 육지에서 못 산다는 뜻이에요","비슷한 처지의 사람끼리 편을 든다는 뜻이에요"],"answerIndex":3},{"type":"synonym","word":"머쓱하다","choices":["무안하다","떳떳하다","당당하다","자랑스럽다"],"answerIndex":0},{"type":"antonym","word":"망설이다","choices":["주저하다","결단하다","머뭇거리다","고민하다"],"answerIndex":1},{"type":"spelling","word":"낚시꾼","choices":["낙시꾼","낚싣꾼","낚시꾼","낙싣꾼"],"answerIndex":2}]'::jsonb, 170)
