insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('sports-day-postponed-dust', '🌫️', '미세먼지로 미뤄진 체육대회', '["몇 주간 기다려온 체육대회 날 아침, 하늘이 뿌옇게 흐려 있었어요.","미세먼지 경보가 발령되어 체육대회는 결국 다음 달로 연기되었어요.","반 아이들은 크게 실망하며 여기저기서 아쉬운 탄식이 터져 나왔어요.","설상가상으로 그날 오후에는 강당 공사까지 겹쳐 체육관도 쓸 수 없게 되었어요.","담임 선생님은 실망한 아이들을 보며 교실에서 할 수 있는 미니 게임 대회를 제안하셨어요.","아이들은 처음엔 시큰둥했지만, 막상 시작하니 웃음소리가 끊이지 않았어요.","퀴즈 게임과 손동작 놀이로 반 전체가 하나가 되어 즐거운 시간을 보냈어요.","체육대회는 아니었지만, 아이들은 예상치 못한 재미를 발견했어요.","선생님은 \"안 좋은 일이 겹쳐도 마음먹기에 따라 즐거움을 찾을 수 있단다\"라고 말씀하셨어요."]'::jsonb, '[{"word":"설상가상","meaning":"난처한 일이 겹치는 것"},{"word":"시큰둥하다","meaning":"달갑지 않아 무관심하거나 시들한 태도이다"}]'::jsonb, '[{"answer":true,"statement":"체육대회는 미세먼지 때문에 연기되었다."},{"answer":false,"statement":"그날 강당도 문제없이 사용할 수 있었다."},{"answer":false,"statement":"아이들은 교실 게임을 전혀 즐기지 못했다."}]'::jsonb, '{"choices":["체육대회가 취소되면 아무것도 할 수 없다","미세먼지는 신경 쓸 필요가 없다","교실 게임은 체육대회보다 항상 재미없다","안 좋은 일이 겹쳐도 마음먹기에 따라 즐거움을 찾을 수 있다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"설상가상","choices":["좋은 일이 겹치는 것","아무 일도 없는 것","일이 순조롭게 풀리는 것","난처한 일이 겹치는 것"],"answerIndex":3},{"type":"proverb","word":"산 넘어 산이다","choices":["어려운 일을 하나 넘으면 또 다른 어려운 일이 기다리고 있다는 뜻이에요","산은 오를수록 낮아진다는 뜻이에요","산 위에 오르면 편히 쉴 수 있다는 뜻이에요","여행은 항상 힘들다는 뜻이에요"],"answerIndex":0},{"type":"synonym","word":"시큰둥하다","choices":["열성적이다","무관심하다","적극적이다","기대에 차다"],"answerIndex":1},{"type":"antonym","word":"시큰둥하다","choices":["무관심하다","시들하다","열성적이다","심드렁하다"],"answerIndex":2},{"type":"spelling","word":"통틀어","choices":["통털어","통트러","통틀려","통틀어"],"answerIndex":3}]'::jsonb, 171)
