insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('grandpa-old-story-history-interest', '👴', '할아버지의 옛이야기', '["방학 숙제로 가족의 옛이야기를 조사해 오라는 과제가 나왔어요.","지우는 별생각 없이 할아버지께 어릴 적 이야기를 여쭈어보았어요.","할아버지는 전쟁 직후 어렵던 시절과 마을에서 함께 학교를 세운 이야기를 들려주셨어요.","지우는 할아버지가 그렇게 특별한 경험을 가지고 계셨는지 전혀 몰랐어요.","이야기를 들을수록 지우는 역사가 먼 옛날 책 속 이야기가 아니라는 걸 느꼈어요.","지우는 할아버지의 이야기를 꼼꼼히 받아 적고 사진도 함께 찍어 정리했어요.","발표 시간에 지우의 생생한 이야기에 반 친구들 모두 귀를 기울였어요.","선생님도 살아있는 역사 이야기라며 크게 칭찬해 주셨어요.","지우는 그 뒤로 역사책을 훨씬 더 흥미롭게 읽게 되었어요."]'::jsonb, '[{"word":"꼼꼼히","meaning":"빈틈없이 자세하고 찬찬하게"},{"word":"흥미롭다","meaning":"관심을 끄는 재미가 있다"}]'::jsonb, '[{"answer":true,"statement":"지우는 할아버지의 옛이야기를 전혀 몰랐었다."},{"answer":false,"statement":"할아버지의 이야기는 지우에게 지루하게 느껴졌다."},{"answer":true,"statement":"지우는 발표 후 역사에 더 흥미를 갖게 되었다."}]'::jsonb, '{"choices":["가까운 사람의 이야기 속에서도 소중한 역사를 발견할 수 있다","옛이야기는 아이들에게 지루하기만 하다","역사는 책에서만 배울 수 있다","숙제는 최대한 간단히 끝내는 것이 좋다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"꼼꼼히","choices":["빈틈없이 자세하게","대충대충","빠르고 대강","느긋하게 천천히"],"answerIndex":0},{"type":"proverb","word":"열 길 물속은 알아도 한 길 사람 속은 모른다","choices":["물속은 절대 알 수 없다는 뜻이에요","사람의 속마음은 겉으로 다 알기 어렵다는 뜻이에요","사람은 물보다 깊다는 뜻이에요","길이는 잴 수 없다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"흥미롭다","choices":["지루하다","따분하다","재미있다","심심하다"],"answerIndex":2},{"type":"antonym","word":"흥미롭다","choices":["재미있다","즐겁다","신난다","지루하다"],"answerIndex":3},{"type":"spelling","word":"빈털터리","choices":["빈털터리","빈털털이","빈텅터리","빈턴터리"],"answerIndex":0}]'::jsonb, 172)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('quiz-contest-quiet-hero', '🏆', '반대항 퀴즈대회의 숨은 활약', '["학년 전체가 참여하는 반대항 퀴즈대회가 열렸어요.","우리 반 대표팀은 평소 말이 없고 조용한 시우를 마지막 자리에 앉혔어요.","몇몇 친구들은 시우가 큰 도움이 안 될 거라고 수군거렸어요.","경기 중반, 아무도 풀지 못한 어려운 과학 문제가 나왔어요.","그때 조용히 있던 시우가 손을 들어 정확한 답을 말했어요.","교실에는 놀라움과 함께 큰 박수가 터져 나왔어요.","시우 덕분에 우리 반은 근소한 차이로 우승을 차지했어요.","친구들은 그제야 시우가 평소에도 꾸준히 책을 많이 읽어 왔다는 것을 알게 되었어요.","반 아이들은 겉모습만으로 친구를 판단했던 것을 반성했어요."]'::jsonb, '[{"word":"수군거리다","meaning":"낮은 목소리로 자꾸 이야기하다"},{"word":"근소하다","meaning":"정도나 차이가 아주 작다"}]'::jsonb, '[{"answer":false,"statement":"시우는 평소 말이 많고 활발한 성격이었다."},{"answer":true,"statement":"시우는 어려운 문제의 답을 맞혔다."},{"answer":false,"statement":"우리 반은 큰 점수 차이로 우승했다."},{"answer":true,"statement":"친구들은 시우를 다시 보게 되었다."}]'::jsonb, '{"choices":["조용한 사람은 도움이 되지 않는다","겉모습만으로 사람의 능력을 판단해서는 안 된다","퀴즈대회는 시끄러운 사람이 유리하다","책을 많이 읽는 것은 소용없다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"수군거리다","choices":["큰 소리로 발표하다","낮은 목소리로 자꾸 이야기하다","조용히 혼자 생각하다","활짝 웃으며 인사하다"],"answerIndex":1},{"type":"proverb","word":"물이 깊을수록 소리가 없다","choices":["깊은 물은 위험하다는 뜻이에요","물소리는 얕을수록 크다는 뜻이에요","능력이 뛰어난 사람일수록 겉으로 요란하지 않다는 뜻이에요","물은 깊을수록 차갑다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"근소하다","choices":["크다","엄청나다","거대하다","미미하다"],"answerIndex":3},{"type":"antonym","word":"근소하다","choices":["크다","미미하다","작다","적다"],"answerIndex":0},{"type":"spelling","word":"부치다","choices":["편지를 붙이다","편지를 부치다","편지를 붇이다","편지를 붓이다"],"answerIndex":1}]'::jsonb, 173)
