insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('transfer-student-first-day-shy', '🚪', '전학 온 첫날의 낯가림', '["리아는 전학 온 첫날, 낯선 교실 문 앞에서 심장이 두근거렸어요.","쉬는 시간에도 누구에게 먼저 말을 걸어야 할지 몰라 자리에서 혼자 책만 들여다보았어요.","점심시간, 짝꿍인 서윤이가 먼저 다가와 함께 밥을 먹자고 말을 걸어 주었어요.","리아는 부끄러워하며 작은 목소리로 고맙다고 대답했어요.","서윤이는 리아가 좋아하는 책 이야기를 물으며 자연스럽게 대화를 이어 갔어요.","며칠이 지나자 리아는 서윤이뿐 아니라 다른 친구들과도 점점 친해졌어요.","한 달 후, 리아는 새로운 친구들과 어울려 운동장에서 뛰노는 사이가 되었어요.","리아는 낯선 곳에서도 먼저 다가와 준 친구 한 명이 얼마나 큰 힘이 되는지 느꼈어요.","리아도 다음에 전학생이 오면 먼저 다가가 주겠다고 다짐했어요."]'::jsonb, '[{"word":"낯가림","meaning":"낯선 사람을 대하기 어려워하는 성질"},{"word":"자연스럽다","meaning":"억지로 꾸미지 않아 순리에 맞고 어색하지 않다"}]'::jsonb, '[{"answer":false,"statement":"리아는 전학 첫날부터 친구들과 쉽게 어울렸다."},{"answer":true,"statement":"서윤이가 먼저 리아에게 말을 걸어 주었다."},{"answer":false,"statement":"리아는 결국 아무와도 친해지지 못했다."}]'::jsonb, '{"choices":["낯가림이 심한 사람과는 친구가 될 수 없다","전학생은 혼자 지내는 것이 편하다","먼저 다가가는 작은 친절이 누군가에게 큰 힘이 될 수 있다","친구는 시간이 지나도 저절로 생기지 않는다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"낯가림","choices":["누구와도 쉽게 친해지는 성질","말을 많이 하는 성질","낯선 사람을 어려워하는 성질","화를 잘 내는 성질"],"answerIndex":2},{"type":"proverb","word":"짚신도 짝이 있다","choices":["짚신은 혼자 신어야 한다는 뜻이에요","짚신은 오래 신을 수 없다는 뜻이에요","짝을 찾는 것은 불가능하다는 뜻이에요","누구에게나 어울리는 짝이 있다는 뜻이에요"],"answerIndex":3},{"type":"synonym","word":"자연스럽다","choices":["편안하다","어색하다","부자연스럽다","억지스럽다"],"answerIndex":0},{"type":"antonym","word":"낯가림","choices":["수줍음","붙임성","내성적","소심함"],"answerIndex":1},{"type":"spelling","word":"딱히","choices":["딱이","딱흐","딱히","딱기"],"answerIndex":2}]'::jsonb, 174)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('library-volunteer-pride', '📖', '도서관 봉사를 하며', '["여름방학, 하람이는 동네 어린이 도서관에서 봉사활동을 시작했어요.","처음 맡은 일은 아이들이 아무렇게나 꽂아 둔 책을 순서대로 정리하는 일이었어요.","생각보다 단순하고 반복적인 일이라 하람이는 조금 지루하게 느껴졌어요.","그러던 어느 날, 한 어린아이가 원하던 그림책을 찾지 못해 울상을 짓고 있었어요.","하람이는 정리해 둔 책장 덕분에 금세 그 책을 찾아 건네주었어요.","아이는 활짝 웃으며 하람이에게 몇 번이고 고맙다고 인사했어요.","그 순간 하람이는 자신이 한 작은 정리가 누군가에게 큰 도움이 되었다는 걸 깨달았어요.","그 후로 하람이는 봉사 시간을 더 즐겁고 성실하게 채워 나갔어요.","하람이는 베푼 만큼 마음속에 뿌듯함이 돌아온다는 것을 느꼈어요."]'::jsonb, '[{"word":"반복적","meaning":"같은 일이 되풀이되는 것"},{"word":"베풀다","meaning":"남에게 도움이 되는 일을 하다"}]'::jsonb, '[{"answer":true,"statement":"하람이는 도서관에서 책 정리 봉사를 했다."},{"answer":false,"statement":"하람이는 처음부터 이 일이 아주 재미있다고 느꼈다."},{"answer":true,"statement":"하람이 덕분에 한 아이가 원하던 책을 찾았다."},{"answer":false,"statement":"하람이는 그 뒤로 봉사를 그만두었다."}]'::jsonb, '{"choices":["봉사는 항상 재미있어야만 가치가 있다","책 정리는 아무나 할 수 없는 어려운 일이다","작은 일은 아무런 의미가 없다","베푸는 마음은 결국 뿌듯함이 되어 돌아온다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"베풀다","choices":["혼자만 이익을 챙기다","남의 것을 빼앗다","아무 일도 하지 않다","남에게 도움이 되는 일을 하다"],"answerIndex":3},{"type":"proverb","word":"되로 주고 말로 받는다","choices":["조금 주고 훨씬 많이 돌려받는다는 뜻이에요","되와 말은 같은 크기라는 뜻이에요","주는 것은 항상 손해라는 뜻이에요","받은 것은 반드시 돌려줘야 한다는 뜻이에요"],"answerIndex":0},{"type":"synonym","word":"반복적","choices":["일회적","되풀이되는","단발적","일시적"],"answerIndex":1},{"type":"antonym","word":"베풀다","choices":["나누다","돕다","빼앗다","선사하다"],"answerIndex":2},{"type":"spelling","word":"뒤처지다","choices":["뒤쳐지다","뒤쳐진다","뒤처진다서","뒤처지다"],"answerIndex":3}]'::jsonb, 175)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('picture-diary-cramming-lesson', '🖍️', '미뤄 둔 그림일기', '["여름방학이 끝나갈 무렵, 유나는 그림일기 40일 치를 하나도 쓰지 않은 것을 깨달았어요.","유나는 급한 마음에 하루 만에 몰아서 다 쓰려고 했어요.","하지만 몇 주 전 있었던 일들이 잘 기억나지 않아 자꾸 손이 멈췄어요.","결국 대충 지어낸 문장과 엉성한 그림으로 겨우 숙제를 채워 넣었어요.","개학 날, 선생님은 유나의 일기에서 날씨와 사건이 앞뒤가 맞지 않는 것을 알아채셨어요.","유나는 부끄러운 마음에 얼굴이 빨개졌어요.","선생님은 화를 내는 대신 \"그날그날 기록하는 습관이 왜 중요한지 알겠지?\"라고 조용히 말씀하셨어요.","유나는 다음 방학부터는 매일 짧게라도 일기를 쓰기로 결심했어요.","미리 조금씩 하는 것이 나중에 몰아서 하는 것보다 훨씬 편하다는 걸 깨달았어요."]'::jsonb, '[{"word":"엉성하다","meaning":"짜임새가 없고 허술하다"},{"word":"알아채다","meaning":"낌새를 미리 눈치채어 알다"}]'::jsonb, '[{"answer":false,"statement":"유나는 그림일기를 매일 꾸준히 써 왔다."},{"answer":true,"statement":"유나는 하루 만에 40일 치 일기를 몰아 쓰려고 했다."},{"answer":false,"statement":"선생님은 유나의 일기가 완벽하다고 칭찬하셨다."}]'::jsonb, '{"choices":["미리미리 조금씩 하는 습관이 나중에 몰아서 하는 것보다 낫다","그림일기는 방학이 끝날 때 한꺼번에 쓰는 것이 효율적이다","선생님께 혼나지만 않으면 대충 써도 괜찮다","일기는 사실과 달라도 상관없다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"엉성하다","choices":["짜임새가 없고 허술하다","빈틈없이 완벽하다","화려하고 정교하다","단단하고 견고하다"],"answerIndex":0},{"type":"proverb","word":"급하면 바늘허리에 실 매어 쓸까","choices":["바늘은 허리부터 꿰어야 한다는 뜻이에요","아무리 급해도 순서를 건너뛸 수는 없다는 뜻이에요","급할 땐 아무 방법이나 써도 된다는 뜻이에요","실은 바늘보다 중요하다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"알아채다","choices":["모르다","놓치다","눈치채다","잊어버리다"],"answerIndex":2},{"type":"antonym","word":"엉성하다","choices":["허술하다","허접하다","부실하다","치밀하다"],"answerIndex":3},{"type":"spelling","word":"낭떠러지","choices":["낭떠러지","낭떨어지","낭떨어져","낭떠러쟈"],"answerIndex":0}]'::jsonb, 176)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('garden-vegetable-thief-forgiveness', '🥬', '텃밭 채소 서리 사건', '["학교 텃밭에서 정성껏 키운 상추와 방울토마토가 어느 날 몇 개 사라졌어요.","반 아이들은 누가 그랬을지 서로 의심하며 술렁였어요.","며칠 뒤, 배가 고팠던 1학년 동생이 몰래 따 먹었다는 것이 밝혀졌어요.","동생은 눈물을 글썽이며 미안하다고 사과했어요.","화가 났던 아이들도 어린 동생의 사정을 듣고 마음이 누그러졌어요.","6학년 반장 도현이는 동생을 혼내는 대신 같이 텃밭을 돌보자고 제안했어요.","그날부터 동생은 매일 방과 후 텃밭에 물을 주는 일을 도왔어요.","텃밭은 다시 무성하게 자라났고, 동생도 채소 가꾸는 재미를 알게 되었어요.","아이들은 화를 내기보다 이해하고 함께한 것이 더 좋은 결과를 만들었다는 걸 느꼈어요."]'::jsonb, '[{"word":"술렁이다","meaning":"어수선하게 소란이 이는 것"},{"word":"누그러지다","meaning":"화나 흥분이 풀려 부드러워지다"}]'::jsonb, '[{"answer":true,"statement":"텃밭 채소를 가져간 사람은 1학년 동생이었다."},{"answer":false,"statement":"아이들은 동생을 끝까지 심하게 혼냈다."},{"answer":true,"statement":"동생은 그 뒤로 텃밭 돌보는 것을 도왔다."},{"answer":false,"statement":"텃밭은 그 사건 이후로 더 이상 자라지 못했다."}]'::jsonb, '{"choices":["잘못은 무조건 크게 벌해야 한다","이해하고 함께하는 태도가 화를 내는 것보다 더 좋은 결과를 만든다","어린 동생의 실수는 그냥 넘어가면 된다","텃밭은 아이들이 가꿀 수 없는 곳이다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"누그러지다","choices":["화가 점점 더 커지다","화나 흥분이 풀려 부드러워지다","갑자기 놀라다","아무 감정도 없다"],"answerIndex":1},{"type":"proverb","word":"세 살 버릇 여든까지 간다","choices":["여든 살이 되면 버릇이 저절로 없어진다는 뜻이에요","세 살 아이는 버릇이 없다는 뜻이에요","어릴 때 든 버릇은 늙어서도 고치기 어렵다는 뜻이에요","버릇은 나이와 관계없다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"술렁이다","choices":["잠잠하다","고요하다","차분하다","어수선하다"],"answerIndex":3},{"type":"antonym","word":"누그러지다","choices":["격해지다","가라앉다","풀리다","진정되다"],"answerIndex":0},{"type":"spelling","word":"통째로","choices":["통채로","통째로","통짜로","통채루"],"answerIndex":1}]'::jsonb, 177)
