insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('deskmate-fight-reconciliation', '🤝', '짝꿍과 다툰 뒤 화해하기', '["지훈이와 짝꿍 은우는 사물함 자리를 두고 사소한 말다툼을 벌였어요.","서로 자존심을 굽히지 않다가 결국 하루 종일 말을 하지 않게 되었어요.","다음 날 지훈이는 은우 없이 혼자 급식을 먹으니 왠지 허전한 기분이 들었어요.","쉬는 시간, 지훈이는 답답한 마음에 지푸라기라도 잡는 심정으로 은우에게 먼저 말을 걸어 보기로 했어요.","\"어제는 나도 너무 예민했던 것 같아, 미안해\" 하고 조심스럽게 사과했어요.","은우도 머뭇거리다가 \"나도 사물함 문제로 너무 화냈어, 미안해\" 하고 답했어요.","둘은 사물함을 요일별로 나눠 쓰기로 새롭게 약속을 정했어요.","화해한 뒤 둘은 예전보다 더 편하게 이야기를 나누게 되었어요.","지훈이는 먼저 다가가는 용기가 관계를 회복시킨다는 것을 배웠어요."]'::jsonb, '[{"word":"허전하다","meaning":"무엇을 잃거나 텅 빈 것처럼 서운하다"},{"word":"예민하다","meaning":"자극에 대해 지나치게 민감하다"}]'::jsonb, '[{"answer":true,"statement":"지훈이와 은우는 사물함 자리 때문에 다투었다."},{"answer":false,"statement":"둘은 그 뒤로 다시는 말을 하지 않았다."},{"answer":true,"statement":"지훈이가 먼저 사과의 말을 건넸다."}]'::jsonb, '{"choices":["다툰 뒤에는 절대 먼저 사과하면 안 된다","짝꿍과는 항상 싸우게 마련이다","먼저 다가가 사과하는 용기가 관계를 회복시킨다","사물함 문제는 해결할 방법이 없다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"허전하다","choices":["가득 차서 뿌듯하다","신이 나고 즐겁다","무엇을 잃은 듯 서운하다","편안하고 안정되다"],"answerIndex":2},{"type":"proverb","word":"물에 빠지면 지푸라기라도 잡는다","choices":["지푸라기는 물에 뜨지 않는다는 뜻이에요","물에 빠지면 아무것도 할 수 없다는 뜻이에요","지푸라기를 미리 준비해야 한다는 뜻이에요","위급할 때는 작은 도움에도 매달리게 된다는 뜻이에요"],"answerIndex":3},{"type":"synonym","word":"예민하다","choices":["민감하다","둔감하다","무디다","느긋하다"],"answerIndex":0},{"type":"antonym","word":"예민하다","choices":["민감하다","둔감하다","날카롭다","섬세하다"],"answerIndex":1},{"type":"spelling","word":"재작년","choices":["제작년","재작연","재작년","제작연"],"answerIndex":2}]'::jsonb, 178)
