insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('swimming-fear-overcome', '🏊', '수영대회를 앞둔 두려움', '["여름이는 학교 대표로 교내 수영대회에 나가게 되었지만, 물에 대한 두려움이 남아 있었어요.","특히 깊은 물에 들어갈 때마다 숨이 가빠지고 팔다리가 뻣뻣해졌어요.","코치 선생님은 여름이에게 조급해하지 말고 천천히 호흡법부터 다시 연습하자고 하셨어요.","여름이는 매일 방과 후 남아 얕은 물에서부터 차근차근 연습을 반복했어요.","처음엔 25미터도 힘겨웠지만, 한 달이 지나자 50미터를 거뜬히 헤엄칠 수 있게 되었어요.","대회 당일, 여름이는 여전히 긴장했지만 연습한 대로 침착하게 출발했어요.","비록 1등은 하지 못했지만, 여름이는 자신의 최고 기록을 경신했어요.","부모님과 코치 선생님은 여름이의 용기와 성장을 크게 축하해 주었어요.","여름이는 두려움을 이겨내고 도전한 자신이 정말 자랑스러웠어요."]'::jsonb, '[{"word":"거뜬히","meaning":"다루기 쉽고 가벼운 정도로"},{"word":"경신하다","meaning":"종전의 기록을 깨뜨리다"}]'::jsonb, '[{"answer":false,"statement":"여름이는 원래 물을 전혀 무서워하지 않았다."},{"answer":true,"statement":"여름이는 매일 방과 후 연습했다."},{"answer":true,"statement":"여름이는 대회에서 자신의 최고 기록을 경신했다."},{"answer":false,"statement":"여름이는 대회에서 1등을 차지했다."}]'::jsonb, '{"choices":["1등을 하지 못하면 노력은 의미가 없다","물을 무서워하는 사람은 수영을 배울 수 없다","코치의 도움 없이는 아무것도 배울 수 없다","두려움을 극복하고 꾸준히 노력하면 스스로 성장할 수 있다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"거뜬히","choices":["매우 힘겹고 무겁게","느리고 답답하게","위험하고 아슬아슬하게","다루기 쉽고 가볍게"],"answerIndex":3},{"type":"proverb","word":"개천에서 용 난다","choices":["어려운 환경에서도 훌륭한 인물이 나올 수 있다는 뜻이에요","개천에는 용이 살 수 없다는 뜻이에요","용은 큰 강에서만 산다는 뜻이에요","개천은 위험한 곳이라는 뜻이에요"],"answerIndex":0},{"type":"synonym","word":"경신하다","choices":["유지하다","갱신하다","포기하다","머무르다"],"answerIndex":1},{"type":"antonym","word":"거뜬히","choices":["가뿐히","수월하게","힘겹게","쉽게"],"answerIndex":2},{"type":"spelling","word":"삼가다","choices":["삼가하다","삼가하고","삼가함","삼가다"],"answerIndex":3}]'::jsonb, 179)
