insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('presentation-forgotten-script-improvise', '🎤', '발표 대본을 잊어버린 순간', '["국어 시간 발표를 앞두고 은서는 대본을 몇 번이고 외웠어요.","그런데 정작 발표 순서가 되어 앞에 서자 머릿속이 하얘지며 대본이 하나도 떠오르지 않았어요.","몇 초간 정적이 흐르자 은서는 식은땀이 났어요.","은서는 대본 대신 자신이 직접 겪은 일을 예로 들어 즉흥적으로 이야기를 이어갔어요.","생각보다 자연스럽게 말이 이어졌고, 오히려 친구들이 더 집중해서 들어 주었어요.","발표를 마친 뒤 선생님은 준비한 것 못지않게 순발력 있는 대응이 훌륭했다고 칭찬해 주셨어요.","은서는 완벽한 대본보다 진심을 담아 말하는 것이 더 큰 힘이 된다는 것을 깨달았어요.","그날 이후 은서는 발표할 때 대본에만 의존하지 않고 자신의 말로 표현하는 연습을 시작했어요.","은서의 발표 실력은 그 사건을 계기로 부쩍 늘었어요."]'::jsonb, '[{"word":"정적","meaning":"고요하여 아무 소리도 없는 상태"},{"word":"순발력","meaning":"갑작스러운 상황에 재빠르게 대응하는 힘"}]'::jsonb, '[{"answer":true,"statement":"은서는 발표 중 대본을 다 잊어버렸다."},{"answer":false,"statement":"은서는 발표를 포기하고 자리에 앉았다."},{"answer":true,"statement":"선생님은 은서의 대응을 칭찬했다."}]'::jsonb, '{"choices":["예상치 못한 상황에서도 진심을 담아 대응하면 좋은 결과를 얻을 수 있다","대본을 완벽히 외우지 못하면 발표는 실패한 것이다","발표는 항상 대본 그대로 읽어야 한다","긴장하면 발표를 하지 않는 것이 좋다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"정적","choices":["고요하여 소리가 없는 상태","시끄럽고 소란스러운 상태","밝고 화려한 상태","따뜻하고 포근한 상태"],"answerIndex":0},{"type":"proverb","word":"개똥도 약에 쓰려면 없다","choices":["개똥은 약으로 쓸 수 없다는 뜻이에요","흔한 것도 막상 필요할 때는 찾기 어렵다는 뜻이에요","약은 항상 넉넉히 준비해야 한다는 뜻이에요","필요 없는 것은 버려야 한다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"순발력","choices":["무기력","둔감함","대응력","느긋함"],"answerIndex":2},{"type":"antonym","word":"정적","choices":["고요함","적막함","잠잠함","소란함"],"answerIndex":3},{"type":"spelling","word":"봉우리","choices":["봉우리","봉오리","봉오르","봉우르"],"answerIndex":0}]'::jsonb, 180)
