insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('robot-project-with-dad-rumor', '🤖', '아빠와 함께 만든 로봇', '["과학 발명대회를 앞두고 준혁이는 아빠와 함께 주말마다 로봇을 만들기 시작했어요.","처음에는 부품끼리 자꾸 어긋나 로봇이 제대로 움직이지 않았어요.","준혁이와 아빠는 설명서를 몇 번이고 다시 살피며 조금씩 문제를 고쳐 나갔어요.","드디어 발명대회 전날 밤, 로봇이 스스로 장애물을 피해 움직이는 데 성공했어요.","대회 당일 준혁이의 로봇은 무사히 미션을 완수해 큰 박수를 받았어요.","이 소식은 발 없는 말이 천 리 가듯 순식간에 학교 전체에 퍼졌어요.","다른 반 친구들까지 찾아와 로봇 만드는 비법을 물어볼 정도였어요.","준혁이는 인터뷰에서 아빠와 함께한 시간이 가장 값진 상이었다고 말했어요.","준혁이와 아빠는 그 뒤로도 함께 새로운 발명품을 만들기로 약속했어요."]'::jsonb, '[{"word":"어긋나다","meaning":"서로 맞지 않고 틀어지다"},{"word":"완수하다","meaning":"뜻한 바를 완전히 이루다"}]'::jsonb, '[{"answer":true,"statement":"준혁이는 아빠와 함께 로봇을 만들었다."},{"answer":false,"statement":"로봇은 처음부터 완벽하게 작동했다."},{"answer":false,"statement":"로봇 대회 소식은 학교에 전혀 알려지지 않았다."},{"answer":true,"statement":"준혁이는 아빠와 함께한 시간을 가장 값지게 여겼다."}]'::jsonb, '{"choices":["발명품은 혼자 만들어야 진짜 실력이다","실패를 반복하며 함께 노력한 과정 자체가 큰 의미를 갖는다","대회에서 상을 받는 것이 가장 중요하다","부모님의 도움을 받는 것은 부끄러운 일이다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"어긋나다","choices":["정확히 딱 들어맞다","서로 맞지 않고 틀어지다","가지런히 정돈되다","매끄럽게 연결되다"],"answerIndex":1},{"type":"proverb","word":"발 없는 말이 천 리 간다","choices":["말을 하지 않으면 소문이 나지 않는다는 뜻이에요","천 리 길은 걸어서 가야 한다는 뜻이에요","소문은 순식간에 멀리까지 퍼진다는 뜻이에요","말에는 발이 달려 있다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"완수하다","choices":["실패하다","포기하다","미루다","이루다"],"answerIndex":3},{"type":"antonym","word":"완수하다","choices":["포기하다","성취하다","이루다","달성하다"],"answerIndex":0},{"type":"spelling","word":"어쭙잖다","choices":["어줍잖다","어쭙잖다","어쭙짢다","어줍짢다"],"answerIndex":1}]'::jsonb, 181)
