insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('school-bus-seat-regret', '🚌', '통학버스에서 놓친 자리 양보', '["아침 통학버스 안, 세연이는 창가 자리에 앉아 이어폰을 끼고 음악을 듣고 있었어요.","다음 정류장에서 짐을 든 할머니 한 분이 타셨지만, 세연이는 음악에 빠져 알아채지 못했어요.","바로 앞자리에 앉은 친구가 먼저 일어나 자리를 양보하는 모습을 보고 나서야 상황을 깨달았어요.","세연이는 그렇게 가까이 계셨는데도 전혀 눈치채지 못한 것이 부끄러웠어요.","그날 밤 세연이는 앞으로 버스에서는 이어폰 볼륨을 줄이고 주변을 살피기로 다짐했어요.","다음 날 아침, 세연이는 버스에 타자마자 주위를 한번 둘러보는 습관을 들였어요.","며칠 뒤, 다리를 다친 친구가 목발을 짚고 버스에 올라탔어요.","이번에는 세연이가 가장 먼저 자리에서 일어나 자리를 양보했어요.","세연이는 작은 관심이 주변을 더 따뜻하게 만든다는 것을 배웠어요."]'::jsonb, '[{"word":"눈치채다","meaning":"남의 마음이나 상황을 미리 알아차리다"},{"word":"다짐하다","meaning":"마음을 굳게 정하다"}]'::jsonb, '[{"answer":false,"statement":"세연이는 처음에 할머니가 타신 것을 바로 알아챘다."},{"answer":true,"statement":"친구가 먼저 할머니께 자리를 양보했다."},{"answer":false,"statement":"세연이는 그 후로도 계속 무관심하게 지냈다."}]'::jsonb, '{"choices":["이어폰은 버스 안에서 사용해서는 안 된다","자리 양보는 어른들만 해야 하는 일이다","가까운 주변에 조금만 관심을 기울이면 더 따뜻한 배려를 할 수 있다","버스에서는 항상 조용히 있어야 한다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"눈치채다","choices":["전혀 모르다","일부러 무시하다","미리 알아차리다","잊어버리다"],"answerIndex":2},{"type":"proverb","word":"낙숫물이 댓돌을 뚫는다","choices":["물은 돌보다 약하다는 뜻이에요","빗물은 위험하다는 뜻이에요","한 번의 노력으로 충분하다는 뜻이에요","작은 노력도 꾸준히 계속하면 큰 결과를 이룰 수 있다는 뜻이에요"],"answerIndex":3},{"type":"synonym","word":"다짐하다","choices":["결심하다","포기하다","망설이다","미루다"],"answerIndex":0},{"type":"antonym","word":"눈치채다","choices":["알아차리다","놓치다","간파하다","감지하다"],"answerIndex":1},{"type":"spelling","word":"희한하다","choices":["희안하다","희환하다","희한하다","히한하다"],"answerIndex":2}]'::jsonb, 182)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('winter-break-reading-envy-motivation', '📕', '독서왕 상장을 보고 부러웠던 마음', '["겨울방학이 끝난 개학식 날, 담임 선생님은 방학 동안 가장 많은 책을 읽은 친구에게 ''독서왕'' 상장을 주셨어요.","상을 받은 친구는 다름 아닌 평소 조용했던 서준이였어요.","그 모습을 본 나윤이는 괜히 마음이 콕콕 쑤셨어요.","''나도 책 많이 읽었는데 왜 나는 상을 못 받았지'' 하는 부러운 마음이 자꾸 들었어요.","나윤이는 서운한 마음에 며칠간 서준이를 슬쩍 피하기도 했어요.","그러던 어느 날, 나윤이는 자신이 사실 방학 동안 책을 별로 읽지 않았다는 것을 인정하게 되었어요.","나윤이는 부러워만 하는 대신, 이번 학기부터 매일 조금씩 책을 읽기로 결심했어요.","한 학기가 지나자 나윤이도 스스로 뿌듯할 만큼 많은 책을 읽게 되었어요.","나윤이는 남을 부러워하는 마음보다 스스로 노력하는 것이 훨씬 값지다는 걸 깨달았어요."]'::jsonb, '[{"word":"쑤시다","meaning":"마음이 찌르는 듯 아프고 괴롭다"},{"word":"인정하다","meaning":"확실히 그렇다고 받아들이다"}]'::jsonb, '[{"answer":false,"statement":"독서왕 상장은 나윤이가 받았다."},{"answer":true,"statement":"나윤이는 처음엔 서준이를 부러워했다."},{"answer":false,"statement":"나윤이는 그 뒤로 전혀 책을 읽지 않았다."},{"answer":true,"statement":"나윤이는 한 학기 후 스스로 뿌듯함을 느꼈다."}]'::jsonb, '{"choices":["상장은 조용한 친구만 받을 수 있다","부러운 마음은 절대 가지면 안 된다","독서는 상을 받기 위해서만 하는 것이다","다른 사람을 부러워하기보다 스스로 노력하는 것이 더 값지다"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"쑤시다","choices":["가볍고 상쾌하다","즐겁고 기쁘다","차분하고 편안하다","찌르는 듯 아프고 괴롭다"],"answerIndex":3},{"type":"proverb","word":"사촌이 땅을 사면 배가 아프다","choices":["가까운 사람이 잘되면 오히려 배가 아프도록 부러워한다는 뜻이에요","사촌과는 땅을 함께 사야 한다는 뜻이에요","땅을 사면 배탈이 난다는 뜻이에요","사촌 사이는 항상 사이가 좋다는 뜻이에요"],"answerIndex":0},{"type":"synonym","word":"인정하다","choices":["부인하다","받아들이다","거부하다","무시하다"],"answerIndex":1},{"type":"antonym","word":"인정하다","choices":["수긍하다","받아들이다","부인하다","시인하다"],"answerIndex":2},{"type":"spelling","word":"며칠","choices":["몇일","몇 일","며 칠","며칠"],"answerIndex":3}]'::jsonb, 183)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('shim-cheong-lotus-flower', '🪷', '심청전', '["옛날 앞을 보지 못하는 아버지를 모시고 사는 효심 깊은 딸 심청이 있었어요.","심청은 아버지가 눈을 뜰 수 있다는 말을 듣고, 공양미 삼백 석을 구하기로 결심했어요.","뱃사람들이 바다의 신에게 제물을 바쳐야 한다며 큰돈을 준다고 하자, 심청은 아버지를 위해 배에 올랐어요.","거센 바다 앞에서 심청은 아버지의 눈이 뜨이기를 간절히 빌며 물속에 몸을 던졌어요.","그런데 용왕님이 심청의 효심에 감동하여 그녀를 구해 주었고, 심청은 아름다운 연꽃을 타고 다시 세상으로 돌아왔어요.","연꽃 속에서 나온 심청은 마침내 나라의 왕비가 되었어요.","심청은 아버지를 찾기 위해 온 나라의 눈먼 사람들을 위한 잔치를 열었어요.","잔치에서 딸의 목소리를 들은 아버지는 너무 놀라고 기쁜 나머지 번쩍 눈을 떴답니다.","아버지와 심청은 서로를 부둥켜안고 오래도록 행복하게 살았어요."]'::jsonb, '[{"word":"공양미","meaning":"부처님이나 신령에게 정성으로 올리는 쌀"},{"word":"간절하다","meaning":"마음속에서 우러나와 매우 진실하고 절실하다"},{"word":"감동하다","meaning":"깊이 느껴 마음이 움직이다"}]'::jsonb, '[{"answer":true,"statement":"심청의 아버지는 앞을 보지 못했어요."},{"answer":true,"statement":"심청은 아버지를 위해 배에 올랐어요."},{"answer":false,"statement":"용왕님은 심청을 도와주지 않았어요."},{"answer":false,"statement":"심청의 아버지는 끝까지 눈을 뜨지 못했어요."}]'::jsonb, '{"choices":["부모를 향한 지극한 효심은 결국 좋은 결과로 이어질 수 있어요","바다는 위험하니 가까이 가면 안 돼요","제물을 바치는 것은 좋은 일이에요","눈이 안 보이면 아무것도 할 수 없어요"],"question":"이 이야기가 전하고 싶은 마음은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"공양미","choices":["부처님이나 신령에게 정성으로 올리는 쌀","매일 먹는 평범한 쌀","시장에서 파는 값싼 쌀","동물에게 주는 먹이"],"answerIndex":0},{"type":"vocab","word":"간절하다","choices":["전혀 관심이 없다","마음속에서 우러나와 매우 진실하고 절실하다","화가 나서 소리치다","아주 기쁘고 즐겁다"],"answerIndex":1},{"type":"proverb","word":"지성이면 감천","choices":["아무리 노력해도 소용없다는 뜻이에요","정성이 지나치면 오히려 화를 부른다는 뜻이에요","정성을 다하면 하늘도 감동하여 좋은 결과를 준다는 뜻이에요","하늘은 감동하지 않는다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"간절하다","choices":["무심하다","냉담하다","심드렁하다","절실하다"],"answerIndex":3},{"type":"spelling","word":"며칠","choices":["며칠","몇일","멷칠","며츨"],"answerIndex":0}]'::jsonb, 184)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('toad-repays-favor-centipede', '🐸', '은혜 갚은 두꺼비', '["옛날 마음씨 착한 소녀가 살았는데, 어느 날 작은 두꺼비 한 마리에게 밥을 나누어 주었어요.","소녀는 매일 두꺼비에게 밥을 주며 정성껏 돌보았고, 두꺼비는 소녀를 마치 가족처럼 따랐어요.","어느 날 마을에서는 해마다 처녀 한 명을 지네 요괴에게 바쳐야 한다는 무서운 전설이 있었어요.","제비뽑기에서 하필 그 소녀가 뽑혔고, 마을 사람들은 소녀를 산속 사당으로 데려갔어요.","소녀가 사당에서 두려움에 떨고 있을 때, 그동안 몰래 따라온 두꺼비가 소녀 곁을 지켰어요.","한밤중 커다란 지네가 나타나자 두꺼비는 온 힘을 다해 맞서 싸웠어요.","다음 날 아침, 지네는 사라지고 두꺼비도 지쳐 보이지 않게 되었지만 소녀는 무사했어요.","소녀는 은혜를 갚은 두꺼비를 오래도록 잊지 않고 고맙게 기억했답니다."]'::jsonb, '[{"word":"정성껏","meaning":"온 마음을 다해서"},{"word":"은혜","meaning":"다른 사람에게서 받은 고마운 도움"}]'::jsonb, '[{"answer":true,"statement":"소녀는 두꺼비에게 밥을 나누어 주었어요."},{"answer":false,"statement":"소녀는 제비뽑기에 뽑히지 않았어요."},{"answer":true,"statement":"두꺼비는 소녀를 위해 지네와 맞서 싸웠어요."}]'::jsonb, '{"choices":["동물은 사람을 도울 수 없어요","작은 선행이 큰 은혜로 돌아올 수 있어요","무서운 전설은 모두 거짓이에요","혼자 힘으로만 위기를 이겨내야 해요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"은혜","choices":["아무 의미 없는 행동","다른 사람에게서 받은 고마운 도움","혼자 이룬 성과","잊어버려도 되는 일"],"answerIndex":1},{"type":"proverb","word":"가는 정이 있어야 오는 정이 있다","choices":["정은 원래 오고 가지 않는다는 뜻이에요","가는 사람을 잡지 말라는 뜻이에요","내가 먼저 마음을 주어야 상대도 마음을 준다는 뜻이에요","정이 많으면 손해를 본다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"은혜","choices":["무시","배신","손해","신세"],"answerIndex":3},{"type":"antonym","word":"정성껏","choices":["대충","꼼꼼히","성실히","진심으로"],"answerIndex":0},{"type":"spelling","word":"왠지","choices":["웬지","왠지","웬지는","왠쥐"],"answerIndex":1}]'::jsonb, 185)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('fox-and-crane-dinner-invite', '🦊', '여우와 두루미', '["여우와 두루미는 서로 친하게 지내는 이웃이었어요.","어느 날 여우가 두루미를 저녁 식사에 초대했어요.","여우는 납작한 접시에 수프를 담아 내놓았고, 부리가 긴 두루미는 아무리 애써도 한 방울도 먹을 수 없었어요.","두루미는 서운했지만 내색하지 않고 조용히 자리를 떠났어요.","며칠 뒤 두루미가 여우를 저녁 식사에 초대했어요.","두루미는 목이 좁고 긴 병에 음식을 담아 내놓았고, 이번엔 여우가 전혀 먹을 수 없었어요.","여우는 그제야 지난번 자신의 행동이 두루미를 얼마나 힘들게 했는지 깨닫고 진심으로 사과했어요."]'::jsonb, '[{"word":"내색하다","meaning":"감정을 얼굴이나 말에 드러내다"},{"word":"서운하다","meaning":"마음에 부족하여 아쉽고 섭섭하다"}]'::jsonb, '[{"answer":true,"statement":"여우는 납작한 접시에 수프를 담았어요."},{"answer":false,"statement":"두루미는 여우의 수프를 잘 먹었어요."},{"answer":false,"statement":"여우는 끝까지 자신의 잘못을 몰랐어요."}]'::jsonb, '{"choices":["친구를 초대하는 것은 좋지 않아요","수프는 납작한 접시에 먹어야 해요","상대방의 입장을 배려하며 행동해야 해요","한 번 서운하면 관계를 끊어야 해요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"내색하다","choices":["감정을 마음속에 숨기다","크게 소리 내어 울다","감정을 얼굴이나 말에 드러내다","기쁘게 웃다"],"answerIndex":2},{"type":"vocab","word":"서운하다","choices":["매우 기쁘고 만족스럽다","화가 나서 소리치다","아무 느낌이 없다","마음에 부족하여 아쉽고 섭섭하다"],"answerIndex":3},{"type":"proverb","word":"누워서 침 뱉기","choices":["남을 해치려다 오히려 자기가 피해를 입는다는 뜻이에요","침은 아무 데서나 뱉으면 안 된다는 뜻이에요","누워 있으면 편하다는 뜻이에요","친구는 많을수록 좋다는 뜻이에요"],"answerIndex":0},{"type":"synonym","word":"서운하다","choices":["기쁘다","섭섭하다","즐겁다","편안하다"],"answerIndex":1},{"type":"spelling","word":"어이없다","choices":["어의없다","어히없다","어이없다","어이업다"],"answerIndex":2}]'::jsonb, 186)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('wolf-and-seven-kids', '🐑', '늑대와 일곱 마리 아기 양', '["엄마 양은 먹이를 구하러 나가며 아기 양 일곱 마리에게 아무에게도 문을 열어주지 말라고 신신당부했어요.","엄마가 나가자마자 늑대가 문을 두드리며 걸걸한 목소리로 엄마 흉내를 냈어요.","아기 양들은 목소리가 이상하다는 것을 눈치채고 문을 열지 않았어요.","늑대는 꾀를 내어 발에 밀가루를 묻혀 하얗게 만들고 다시 찾아왔어요.","막내 아기 양이 문틈으로 늑대의 까만 발을 발견하고 다른 형제들에게 알렸어요.","아기 양들은 재빨리 옷장 속에 숨어 늑대를 피했어요.","엄마 양이 돌아와 이야기를 듣고는 지혜롭게 대처한 아기 양들을 크게 칭찬해 주었어요."]'::jsonb, '[{"word":"신신당부하다","meaning":"여러 번 간곡히 부탁하다"},{"word":"눈치채다","meaning":"남의 마음이나 상황을 미루어 알아차리다"}]'::jsonb, '[{"answer":true,"statement":"엄마 양은 문을 열어주지 말라고 당부했어요."},{"answer":false,"statement":"아기 양들은 늑대의 목소리를 바로 엄마 목소리로 믿었어요."},{"answer":true,"statement":"막내 아기 양이 늑대의 까만 발을 발견했어요."}]'::jsonb, '{"choices":["낯선 소리는 무조건 무시해도 돼요","혼자 있을 때는 아무것도 하면 안 돼요","약속은 지키지 않아도 괜찮아요","조심성과 지혜로 위험을 잘 피할 수 있어요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"신신당부하다","choices":["한 번도 말하지 않다","화를 내며 명령하다","조용히 부탁하다","여러 번 간곡히 부탁하다"],"answerIndex":3},{"type":"vocab","word":"눈치채다","choices":["남의 마음이나 상황을 미루어 알아차리다","전혀 알아차리지 못하다","크게 소리치다","무시하고 지나치다"],"answerIndex":0},{"type":"proverb","word":"자라 보고 놀란 가슴 솥뚜껑 보고도 놀란다","choices":["자라와 솥뚜껑은 생김새가 같다는 뜻이에요","한 번 놀란 경험 때문에 비슷한 것만 봐도 겁을 낸다는 뜻이에요","가슴이 아프면 병원에 가야 한다는 뜻이에요","겁이 많은 사람은 자라를 키우면 안 된다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"눈치채다","choices":["무시하다","잊어버리다","알아차리다","속다"],"answerIndex":2},{"type":"spelling","word":"설거지","choices":["설겆이","설것이","설걷이","설거지"],"answerIndex":3}]'::jsonb, 187)
