insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('frog-prince-broken-promise', '🐸', '개구리 왕자', '["공주는 연못가에서 놀다가 황금 공을 물에 빠뜨리고 말았어요.","개구리 한 마리가 나타나 친구가 되어 준다면 공을 찾아 주겠다고 했어요.","공주는 얼른 그러겠다고 대답했지만, 공을 돌려받자마자 개구리와의 약속을 잊고 성으로 돌아가 버렸어요.","다음 날 개구리가 성문 앞에 찾아와 약속을 지켜 달라고 부탁했어요.","임금님은 한 번 한 약속은 반드시 지켜야 한다며 공주를 타일렀어요.","공주는 마지못해 개구리와 함께 식사도 하고 시간을 보내며 점점 진심으로 친해졌어요.","그러던 어느 날 개구리는 마법이 풀리며 멋진 왕자로 변했고, 둘은 진정한 친구가 되었답니다."]'::jsonb, '[{"word":"타이르다","meaning":"잘 알아듣도록 부드럽게 말하다"},{"word":"마지못해","meaning":"내키지 않지만 하는 수 없이"}]'::jsonb, '[{"answer":true,"statement":"공주는 황금 공을 연못에 빠뜨렸어요."},{"answer":false,"statement":"공주는 개구리와의 약속을 바로 지켰어요."},{"answer":true,"statement":"임금님은 약속을 지키라고 타일렀어요."}]'::jsonb, '{"choices":["한 번 한 약속은 소중히 여기고 지켜야 해요","개구리와는 친구가 될 수 없어요","공주는 거짓말을 해도 괜찮아요","약속은 상황에 따라 잊어도 돼요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"타이르다","choices":["잘 알아듣도록 부드럽게 말하다","화를 내며 소리치다","못 본 척 무시하다","억지로 시키다"],"answerIndex":0},{"type":"vocab","word":"마지못해","choices":["기쁜 마음으로 스스로","내키지 않지만 하는 수 없이","전혀 관심 없이","신나고 즐겁게"],"answerIndex":1},{"type":"proverb","word":"한번 뱉은 말은 주워 담을 수 없다","choices":["말은 아무리 해도 상관없다는 뜻이에요","말을 많이 할수록 좋다는 뜻이에요","한 번 한 말이나 약속은 함부로 하면 안 된다는 뜻이에요","약속은 원래 지키지 않아도 된다는 뜻이에요"],"answerIndex":2},{"type":"antonym","word":"마지못해","choices":["억지로","마지못해서","떠밀려서","기꺼이"],"answerIndex":3},{"type":"spelling","word":"오랜만","choices":["오랜만","오랫만","오랜동안만","오랫동안"],"answerIndex":0}]'::jsonb, 188)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('lion-and-mouse-kindness', '🦁', '사자와 생쥐', '["낮잠을 자던 사자의 몸 위로 작은 생쥐가 실수로 지나가다 사자를 깨우고 말았어요.","화가 난 사자가 생쥐를 잡았지만, 생쥐는 언젠가 은혜를 갚겠다며 살려 달라고 빌었어요.","사자는 피식 웃으며 작은 생쥐가 무슨 도움이 되겠냐면서도 순순히 놓아주었어요.","며칠 뒤 사자는 사냥꾼이 쳐 놓은 그물에 걸려 꼼짝도 할 수 없게 되었어요.","그때 생쥐가 나타나 날카로운 이빨로 그물을 밤새 갉아 사자를 구해 주었어요.","사자는 작다고 무시했던 생쥐의 도움에 크게 감사하며 진심으로 미안해했어요.","그 뒤로 사자와 생쥐는 서로를 존중하는 진짜 친구가 되었답니다."]'::jsonb, '[{"word":"순순히","meaning":"고분고분하고 순하게"},{"word":"갉다","meaning":"이로 조금씩 자꾸 물어뜯다"}]'::jsonb, '[{"answer":true,"statement":"생쥐는 사자를 실수로 깨웠어요."},{"answer":false,"statement":"사자는 생쥐를 끝까지 잡아먹었어요."},{"answer":true,"statement":"생쥐는 그물을 갉아 사자를 구했어요."}]'::jsonb, '{"choices":["힘이 센 존재만 도움을 줄 수 있어요","아무리 작은 존재라도 큰 도움을 줄 수 있어요","작은 동물은 무시해도 괜찮아요","은혜는 갚지 않아도 상관없어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"순순히","choices":["화를 내며 거칠게","고분고분하고 순하게","억지로 반항하며","몰래 숨어서"],"answerIndex":1},{"type":"vocab","word":"갉다","choices":["한입에 삼키다","손으로 두드리다","이로 조금씩 자꾸 물어뜯다","발로 밟다"],"answerIndex":2},{"type":"proverb","word":"작은 고추가 맵다","choices":["고추는 작을수록 맛이 없다는 뜻이에요","큰 것이 항상 좋다는 뜻이에요","매운 음식은 몸에 좋지 않다는 뜻이에요","몸집이 작아도 재주나 능력이 뛰어날 수 있다는 뜻이에요"],"answerIndex":3},{"type":"synonym","word":"순순히","choices":["고분고분","반항하며","억지로","거칠게"],"answerIndex":0},{"type":"spelling","word":"뒤처지다","choices":["뒤쳐지다","뒤처지다","뒤처치다","뒤쳐치다"],"answerIndex":1}]'::jsonb, 189)
