insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('peter-pan-neverland-adventure', '🧚', '피터팬', '["웬디와 동생들은 어느 밤 창문으로 날아든 소년 피터팬을 만나게 되었어요.","피터팬은 요정 가루를 뿌려 아이들에게 하늘을 나는 법을 가르쳐 주었어요.","아이들은 피터팬을 따라 네버랜드라는 신비한 섬으로 함께 날아갔어요.","네버랜드에는 장난꾸러기 요정 팅커벨과 씩씩한 아이들이 살고 있었어요.","어느 날 후크 선장이 아이들을 위협했지만, 피터팬은 꾀와 용기로 모두를 지켜냈어요.","신나는 모험을 마친 웬디는 문득 집이 그리워졌고, 동생들과 함께 집으로 돌아가기로 했어요.","피터팬은 아쉬워하면서도 웬디의 선택을 존중하며 따뜻하게 배웅해 주었어요."]'::jsonb, '[{"word":"신비하다","meaning":"이상하고 신기하여 잘 알 수 없다"},{"word":"배웅하다","meaning":"떠나는 사람을 일정한 곳까지 나가서 보내다"}]'::jsonb, '[{"answer":true,"statement":"피터팬은 아이들에게 나는 법을 가르쳐 주었어요."},{"answer":false,"statement":"네버랜드에는 아무도 살지 않았어요."},{"answer":true,"statement":"웬디는 결국 집으로 돌아가기로 했어요."}]'::jsonb, '{"choices":["모험을 떠나면 다시는 집에 갈 수 없어요","요정은 존재하지 않아요","신나는 모험도 좋지만 소중한 것을 지키는 용기와 그리움도 중요해요","후크 선장은 착한 사람이에요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"신비하다","choices":["아주 평범하고 흔하다","지루하고 재미없다","이상하고 신기하여 잘 알 수 없다","무섭고 두렵다"],"answerIndex":2},{"type":"vocab","word":"배웅하다","choices":["오는 사람을 문 앞에서 맞이하다","혼자 조용히 있다","화를 내며 쫓아내다","떠나는 사람을 일정한 곳까지 나가서 보내다"],"answerIndex":3},{"type":"proverb","word":"가랑비에 옷 젖는 줄 모른다","choices":["작은 일이 반복되면 나도 모르게 큰 영향을 받는다는 뜻이에요","비가 오면 꼭 우산을 챙겨야 한다는 뜻이에요","작은 비는 맞아도 괜찮다는 뜻이에요","옷은 마르면 그만이라는 뜻이에요"],"answerIndex":0},{"type":"synonym","word":"신비하다","choices":["평범하다","신기하다","흔하다","단순하다"],"answerIndex":1},{"type":"spelling","word":"희한하다","choices":["희안하다","희환하다","희한하다","히한하다"],"answerIndex":2}]'::jsonb, 190)
