insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('jungle-book-mowgli-friendship', '🐯', '정글북', '["아기였을 때 정글에 홀로 남겨진 모글리는 늑대 무리의 보살핌을 받으며 자랐어요.","모글리는 지혜로운 곰 발루에게 정글에서 살아가는 법을 배웠어요.","검은 표범 바기라는 모글리를 친자식처럼 아끼며 늘 곁에서 지켜 주었어요.","어느 날 사나운 호랑이 시어칸이 모글리를 위협하며 나타났어요.","모글리는 정글 친구들과 지혜를 모아 힘을 합쳐 시어칸의 위협에 맞섰어요.","발루와 바기라의 도움 덕분에 모글리는 무사히 위기를 넘길 수 있었어요.","모글리는 서로 다른 존재라도 진심으로 아끼면 가족이 될 수 있다는 것을 깨달았답니다."]'::jsonb, '[{"word":"보살피다","meaning":"정성을 기울여 보호하며 돌보다"},{"word":"위협하다","meaning":"위험한 상황으로 두렵게 하다"}]'::jsonb, '[{"answer":true,"statement":"모글리는 늑대 무리의 보살핌을 받았어요."},{"answer":false,"statement":"바기라는 모글리를 미워했어요."},{"answer":true,"statement":"모글리는 친구들과 힘을 합쳐 위기를 넘겼어요."}]'::jsonb, '{"choices":["정글은 위험하니 가지 말아야 해요","혼자 힘으로만 살아가야 해요","동물은 사람과 친구가 될 수 없어요","서로 다른 존재라도 진심으로 아끼면 가족이 될 수 있어요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"보살피다","choices":["전혀 신경 쓰지 않다","멀리서 구경만 하다","힘들게 하고 괴롭히다","정성을 기울여 보호하며 돌보다"],"answerIndex":3},{"type":"vocab","word":"위협하다","choices":["위험한 상황으로 두렵게 하다","친절하게 도와주다","조용히 응원하다","기쁘게 맞이하다"],"answerIndex":0},{"type":"synonym","word":"보살피다","choices":["방치하다","돌보다","괴롭히다","무시하다"],"answerIndex":1},{"type":"antonym","word":"위협하다","choices":["협박하다","겁주다","보호하다","해치다"],"answerIndex":2},{"type":"spelling","word":"넉넉지","choices":["넉넉치","넉넉지이","넉넉하치","넉넉지"],"answerIndex":3}]'::jsonb, 191)
