insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('boy-who-bought-tree-shade', '🌳', '나무 그늘을 산 총각', '["가난한 총각이 무더운 여름날 부잣집 마당의 큰 느티나무 그늘에서 쉬고 있었어요.","구두쇠로 소문난 부자는 자기 나무 그늘이니 돈을 내고 쉬라며 총각을 나무랐어요.","총각은 웃으며 얼마 안 되는 돈을 주고 그 나무의 그늘을 아예 사 버렸어요.","해가 움직이면서 그늘도 점점 부자의 마당 안쪽으로 길게 늘어졌어요.","총각은 그늘을 따라 당당하게 부잣집 마루까지 들어가 쉬기 시작했어요.","부자는 크게 당황했지만, 이미 그늘을 판 것을 되돌릴 방법이 없었어요.","마을 사람들은 총각의 재치 있는 지혜에 감탄하며 두고두고 이야기했답니다."]'::jsonb, '[{"word":"구두쇠","meaning":"돈이나 물건을 아주 아끼고 인색한 사람"},{"word":"재치","meaning":"빠르고 슬기롭게 대처하는 능력"}]'::jsonb, '[{"answer":true,"statement":"총각은 느티나무 그늘에서 쉬고 있었어요."},{"answer":false,"statement":"부자는 그늘값을 받지 않겠다고 했어요."},{"answer":true,"statement":"총각은 그늘을 따라 마루까지 들어갔어요."}]'::jsonb, '{"choices":["지혜와 재치는 어려운 상황을 이겨내는 힘이 될 수 있어요","가난한 사람은 항상 손해를 봐요","나무 그늘은 아무도 가질 수 없어요","욕심을 부리면 항상 이길 수 있어요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"구두쇠","choices":["돈이나 물건을 아주 아끼고 인색한 사람","돈을 잘 쓰는 사람","나무를 심는 사람","그늘을 좋아하는 사람"],"answerIndex":0},{"type":"vocab","word":"재치","choices":["화를 잘 내는 성격","빠르고 슬기롭게 대처하는 능력","느리고 둔한 행동","겁이 많은 마음"],"answerIndex":1},{"type":"proverb","word":"말 한마디에 천 냥 빚도 갚는다","choices":["빚은 절대 갚을 수 없다는 뜻이에요","돈이 없으면 말도 하지 말라는 뜻이에요","말을 지혜롭고 슬기롭게 하면 큰일도 해결할 수 있다는 뜻이에요","말은 많이 할수록 손해라는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"재치","choices":["둔함","무지","어리석음","기지"],"answerIndex":3},{"type":"spelling","word":"통째로","choices":["통째로","통채로","통재로","통체로"],"answerIndex":0}]'::jsonb, 192)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('fisherman-wife-three-wishes-greed', '🎣', '어부와 세 가지 소원', '["가난한 어부가 바다에서 말하는 금빛 물고기를 잡았어요.","물고기는 자신을 놓아주면 소원을 들어주겠다고 했고, 어부는 물고기를 풀어 주었어요.","집에 돌아온 어부의 아내는 작은 오두막 대신 커다란 집을 갖게 해 달라고 졸랐어요.","소원은 이루어졌지만 아내의 욕심은 점점 커져 성과 보물까지 요구하게 되었어요.","결국 아내는 세상 모든 것을 다스리는 자리까지 욕심을 냈어요.","화가 난 물고기는 지나친 욕심에 실망하여 모든 것을 원래대로 되돌려 버렸어요.","어부와 아내는 예전의 작은 오두막으로 돌아와서야 소박한 삶의 소중함을 깨달았답니다."]'::jsonb, '[{"word":"소박하다","meaning":"꾸밈이 없고 수수하다"},{"word":"지나치다","meaning":"정도가 적당한 선을 넘다"}]'::jsonb, '[{"answer":true,"statement":"어부는 말하는 물고기를 잡았어요."},{"answer":false,"statement":"아내의 소원은 점점 줄어들었어요."},{"answer":true,"statement":"물고기는 결국 모든 것을 원래대로 되돌렸어요."}]'::jsonb, '{"choices":["소원은 많이 빌수록 좋아요","지나친 욕심은 결국 있던 것마저 잃게 만들 수 있어요","물고기는 사람을 도와주지 않아요","가난하게 사는 것은 항상 나쁜 일이에요"],"question":"이 이야기가 주는 교훈은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"소박하다","choices":["화려하고 사치스럽다","꾸밈이 없고 수수하다","복잡하고 어렵다","시끄럽고 요란하다"],"answerIndex":1},{"type":"vocab","word":"지나치다","choices":["적당히 알맞다","전혀 부족하다","정도가 적당한 선을 넘다","매우 조심스럽다"],"answerIndex":2},{"type":"proverb","word":"말 타면 경마 잡히고 싶다","choices":["말을 타면 항상 조심해야 한다는 뜻이에요","말은 원래 혼자 탈 수 없다는 뜻이에요","욕심을 내면 항상 손해만 본다는 뜻이에요","사람의 욕심은 끝이 없어서 자꾸 더 원하게 된다는 뜻이에요"],"answerIndex":3},{"type":"antonym","word":"소박하다","choices":["화려하다","수수하다","검소하다","단순하다"],"answerIndex":0},{"type":"spelling","word":"개수","choices":["갯수","개수","개숫","갯숫"],"answerIndex":1}]'::jsonb, 193)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('peter-and-the-wolf-courage', '🐺', '피터와 늑대', '["할아버지는 피터에게 숲에는 위험한 늑대가 있으니 절대 혼자 나가지 말라고 당부했어요.","피터는 호기심을 참지 못하고 몰래 대문 밖 초원으로 나가 친구인 새, 오리와 함께 놀았어요.","그때 정말로 커다란 늑대가 나타났고, 오리는 미처 피하지 못해 늑대에게 쫓기게 되었어요.","피터는 겁먹지 않고 침착하게 나무 위로 올라가 밧줄로 고리를 만들었어요.","늑대가 나무 아래를 서성이자 피터는 늑대의 꼬리에 밧줄 고리를 정확히 걸었어요.","마침 사냥꾼들이 지나가다 소란을 듣고 달려와 늑대를 안전하게 동물원으로 데려갔어요.","할아버지는 놀라면서도 용기와 지혜를 발휘한 피터를 자랑스러워했답니다."]'::jsonb, '[{"word":"당부하다","meaning":"말로 단단히 부탁하다"},{"word":"서성이다","meaning":"한곳에 머무르지 못하고 왔다 갔다 하다"}]'::jsonb, '[{"answer":true,"statement":"할아버지는 피터에게 숲에 가지 말라고 당부했어요."},{"answer":false,"statement":"피터는 늑대를 보고 도망쳐 숨었어요."},{"answer":true,"statement":"피터는 밧줄로 늑대를 잡는 데 성공했어요."}]'::jsonb, '{"choices":["위험한 상황에서는 무조건 도망가야 해요","어른들의 말은 안 들어도 괜찮아요","침착함과 용기가 있으면 위기를 슬기롭게 이겨낼 수 있어요","늑대는 절대 잡을 수 없어요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"당부하다","choices":["전혀 신경 쓰지 않다","화를 내며 다그치다","말로 단단히 부탁하다","조용히 무시하다"],"answerIndex":2},{"type":"vocab","word":"서성이다","choices":["가만히 앉아 있다","빠르게 뛰어가다","깊이 잠들다","한곳에 머무르지 못하고 왔다 갔다 하다"],"answerIndex":3},{"type":"synonym","word":"서성이다","choices":["배회하다","정착하다","머무르다","잠들다"],"answerIndex":0},{"type":"antonym","word":"당부하다","choices":["부탁하다","방치하다","권하다","타이르다"],"answerIndex":1},{"type":"spelling","word":"곱빼기","choices":["곱배기","곱백이","곱빼기","곱배끼"],"answerIndex":2}]'::jsonb, 194)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('goblin-and-roasted-chestnut', '🌰', '도깨비와 개암', '["나무꾼이 산에서 나무를 하다가 잘 익은 개암 세 개를 주워 주머니에 넣었어요.","밤이 되어 길을 잃은 나무꾼은 빈 집에서 하룻밤을 묵기로 했어요.","한밤중 도깨비들이 몰려와 방망이를 두드리며 신나게 놀기 시작했어요.","배가 고팠던 나무꾼이 개암 하나를 깨물자 딱 하는 큰 소리가 났어요.","놀란 도깨비들은 집이 무너지는 줄 알고 방망이도 챙기지 못한 채 도망쳐 버렸어요.","나무꾼은 도깨비들이 두고 간 방망이를 주워 뚝딱뚝딱 두드려 원하는 것을 얻었어요.","나무꾼은 작은 개암 하나가 큰 행운을 가져다준 것에 감사했답니다."]'::jsonb, '[{"word":"묵다","meaning":"일정한 곳에서 나그네로 머무르다"},{"word":"행운","meaning":"좋은 운수"}]'::jsonb, '[{"answer":true,"statement":"나무꾼은 개암 세 개를 주웠어요."},{"answer":false,"statement":"도깨비들은 나무꾼을 반갑게 맞아주었어요."},{"answer":true,"statement":"나무꾼은 도깨비 방망이를 얻었어요."}]'::jsonb, '{"choices":["도깨비는 원래 착한 존재예요","산에서는 아무것도 줍지 말아야 해요","시끄러운 소리는 항상 위험해요","작은 기지와 우연이 뜻밖의 좋은 결과로 이어질 수 있어요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"묵다","choices":["한곳에 영원히 살다","물건을 새로 사다","빠르게 지나가다","일정한 곳에서 나그네로 머무르다"],"answerIndex":3},{"type":"vocab","word":"행운","choices":["좋은 운수","나쁜 운수","힘든 노동","슬픈 소식"],"answerIndex":0},{"type":"proverb","word":"호랑이 굴에 가야 호랑이를 잡는다","choices":["호랑이는 절대 잡을 수 없다는 뜻이에요","위험을 무릅써야 원하는 것을 얻을 수 있다는 뜻이에요","굴속은 항상 안전하다는 뜻이에요","위험한 곳은 절대 가면 안 된다는 뜻이에요"],"answerIndex":1},{"type":"antonym","word":"행운","choices":["행복","기쁨","불운","축복"],"answerIndex":2},{"type":"spelling","word":"삼가다","choices":["삼가하다","삼가하는","삼가는다","삼가다"],"answerIndex":3}]'::jsonb, 195)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('wise-daughter-in-law-riddles', '🧠', '슬기로운 며느리', '["어느 부잣집 원님이 며느릿감을 구하려고 마을에 어려운 문제를 냈어요.","\"쌀 한 톨로 잔치를 차려 오라\"는 문제에 마을 처녀들은 모두 고개를 저었어요.","한 가난한 집 딸은 쌀 한 톨을 심어 이듬해 거둔 벼로 잔치를 차리면 된다고 지혜롭게 답했어요.","원님은 그 답에 감탄했지만, 더 어려운 문제로 \"바람을 종이에 싸 오라\"고 했어요.","처녀는 부채를 종이에 정성껏 싸서 가져가 부치면 바람이 나온다고 보여 주었어요.","원님은 처녀의 슬기로움에 크게 감탄하여 마침내 아들의 며느리로 맞이했어요.","처녀는 시집가서도 지혜로운 며느리로 마을 사람들의 사랑을 받았답니다."]'::jsonb, '[{"word":"이듬해","meaning":"바로 다음 해"},{"word":"슬기롭다","meaning":"일을 바르게 판단하고 잘 처리하는 능력이 있다"}]'::jsonb, '[{"answer":true,"statement":"원님은 며느릿감을 구하려고 문제를 냈어요."},{"answer":false,"statement":"처녀는 첫 번째 문제를 풀지 못했어요."},{"answer":true,"statement":"처녀는 부채로 바람 문제를 풀었어요."}]'::jsonb, '{"choices":["지혜로운 생각은 아무리 어려운 문제도 풀어낼 수 있어요","가난하면 지혜도 소용없어요","문제는 풀지 않는 것이 좋아요","부채는 바람과 상관없어요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"이듬해","choices":["바로 다음 해","작년","같은 해","십 년 뒤"],"answerIndex":0},{"type":"vocab","word":"슬기롭다","choices":["성격이 급하고 거칠다","일을 바르게 판단하고 잘 처리하는 능력이 있다","매우 게으르다","겁이 많고 소심하다"],"answerIndex":1},{"type":"synonym","word":"슬기롭다","choices":["어리석다","무모하다","지혜롭다","서투르다"],"answerIndex":2},{"type":"antonym","word":"슬기롭다","choices":["영리하다","현명하다","똑똑하다","어리석다"],"answerIndex":3},{"type":"spelling","word":"웬만하면","choices":["웬만하면","왠만하면","웬만하믄","왠만하믄"],"answerIndex":0}]'::jsonb, 196)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('three-billy-goats-troll-bridge', '🐐', '아기 염소 삼형제와 트롤', '["산 너머 푸른 풀밭으로 가려면 삼 형제 염소는 다리 하나를 건너야 했어요.","그런데 다리 밑에는 무섭게 생긴 트롤이 살면서 지나가는 이들을 위협했어요.","첫째로 막내 염소가 다리를 건너자 트롤이 나타나 잡아먹겠다고 으름장을 놓았어요.","막내 염소는 자신은 너무 작으니 뒤에 오는 형이 더 크고 맛있다고 재치 있게 둘러댔어요.","둘째 염소도 같은 방법으로 트롤을 지나쳤고, 마침내 가장 크고 힘센 셋째 염소가 다리에 올라섰어요.","트롤이 달려들자 셋째 염소는 튼튼한 뿔로 트롤을 밀어내며 다리를 무사히 건넜어요.","삼 형제는 마침내 푸른 풀밭에 모여 마음껏 풀을 뜯으며 행복하게 지냈답니다."]'::jsonb, '[{"word":"으름장","meaning":"말과 행동으로 위협하는 짓"},{"word":"둘러대다","meaning":"그럴듯한 말로 상황을 피하다"}]'::jsonb, '[{"answer":true,"statement":"삼 형제 염소는 다리를 건너야 했어요."},{"answer":false,"statement":"트롤은 다리 위에 살고 있었어요."},{"answer":true,"statement":"셋째 염소는 뿔로 트롤을 밀어냈어요."}]'::jsonb, '{"choices":["다리는 위험하니 절대 건너면 안 돼요","침착한 지혜와 용기로 힘든 상황을 헤쳐 나갈 수 있어요","트롤은 원래 착한 존재예요","형제끼리는 서로 돕지 않아도 돼요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"으름장","choices":["다정하게 건네는 인사","말과 행동으로 위협하는 짓","조용히 부탁하는 말","기쁘게 웃는 표정"],"answerIndex":1},{"type":"vocab","word":"둘러대다","choices":["사실대로 정직하게 말하다","아무 말도 하지 않다","그럴듯한 말로 상황을 피하다","크게 화를 내다"],"answerIndex":2},{"type":"proverb","word":"궁하면 통한다","choices":["어려운 상황은 절대 해결할 수 없다는 뜻이에요","궁한 사람은 도와주면 안 된다는 뜻이에요","통하는 길은 하나뿐이라는 뜻이에요","아무리 어려운 상황도 지혜를 짜내면 길이 열린다는 뜻이에요"],"answerIndex":3},{"type":"synonym","word":"둘러대다","choices":["둘러치다","실토하다","고백하다","자백하다"],"answerIndex":0},{"type":"spelling","word":"빈털터리","choices":["빈털털이","빈털터리","빈틀터리","빈털떠리"],"answerIndex":1}]'::jsonb, 197)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('little-red-hen-hard-work', '🐔', '부지런한 빨간 암탉', '["빨간 암탉이 밀알을 발견하고 농장 친구들에게 함께 심자고 물었지만 아무도 나서지 않았어요.","암탉은 혼자서 밀알을 땅에 심고, 물을 주며 정성껏 돌보았어요.","밀이 자라 수확할 때가 되었을 때도, 빵을 구울 때도 친구들은 이런저런 핑계를 대며 돕지 않았어요.","암탉은 홀로 밀을 베고, 방아를 찧고, 반죽을 해서 마침내 따뜻한 빵을 구워 냈어요.","고소한 빵 냄새를 맡은 친구들이 그제야 몰려와 함께 먹자고 했어요.","암탉은 힘들 때 돕지 않은 친구들에게 서운함을 표현하며, 이번에는 자신이 직접 빵을 나눌 친구를 정하겠다고 했어요.","결국 암탉은 함께 애쓴 병아리들과 사이좋게 빵을 나누어 먹었답니다."]'::jsonb, '[{"word":"수확하다","meaning":"익은 농작물을 거두어들이다"},{"word":"반죽하다","meaning":"가루에 물을 부어 이겨서 재료를 만들다"}]'::jsonb, '[{"answer":true,"statement":"암탉은 밀알 심는 것을 혼자서 했어요."},{"answer":false,"statement":"친구들은 처음부터 적극적으로 도와주었어요."},{"answer":true,"statement":"암탉은 결국 빵을 다같이 나누어 먹었어요."}]'::jsonb, '{"choices":["일은 항상 나눠서 해야만 해요","빵은 혼자 다 먹어야 해요","스스로 노력한 만큼 소중한 결실을 얻을 수 있어요","친구는 도움이 필요 없는 존재예요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"수확하다","choices":["씨앗을 처음 심다","밭에 물을 주다","익은 농작물을 거두어들이다","잡초를 뽑아내다"],"answerIndex":2},{"type":"vocab","word":"반죽하다","choices":["음식을 그릇에 담다","불을 피워 음식을 굽다","재료를 냉장고에 넣다","가루에 물을 부어 이겨서 재료를 만들다"],"answerIndex":3},{"type":"proverb","word":"심은 대로 거둔다","choices":["노력하고 애쓴 만큼 결과를 얻게 된다는 뜻이에요","심은 것은 늘 실패한다는 뜻이에요","농사는 아무나 지을 수 없다는 뜻이에요","거두는 것은 운에 달려 있다는 뜻이에요"],"answerIndex":0},{"type":"antonym","word":"수확하다","choices":["거두다","심다","베다","모으다"],"answerIndex":1},{"type":"spelling","word":"아니에요","choices":["아니예요","아니예여","아니에요","아니에여"],"answerIndex":2}]'::jsonb, 198)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('stone-soup-village-sharing', '🍲', '돌멩이 수프', '["먼 길을 걷던 나그네가 배가 고파 작은 마을에 들어섰지만 아무도 먹을 것을 나눠 주지 않았어요.","나그네는 큰 냄비에 물을 붓고 매끈한 돌멩이 하나를 넣어 \"맛있는 돌멩이 수프\"를 끓이겠다고 했어요.","신기해하던 마을 사람들이 하나둘 모여들었고, 나그네는 \"양배추가 조금 있으면 더 맛있을 텐데\"라며 혼잣말을 했어요.","한 사람이 양배추를 가져오자 다른 사람들도 당근과 감자, 고기를 조금씩 가져왔어요.","냄비 속 수프는 점점 풍성해졌고, 마침내 온 마을이 함께 먹을 만큼 맛있는 수프가 완성되었어요.","마을 사람들은 작은 것을 나누니 모두가 배부르게 먹을 수 있다는 것을 깨달았어요.","그날 이후 마을 사람들은 서로 나누고 도우며 더욱 사이좋게 지냈답니다."]'::jsonb, '[{"word":"풍성하다","meaning":"넉넉하고 많다"},{"word":"혼잣말","meaning":"듣는 사람 없이 혼자 하는 말"}]'::jsonb, '[{"answer":true,"statement":"나그네는 돌멩이로 수프를 끓이겠다고 했어요."},{"answer":false,"statement":"마을 사람들은 처음부터 재료를 아낌없이 나눠 주었어요."},{"answer":true,"statement":"결국 온 마을이 함께 수프를 먹었어요."}]'::jsonb, '{"choices":["나그네는 마을에 들어오면 안 돼요","수프는 돌멩이로만 끓여야 맛있어요","혼자 먹는 것이 가장 좋아요","작은 것이라도 서로 나누면 모두가 풍족해질 수 있어요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"풍성하다","choices":["부족하고 적다","단조롭고 심심하다","차갑고 딱딱하다","넉넉하고 많다"],"answerIndex":3},{"type":"vocab","word":"혼잣말","choices":["듣는 사람 없이 혼자 하는 말","여럿이 함께 나누는 대화","큰 소리로 외치는 말","글로 적어 놓은 말"],"answerIndex":0},{"type":"proverb","word":"십시일반","choices":["밥은 혼자 먹어야 맛있다는 뜻이에요","여럿이 조금씩 힘을 보태면 한 사람 몫이 된다는 뜻이에요","열 사람 중 한 사람만 도와도 충분하다는 뜻이에요","밥은 나눠 먹으면 안 된다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"풍성하다","choices":["빈약하다","부족하다","넉넉하다","메마르다"],"answerIndex":2},{"type":"spelling","word":"목걸이","choices":["목거리","목걸의","목거이","목걸이"],"answerIndex":3}]'::jsonb, 199)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('rumpelstiltskin-name-guess', '🧵', '룸펠슈틸츠킨', '["방앗간 딸은 아버지의 거짓 자랑 때문에 짚을 황금실로 자아내야 하는 처지에 놓였어요.","막막해하던 딸 앞에 작은 난쟁이가 나타나 목걸이를 받는 대가로 짚을 황금실로 바꾸어 주었어요.","딸은 왕비가 되었지만, 난쟁이는 이번엔 첫아이를 달라는 무서운 약속을 내걸었어요.","왕비가 된 딸이 울며 후회하자, 난쟁이는 사흘 안에 자기 이름을 맞히면 약속을 없던 일로 해 주겠다고 했어요.","왕비의 신하가 우연히 숲속에서 난쟁이가 자기 이름을 외치며 춤추는 모습을 보게 되었어요.","왕비가 그 이름을 정확히 맞히자, 난쟁이는 크게 놀라며 약속대로 순순히 물러갔어요.","왕비는 지혜와 기지로 소중한 아이를 지켜낼 수 있었답니다."]'::jsonb, '[{"word":"막막하다","meaning":"어찌할 바를 몰라 답답하다"},{"word":"물러가다","meaning":"있던 자리에서 뒤로 떠나가다"}]'::jsonb, '[{"answer":true,"statement":"딸은 짚을 황금실로 자아내야 했어요."},{"answer":false,"statement":"난쟁이는 처음부터 아무 대가도 원하지 않았어요."},{"answer":true,"statement":"왕비는 난쟁이의 이름을 알아맞혔어요."}]'::jsonb, '{"choices":["어려운 약속 앞에서도 포기하지 않고 지혜를 찾으면 길이 열려요","약속은 절대 지킬 필요가 없어요","이름은 아무 힘이 없어요","도움을 주는 존재는 항상 믿어도 돼요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"막막하다","choices":["어찌할 바를 몰라 답답하다","마음이 편안하고 여유롭다","기쁘고 즐겁다","자신감이 넘치다"],"answerIndex":0},{"type":"vocab","word":"물러가다","choices":["앞으로 나아가다","있던 자리에서 뒤로 떠나가다","계속 머무르다","더 가까이 다가오다"],"answerIndex":1},{"type":"synonym","word":"막막하다","choices":["홀가분하다","든든하다","난감하다","편안하다"],"answerIndex":2},{"type":"antonym","word":"물러가다","choices":["떠나가다","사라지다","물러서다","다가오다"],"answerIndex":3},{"type":"spelling","word":"얼마큼","choices":["얼마큼","얼만큼","얼마큼이","얼만치"],"answerIndex":0}]'::jsonb, 200)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('beauty-and-beast-kindness', '🌹', '미녀와 야수', '["상인의 막내딸 벨은 아버지 대신 무서운 야수의 성에서 지내기로 스스로 결심했어요.","벨은 처음에는 야수의 무서운 겉모습에 두려워했지만, 야수는 늘 벨에게 정중하고 다정하게 대했어요.","함께 책을 읽고 정원을 거닐며 시간을 보내는 동안 벨은 야수의 따뜻한 마음을 알게 되었어요.","어느 날 벨은 아버지가 편찮으시다는 소식을 듣고 야수에게 며칠만 다녀오겠다고 부탁했어요.","야수는 벨이 그리워 점점 야위어 갔지만, 약속대로 벨을 보내 주며 기다렸어요.","벨은 야수의 진심을 깨닫고 서둘러 성으로 돌아와 눈물로 사랑을 고백했어요.","그 순간 마법이 풀리며 야수는 본래의 왕자 모습으로 돌아왔고, 둘은 행복하게 살았답니다."]'::jsonb, '[{"word":"정중하다","meaning":"태도가 점잖고 예의 바르다"},{"word":"야위다","meaning":"몸이 여위어 마르다"}]'::jsonb, '[{"answer":true,"statement":"벨은 아버지 대신 야수의 성에서 지내기로 했어요."},{"answer":false,"statement":"야수는 벨에게 늘 무례하게 대했어요."},{"answer":true,"statement":"벨은 결국 성으로 돌아왔어요."}]'::jsonb, '{"choices":["무서운 겉모습을 가진 존재는 항상 나쁜 사람이에요","겉모습보다 마음이 더 중요할 수 있어요","약속은 지키지 않아도 상관없어요","가족보다 자신의 안전이 먼저예요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"정중하다","choices":["말투가 거칠고 무례하다","태도가 점잖고 예의 바르다","행동이 산만하고 부주의하다","성격이 급하고 사납다"],"answerIndex":1},{"type":"vocab","word":"야위다","choices":["몸이 통통하게 살찌다","기운이 넘쳐 활발하다","몸이 여위어 마르다","피부가 곱고 매끈하다"],"answerIndex":2},{"type":"proverb","word":"뚝배기보다 장맛","choices":["뚝배기는 장맛보다 비싸다는 뜻이에요","음식은 그릇이 중요하다는 뜻이에요","장맛은 뚝배기에서만 난다는 뜻이에요","겉모습보다 속에 담긴 진짜 가치가 더 중요하다는 뜻이에요"],"answerIndex":3},{"type":"synonym","word":"정중하다","choices":["공손하다","무례하다","거칠다","불손하다"],"answerIndex":0},{"type":"spelling","word":"돼요","choices":["되요","돼요","됀요","되여요"],"answerIndex":1}]'::jsonb, 201)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('puss-in-boots-clever-cat', '🐱', '장화 신은 고양이', '["방앗간 주인이 세상을 떠나며 막내아들에게는 고양이 한 마리만 남겨 주었어요.","막내아들이 낙담하자 고양이는 장화 한 켤레만 마련해 주면 큰 부자로 만들어 주겠다고 말했어요.","고양이는 사냥한 토끼와 꿩을 임금님께 주인의 이름으로 바치며 좋은 인상을 심어 주었어요.","고양이는 꾀를 내어 주인이 강물에 빠진 척하게 하고, 임금님의 마차가 지나가게 했어요.","고양이는 도둑맞은 옷이라며 둘러대 임금님께 근사한 옷을 얻어 주인에게 입혔어요.","고양이는 마지막으로 욕심 많은 요술사를 꾀어 작은 쥐로 변신하게 한 뒤, 성을 차지하여 주인에게 바쳤어요.","막내아들은 고양이의 지혜 덕분에 성의 주인이 되어 행복하게 살았답니다."]'::jsonb, '[{"word":"낙담하다","meaning":"바라던 일이 뜻대로 되지 않아 마음이 상하다"},{"word":"근사하다","meaning":"그럴듯하게 좋다"}]'::jsonb, '[{"answer":true,"statement":"막내아들은 고양이 한 마리만 물려받았어요."},{"answer":false,"statement":"고양이는 주인을 돕지 않고 혼자 도망갔어요."},{"answer":true,"statement":"고양이는 꾀를 내어 요술사의 성을 차지했어요."}]'::jsonb, '{"choices":["고양이는 절대 사람을 도울 수 없어요","가진 것이 적으면 결코 성공할 수 없어요","지혜와 꾀는 어려운 상황을 뒤바꿀 수 있는 힘이 될 수 있어요","꾀는 아무 쓸모가 없어요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"낙담하다","choices":["기대 이상으로 기뻐하다","아무 감정이 없다","바라던 일이 뜻대로 되지 않아 마음이 상하다","화를 내며 소리치다"],"answerIndex":2},{"type":"vocab","word":"근사하다","choices":["초라하고 볼품없다","평범하고 흔하다","지저분하고 낡다","그럴듯하게 좋다"],"answerIndex":3},{"type":"synonym","word":"근사하다","choices":["멋지다","초라하다","허름하다","볼품없다"],"answerIndex":0},{"type":"antonym","word":"낙담하다","choices":["실망하다","희망차다","좌절하다","낙심하다"],"answerIndex":1},{"type":"spelling","word":"안 돼","choices":["안되","안됀","안 돼","않돼"],"answerIndex":2}]'::jsonb, 202)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('snow-queen-gerda-friendship', '❄️', '눈의 여왕', '["카이와 게르다는 둘도 없이 친한 이웃 친구였어요.","어느 날 카이의 눈과 마음에 차가운 얼음 조각이 들어가면서, 카이는 갑자기 차갑고 무뚝뚝하게 변해 버렸어요.","카이는 눈의 여왕을 따라 멀고 추운 나라로 떠나 버렸고, 게르다는 슬픔에 잠겼어요.","게르다는 포기하지 않고 카이를 찾아 눈보라를 헤치며 먼 길을 떠났어요.","게르다는 여러 어려움을 만났지만 따뜻한 마음씨 덕분에 곳곳에서 도움을 받았어요.","마침내 눈의 궁전에 도착한 게르다는 뜨거운 눈물을 흘리며 카이를 꼭 안아 주었어요.","게르다의 따뜻한 눈물이 카이 마음속 얼음 조각을 녹였고, 둘은 다시 예전의 다정한 사이로 돌아갔답니다."]'::jsonb, '[{"word":"무뚝뚝하다","meaning":"말이나 행동이 부드럽지 못하고 딱딱하다"},{"word":"눈보라","meaning":"눈이 몰아치는 사나운 바람"}]'::jsonb, '[{"answer":true,"statement":"카이는 얼음 조각 때문에 차갑게 변했어요."},{"answer":false,"statement":"게르다는 카이를 찾는 것을 곧 포기했어요."},{"answer":true,"statement":"게르다의 눈물이 카이의 마음을 녹였어요."}]'::jsonb, '{"choices":["추운 곳에는 절대 가면 안 돼요","한 번 변한 마음은 되돌릴 수 없어요","우정보다 혼자가 더 편해요","진심 어린 우정과 따뜻한 마음은 얼어붙은 마음도 녹일 수 있어요"],"question":"이 이야기가 전하고 싶은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"무뚝뚝하다","choices":["성격이 밝고 상냥하다","매우 다정하고 부드럽다","활발하고 명랑하다","말이나 행동이 부드럽지 못하고 딱딱하다"],"answerIndex":3},{"type":"vocab","word":"눈보라","choices":["눈이 몰아치는 사나운 바람","따뜻한 봄바람","잔잔하고 고요한 날씨","맑고 화창한 하늘"],"answerIndex":0},{"type":"proverb","word":"급히 먹는 밥이 체한다","choices":["밥은 천천히 먹어야 맛있다는 뜻이에요","너무 서두르면 오히려 탈이 날 수 있다는 뜻이에요","배고플 때는 무엇이든 맛있다는 뜻이에요","밥을 많이 먹으면 배탈이 난다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"무뚝뚝하다","choices":["상냥하다","다정하다","퉁명스럽다","친절하다"],"answerIndex":2},{"type":"spelling","word":"봬요","choices":["뵈요","뵤아요","봐요","봬요"],"answerIndex":3}]'::jsonb, 203)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('gymnastics-champion-misstep', '🤸', '체조왕의 예상 밖 실수', '["하윤이는 학교에서 가장 뜀틀을 잘 넘는 아이로 유명했어요.","체육대회 날, 하윤이는 자신만만하게 뜀틀 앞에 섰어요.","그런데 도움닫기를 하다가 발이 살짝 미끄러지면서 자세가 흐트러지고 말았어요.","결국 하윤이는 착지에 실패해 매트에 주저앉고 말았어요.","친구들은 깜짝 놀랐지만, 아무도 하윤이를 놀리지 않았어요.","선생님은 \"아무리 잘하는 사람도 실수할 때가 있단다\"라고 다독여 주셨어요.","하윤이는 속상했지만, 다음 시도에서는 더 집중해서 멋지게 성공했어요.","그날 이후 하윤이는 잘하는 것에도 늘 겸손한 마음으로 연습하게 되었어요."]'::jsonb, '[{"word":"자신만만하다","meaning":"매우 자신 있어 하는 태도가 있다"},{"word":"겸손하다","meaning":"남을 존중하고 자기를 낮추는 태도가 있다"}]'::jsonb, '[{"answer":true,"statement":"하윤이는 뜀틀을 잘 넘기로 유명했어요."},{"answer":false,"statement":"하윤이는 첫 시도에서 완벽하게 성공했어요."},{"answer":false,"statement":"선생님은 하윤이를 혼내셨어요."},{"answer":true,"statement":"하윤이는 다음 시도에서 성공했어요."}]'::jsonb, '{"choices":["잘하는 사람은 절대 실수하지 않아요","실수한 사람은 다시 도전하면 안 돼요","아무리 잘하는 사람도 실수할 수 있으니 겸손해야 해요","체육대회는 항상 힘들어요"],"question":"이 이야기가 전하고 싶은 생각으로 가장 알맞은 것은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"자신만만하다","choices":["매우 자신 있어 하는 태도가 있다","걱정이 많아 불안하다","아무 관심이 없다","몹시 피곤하다"],"answerIndex":0},{"type":"proverb","word":"원숭이도 나무에서 떨어진다","choices":["원숭이는 나무를 잘 타지 못한다는 뜻이에요","아무리 잘하는 사람도 실수할 때가 있다는 뜻이에요","나무에 오르면 위험하다는 뜻이에요","동물은 실수하지 않는다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"겸손하다","choices":["거만하다","잘난 척하다","공손하다","무뚝뚝하다"],"answerIndex":2},{"type":"antonym","word":"겸손하다","choices":["얌전하다","소박하다","정중하다","거만하다"],"answerIndex":3},{"type":"spelling","word":"왠지","choices":["왠지","웬지","웨지","왠쥐"],"answerIndex":0}]'::jsonb, 204)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('rainy-season-hope-returns', '🌈', '긴 장마 끝에 뜬 무지개', '["도현이는 요즘 되는 일이 하나도 없다고 느꼈어요.","줄넘기 대회에서 예선 탈락했고, 감기까지 걸려 일주일 내내 결석했어요.","겨우 학교에 나온 날에는 아끼던 필통마저 잃어버리고 말았어요.","도현이는 \"나는 되는 일이 하나도 없나 봐\" 하며 시무룩해졌어요.","짝꿍 서아는 \"너무 힘들었겠다, 그래도 곧 좋은 일도 생길 거야\"라며 위로해 주었어요.","며칠 뒤, 선생님이 도현이의 그림일기를 학급 게시판에 뽑아 걸어 주셨어요.","잃어버린 줄 알았던 필통도 분실물 보관함에서 찾았다는 연락을 받았어요.","도현이는 힘든 날들이 지나가고 나니 다시 웃을 일이 생긴다는 것을 깨달았어요."]'::jsonb, '[{"word":"예선 탈락","meaning":"본 경기에 나가지 못하고 미리 떨어지는 것"},{"word":"시무룩하다","meaning":"마음에 못마땅해서 말이 없고 표정이 어둡다"}]'::jsonb, '[{"answer":true,"statement":"도현이는 줄넘기 대회 예선에서 탈락했어요."},{"answer":false,"statement":"도현이는 감기에 걸리지 않았어요."},{"answer":true,"statement":"도현이의 그림일기가 학급 게시판에 걸렸어요."}]'::jsonb, '{"choices":["한번 나쁜 일이 생기면 계속 나쁜 일만 생겨요","힘든 일이 있으면 포기하는 것이 좋아요","친구의 위로는 별로 도움이 되지 않아요","힘든 시간이 지나면 다시 좋은 일이 찾아와요"],"question":"이 이야기가 주는 교훈으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"시무룩하다","choices":["기분이 아주 좋다","마음에 못마땅해서 말이 없고 표정이 어둡다","몹시 화가 나다","배가 고프다"],"answerIndex":1},{"type":"proverb","word":"쥐구멍에도 볕 들 날 있다","choices":["쥐는 어두운 곳을 좋아한다는 뜻이에요","볕이 드는 곳에는 쥐가 없다는 뜻이에요","아무리 힘들어도 언젠가는 좋은 일이 생긴다는 뜻이에요","쥐구멍은 늘 어둡다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"시무룩하다","choices":["명랑하다","즐겁다","신나다","울적하다"],"answerIndex":3},{"type":"antonym","word":"시무룩하다","choices":["명랑하다","울적하다","침울하다","시들하다"],"answerIndex":0},{"type":"spelling","word":"오랜만","choices":["오랫만","오랜만","오랜동안만","오랫동안"],"answerIndex":1}]'::jsonb, 205)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('field-trip-mishap-cascade', '⛈️', '엎친 데 덮친 체험학습 날', '["지우는 손꼽아 기다리던 체험학습 날 아침, 늦잠을 자서 버스를 놓칠 뻔했어요.","겨우 버스를 탔지만 이번엔 도시락을 집에 두고 온 것을 알게 됐어요.","\"설마 오늘보다 더 힘든 일은 없겠지\" 생각했지만, 목적지에 도착하니 갑자기 비가 쏟아졌어요.","준비했던 야외 활동은 모두 취소되고, 실내에서 얌전히 기다려야 했어요.","지우는 \"오늘은 정말 갈수록 태산이네\" 하며 한숨을 쉬었어요.","그때 선생님이 우산을 나눠 주시고, 친구가 도시락을 나눠 먹자고 했어요.","비가 그친 뒤에는 예정에 없던 무지개까지 볼 수 있었어요.","지우는 힘든 하루였지만 결국 좋은 추억으로 남았다고 생각했어요."]'::jsonb, '[{"word":"손꼽아 기다리다","meaning":"날짜를 세어 가며 몹시 기다리다"},{"word":"막막하다","meaning":"어찌할 바를 몰라 답답하다"}]'::jsonb, '[{"answer":true,"statement":"지우는 체험학습 날 늦잠을 잤어요."},{"answer":false,"statement":"지우는 도시락을 챙겨 갔어요."},{"answer":true,"statement":"목적지에서 비가 내렸어요."},{"answer":false,"statement":"야외 활동이 예정대로 진행됐어요."}]'::jsonb, '{"choices":["힘든 일이 계속돼도 주변의 도움과 마음가짐으로 좋은 하루를 만들 수 있어요","체험학습은 항상 계획대로 되어야 해요","비 오는 날에는 아무것도 할 수 없어요","늦잠을 자면 하루를 망치게 돼요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":0}'::jsonb, '[{"type":"vocab","word":"손꼽아 기다리다","choices":["전혀 기대하지 않다","급하게 서두르다","날짜를 세어 가며 몹시 기다리다","아무 생각 없이 있다"],"answerIndex":2},{"type":"proverb","word":"갈수록 태산","choices":["갈수록 길이 편해진다는 뜻이에요","태산은 오르기 쉽다는 뜻이에요","처음이 가장 힘들다는 뜻이에요","어려운 일이 자꾸 겹쳐서 점점 더 힘들어진다는 뜻이에요"],"answerIndex":3},{"type":"synonym","word":"막막하다","choices":["답답하다","홀가분하다","상쾌하다","즐겁다"],"answerIndex":0},{"type":"antonym","word":"막막하다","choices":["답답하다","홀가분하다","걱정스럽다","막연하다"],"answerIndex":1},{"type":"spelling","word":"며칠","choices":["몇일","몇 일","며칠","며칟"],"answerIndex":2}]'::jsonb, 206)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('missing-glasses-on-head', '👓', '온 집을 뒤진 안경', '["민서는 아침부터 안경이 안 보인다며 온 집안을 다 뒤졌어요.","서랍도 열어 보고 침대 밑도 살펴봤지만 안경은 어디에도 없었어요.","엄마도 함께 찾아 주셨지만 도무지 보이지 않았어요.","학교 갈 시간이 다 되어 걱정하던 그때, 동생이 \"언니, 안경 머리 위에 있는데?\" 하고 말했어요.","민서는 그제야 자기 머리 위에 안경을 올려 둔 걸 까맣게 잊고 있었다는 걸 깨달았어요.","가족들은 다 함께 웃음을 터뜨렸어요.","엄마는 \"등잔 밑이 어둡다더니, 가장 가까운 곳을 못 봤구나\"라며 웃으셨어요.","민서는 앞으로 물건을 찾을 때 가까운 곳부터 차분히 살펴보기로 했어요."]'::jsonb, '[{"word":"뒤지다","meaning":"무엇을 찾으려고 이곳저곳을 살펴보다"},{"word":"깜빡하다","meaning":"기억이나 정신이 잠깐 흐려지다"}]'::jsonb, '[{"answer":true,"statement":"민서는 아침에 안경을 찾고 있었어요."},{"answer":false,"statement":"안경은 처음부터 가방 속에 있었어요."},{"answer":true,"statement":"동생이 안경의 위치를 알려 주었어요."}]'::jsonb, '{"choices":["안경은 항상 잃어버리기 쉬운 물건이에요","가까운 곳에 있는 것을 오히려 못 알아챌 때가 있어요","동생 말은 믿을 필요가 없어요","물건을 잃어버리면 화부터 내야 해요"],"question":"이 이야기가 전하고 싶은 생각으로 알맞은 것은 무엇일까요?","answerIndex":1}'::jsonb, '[{"type":"vocab","word":"뒤지다","choices":["깨끗이 정리하다","조용히 앉아 있다","멀리 던지다","무엇을 찾으려고 이곳저곳을 살펴보다"],"answerIndex":3},{"type":"proverb","word":"등잔 밑이 어둡다","choices":["가까이 있는 것을 오히려 잘 모르거나 알아채지 못한다는 뜻이에요","등잔은 항상 밝다는 뜻이에요","밤에는 아무것도 안 보인다는 뜻이에요","등잔불은 위험하다는 뜻이에요"],"answerIndex":0},{"type":"synonym","word":"깜빡하다","choices":["명심하다","잊어버리다","기억하다","되새기다"],"answerIndex":1},{"type":"antonym","word":"깜빡하다","choices":["잊어버리다","놓치다","명심하다","착각하다"],"answerIndex":2},{"type":"spelling","word":"설거지","choices":["설겆이","설겆히","설것이","설거지"],"answerIndex":3}]'::jsonb, 207)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('classroom-gossip-overheard', '🤫', '아무도 없는 줄 알았던 교실', '["하은이와 지민이는 쉬는 시간에 다른 반 친구의 흉을 몰래 이야기했어요.","\"교실에 아무도 없으니까 괜찮겠지\" 하며 마음 놓고 이야기를 나눴어요.","그런데 사실 책상 뒤편에서 그 친구의 짝꿍이 책을 읽고 있었어요.","짝꿍은 두 사람의 이야기를 다 듣고 마음이 상해 그 친구에게 그대로 전했어요.","다음 날, 흉을 봤던 그 친구가 하은이와 지민이에게 서운한 마음을 이야기했어요.","하은이와 지민이는 얼굴이 빨개지며 진심으로 사과했어요.","어른들이 \"낮말은 새가 듣고 밤말은 쥐가 듣는다\"고 하신 말씀이 이제야 이해가 됐어요.","두 사람은 그 뒤로 다른 사람 이야기를 할 때 더욱 조심하게 되었어요."]'::jsonb, '[{"word":"마음이 상하다","meaning":"기분이 나빠지고 속이 상하다"},{"word":"서운하다","meaning":"마음에 아쉽고 섭섭한 데가 있다"}]'::jsonb, '[{"answer":true,"statement":"하은이와 지민이는 다른 반 친구의 흉을 봤어요."},{"answer":false,"statement":"교실에는 정말 아무도 없었어요."},{"answer":false,"statement":"짝꿍은 들은 이야기를 아무에게도 전하지 않았어요."},{"answer":true,"statement":"하은이와 지민이는 결국 사과했어요."}]'::jsonb, '{"choices":["아무도 없을 때는 어떤 말을 해도 괜찮아요","친구의 흉을 보는 것은 재미있는 일이에요","말은 언제 누가 들을지 모르니 항상 조심해야 해요","사과는 할 필요가 없어요"],"question":"이 이야기가 전하고 싶은 생각은 무엇일까요?","answerIndex":2}'::jsonb, '[{"type":"vocab","word":"마음이 상하다","choices":["기분이 나빠지고 속이 상하다","기분이 아주 좋아지다","배가 부르다","잠이 오다"],"answerIndex":0},{"type":"proverb","word":"낮말은 새가 듣고 밤말은 쥐가 듣는다","choices":["낮에는 새가 많고 밤에는 쥐가 많다는 뜻이에요","아무도 안 듣는 것 같아도 말은 결국 새어 나가니 늘 조심해야 한다는 뜻이에요","새와 쥐는 말을 알아듣는다는 뜻이에요","밤에는 말을 하면 안 된다는 뜻이에요"],"answerIndex":1},{"type":"synonym","word":"서운하다","choices":["흡족하다","만족하다","섭섭하다","통쾌하다"],"answerIndex":2},{"type":"antonym","word":"서운하다","choices":["섭섭하다","아쉽다","서글프다","흡족하다"],"answerIndex":3},{"type":"spelling","word":"어이없다","choices":["어이없다","어의없다","어이업다","어히없다"],"answerIndex":0}]'::jsonb, 208)
on conflict (id) do update set emoji = excluded.emoji, title = excluded.title, paragraphs = excluded.paragraphs, vocabulary = excluded.vocabulary, true_false = excluded.true_false, main_theme = excluded.main_theme, vocab_quiz = excluded.vocab_quiz, sort_order = excluded.sort_order;
insert into stories (id, emoji, title, paragraphs, vocabulary, true_false, main_theme, vocab_quiz, sort_order) values ('bike-brake-check-habit', '🚲', '익숙한 길에서 생긴 일', '["준우는 매일 다니던 익숙한 자전거길이라 브레이크 점검도 없이 씽씽 달렸어요.","\"이 길은 하도 다녀서 눈감고도 갈 수 있어\"라며 자신만만해했어요.","그런데 내리막길에서 브레이크를 잡으려는 순간, 브레이크 줄이 헐거워진 걸 알아챘어요.","다행히 준우는 속도를 줄이며 겨우 안전하게 멈춰 설 수 있었어요.","깜짝 놀란 준우는 그제야 며칠 동안 브레이크를 점검하지 않았다는 걸 떠올렸어요.","아빠는 \"아무리 익숙한 길이라도 출발 전에 점검하는 습관이 중요하단다\"라고 말씀해 주셨어요.","준우는 다음 날부터 자전거를 타기 전에 항상 브레이크와 타이어를 확인했어요.","작은 습관 하나가 큰 사고를 막아 줄 수 있다는 것을 깨달았어요."]'::jsonb, '[{"word":"헐겁다","meaning":"끼워지거나 죄어져야 할 것이 꽉 맞지 않고 느슨하다"},{"word":"점검하다","meaning":"무엇이 이상이 없는지 자세히 살펴보다"}]'::jsonb, '[{"answer":true,"statement":"준우는 익숙한 길이라 브레이크를 점검하지 않았어요."},{"answer":false,"statement":"브레이크 줄에는 아무 문제가 없었어요."},{"answer":true,"statement":"준우는 다음 날부터 자전거를 점검하는 습관을 가졌어요."}]'::jsonb, '{"choices":["익숙한 길에서는 조심할 필요가 없어요","자전거는 타지 않는 것이 가장 안전해요","사고는 아무리 조심해도 막을 수 없어요","익숙하고 안전해 보이는 것도 미리 살펴보는 습관이 중요해요"],"question":"이 이야기가 주는 교훈으로 가장 알맞은 것은 무엇일까요?","answerIndex":3}'::jsonb, '[{"type":"vocab","word":"점검하다","choices":["아무렇게나 두다","무엇이 이상이 없는지 자세히 살펴보다","빠르게 지나가다","크게 소리치다"],"answerIndex":1},{"type":"proverb","word":"돌다리도 두들겨 보고 건너라","choices":["돌다리는 위험해서 건너면 안 된다는 뜻이에요","다리는 두드리면 무너진다는 뜻이에요","잘 아는 일이라도 꼼꼼히 확인하고 조심해야 한다는 뜻이에요","돌다리가 나무다리보다 튼튼하다는 뜻이에요"],"answerIndex":2},{"type":"synonym","word":"헐겁다","choices":["팽팽하다","단단하다","빽빽하다","느슨하다"],"answerIndex":3},{"type":"antonym","word":"헐겁다","choices":["팽팽하다","느슨하다","헐렁하다","헤프다"],"answerIndex":0},{"type":"spelling","word":"웬일","choices":["왠일","웬일","웬닐","왠닐"],"answerIndex":1}]'::jsonb, 209)
