insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('reschedule', '친구와 만나는 시간을 다시 정하고 있어요.', '[{"text":"우리 3시에 놀이터에서 만나기로 했지?","speaker":"A"},{"text":"응! 근데 미안한데 4시로 늦춰도 될까?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"고마워! 이따 봐 😊","speaker":"B"}]'::jsonb, '[{"label":"괜찮아, 4시에 보자!"},{"label":"싫어! 꼭 3시여야 해!"},{"label":"너랑 안 놀아!"},{"label":"그냥 취소하자"}]'::jsonb, 0, 0)
