insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('celebration', '친구가 대회에서 1등을 했다고 자랑하고 있어요.', '[{"text":"나 오늘 그리기 대회에서 1등 했어!","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"헤헤, 고마워! 너무 기뻐!","speaker":"A"}]'::jsonb, '[{"label":"🤔","isEmoji":true},{"label":"🎉","isEmoji":true},{"label":"😡","isEmoji":true},{"label":"🙄","isEmoji":true}]'::jsonb, 1, 1)
