insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-bike-repair-brake-fix', '자전거 수리점 아저씨께 브레이크가 이상하다고 말씀드리고 있어요.', '[{"text":"아저씨, 자전거 브레이크를 잡으면 이상한 소리가 나요.","speaker":"A"},{"text":"언제부터 그런 소리가 났니?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그럼 브레이크 패드를 확인해봐야겠다.","speaker":"B"}]'::jsonb, '[{"label":"오늘 아침에 새로 샀어요."},{"label":"그냥 신경 안 써도 돼요."},{"label":"지난주부터 그랬는데 점점 심해져요."},{"label":"소리 안 나는데요."}]'::jsonb, 2, 110)
