insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-bathhouse-manager-schedule', '목욕탕 관리인 아저씨께 이용 시간을 여쭤보고 있어요.', '[{"text":"아저씨, 오늘 목욕탕 몇 시까지 해요?","speaker":"A"},{"text":"저녁 9시까지 하는데, 왜 궁금하니?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그럼 여유 있게 올 수 있겠다.","speaker":"B"}]'::jsonb, '[{"label":"목욕탕 안 좋아해요."},{"label":"그냥 궁금해서요, 안 갈 거예요."},{"label":"이미 다 씻었어요."},{"label":"할머니랑 같이 오려고 시간을 여쭤봤어요."}]'::jsonb, 3, 111)
