insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-playground-guardian-safety-warning', '놀이터 안전지킴이 선생님이 미끄럼틀을 거꾸로 올라가지 말라고 주의를 주고 있어요.', '[{"text":"얘, 미끄럼틀은 아래에서 위로 올라가면 다른 친구랑 부딪힐 수 있어.","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"앞으로는 순서를 지켜서 타 줄래?","speaker":"A"},{"text":"네, 조심할게요.","speaker":"B"}]'::jsonb, '[{"label":"죄송해요, 재미있어서 그랬어요."},{"label":"저는 잘못한 거 없는데요."},{"label":"다른 애들도 다 그래요."},{"label":"싫어요, 계속 할래요."}]'::jsonb, 0, 112)
