insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-crossing-guard-traffic-safety', '등굣길 횡단보도에서 녹색어머니회 선생님이 안전하게 건너는 법을 알려주고 있어요.', '[{"text":"얘, 횡단보도를 건널 땐 좌우를 꼭 살펴야 해.","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"그래, 그렇게 하면 훨씬 안전해.","speaker":"A"},{"text":"알려주셔서 감사해요!","speaker":"B"}]'::jsonb, '[{"label":"빨간불에도 빨리 뛰어갈래요."},{"label":"네, 초록불이어도 확인하고 건널게요."},{"label":"귀찮으니까 그냥 건널게요."},{"label":"신경 안 써도 되잖아요."}]'::jsonb, 1, 113)
