insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-elevator-neighbor-greeting', '아파트 엘리베이터에서 이웃 아저씨를 만나 인사하고 있어요.', '[{"text":"안녕하세요! 오늘 날씨가 참 좋네요.","speaker":"A"},{"text":"그러게, 반갑구나. 학교 다녀오는 길이니?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그래, 오늘도 좋은 하루 보내렴!","speaker":"B"}]'::jsonb, '[{"label":"🙄","isEmoji":true},{"label":"😠","isEmoji":true},{"label":"😊","isEmoji":true},{"label":"😴","isEmoji":true}]'::jsonb, 2, 114)
