insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-village-bus-driver-bell-question', '마을버스 안에서 기사님께 하차벨 위치를 여쭤보고 있어요.', '[{"text":"기사님, 하차벨이 어디 있는지 모르겠어요.","speaker":"A"},{"text":"저기 창문 옆에 노란 버튼이 있단다.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그래, 미리 눌러야 기사님이 알 수 있어.","speaker":"B"}]'::jsonb, '[{"label":"몰라도 상관없어요."},{"label":"안 눌러도 될 것 같아요."},{"label":"그냥 소리쳐서 세울게요."},{"label":"아, 찾았어요! 다음 정류장에서 누를게요."}]'::jsonb, 3, 115)
