insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-subway-staff-card-recharge', '지하철역에서 역무원 아저씨께 교통카드 충전 방법을 여쭤보고 있어요.', '[{"text":"아저씨, 교통카드를 어떻게 충전해야 해요?","speaker":"A"},{"text":"저기 충전기에 카드를 대고 돈을 넣으면 돼.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"응, 카드 충전도 가능하니 걱정하지 마.","speaker":"B"}]'::jsonb, '[{"label":"현금이 없는데 카드로도 충전할 수 있나요?"},{"label":"그냥 안 탈래요."},{"label":"충전은 필요 없어요."},{"label":"돈은 아저씨가 내주세요."}]'::jsonb, 0, 116)
