insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-taxi-driver-destination', '택시를 타고 기사님께 가고 싶은 곳을 설명하고 있어요.', '[{"text":"손님, 어디로 모실까요?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"알겠습니다, 금방 도착할 거예요.","speaker":"A"},{"text":"감사합니다!","speaker":"B"}]'::jsonb, '[{"label":"아무 데나 가주세요."},{"label":"시립도서관으로 가주세요, 정문 앞에 내려주시면 돼요."},{"label":"몰라요, 기사님이 정해주세요."},{"label":"그냥 돌아다녀 주세요."}]'::jsonb, 1, 117)
