insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-village-festival-signup', '마을 축제 담당자님께 장기자랑 참가 신청을 하고 있어요.', '[{"text":"이번 마을 축제 장기자랑에 참가하고 싶어요.","speaker":"A"},{"text":"좋아, 어떤 걸 준비했니?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"재밌겠다, 신청서에 이름을 적어줄래?","speaker":"B"}]'::jsonb, '[{"label":"참가 취소할래요."},{"label":"아무것도 준비 안 했어요."},{"label":"그냥 구경만 할래요."},{"label":"친구랑 같이 춤을 준비했어요."}]'::jsonb, 3, 119)
