insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-librarian-reading-quiz-prep', '도서관 사서 선생님과 독서 골든벨 대회를 준비하고 있어요.', '[{"text":"선생님, 독서 골든벨에 어떤 책이 나올까요?","speaker":"A"},{"text":"이번 학기에 다 같이 읽은 책들 위주로 나올 거야.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"좋은 생각이야, 요약 노트를 만들어봐도 좋아.","speaker":"B"}]'::jsonb, '[{"label":"그냥 안 볼래요."},{"label":"그럼 그 책들을 다시 한번 읽어봐야겠어요."},{"label":"한 권도 안 읽었는데 어떡하죠."},{"label":"대회는 재미없을 것 같아요."}]'::jsonb, 1, 121)
