insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-festival-volunteer-signup', '지역 축제 자원봉사 담당자님께 봉사활동 신청을 하고 있어요.', '[{"text":"이번 축제에서 자원봉사를 하고 싶은데 어떻게 신청해요?","speaker":"A"},{"text":"이 신청서에 이름과 희망 시간을 적어주면 돼.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"좋아, 그럼 안내 데스크로 배정해줄게.","speaker":"B"}]'::jsonb, '[{"label":"아무 때나 상관없어요, 안 할래요."},{"label":"저는 오전 시간에 할 수 있어요."},{"label":"그냥 구경만 할래요."},{"label":"봉사는 힘들어서 싫어요."}]'::jsonb, 1, 125)
