insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-bank-teller-savings', '은행 창구직원 선생님과 용돈을 저금하는 방법을 상담하고 있어요.', '[{"text":"제 용돈을 조금씩 저금하고 싶은데 어떻게 해야 해요?","speaker":"A"},{"text":"통장을 만들고 매달 조금씩 넣으면 돼.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"좋은 계획이야, 꾸준히 하면 금방 모일 거야.","speaker":"B"}]'::jsonb, '[{"label":"저금은 귀찮아서 안 할래요."},{"label":"그럼 이번 달부터 오천 원씩 넣어볼게요."},{"label":"그냥 다 써버릴래요."},{"label":"통장은 필요 없어요."}]'::jsonb, 1, 129)
