insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-amusement-park-info-desk-lost-item', '놀이공원 안내소에서 잃어버린 모자를 찾아준 직원분께 인사하고 있어요.', '[{"text":"저기, 제 모자를 찾아주셔서 정말 감사해요!","speaker":"A"},{"text":"아니야, 벤치에 놓고 갔더라고. 여기 있어.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"다음엔 물건 잘 챙기렴!","speaker":"B"}]'::jsonb, '[{"label":"🙄","isEmoji":true},{"label":"😤","isEmoji":true},{"label":"😊","isEmoji":true},{"label":"😴","isEmoji":true}]'::jsonb, 2, 130)
