insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-tourist-info-center-travel-question', '여행 중 관광안내소 직원분께 가볼 만한 곳을 여쭤보고 있어요.', '[{"text":"저희 가족이 오늘 하루 여기 있는데, 어디가 좋을까요?","speaker":"A"},{"text":"근처에 아이들이 좋아하는 체험 박물관이 있어.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"여기서 버스로 십 분 정도면 갈 수 있어.","speaker":"B"}]'::jsonb, '[{"label":"박물관은 재미없어요."},{"label":"별로 안 궁금해요."},{"label":"그냥 숙소에 있을래요."},{"label":"오, 좋아요! 거기까지 어떻게 가면 되나요?"}]'::jsonb, 3, 131)
