insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-swim-coach-stroke-correction', '수영장에서 코치님이 자유형 팔 동작을 교정해주고 있어요.', '[{"text":"코치님, 팔을 저을 때 자꾸 힘이 빠져요.","speaker":"A"},{"text":"팔꿈치를 더 높이 들고 물을 밀어내듯 저어봐.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"맞아, 그 느낌 잊지 말고 계속 연습해봐.","speaker":"B"}]'::jsonb, '[{"label":"아, 이렇게요? 훨씬 앞으로 잘 나가는 것 같아요!"},{"label":"수영은 이제 안 할래요."},{"label":"팔은 그냥 아무렇게나 저을래요."},{"label":"코치님이 대신 헤엄쳐 주세요."}]'::jsonb, 0, 132)
