insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-baseball-coach-batting-form', '야구 코치님이 타격 자세를 봐주고 있어요.', '[{"text":"코치님, 방망이를 어떻게 잡아야 힘이 더 실려요?","speaker":"A"},{"text":"손을 배꼽 높이에 두고 어깨 힘을 빼봐.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그렇지, 그 자세로 계속 연습해보자.","speaker":"B"}]'::jsonb, '[{"label":"타격은 재미없어요."},{"label":"방망이는 아무렇게나 잡을래요."},{"label":"이렇게 하니까 훨씬 편하게 휘둘러져요."},{"label":"힘은 안 줘도 되잖아요."}]'::jsonb, 2, 134)
