insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-amusement-park-info-desk-lost-parent', '놀이공원에서 부모님을 잃어버려 안내소 직원분께 도움을 요청하고 있어요.', '[{"text":"저... 부모님이랑 떨어져서 못 찾겠어요.","speaker":"A"},{"text":"놀라지 마, 부모님 성함이나 연락처 아니?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"잘했어, 그럼 방송으로 안내하고 전화도 걸어줄게.","speaker":"B"}]'::jsonb, '[{"label":"그냥 여기 앉아 있을래요."},{"label":"몰라요, 그냥 혼자 찾을래요."},{"label":"저 원래 혼자 다녀요."},{"label":"네, 엄마 전화번호는 기억하고 있어요."}]'::jsonb, 3, 135)
