insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-subway-staff-lost-parent-help', '지하철역에서 사람이 많아 부모님을 놓쳐 역무원 아저씨께 도움을 요청하고 있어요.', '[{"text":"아저씨, 사람이 많아서 엄마를 놓쳤어요.","speaker":"A"},{"text":"걱정 마, 어느 역에서 타고 어디로 가는 길이었니?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"알겠어, 방송실에 연락해서 찾아볼게.","speaker":"B"}]'::jsonb, '[{"label":"시청역에서 타서 잠실역으로 가는 길이었어요."},{"label":"몰라요, 그냥 아무 데나 갈래요."},{"label":"혼자 집에 갈 수 있어요."},{"label":"괜찮아요, 신경 쓰지 마세요."}]'::jsonb, 0, 136)
