insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-museum-docent-exhibit-question', '박물관에서 도슨트 선생님께 전시된 유물에 대해 여쭤보고 있어요.', '[{"text":"선생님, 이 그릇은 옛날에 뭐 하는 데 썼어요?","speaker":"A"},{"text":"이건 옛날 사람들이 곡식을 담아두던 항아리야.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"맞아, 천 년도 더 된 거란다.","speaker":"B"}]'::jsonb, '[{"label":"빨리 나가고 싶어요."},{"label":"그냥 평범한 그릇 같은데요."},{"label":"박물관은 지루해요."},{"label":"우와, 정말 오래된 물건이네요!"}]'::jsonb, 3, 139)
