insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-library-book-return-overdue', '도서관 사서 선생님께 연체된 책 반납에 대해 여쭤보고 있어요.', '[{"text":"선생님, 책을 늦게 반납했는데 어떡하죠?","speaker":"A"},{"text":"며칠 늦었는지에 따라 연체료가 조금 있을 수 있어.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그래, 다음부터 기한을 잘 지켜주면 돼.","speaker":"B"}]'::jsonb, '[{"label":"다시는 책 안 빌릴래요."},{"label":"그게 뭐 큰일이라고요."},{"label":"연체료는 안 낼래요."},{"label":"죄송해요, 다음부턴 날짜를 꼭 확인할게요."}]'::jsonb, 3, 143)
