insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-village-choir-director', '마을 합창단 지휘자 선생님과 다음 발표회 곡을 연습하고 있어요.', '[{"text":"선생님, 이 부분에서 자꾸 음이 틀려요.","speaker":"A"},{"text":"여기서는 숨을 미리 크게 들이쉬고 불러봐.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"좋아, 그 느낌으로 계속 연습해보자.","speaker":"B"}]'::jsonb, '[{"label":"노래는 이제 안 할래요."},{"label":"아, 이렇게 하니까 소리가 훨씬 안정적이에요."},{"label":"합창은 재미없어요."},{"label":"선생님이 대신 불러주세요."}]'::jsonb, 1, 149)
