insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('community-cooking-class-instructor', '문화센터 요리교실에서 강사님과 함께 만든 요리를 완성했어요.', '[{"text":"선생님, 저 드디어 오므라이스를 완성했어요!","speaker":"A"},{"text":"우와, 모양도 예쁘게 잘 만들었네!","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"다음엔 더 어려운 요리에도 도전해보자!","speaker":"B"}]'::jsonb, '[{"label":"😡","isEmoji":true},{"label":"😭","isEmoji":true},{"label":"😆","isEmoji":true},{"label":"😑","isEmoji":true}]'::jsonb, 2, 150)
