insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-allowance-negotiate', '이번 달 용돈을 올려달라고 부모님과 이야기하고 있어요.', '[{"text":"엄마, 저 이번 달부터 용돈을 조금 올려주실 수 있어요?","speaker":"A"},{"text":"갑자기 왜 그런 생각을 했어?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그렇구나, 그럼 얼마나 필요한지 같이 이야기해볼까?","speaker":"B"}]'::jsonb, '[{"label":"요즘 준비물 살 일이 많아져서 그래요."},{"label":"그냥 무조건 더 주세요."},{"label":"친구들도 다 많이 받아요."},{"label":"이유는 없고 그냥요."}]'::jsonb, 0, 151)
