insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-sibling-fight-makeup', '장난감 때문에 다툰 동생과 화해하려고 해요.', '[{"text":"아까 너무 세게 말해서 미안해.","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"그럼 우리 이제 화해한 거지?","speaker":"A"},{"text":"응! 이제 같이 놀자.","speaker":"B"}]'::jsonb, '[{"label":"😠","isEmoji":true},{"label":"😊","isEmoji":true},{"label":"🙄","isEmoji":true},{"label":"😢","isEmoji":true}]'::jsonb, 1, 152)
