insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-chores-schedule', '가족이 모여 집안일을 어떻게 나눌지 이야기하고 있어요.', '[{"text":"이번 주부터 집안일을 나눠서 해보는 게 어때?","speaker":"A"},{"text":"좋아요! 저는 뭘 맡으면 될까요?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"네, 설거지는 자신 있어요!","speaker":"B"}]'::jsonb, '[{"label":"넌 그냥 아무것도 안 해도 돼."},{"label":"집안일은 원래 어른만 하는 거야."},{"label":"저녁마다 설거지를 맡아주면 어때?"},{"label":"네 마음대로 골라, 상관없어."}]'::jsonb, 2, 153)
