insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-trip-destination-vote', '이번 여름 가족여행지를 어디로 갈지 상의하고 있어요.', '[{"text":"이번엔 바다랑 산 중에 어디로 갈까?","speaker":"A"},{"text":"저는 바다에 가서 물놀이하고 싶어요!","speaker":"B"},{"text":"그렇구나, 아빠는 산에서 캠핑도 좋을 것 같은데.","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"무조건 바다 아니면 안 갈래요."},{"label":"여행 자체를 안 가고 싶어요."},{"label":"아빠는 신경 쓰지 말고 저만 정할게요."},{"label":"그럼 이번엔 바다, 다음엔 산으로 가는 건 어때요?"}]'::jsonb, 3, 154)
