insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-report-card-share', '성적표를 받고 부모님께 보여드리고 있어요.', '[{"text":"이번 학기 성적표 나왔어요.","speaker":"A"},{"text":"어디 보자, 열심히 한 게 보이네.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"괜찮아, 다음엔 그 과목도 같이 노력해보자.","speaker":"B"}]'::jsonb, '[{"label":"근데 수학은 생각보다 점수가 낮게 나왔어요."},{"label":"성적표는 보여드리기 싫어요."},{"label":"공부 안 해도 다 잘 나와요."},{"label":"이제 성적 얘기는 그만하고 싶어요."}]'::jsonb, 0, 155)
