insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-pet-request-hamster', '햄스터를 기르고 싶다고 부모님을 설득하고 있어요.', '[{"text":"엄마, 저 햄스터 한 마리만 키우면 안 돼요?","speaker":"A"},{"text":"돌보는 게 쉽지 않을 텐데, 자신 있어?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그렇게까지 계획했다니, 한번 생각해볼게.","speaker":"B"}]'::jsonb, '[{"label":"그냥 엄마가 알아서 돌봐주세요."},{"label":"네, 밥 주고 청소하는 것도 제가 다 할게요."},{"label":"힘들면 금방 버릴 거예요."},{"label":"자신은 없지만 그냥 키우고 싶어요."}]'::jsonb, 1, 156)
