insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-bedtime-rule-talk', '밤늦게까지 안 자려는 것 때문에 부모님과 이야기하고 있어요.', '[{"text":"오늘도 늦게까지 안 자고 있네.","speaker":"A"},{"text":"조금만 더 하고 잘게요.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"네, 10시까지만 하고 잘게요.","speaker":"B"}]'::jsonb, '[{"label":"평생 자지 마."},{"label":"몇 시에 자든 상관없어."},{"label":"그냥 지금 당장 끄고 자."},{"label":"그럼 10시까지만 하고 자는 걸로 약속하자."}]'::jsonb, 3, 158)
