insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-holiday-prep-help', '명절을 앞두고 할머니와 함께 전을 부치며 이야기하고 있어요.', '[{"text":"할머니, 저도 전 부치는 거 도와드릴게요!","speaker":"A"},{"text":"오구, 기특하네. 조심해서 뒤집어봐.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"허허, 그렇게 하면 훌륭하지.","speaker":"B"}]'::jsonb, '[{"label":"😑","isEmoji":true},{"label":"😊","isEmoji":true},{"label":"😤","isEmoji":true},{"label":"🥱","isEmoji":true}]'::jsonb, 1, 160)
