insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-grandma-phone-call', '오랜만에 할머니께 전화를 드려 안부를 여쭙고 있어요.', '[{"text":"할머니, 저 민서예요! 잘 지내셨어요?","speaker":"A"},{"text":"우리 강아지구나, 할미는 잘 지내지.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그래, 다음 주말에 꼭 놀러 오렴.","speaker":"B"}]'::jsonb, '[{"label":"바쁘니까 끊을게요."},{"label":"전화하기 귀찮았는데 어쩔 수 없이 했어요."},{"label":"보고 싶어요, 이번 주말에 놀러 가도 돼요?"},{"label":"딱히 할 말 없어요."}]'::jsonb, 2, 161)
