insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-moving-house-news', '다음 달에 이사를 간다는 소식을 부모님께 듣고 있어요.', '[{"text":"우리 다음 달에 새 집으로 이사 갈 거야.","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"학교는 걱정 마, 전학 절차도 다 알아봤어.","speaker":"A"},{"text":"그럼 새 학교에서도 잘 지내볼게요.","speaker":"B"}]'::jsonb, '[{"label":"이사 절대 안 갈래요."},{"label":"어디로 가든 상관없어요."},{"label":"친구들 얘기는 꺼내지도 마세요."},{"label":"그렇구나, 근데 학교는 어떻게 되는 거예요?"}]'::jsonb, 3, 162)
