insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-future-dream-talk', '새로 생긴 장래희망을 부모님께 이야기하고 있어요.', '[{"text":"엄마, 저 요즘 수의사가 되고 싶다는 생각이 들어요.","speaker":"A"},{"text":"오, 언제부터 그런 생각을 했어?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"멋진 꿈이네, 우리 딸을 응원할게.","speaker":"B"}]'::jsonb, '[{"label":"그냥 아무 생각 없이 말한 거예요."},{"label":"동물병원에서 강아지 치료하는 걸 보고 나서요."},{"label":"수의사는 별로 안 좋아해요."},{"label":"꿈 같은 건 필요 없어요."}]'::jsonb, 1, 164)
