insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-house-meeting-rules', '저녁 식사 후 가족회의를 열어 집안 규칙을 정하고 있어요.', '[{"text":"오늘은 가족회의를 열어서 우리 집 규칙을 다시 정해볼까?","speaker":"A"},{"text":"저는 방 청소하는 시간을 정했으면 좋겠어요.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"네, 그 정도면 저도 할 수 있어요.","speaker":"B"}]'::jsonb, '[{"label":"청소는 절대 안 할 거야."},{"label":"규칙 같은 거 필요 없어."},{"label":"그건 네가 알아서 해."},{"label":"그럼 일요일 저녁마다 다 같이 정리하는 건 어때?"}]'::jsonb, 3, 166)
