insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-dinner-while-parents-late', '부모님이 늦게 오셔서 동생과 저녁을 챙겨 먹고 있어요.', '[{"text":"엄마 아빠 오늘 늦게 오신다는데, 저녁 뭐 먹을까?","speaker":"A"},{"text":"나 배고픈데 계란볶음밥 해줄 수 있어?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"좋아! 형이 해주는 거 진짜 맛있어.","speaker":"B"}]'::jsonb, '[{"label":"그래, 조심해서 같이 만들어보자."},{"label":"귀찮으니까 그냥 굶어."},{"label":"나도 몰라, 알아서 먹어."},{"label":"부모님 오실 때까지 기다려."}]'::jsonb, 0, 167)
