insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-cousin-visit', '주말에 놀러 오는 사촌을 맞이할 준비를 하고 있어요.', '[{"text":"이번 주말에 사촌 형이 놀러 온대.","speaker":"A"},{"text":"진짜? 무슨 놀이 하면서 놀지?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"좋은 생각이야, 나도 그거 하고 싶었어!","speaker":"B"}]'::jsonb, '[{"label":"그냥 각자 방에서 놀자."},{"label":"보드게임이랑 자전거 타기 준비해두자."},{"label":"사촌이랑은 안 놀고 싶어."},{"label":"놀 거 없으니까 그냥 자."}]'::jsonb, 1, 168)
