insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('family-lost-at-amusement-park', '놀이공원에서 부모님을 놓쳐 전화로 위치를 확인하고 있어요.', '[{"text":"엄마, 저 사람들 사이에서 엄마를 놓쳐버렸어요.","speaker":"A"},{"text":"괜찮아, 침착하게 주변에 뭐가 보이는지 말해줄래?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"좋아, 거기 안내소가 어디인지 알아. 금방 갈게, 그 자리에 있어.","speaker":"B"}]'::jsonb, '[{"label":"모르겠어요, 그냥 아무 데나 갈게요."},{"label":"이제 혼자 집에 갈래요."},{"label":"엄마를 찾아다니면서 뛰어다닐게요."},{"label":"큰 회전목마 옆에 안내소 같은 곳이 보여요."}]'::jsonb, 3, 190)
