insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('teacher-presentation-slide-check', '발표 자료를 만들어서 선생님께 확인받고 있어요.', '[{"text":"선생님, 제 발표 자료 한번 봐주실 수 있어요?","speaker":"A"},{"text":"그럼, 어디 보자. 그림도 잘 넣었네.","speaker":"B"},{"text":"근데 설명이 너무 긴 것 같아서 걱정이에요.","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"그냥 이대로 해."},{"label":"발표는 짧을수록 좋으니 다 지워."},{"label":"중요한 내용만 골라서 조금 줄여보자."},{"label":"발표 안 해도 돼."}]'::jsonb, 2, 196)
