insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('hospital-athletes-foot-checkup', '발가락 사이가 가려워서 피부과에서 무좀을 진료받고 있어요.', '[{"text":"발가락 사이가 가렵고 허물이 벗겨지니?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"그럼 무좀약을 발라주고 양말은 자주 갈아 신자.","speaker":"A"},{"text":"네, 양말도 자주 갈아 신을게요.","speaker":"B"}]'::jsonb, '[{"label":"네, 운동화 신고 나면 더 가려워요."},{"label":"아니요, 발은 멀쩡해요."},{"label":"양말은 갈아 신기 귀찮아요."},{"label":"발은 원래 가려운 거예요."}]'::jsonb, 0, 254)
