insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('online-emoji-spam-request', '채팅방에서 이모티콘을 너무 많이 보내는 친구에게 부드럽게 부탁하고 있어요.', '[{"text":"이모티콘 도배하니까 중요한 메시지를 놓칠 것 같아, 조금만 줄여줄 수 있어?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"고마워, 이해해줘서!","speaker":"A"},{"text":"아니야, 나도 신경 쓸게!","speaker":"B"}]'::jsonb, '[{"label":"내 맘이야, 계속 보낼래"},{"label":"아 미안, 몰랐어. 앞으로 조심할게"},{"label":"싫어, 재밌잖아"},{"label":"그럼 채팅방 나갈래"}]'::jsonb, 1, 380)
