insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('online-videocall-reconnect-slow-net', '화상통화 중 인터넷이 느려져서 다시 연결하려고 이야기하고 있어요.', '[{"text":"어? 네 화면이 자꾸 멈춰, 인터넷 괜찮아?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"알겠어, 잠깐 기다릴게.","speaker":"A"},{"text":"미안, 이제 잘 나오지?","speaker":"B"}]'::jsonb, '[{"label":"몰라, 그냥 이대로 할래"},{"label":"내 문제 아니야, 네가 이상한 거 아니야?"},{"label":"신경 쓰지 마"},{"label":"미안, 인터넷이 느려진 것 같아. 다시 연결해볼게"}]'::jsonb, 3, 382)
