insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('online-groupchat-invite-thanks-emoji', '새로 전학 온 친구를 반 단체 채팅방에 초대해줘서 고마워하고 있어요.', '[{"text":"너 아직 우리 반톡 안 들어와 있길래 초대했어!","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"잘 왔어! 모르는 거 있으면 언제든 물어봐.","speaker":"A"},{"text":"고마워, 잘 지내보자!","speaker":"B"}]'::jsonb, '[{"label":"😐","isEmoji":true},{"label":"😊","isEmoji":true},{"label":"🙄","isEmoji":true},{"label":"😤","isEmoji":true}]'::jsonb, 1, 384)
