insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-airport-checkin-luggage-weight', '공항 체크인 카운터에서 캐리어 무게가 초과됐다는 안내를 받고 있어요.', '[{"text":"저희 캐리어가 무게 초과라고 하셨는데 어떻게 해야 하나요?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"네, 그럼 무거운 책 몇 권을 기내용 가방으로 옮길게요.","speaker":"A"},{"text":"좋습니다, 옮기고 다시 저울에 올려주세요.","speaker":"B"}]'::jsonb, '[{"label":"짐 일부를 기내용 가방으로 옮기시면 초과 요금 없이 가능해요."},{"label":"그냥 짐을 다 버리세요."},{"label":"저희는 도와드릴 수 없어요."},{"label":"비행기를 놓치실 것 같아요."}]'::jsonb, 0, 385)
