insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-airport-security-liquids-check', '공항 보안 검색대에서 액체류 반입 규정에 대해 안내받고 있어요.', '[{"text":"이 물통은 가지고 탈 수 있나요?","speaker":"A"},{"text":"100밀리리터 이상 액체는 반입이 안 돼서 비우거나 버리셔야 해요.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"네, 저기 정수기에서 다시 채우실 수 있어요.","speaker":"B"}]'::jsonb, '[{"label":"저는 그냥 몰래 가지고 갈래요."},{"label":"그건 너무 불공평해요."},{"label":"물은 원래 다 가지고 탈 수 있잖아요."},{"label":"그럼 안에 있는 물은 여기서 비울게요."}]'::jsonb, 3, 386)
