insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-flight-attendant-meal-choice', '비행기 안에서 승무원분께 기내식을 주문하고 있어요.', '[{"text":"식사는 치킨과 비빔밥 중에 어떤 걸로 드릴까요?","speaker":"A"},{"text":"저는 비빔밥으로 주세요.","speaker":"B"},{"text":"네, 음료는 뭘로 드릴까요?","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"아무거나 상관없어요."},{"label":"그냥 다 가져다주세요."},{"label":"오렌지 주스로 주세요, 감사합니다."},{"label":"저 음료는 안 마셔요."}]'::jsonb, 2, 387)
