insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-train-ticket-seat-confusion', '기차역에서 표에 적힌 좌석 번호를 확인하고 있어요.', '[{"text":"이 표에 적힌 좌석이 몇 호차인지 잘 모르겠어요.","speaker":"A"},{"text":"표 위쪽에 있는 숫자를 보면 돼요, 3호차 12번이네요.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"네, 저쪽 계단으로 내려가시면 돼요.","speaker":"B"}]'::jsonb, '[{"label":"저는 이 표 필요 없어요."},{"label":"숫자는 안 믿어요."},{"label":"그냥 아무 데나 앉을래요."},{"label":"아, 감사합니다! 그럼 저쪽으로 가면 되나요?"}]'::jsonb, 3, 390)
