insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-train-conductor-wrong-seat', '기차에서 다른 사람 좌석에 잘못 앉아 있다는 걸 알게 됐어요.', '[{"text":"실례지만 여기 제 자리인 것 같은데요.","speaker":"A"},{"text":"아, 죄송해요! 표를 잘못 봤나 봐요.","speaker":"B"},{"text":"제 자리는 아마 뒤쪽인 것 같아요.","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"그럴 리가 없는데요."},{"label":"자리는 다 똑같잖아요."},{"label":"네, 천천히 확인해 보세요."},{"label":"빨리 좀 비켜주세요."}]'::jsonb, 2, 391)
