insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-hotel-checkin-early-request', '호텔 프런트에서 예정보다 일찍 체크인이 가능한지 문의하고 있어요.', '[{"text":"저희가 좀 일찍 도착했는데 지금 체크인이 될까요?","speaker":"A"},{"text":"확인해 볼게요, 방이 준비되면 바로 안내해 드릴게요.","speaker":"B"},{"text":"네, 그동안 짐만 맡겨도 될까요?","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"저희도 몰라요."},{"label":"그럼요, 이쪽에 보관해 드릴게요."},{"label":"짐은 못 맡아드려요."},{"label":"그냥 밖에 두세요."}]'::jsonb, 1, 392)
