insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-hotel-extra-towel-request', '호텔 프런트에 전화해서 수건을 더 요청하고 있어요.', '[{"text":"안녕하세요, 저희 방에 수건이 두 개뿐인데 더 받을 수 있을까요?","speaker":"A"},{"text":"네, 몇 개나 더 필요하신가요?","speaker":"B"},{"text":"두 개만 더 가져다주시면 될 것 같아요.","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"알겠습니다, 10분 안에 가져다드릴게요."},{"label":"수건은 못 드려요."},{"label":"다음에 가져다드릴게요."},{"label":"그건 저희 담당이 아니에요."}]'::jsonb, 0, 393)
