insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-tour-guide-photo-spot-recommend', '여행 가이드분께 사진 찍기 좋은 장소를 추천받고 있어요.', '[{"text":"여기서 사진 찍기 제일 좋은 곳이 어디예요?","speaker":"A"},{"text":"저 다리 위에서 찍으면 노을이랑 같이 예쁘게 나와요.","speaker":"B"},{"text":"오, 그럼 지금 가서 찍어봐도 돼요?","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"사진은 못 찍게 해요."},{"label":"네, 시간 충분하니까 다녀오세요."},{"label":"시간이 없어서 안 돼요."},{"label":"다리는 위험해서 안 돼요."}]'::jsonb, 1, 396)
