insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-fellow-traveler-train-chat', '기차에서 옆자리에 앉은 또래 여행객과 이야기를 나누고 있어요.', '[{"text":"안녕, 너도 부산으로 여행 가는 거야?","speaker":"A"},{"text":"응! 해운대 가려고. 너는 어디 가?","speaker":"B"},{"text":"나도 해운대 가는데! 같이 사진 찍을 친구 생겼네.","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"진짜? 완전 반갑다, 도착하면 같이 다니자!"},{"label":"난 너랑 안 다닐래."},{"label":"그게 무슨 상관이야."},{"label":"관심 없어."}]'::jsonb, 0, 397)
