insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-local-resident-landmark-directions', '낯선 도시에서 지나가는 주민분께 유명한 탑으로 가는 길을 여쭤보고 있어요.', '[{"text":"저... 실례지만 여기서 탑까지 어떻게 가야 하나요?","speaker":"A"},{"text":"이 길을 따라 쭉 가다가 두 번째 골목에서 왼쪽으로 꺾으면 돼요.","speaker":"B"},{"text":"알겠습니다, 그럼 걸어서 얼마나 걸릴까요?","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"그건 저도 몰라요."},{"label":"걸어서는 못 가요."},{"label":"시간은 안 알려드려요."},{"label":"한 10분 정도면 도착할 거예요."}]'::jsonb, 3, 398)
