insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-foreign-tourist-subway-help-korea', '한국에 온 외국인 관광객이 지하철 타는 법을 몰라 도움을 요청하고 있어요.', '[{"text":"Excuse me, could you help me? I don''t know how to use this subway card machine.","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"Oh, thank you so much! Which line should I take?","speaker":"A"},{"text":"이 노선으로 타시면 환승 없이 바로 가실 수 있어요.","speaker":"B"}]'::jsonb, '[{"label":"그냥 다른 사람한테 물어보세요."},{"label":"지하철은 복잡해서 몰라요."},{"label":"네, 제가 도와드릴게요! 여기 화면에서 목적지를 누르시면 돼요."},{"label":"저는 영어 못해서 몰라요."}]'::jsonb, 2, 399)
on conflict (id) do update set situation = excluded.situation, messages = excluded.messages, choices = excluded.choices, answer_index = excluded.answer_index, sort_order = excluded.sort_order;
insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-foreign-tourist-hanbok-rental-question', '외국인 관광객이 한복을 어디서 빌릴 수 있는지 물어보고 있어요.', '[{"text":"혹시 한복을 빌릴 수 있는 곳이 어디 있는지 아세요?","speaker":"A"},{"text":"네! 저기 골목 안쪽에 한복 대여점이 있어요.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그럼요, 특히 오후 햇살에 찍으면 정말 예뻐요.","speaker":"B"}]'::jsonb, '[{"label":"저는 잘 몰라요."},{"label":"정말요? 궁 앞에서 입으면 사진도 예쁘게 나올까요?"},{"label":"한복은 안 예뻐요."},{"label":"거기까지 안 갈래요."}]'::jsonb, 1, 400)
