insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-customs-officer-declare-item', '공항 세관에서 신고할 물품이 있는지 안내받고 있어요.', '[{"text":"혹시 신고하실 물품이 있으신가요?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"과일은 반입이 안 되니 여기서 폐기해 주셔야 해요.","speaker":"A"},{"text":"아, 알겠습니다, 여기 두면 될까요?","speaker":"B"}]'::jsonb, '[{"label":"과일이랑 견과류를 조금 가져왔는데 괜찮을까요?"},{"label":"저는 아무것도 안 가져왔어요."},{"label":"신고는 필요 없잖아요."},{"label":"그냥 몰래 가지고 갈래요."}]'::jsonb, 0, 401)
