insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-restaurant-unfamiliar-food-order', '여행지 식당에서 처음 보는 음식을 종업원분께 여쭤보며 주문하고 있어요.', '[{"text":"이 메뉴는 어떤 맛이에요? 처음 보는 음식이라서요.","speaker":"A"},{"text":"약간 매콤하면서 새콤한 맛이에요, 인기 메뉴예요.","speaker":"B"},{"text":"오, 그럼 그걸로 한번 먹어볼게요.","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"그 메뉴는 못 팔아요."},{"label":"다른 걸로 바꾸세요."},{"label":"오래 걸릴 거예요, 포기하세요."},{"label":"좋은 선택이세요, 곧 가져다드릴게요."}]'::jsonb, 3, 402)
