insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-souvenir-shop-haggle-price', '여행지 기념품 가게에서 가격을 여쭤보고 있어요.', '[{"text":"이 열쇠고리는 얼마예요?","speaker":"A"},{"text":"두 개에 5천 원이에요.","speaker":"B"},{"text":"그럼 세 개 사면 조금 깎아주실 수 있나요?","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"그냥 다른 데 가서 사세요."},{"label":"비싸도 어쩔 수 없어요."},{"label":"좋아요, 세 개에 7천 원으로 드릴게요."},{"label":"할인은 절대 안 돼요."}]'::jsonb, 2, 403)
