insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-souvenir-shop-family-gift-choice', '가족들에게 줄 기념품을 고르며 점원분과 이야기하고 있어요.', '[{"text":"부모님께 드릴 선물로 뭐가 좋을까요?","speaker":"A"},{"text":"이 전통차 세트가 어르신들께 인기가 많아요.","speaker":"B"},{"text":"좋네요, 그럼 이걸로 두 세트 주세요.","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"포장할 시간 없어요."},{"label":"포장도 예쁘게 해드릴까요?"},{"label":"포장은 안 해드려요."},{"label":"그냥 봉지에 담아가세요."}]'::jsonb, 1, 404)
