insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-timezone-call-grandma-confusion', '시차 때문에 할머니께 전화드릴 시간을 여행 동행 친구와 상의하고 있어요.', '[{"text":"지금 한국은 몇 시일까? 할머니께 전화드리고 싶은데.","speaker":"A"},{"text":"여기가 저녁 7시니까 한국은 아마 새벽일 거야.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"응, 한국 아침 시간에 맞춰서 걸어보자.","speaker":"B"}]'::jsonb, '[{"label":"아, 그럼 조금 이따가 전화드려야겠다."},{"label":"상관없이 그냥 지금 걸래."},{"label":"시차는 왜 있는 거야?"},{"label":"전화 안 할래."}]'::jsonb, 0, 405)
