insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-jetlag-companion-notice-sleepy-emoji', '장시간 비행 후 시차 적응이 안 돼서 계속 졸린 상태예요.', '[{"text":"괜찮아? 계속 하품하네.","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"그럼 조금 쉬었다가 나갈까?","speaker":"A"},{"text":"응, 잠깐 눈 좀 붙일게.","speaker":"B"}]'::jsonb, '[{"label":"😆","isEmoji":true},{"label":"😡","isEmoji":true},{"label":"🤩","isEmoji":true},{"label":"😪","isEmoji":true}]'::jsonb, 3, 406)
