insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-packing-list-friend-discussion', '여행 가기 전 친구와 짐 목록을 함께 확인하고 있어요.', '[{"text":"우산이랑 우비는 챙겼어?","speaker":"A"},{"text":"아, 깜빡했다! 지금 넣을게. 너는 충전기 챙겼어?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"좋아, 그럼 이제 준비 다 된 것 같아!","speaker":"B"}]'::jsonb, '[{"label":"그런 건 필요 없어."},{"label":"나 짐 안 챙겼어."},{"label":"응, 보조배터리까지 챙겼어."},{"label":"충전기가 뭐야?"}]'::jsonb, 2, 407)
