insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-itinerary-planning-vote', '여행 동행 친구와 오늘 갈 장소를 함께 정하고 있어요.', '[{"text":"오늘은 박물관이랑 시장 중에 어디 먼저 갈까?","speaker":"A"},{"text":"나는 시장이 더 궁금한데, 오전에 사람 적을 때 가는 게 어때?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"콜! 그럼 지금 바로 출발하자.","speaker":"B"}]'::jsonb, '[{"label":"그건 별로인 것 같아."},{"label":"좋은 생각이야, 그럼 시장 먼저 가고 박물관은 오후에 가자."},{"label":"난 아무데도 안 갈래."},{"label":"네 마음대로 정해."}]'::jsonb, 1, 408)
