insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-homestay-host-greeting', '해외 홈스테이 집에 도착해서 호스트 가족과 첫인사를 나누고 있어요.', '[{"text":"안녕하세요, 저는 이번에 머물게 된 학생이에요.","speaker":"A"},{"text":"만나서 반가워요! 여기가 네 방이야, 편하게 지내렴.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"필요한 게 있으면 언제든 얘기해줘.","speaker":"B"}]'::jsonb, '[{"label":"감사합니다, 잘 부탁드려요!"},{"label":"저는 별로 안 반가워요."},{"label":"방이 마음에 안 들어요."},{"label":"그냥 혼자 있을래요."}]'::jsonb, 0, 409)
