insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-beach-resort-snorkel-rental', '해변 리조트에서 스노클링 장비를 빌리고 있어요.', '[{"text":"스노클 장비 빌리려고 하는데 얼마예요?","speaker":"A"},{"text":"한 시간에 만 원이고, 구명조끼도 같이 드려요.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"네, 여기 서명하시고 준비해 드릴게요.","speaker":"B"}]'::jsonb, '[{"label":"구명조끼는 필요 없어요."},{"label":"너무 비싸서 안 빌릴래요."},{"label":"그냥 물에 안 들어갈래요."},{"label":"좋아요, 그럼 두 시간 빌릴게요."}]'::jsonb, 3, 410)
