insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-ski-resort-equipment-rental', '스키 리조트에서 처음으로 스키 장비를 대여하고 있어요.', '[{"text":"스키가 처음인데 어떤 장비가 필요해요?","speaker":"A"},{"text":"스키, 부츠, 폴대까지 세트로 빌려드릴게요, 발 사이즈가 어떻게 되세요?","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"확인했습니다, 헬멧도 필요하시면 같이 드릴게요.","speaker":"B"}]'::jsonb, '[{"label":"장비는 필요 없어요."},{"label":"그냥 눈만 구경할래요."},{"label":"230이에요."},{"label":"발 사이즈는 안 알려드려요."}]'::jsonb, 2, 411)
