insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-amusement-park-abroad-fastpass-question', '해외 놀이공원에서 패스트패스 이용 방법을 직원분께 여쭤보고 있어요.', '[{"text":"이 패스트패스는 어떻게 쓰는 거예요?","speaker":"A"},{"text":"앱으로 시간을 예약하면 그 시간에 줄 안 서고 탈 수 있어요.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"네, 원하는 놀이기구를 골라서 예약해 보세요.","speaker":"B"}]'::jsonb, '[{"label":"앱은 쓸 줄 몰라요."},{"label":"오, 그럼 지금 바로 예약해도 되나요?"},{"label":"그런 건 필요 없어요."},{"label":"그냥 줄 서서 기다릴래요."}]'::jsonb, 1, 412)
