insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-museum-abroad-audioguide-rental', '해외 박물관 입구에서 한국어 오디오가이드를 대여하고 있어요.', '[{"text":"한국어로 된 오디오가이드도 있나요?","speaker":"A"},{"text":"네, 여기서 헤드폰과 함께 빌려드려요.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"보증금은 관람 끝나고 반납하시면 돌려드려요.","speaker":"B"}]'::jsonb, '[{"label":"좋아요, 하나 빌릴게요."},{"label":"한국어는 필요 없어요."},{"label":"그냥 대충 볼래요."},{"label":"오디오가이드 몰라요."}]'::jsonb, 0, 413)
