insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-language-barrier-gesture-order', '말이 통하지 않는 가게에서 손짓으로 음식을 주문하고 있어요.', '[{"text":"저기요, 이거 하나 주세요.","speaker":"A"},{"text":"Sorry, I don''t understand Korean.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"Oh I see, one moment please!","speaker":"B"}]'::jsonb, '[{"label":"그냥 안 먹을래요."},{"label":"왜 한국어를 몰라요?"},{"label":"다른 가게 갈래요."},{"label":"아, 그럼 이 사진을 손가락으로 가리키며 손짓할게요."}]'::jsonb, 3, 414)
