insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-airport-lost-luggage-counter', '공항에서 짐이 안 나와서 분실물 카운터에 신고하고 있어요.', '[{"text":"제 캐리어가 아직 안 나왔는데 어떻게 해야 하나요?","speaker":"A"},{"text":"수하물표 좀 보여주시겠어요? 확인해 드릴게요.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"확인했습니다, 오늘 중으로 숙소로 배송해 드릴게요.","speaker":"B"}]'::jsonb, '[{"label":"그냥 포기할래요."},{"label":"짐은 필요 없어요."},{"label":"네, 여기 있어요."},{"label":"저 표 없는데요."}]'::jsonb, 2, 415)
