insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-flight-delay-waiting-companion', '비행기가 지연돼서 친구와 함께 공항에서 기다리고 있어요.', '[{"text":"두 시간이나 지연이래, 심심한데 뭐 할까?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"좋아, 그럼 저기 의자에 앉아서 하자.","speaker":"A"},{"text":"그래, 시간 금방 갈 거야.","speaker":"B"}]'::jsonb, '[{"label":"너 혼자 기다려."},{"label":"같이 카드게임 하면서 기다리자!"},{"label":"그냥 짜증만 낼래."},{"label":"아무것도 하기 싫어."}]'::jsonb, 1, 416)
