insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('travel-camping-trip-tent-setup-friend', '캠핑장에서 친구와 함께 텐트를 치고 있어요.', '[{"text":"이 기둥을 어디에 꽂아야 하는지 모르겠어.","speaker":"A"},{"text":"설명서 보니까 네 모서리에 하나씩 꽂으면 되나 봐.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"좋아, 나는 반대쪽 잡고 있을게.","speaker":"B"}]'::jsonb, '[{"label":"아, 그렇구나! 그럼 이쪽부터 해볼게."},{"label":"그냥 안 칠래."},{"label":"텐트는 너무 어려워."},{"label":"네가 다 해."}]'::jsonb, 0, 417)
