insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-celebrity-pretend-friendly', '낯선 사람이 유명한 사람이라며 친한 척 다가와요.', '[{"text":"어, 너 나 모르는구나! 나 티비에 나오는 사람인데, 사인 받고 싶으면 이리 와봐.","speaker":"A"},{"text":"아... 잘 모르겠어요.","speaker":"B"},{"text":"이리 와서 사진 한 장 찍자.","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"우와, 사인해 주세요!"},{"label":"진짜 유명하신 분이에요?"},{"label":"네, 사진 찍어요!"},{"label":"저는 여기서 볼게요, 괜찮아요."}]'::jsonb, 3, 502)
on conflict (id) do update set situation = excluded.situation, messages = excluded.messages, choices = excluded.choices, answer_index = excluded.answer_index, sort_order = excluded.sort_order;
insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-academy-pickup-lie', '학원 앞에서 처음 보는 사람이 선생님이 보내서 데리러 왔다고 해요.', '[{"text":"안녕, 학원 선생님이 오늘 나보고 대신 데리러 오라고 하셨어.","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"급하게 부탁받아서 그래, 얼른 가자.","speaker":"A"},{"text":"먼저 선생님께 전화드려서 확인해볼게요.","speaker":"B"}]'::jsonb, '[{"label":"정말요? 그럼 선생님께 먼저 전화해서 확인해볼게요."},{"label":"네, 알겠습니다."},{"label":"차는 어디 있어요?"},{"label":"선생님 성함이 뭐예요?"}]'::jsonb, 0, 503)
on conflict (id) do update set situation = excluded.situation, messages = excluded.messages, choices = excluded.choices, answer_index = excluded.answer_index, sort_order = excluded.sort_order;
insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-just-talk-detain', '골목에서 낯선 사람이 잠깐 이야기만 하자며 자꾸 붙잡아요.', '[{"text":"얘, 잠깐만 이야기 좀 하고 가자, 금방이면 돼.","speaker":"A"},{"text":"저 지금 집에 가야 해서요.","speaker":"B"},{"text":"딱 오 분만, 재밌는 얘기 해줄게.","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"음, 오 분만 있을게요."},{"label":"죄송해요, 지금은 안 될 것 같아요. 가볼게요."},{"label":"무슨 얘기인데요?"},{"label":"그럼 잠깐만요."}]'::jsonb, 1, 504)
