insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-heavy-bag-help', '주차장 근처에서 낯선 사람이 무거운 짐을 들어달라고 해요.', '[{"text":"학생, 이 짐이 너무 무거운데 저기까지만 같이 들어줄 수 있어?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"금방이야, 힘든 것도 아니고.","speaker":"A"},{"text":"저 말고 다른 어른께 부탁드려보세요.","speaker":"B"}]'::jsonb, '[{"label":"네, 어디로 들고 가면 돼요?"},{"label":"얼마나 무거운데요?"},{"label":"죄송하지만 도와드리기 어려워요."},{"label":"조금이면 도와드릴게요."}]'::jsonb, 2, 505)
