insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-stray-cat-feed-help', '골목 안쪽에서 낯선 사람이 길고양이 밥 주는 걸 도와달라고 해요.', '[{"text":"저 안쪽에 길고양이들이 있는데 같이 밥 좀 챙겨줄래?","speaker":"A"},{"text":"고양이는 좋아하는데, 저 안쪽까진 잘 모르겠어요.","speaker":"B"},{"text":"바로 요 앞이야, 금방 갔다 오면 돼.","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"그럼 잠깐만 가볼게요."},{"label":"고양이가 몇 마리예요?"},{"label":"네, 같이 가요."},{"label":"안쪽은 안 될 것 같아요, 여기서 인사만 할게요."}]'::jsonb, 3, 506)
