insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-new-neighbor-house-tour', '이사 왔다는 낯선 사람이 집을 구경시켜달라며 접근해요.', '[{"text":"안녕, 나 어제 이사 온 사람인데 너네 집 구경 좀 시켜줄 수 있어?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"잠깐이면 되는데, 그렇게 안 되나?","speaker":"A"},{"text":"네, 부모님이 계실 때 다시 놀러오세요.","speaker":"B"}]'::jsonb, '[{"label":"음, 지금은 부모님이 안 계셔서 안 될 것 같아요."},{"label":"네, 들어오세요."},{"label":"저희 집은 몇 층인지 아세요?"},{"label":"좋아요, 구경시켜드릴게요."}]'::jsonb, 0, 507)
