insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-phone-borrow-request', '길에서 낯선 사람이 급하다며 휴대폰을 빌려달라고 해요.', '[{"text":"학생, 미안한데 휴대폰이 꺼져서 그런데 잠깐만 빌려줄 수 있어?","speaker":"A"},{"text":"어디에 쓰시려고요?","speaker":"B"},{"text":"전화 한 통만 하면 돼, 금방이야.","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"네, 여기요."},{"label":"죄송해요, 저는 편의점 직원분께 부탁드려보시는 게 좋을 것 같아요."},{"label":"제가 대신 전화번호를 눌러드릴까요?"},{"label":"어디로 전화하실 건데요?"}]'::jsonb, 1, 508)
