insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-ice-cream-treat-lure', '공원에서 낯선 아저씨가 아이스크림을 사준다며 같이 가자고 해요.', '[{"text":"저기 아이스크림 가게 있는데 아저씨가 하나 사줄게, 같이 가자.","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"에이, 그냥 하나만 먹자니까.","speaker":"A"},{"text":"정말 괜찮아요, 감사합니다.","speaker":"B"}]'::jsonb, '[{"label":"무슨 맛 있어요?"},{"label":"네, 좋아요!"},{"label":"괜찮아요, 저는 안 갈게요."},{"label":"조금만 먹고 올게요."}]'::jsonb, 2, 509)
