insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-mom-friend-pretend', '낯선 여자분이 엄마 친구라며 데리러 왔다고 해요.', '[{"text":"안녕, 나 너희 엄마 친구인데 오늘 대신 데리러 왔어.","speaker":"A"},{"text":"저는 처음 뵙는 것 같아요.","speaker":"B"},{"text":"엄마가 바빠서 나한테 부탁했어, 얼른 가자.","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"네, 알겠어요."},{"label":"성함이 어떻게 되세요?"},{"label":"엄마랑 어떻게 친구세요?"},{"label":"엄마한테 먼저 확인 전화를 해볼게요."}]'::jsonb, 3, 510)
