insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-agency-scout-offer', '거리에서 낯선 사람이 연예기획사 관계자라며 캐스팅 제안을 해요.', '[{"text":"얘, 너 얼굴이 참 예쁘게 생겼다. 우리 기획사에서 캐스팅하고 싶은데 명함 줄까?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"부모님 없어도 지금 이야기 나눌 수 있는데.","speaker":"A"},{"text":"부모님과 먼저 상의하고 연락드릴게요.","speaker":"B"}]'::jsonb, '[{"label":"명함 주시면 부모님과 함께 알아볼게요."},{"label":"우와, 저 캐스팅해주세요!"},{"label":"얼마나 유명한 회사예요?"},{"label":"지금 계약해도 되나요?"}]'::jsonb, 0, 511)
