insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-survey-gift-card', '낯선 사람이 설문조사에 참여하면 상품권을 준다고 해요.', '[{"text":"이 설문지만 작성하면 문화상품권 준다는데, 해볼래?","speaker":"A"},{"text":"어떤 내용인데요?","speaker":"B"},{"text":"이름이랑 학교, 사는 곳만 적으면 돼.","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"네, 적어드릴게요."},{"label":"그런 건 부모님과 함께 있을 때 할게요."},{"label":"상품권은 얼마짜리예요?"},{"label":"학교 이름도 적어야 해요?"}]'::jsonb, 1, 512)
