insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-car-load-help', '주차장에서 낯선 아저씨가 차에 짐 옮기는 걸 도와달라고 해요.', '[{"text":"학생, 이 상자들 좀 저 차까지 옮기는 것만 도와줄래?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"금방 끝나, 몇 개 안 돼.","speaker":"A"},{"text":"저 대신 다른 분께 부탁드려보세요.","speaker":"B"}]'::jsonb, '[{"label":"네, 몇 개예요?"},{"label":"차가 어느 거예요?"},{"label":"죄송하지만 저는 도와드리기 어려워요."},{"label":"조금만 도와드릴게요."}]'::jsonb, 2, 513)
