insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-playground-lonely-approach', '놀이터에서 혼자 노는 아이에게 낯선 사람이 같이 놀아주겠다며 다가와요.', '[{"text":"혼자 심심하겠다, 아저씨랑 저기 뒤쪽에서 재밌는 거 하고 놀까?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"거기 신기한 게 있는데, 궁금하지 않아?","speaker":"A"},{"text":"괜찮아요, 친구들 곧 올 거예요.","speaker":"B"}]'::jsonb, '[{"label":"네, 뭐가 있는데요?"},{"label":"조금만 보고 올게요."},{"label":"뒤쪽이 어디예요?"},{"label":"저는 여기서 놀고 있을게요, 괜찮아요."}]'::jsonb, 3, 514)
