insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-delivery-door-open', '집 앞에서 낯선 사람이 택배기사인 척하며 문을 열어달라고 해요.', '[{"text":"택배 왔는데요, 문 좀 열어주실래요? 안에 두고 갈게요.","speaker":"A"},{"text":"택배는 문 앞에 두시면 돼요.","speaker":"B"},{"text":"안에 두는 게 더 안전한데, 잠깐만 열어줘.","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"부모님 오시면 그때 받을게요, 문 앞에 두고 가주세요."},{"label":"알겠어요, 문 열어드릴게요."},{"label":"조금만 기다려주세요."},{"label":"어느 택배회사세요?"}]'::jsonb, 0, 515)
