insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-elevator-follow-lure', '아파트 엘리베이터 앞에서 낯선 사람이 같이 타자며 다가와요.', '[{"text":"어, 마침 잘됐다. 나도 위층 가는데 같이 타고 가자.","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"괜찮아, 금방 올라가는데.","speaker":"A"},{"text":"저는 다음 엘리베이터 탈게요, 감사합니다.","speaker":"B"}]'::jsonb, '[{"label":"네, 같이 타요."},{"label":"저는 조금 기다렸다가 다음에 탈게요."},{"label":"몇 층 가세요?"},{"label":"먼저 타세요."}]'::jsonb, 1, 516)
