insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-parent-coworker-urgent', '낯선 사람이 부모님 회사 동료라며 급한 일이라고 접근해요.', '[{"text":"안녕, 너희 아빠 회사 동료인데 급한 일이 있어서 그런데 잠깐 같이 가줄래?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"진짜 급한 일이야, 얼른 가자.","speaker":"A"},{"text":"먼저 아빠한테 전화해서 확인해볼게요.","speaker":"B"}]'::jsonb, '[{"label":"네, 무슨 일이에요?"},{"label":"성함이 어떻게 되세요?"},{"label":"아빠한테 먼저 전화로 확인해볼게요."},{"label":"알겠어요, 같이 가요."}]'::jsonb, 2, 517)
