insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-money-borrow-approach', '길에서 낯선 사람이 차비가 없다며 돈을 빌려달라고 해요.', '[{"text":"학생, 미안한데 차비가 없어서 그런데 돈 좀 빌려줄 수 있어?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"조금이면 돼, 나중에 갚을게.","speaker":"A"},{"text":"죄송해요, 저도 여유가 없어서요.","speaker":"B"}]'::jsonb, '[{"label":"네, 얼마 필요하세요?"},{"label":"어디까지 가시는데요?"},{"label":"조금만 드릴게요."},{"label":"죄송하지만 저는 도와드리기 어려워요."}]'::jsonb, 3, 518)
