insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-online-friend-meetup', '온라인에서 알게 된 사람이 실제로 만나자고 연락해요.', '[{"text":"우리 온라인에서 친해졌잖아, 이번 주말에 직접 만날래?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"그냥 잠깐 얼굴만 보자는 건데.","speaker":"A"},{"text":"부모님께 먼저 말씀드리고 생각해볼게요.","speaker":"B"}]'::jsonb, '[{"label":"음... 저 혼자 만나는 건 좀 조심스러워요."},{"label":"좋아, 어디서 만날까?"},{"label":"몇 시에 만날까?"},{"label":"주소 알려주세요."}]'::jsonb, 0, 519)
