insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-alley-shortcut-lure', '낯선 사람이 지름길이 있다며 좁은 골목으로 데려가려 해요.', '[{"text":"이쪽 골목으로 가면 훨씬 빨라, 아저씨가 안내해줄게.","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"에이, 금방인데 왜 그래.","speaker":"A"},{"text":"저는 원래 다니던 길로 갈게요, 감사합니다.","speaker":"B"}]'::jsonb, '[{"label":"네, 안내해주세요."},{"label":"괜찮아요, 저는 큰길로 다닐게요."},{"label":"얼마나 빠른데요?"},{"label":"그럼 잠깐만 따라갈게요."}]'::jsonb, 1, 520)
