insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-injured-cat-lure', '낯선 사람이 다친 고양이가 있다며 외진 곳으로 유인해요.', '[{"text":"저 뒤에 다친 고양이가 있는데 나 혼자 힘드니까 같이 좀 봐줄래?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"금방이면 되는데, 불쌍하잖아.","speaker":"A"},{"text":"동물병원이나 다른 어른께 도움을 요청해보세요.","speaker":"B"}]'::jsonb, '[{"label":"네, 같이 가볼게요."},{"label":"고양이가 어디 있는데요?"},{"label":"죄송하지만 저 혼자는 안 갈게요."},{"label":"많이 다쳤어요?"}]'::jsonb, 2, 521)
