insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-lost-way-map-lure', '낯선 사람이 지도를 봐달라며 자꾸 붙잡고 이야기해요.', '[{"text":"학생, 이 지도 좀 봐줄래? 여기가 어딘지 잘 모르겠어서.","speaker":"A"},{"text":"음, 잠깐 볼게요.","speaker":"B"},{"text":"근데 이해가 잘 안 되네, 좀 더 자세히 설명해줄 수 있어?","speaker":"A"},{"blank":true,"speaker":"B"}]'::jsonb, '[{"label":"네, 천천히 알려드릴게요."},{"label":"여기 다시 보여주세요."},{"label":"조금만 더 볼게요."},{"label":"죄송한데 저도 이제 가봐야 해서요."}]'::jsonb, 3, 522)
