insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-afterschool-pickup-lie', '학교 앞에서 낯선 사람이 방과후 교실에서 보내서 데리러 왔다고 해요.', '[{"text":"안녕, 방과후 선생님이 오늘은 나보고 데리러 오라고 하셨어.","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"맞아, 선생님이 바쁘셔서 부탁하셨어.","speaker":"A"},{"text":"그럼 담임 선생님께 먼저 확인해볼게요.","speaker":"B"}]'::jsonb, '[{"label":"저는 선생님께 먼저 확인해보고 갈게요."},{"label":"네, 알겠습니다."},{"label":"어디로 가는데요?"},{"label":"성함이 어떻게 되세요?"}]'::jsonb, 0, 523)
