insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-magic-show-lure', '낯선 사람이 신기한 마술을 보여준다며 골목 안으로 부르고 있어요.', '[{"text":"이 안쪽에서 진짜 신기한 마술 보여줄게, 들어와 볼래?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"진짜 신기한데, 후회 안 할 거야.","speaker":"A"},{"text":"밖에서 잠깐만 보여주시면 안 돼요?","speaker":"B"}]'::jsonb, '[{"label":"네, 들어가 볼게요."},{"label":"저는 안쪽까지는 안 들어갈게요."},{"label":"무슨 마술인데요?"},{"label":"친구 데려와도 돼요?"}]'::jsonb, 1, 524)
