insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-cultural-voucher-survey', '거리에서 낯선 사람이 문화상품권을 준다며 개인정보를 요구해요.', '[{"text":"이 종이에 이름이랑 전화번호만 적으면 문화상품권 바로 줄게.","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"금방 끝나, 손해 볼 거 없잖아.","speaker":"A"},{"text":"부모님과 먼저 이야기해볼게요.","speaker":"B"}]'::jsonb, '[{"label":"네, 적어드릴게요."},{"label":"전화번호는 왜 필요해요?"},{"label":"죄송하지만 저 혼자 정보를 드리긴 어려워요."},{"label":"상품권 먼저 보여주세요."}]'::jsonb, 2, 525)
