insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-photographer-shoot-offer', '낯선 사람이 사진작가라며 화보를 찍자고 제안해요.', '[{"text":"나 사진작가인데, 너 모델처럼 화보 한번 찍어볼래?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"금방 끝나는데, 재밌을 거야.","speaker":"A"},{"text":"부모님이랑 같이 계실 때 다시 말씀해주세요.","speaker":"B"}]'::jsonb, '[{"label":"우와, 좋아요! 지금 찍을까요?"},{"label":"어디서 찍는 거예요?"},{"label":"사진은 어디에 쓰이는 건가요?"},{"label":"부모님과 상의 없이는 어려울 것 같아요."}]'::jsonb, 3, 526)
