insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-idol-trainee-offer', '낯선 사람이 아이돌 연습생으로 뽑아준다며 접근해요.', '[{"text":"너 춤이랑 노래 잘할 것 같은데, 우리 회사 연습생 해볼래?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"기회가 흔치 않은데, 지금 결정해야 해.","speaker":"A"},{"text":"부모님과 상의하고 나서 연락드릴게요.","speaker":"B"}]'::jsonb, '[{"label":"부모님과 먼저 상의해봐야 할 것 같아요."},{"label":"네! 지금 바로 할게요!"},{"label":"연습생은 뭐 하는 거예요?"},{"label":"회사 이름이 뭐예요?"}]'::jsonb, 0, 527)
