insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-package-receive-hallway', '아파트 복도에서 낯선 사람이 택배를 대신 받아달라고 해요.', '[{"text":"학생, 이 택배 좀 잠깐 맡아줄 수 있어? 금방 다시 올게.","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"별거 아닌데, 잠깐이면 돼.","speaker":"A"},{"text":"경비실에 맡기시는 게 더 좋을 것 같아요.","speaker":"B"}]'::jsonb, '[{"label":"네, 맡아드릴게요."},{"label":"죄송하지만 저는 맡아드리기 어려울 것 같아요."},{"label":"언제 다시 오세요?"},{"label":"몇 호로 가져다드리면 돼요?"}]'::jsonb, 1, 528)
