insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-free-ticket-amusement-park', '낯선 사람이 놀이공원 무료입장권을 준다며 같이 가자고 해요.', '[{"text":"이거 놀이공원 무료입장권인데, 아저씨랑 같이 쓰러 갈래?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"공짜인데 아깝잖아, 같이 가자.","speaker":"A"},{"text":"저는 부모님이랑 갈 때 쓸게요, 감사합니다.","speaker":"B"}]'::jsonb, '[{"label":"네, 지금 같이 가요!"},{"label":"몇 시까지 쓸 수 있어요?"},{"label":"저 혼자 가는 건 안 될 것 같아요."},{"label":"어느 놀이공원이에요?"}]'::jsonb, 2, 529)
