insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-hurt-animal-remote-lure', '낯선 사람이 다친 동물이 있다며 외진 공터로 유인해요.', '[{"text":"저 공터 쪽에 다친 동물이 있어서 그런데 같이 좀 봐줄 수 있어?","speaker":"A"},{"blank":true,"speaker":"B"},{"text":"불쌍한데, 얼른 같이 가보자.","speaker":"A"},{"text":"동물보호센터에 연락하시는 게 더 좋을 것 같아요.","speaker":"B"}]'::jsonb, '[{"label":"네, 얼른 가볼게요."},{"label":"어떤 동물인데요?"},{"label":"많이 다쳤어요?"},{"label":"죄송하지만 그쪽까지는 안 갈게요."}]'::jsonb, 3, 530)
