insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-police-help-request', '낯선 사람이 자꾸 따라오는 것 같아 경찰관에게 도움을 요청했어요.', '[{"text":"저... 아까부터 낯선 사람이 자꾸 따라오는 것 같아서 무서워요.","speaker":"A"},{"text":"잘 말해줬어, 여기 있으면 안전해. 잠깐 같이 있어줄게.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그래, 이제 괜찮아. 집까지 데려다줄게.","speaker":"B"}]'::jsonb, '[{"label":"😌","isEmoji":true},{"label":"😢","isEmoji":true},{"label":"😠","isEmoji":true},{"label":"😴","isEmoji":true}]'::jsonb, 0, 531)
