insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-store-clerk-help-request', '편의점 앞에서 낯선 사람 때문에 놀라 직원에게 도움을 요청했어요.', '[{"text":"저기, 밖에 낯선 아저씨가 자꾸 말을 걸어서 좀 무서워요.","speaker":"A"},{"text":"잘했어, 여기 안에서 잠깐 기다려도 돼.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그래, 부모님 오실 때까지 여기 있자.","speaker":"B"}]'::jsonb, '[{"label":"😡","isEmoji":true},{"label":"😊","isEmoji":true},{"label":"🙄","isEmoji":true},{"label":"😪","isEmoji":true}]'::jsonb, 1, 532)
