insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-another-parent-help', '공원에서 낯선 사람 때문에 다른 아이의 부모님께 도움을 요청했어요.', '[{"text":"저... 죄송한데 낯선 아저씨가 자꾸 따라와서 그런데 잠깐 같이 있어주실 수 있나요?","speaker":"A"},{"text":"그럼, 물론이지. 여기 우리 옆에 있자.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"잘 말해줬어, 이제 안심해도 돼.","speaker":"B"}]'::jsonb, '[{"label":"😔","isEmoji":true},{"label":"😤","isEmoji":true},{"label":"🥲","isEmoji":true},{"label":"🤩","isEmoji":true}]'::jsonb, 2, 533)
