insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-tell-parent-praised', '낯선 사람에게 있었던 일을 부모님께 이야기하고 칭찬을 받았어요.', '[{"text":"엄마, 아까 낯선 아저씨가 자꾸 따라오려고 해서 무서웠는데 제가 싫다고 말하고 도망쳐 왔어요.","speaker":"A"},{"text":"정말 잘했어! 그렇게 바로 말하고 안전한 곳으로 온 게 최고야.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"앞으로도 그렇게 하면 돼, 정말 대견하다.","speaker":"B"}]'::jsonb, '[{"label":"😭","isEmoji":true},{"label":"😳","isEmoji":true},{"label":"😒","isEmoji":true},{"label":"😊","isEmoji":true}]'::jsonb, 3, 534)
