insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-school-safety-lesson-recap', '학교 안전교육을 듣고 친구와 낯선 사람 대처법을 이야기해요.', '[{"text":"오늘 안전교육에서 낯선 사람이 말 걸면 어떻게 하라고 했지?","speaker":"A"},{"text":"싫다고 크게 말하고 아는 어른한테 가라고 했어.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"맞아, 우리 둘 다 잘 기억해두자.","speaker":"B"}]'::jsonb, '[{"label":"👍","isEmoji":true},{"label":"😩","isEmoji":true},{"label":"😱","isEmoji":true},{"label":"😵","isEmoji":true}]'::jsonb, 0, 535)
