insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-teacher-teach-method-proud', '선생님께 낯선 사람 대처법을 배우고 뿌듯한 마음이 들었어요.', '[{"text":"선생님, 낯선 사람이 따라오려고 하면 정말 소리를 질러도 되나요?","speaker":"A"},{"text":"그럼, 위험하다고 느끼면 크게 소리치고 도망쳐도 괜찮아.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"이제 알았으니 안심해도 돼, 잘 기억해두자.","speaker":"B"}]'::jsonb, '[{"label":"😨","isEmoji":true},{"label":"😌","isEmoji":true},{"label":"😪","isEmoji":true},{"label":"😑","isEmoji":true}]'::jsonb, 1, 536)
