insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-sibling-advice-comfort', '언니가 낯선 사람 대처법을 알려줘서 마음이 놓였어요.', '[{"text":"언니, 나 아까 모르는 아저씨가 말 걸어서 좀 무서웠어.","speaker":"A"},{"text":"그럴 땐 바로 싫다고 말하고 사람 많은 곳으로 가면 돼, 잘했어.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그래, 다음에도 그렇게 하면 돼.","speaker":"B"}]'::jsonb, '[{"label":"😢","isEmoji":true},{"label":"😡","isEmoji":true},{"label":"😮‍💨","isEmoji":true},{"label":"🥱","isEmoji":true}]'::jsonb, 2, 537)
