insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-safety-house-visit', '낯선 사람 때문에 놀라 아동안전지킴이집에 들어가 도움을 요청했어요.', '[{"text":"저... 밖에 낯선 사람이 있어서 무서운데 여기 들어가도 되나요?","speaker":"A"},{"text":"그럼, 여기가 바로 그런 아이들을 위한 곳이야. 잠깐 있다 가.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"이제 안전하니까 천천히 마음을 가라앉히자.","speaker":"B"}]'::jsonb, '[{"label":"😰","isEmoji":true},{"label":"😑","isEmoji":true},{"label":"😤","isEmoji":true},{"label":"😌","isEmoji":true}]'::jsonb, 3, 538)
