insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-emergency-contact-plan', '부모님과 낯선 사람을 만났을 때의 비상연락 방법을 정해요.', '[{"text":"혹시 밖에서 낯선 사람 때문에 무서운 일이 생기면 엄마한테 어떻게 연락할까?","speaker":"A"},{"text":"근처 가게나 아는 어른한테 부탁해서 전화해달라고 하면 돼.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그래, 이렇게 미리 정해두면 훨씬 안심이 되지.","speaker":"B"}]'::jsonb, '[{"label":"👍","isEmoji":true},{"label":"😫","isEmoji":true},{"label":"😾","isEmoji":true},{"label":"😶","isEmoji":true}]'::jsonb, 0, 539)
