insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-walk-together-promise', '친구와 등하교길에 항상 같이 다니기로 약속했어요.', '[{"text":"우리 이제부터 등하교할 때 꼭 같이 다니자, 그게 더 안전하대.","speaker":"A"},{"text":"좋아, 나도 혼자 다니는 것보다 훨씬 안심될 것 같아.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그래, 내일부터 같이 가자!","speaker":"B"}]'::jsonb, '[{"label":"😒","isEmoji":true},{"label":"😪","isEmoji":true},{"label":"😆","isEmoji":true},{"label":"😨","isEmoji":true}]'::jsonb, 2, 541)
