insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-safety-bell-use', '부모님께 호신용 안전벨(경보기) 사용법을 배워요.', '[{"text":"이게 안전벨인데, 위험할 때 이 버튼을 누르면 큰 소리가 나.","speaker":"A"},{"text":"우와, 이러면 주변에 바로 알릴 수 있겠네요.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그래, 가방에 잘 달아두자.","speaker":"B"}]'::jsonb, '[{"label":"😩","isEmoji":true},{"label":"🤔","isEmoji":true},{"label":"😴","isEmoji":true},{"label":"👍","isEmoji":true}]'::jsonb, 3, 542)
