insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-safe-return-service', '부모님과 함께 안심귀가서비스 이용법을 알아봐요.', '[{"text":"이 앱으로 신청하면 혼자 밤에 갈 때 안전요원이 같이 걸어와 준대.","speaker":"A"},{"text":"진짜요? 그럼 늦게 끝나는 날 신청해볼래요.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"좋아, 다음에 학원 끝나고 한번 이용해보자.","speaker":"B"}]'::jsonb, '[{"label":"😄","isEmoji":true},{"label":"😑","isEmoji":true},{"label":"😢","isEmoji":true},{"label":"😤","isEmoji":true}]'::jsonb, 0, 543)
