insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-parent-pickup-relief', '가게 직원에게 도움을 요청한 뒤 부모님이 데리러 왔어요.', '[{"text":"엄마! 저 여기 있어요, 아까 낯선 사람 때문에 무서워서 가게에 들어와 있었어요.","speaker":"A"},{"text":"정말 잘했어, 엄마가 바로 왔으니까 이제 괜찮아.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"다음에도 무서우면 꼭 이렇게 하자.","speaker":"B"}]'::jsonb, '[{"label":"😭","isEmoji":true},{"label":"😮‍💨","isEmoji":true},{"label":"😠","isEmoji":true},{"label":"😶","isEmoji":true}]'::jsonb, 1, 544)
