insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-handled-well-teacher-praise', '낯선 사람에게 잘 대처했다고 선생님께 칭찬을 받았어요.', '[{"text":"선생님, 저 어제 낯선 아저씨가 말 걸었을 때 배운 대로 크게 싫다고 말했어요.","speaker":"A"},{"text":"정말 잘했어! 배운 걸 그렇게 바로 써먹다니 대단하다.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"앞으로도 자신 있게 그렇게 하면 돼.","speaker":"B"}]'::jsonb, '[{"label":"😔","isEmoji":true},{"label":"😳","isEmoji":true},{"label":"😁","isEmoji":true},{"label":"😪","isEmoji":true}]'::jsonb, 2, 545)
