insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-friend-share-scary-experience', '친구가 낯선 사람 때문에 무서웠던 경험을 이야기해요.', '[{"text":"나 어제 모르는 아저씨가 계속 말 걸어서 너무 무서웠어.","speaker":"A"},{"text":"많이 놀랐겠다, 근데 잘 피한 거 보니 정말 대단해.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그래, 앞으로도 무서우면 꼭 나한테 말해줘.","speaker":"B"}]'::jsonb, '[{"label":"😡","isEmoji":true},{"label":"🙄","isEmoji":true},{"label":"😴","isEmoji":true},{"label":"🥹","isEmoji":true}]'::jsonb, 3, 546)
