insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-police-station-location-learn', '부모님과 함께 동네 파출소 위치를 미리 알아둬요.', '[{"text":"저기 보이는 곳이 우리 동네 파출소야, 무서운 일 있으면 저기로 뛰어가면 돼.","speaker":"A"},{"text":"아, 저기구나! 이제 위치를 알았으니 조금 안심돼요.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"그래, 잘 기억해두자.","speaker":"B"}]'::jsonb, '[{"label":"😊","isEmoji":true},{"label":"😫","isEmoji":true},{"label":"😨","isEmoji":true},{"label":"😑","isEmoji":true}]'::jsonb, 0, 547)
