insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-location-share-app-learn', '부모님과 위치공유 앱 사용법을 함께 배워요.', '[{"text":"이 앱을 켜두면 엄마가 네 위치를 바로 확인할 수 있어.","speaker":"A"},{"text":"오, 그럼 밖에서 무슨 일 있어도 금방 찾아올 수 있겠네요.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"맞아, 항상 켜두고 다니자.","speaker":"B"}]'::jsonb, '[{"label":"😩","isEmoji":true},{"label":"👍","isEmoji":true},{"label":"🤨","isEmoji":true},{"label":"😪","isEmoji":true}]'::jsonb, 1, 548)
