insert into conversations (id, situation, messages, choices, answer_index, sort_order) values ('stranger-no-personal-info-pledge', '친구들과 낯선 사람에게 개인정보를 알려주지 않기로 다짐해요.', '[{"text":"우리 앞으로 모르는 사람이 이름이나 주소 물어보면 절대 말하지 말자.","speaker":"A"},{"text":"맞아, 그건 부모님이나 선생님께만 말씀드려야 하는 거였어.","speaker":"B"},{"blank":true,"speaker":"A"},{"text":"좋아, 우리 이렇게 서로 지켜주자.","speaker":"B"}]'::jsonb, '[{"label":"😖","isEmoji":true},{"label":"😱","isEmoji":true},{"label":"🤝","isEmoji":true},{"label":"😪","isEmoji":true}]'::jsonb, 2, 549)
